00152 void ImGui::TextEx(const char* text, const char* text_end, ImGuiTextFlags flags)
00153 {
00154     ImGuiWindow* window = GetCurrentWindow();
00155     if (window->SkipItems)
00156         return;
00157     ImGuiContext& g = *GImGui;
00158 
00159     // Accept null ranges
00160     if (text == text_end)
00161         text = text_end = "";
00162 
00163     // Calculate length
00164     const char* text_begin = text;
00165     if (text_end == NULL)
00166         text_end = text + strlen(text); // FIXME-OPT
00167 
00168     const ImVec2 text_pos(window->DC.CursorPos.x, window->DC.CursorPos.y + window->DC.CurrLineTextBaseOffset);
00169     const float wrap_pos_x = window->DC.TextWrapPos;
00170     const bool wrap_enabled = (wrap_pos_x >= 0.0f);
00171     if (text_end - text <= 2000 || wrap_enabled)
00172     {
00173         // Common case
00174         const float wrap_width = wrap_enabled ? CalcWrapWidthForPos(window->DC.CursorPos, wrap_pos_x) : 0.0f;
00175         const ImVec2 text_size = CalcTextSize(text_begin, text_end, false, wrap_width);
00176 
00177         ImRect bb(text_pos, text_pos + text_size);
00178         ItemSize(text_size, 0.0f);
00179         if (!ItemAdd(bb, 0))
00180             return;
00181 
00182         // Render (we don't hide text after ## in this end-user function)
00183         RenderTextWrapped(bb.Min, text_begin, text_end, wrap_width);
00184     }
00185     else
00186     {
00187         // Long text!
00188         // Perform manual coarse clipping to optimize for long multi-line text
00189         // - From this point we will only compute the width of lines that are visible. Optimization only available when word-wrapping is disabled.
00190         // - We also don't vertically center the text within the line full height, which is unlikely to matter because we are likely the biggest and only item on the line.
00191         // - We use memchr(), pay attention that well optimized versions of those str/mem functions are much faster than a casually written loop.
00192         const char* line = text;
00193         const float line_height = GetTextLineHeight();
00194         ImVec2 text_size(0, 0);
00195 
00196         // Lines to skip (can't skip when logging text)
00197         ImVec2 pos = text_pos;
00198         if (!g.LogEnabled)
00199         {
00200             int lines_skippable = (int)((window->ClipRect.Min.y - text_pos.y) / line_height);
00201             if (lines_skippable > 0)
00202             {
00203                 int lines_skipped = 0;
00204                 while (line < text_end && lines_skipped < lines_skippable)
00205                 {
00206                     const char* line_end = (const char*)memchr(line, '\n', text_end - line);
00207                     if (!line_end)
00208                         line_end = text_end;
00209                     if ((flags & ImGuiTextFlags_NoWidthForLargeClippedText) == 0)
00210                         text_size.x = ImMax(text_size.x, CalcTextSize(line, line_end).x);
00211                     line = line_end + 1;
00212                     lines_skipped++;
00213                 }
00214                 pos.y += lines_skipped * line_height;
00215             }
00216         }
00217 
00218         // Lines to render
00219         if (line < text_end)
00220         {
00221             ImRect line_rect(pos, pos + ImVec2(FLT_MAX, line_height));
00222             while (line < text_end)
00223             {
00224                 if (IsClippedEx(line_rect, 0))
00225                     break;
00226 
00227                 const char* line_end = (const char*)memchr(line, '\n', text_end - line);
00228                 if (!line_end)
00229                     line_end = text_end;
00230                 text_size.x = ImMax(text_size.x, CalcTextSize(line, line_end).x);
00231                 RenderText(pos, line, line_end, false);
00232                 line = line_end + 1;
00233                 line_rect.Min.y += line_height;
00234                 line_rect.Max.y += line_height;
00235                 pos.y += line_height;
00236             }
00237 
00238             // Count remaining lines
00239             int lines_skipped = 0;
00240             while (line < text_end)
00241             {
00242                 const char* line_end = (const char*)memchr(line, '\n', text_end - line);
00243                 if (!line_end)
00244                     line_end = text_end;
00245                 if ((flags & ImGuiTextFlags_NoWidthForLargeClippedText) == 0)
00246                     text_size.x = ImMax(text_size.x, CalcTextSize(line, line_end).x);
00247                 line = line_end + 1;
00248                 lines_skipped++;
00249             }
00250             pos.y += lines_skipped * line_height;
00251         }
00252         text_size.y = (pos - text_pos).y;
00253 
00254         ImRect bb(text_pos, text_pos + text_size);
00255         ItemSize(text_size, 0.0f);
00256         ItemAdd(bb, 0);
00257     }
00258 }
00259 
