00342 // Add a label+text combo aligned to other label+value widgets
00343 void ImGui::LabelTextV(const char* label, const char* fmt, va_list args)
00344 {
00345     ImGuiWindow* window = GetCurrentWindow();
00346     if (window->SkipItems)
00347         return;
00348 
00349     ImGuiContext& g = *GImGui;
00350     const ImGuiStyle& style = g.Style;
00351     const float w = CalcItemWidth();
00352 
00353     const char* value_text_begin, *value_text_end;
00354     ImFormatStringToTempBufferV(&value_text_begin, &value_text_end, fmt, args);
00355     const ImVec2 value_size = CalcTextSize(value_text_begin, value_text_end, false);
00356     const ImVec2 label_size = CalcTextSize(label, NULL, true);
00357 
00358     const ImVec2 pos = window->DC.CursorPos;
00359     const ImRect value_bb(pos, pos + ImVec2(w, value_size.y + style.FramePadding.y * 2));
00360     const ImRect total_bb(pos, pos + ImVec2(w + (label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f), ImMax(value_size.y, label_size.y) + style.FramePadding.y * 2));
00361     ItemSize(total_bb, style.FramePadding.y);
00362     if (!ItemAdd(total_bb, 0))
00363         return;
00364 
00365     // Render
00366     RenderTextClipped(value_bb.Min + style.FramePadding, value_bb.Max, value_text_begin, value_text_end, &value_size, ImVec2(0.0f, 0.0f));
00367     if (label_size.x > 0.0f)
00368         RenderText(ImVec2(value_bb.Max.x + style.ItemInnerSpacing.x, value_bb.Min.y + style.FramePadding.y), label);
00369 }
