00379 // Text with a little bullet aligned to the typical tree node.
00380 void ImGui::BulletTextV(const char* fmt, va_list args)
00381 {
00382     ImGuiWindow* window = GetCurrentWindow();
00383     if (window->SkipItems)
00384         return;
00385 
00386     ImGuiContext& g = *GImGui;
00387     const ImGuiStyle& style = g.Style;
00388 
00389     const char* text_begin, *text_end;
00390     ImFormatStringToTempBufferV(&text_begin, &text_end, fmt, args);
00391     const ImVec2 label_size = CalcTextSize(text_begin, text_end, false);
00392     const ImVec2 total_size = ImVec2(g.FontSize + (label_size.x > 0.0f ? (label_size.x + style.FramePadding.x * 2) : 0.0f), label_size.y);  // Empty text doesn't add padding
00393     ImVec2 pos = window->DC.CursorPos;
00394     pos.y += window->DC.CurrLineTextBaseOffset;
00395     ItemSize(total_size, 0.0f);
00396     const ImRect bb(pos, pos + total_size);
00397     if (!ItemAdd(bb, 0))
00398         return;
00399 
00400     // Render
00401     ImU32 text_col = GetColorU32(ImGuiCol_Text);
00402     RenderBullet(window->DrawList, bb.Min + ImVec2(style.FramePadding.x + g.FontSize * 0.5f, g.FontSize * 0.5f), text_col);
00403     RenderText(bb.Min + ImVec2(g.FontSize + style.FramePadding.x * 2, 0.0f), text_begin, text_end, false);
00404 }
