00429 //-------------------------------------------------------------------------
00430 
00431 // The ButtonBehavior() function is key to many interactions and used by many/most widgets.
00432 // Because we handle so many cases (keyboard/gamepad navigation, drag and drop) and many specific behavior (via ImGuiButtonFlags_),
00433 // this code is a little complex.
00434 // By far the most common path is interacting with the Mouse using the default ImGuiButtonFlags_PressedOnClickRelease button behavior.
00435 // See the series of events below and the corresponding state reported by dear imgui:
00436 //------------------------------------------------------------------------------------------------------------------------------------------------
00437 // with PressedOnClickRelease:             return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
00438 //   Frame N+0 (mouse is outside bb)        -             -                -               -                  -                    -
00439 //   Frame N+1 (mouse moves inside bb)      -             true             -               -                  -                    -
00440 //   Frame N+2 (mouse button is down)       -             true             true            true               -                    true
00441 //   Frame N+3 (mouse button is down)       -             true             true            -                  -                    -
00442 //   Frame N+4 (mouse moves outside bb)     -             -                true            -                  -                    -
00443 //   Frame N+5 (mouse moves inside bb)      -             true             true            -                  -                    -
00444 //   Frame N+6 (mouse button is released)   true          true             -               -                  true                 -
00445 //   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
00446 //   Frame N+8 (mouse moves outside bb)     -             -                -               -                  -                    -
00447 //------------------------------------------------------------------------------------------------------------------------------------------------
00448 // with PressedOnClick:                    return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
00449 //   Frame N+2 (mouse button is down)       true          true             true            true               -                    true
00450 //   Frame N+3 (mouse button is down)       -             true             true            -                  -                    -
00451 //   Frame N+6 (mouse button is released)   -             true             -               -                  true                 -
00452 //   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
00453 //------------------------------------------------------------------------------------------------------------------------------------------------
00454 // with PressedOnRelease:                  return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
00455 //   Frame N+2 (mouse button is down)       -             true             -               -                  -                    true
00456 //   Frame N+3 (mouse button is down)       -             true             -               -                  -                    -
00457 //   Frame N+6 (mouse button is released)   true          true             -               -                  -                    -
00458 //   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
00459 //------------------------------------------------------------------------------------------------------------------------------------------------
00460 // with PressedOnDoubleClick:              return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
00461 //   Frame N+0 (mouse button is down)       -             true             -               -                  -                    true
00462 //   Frame N+1 (mouse button is down)       -             true             -               -                  -                    -
00463 //   Frame N+2 (mouse button is released)   -             true             -               -                  -                    -
00464 //   Frame N+3 (mouse button is released)   -             true             -               -                  -                    -
00465 //   Frame N+4 (mouse button is down)       true          true             true            true               -                    true
00466 //   Frame N+5 (mouse button is down)       -             true             true            -                  -                    -
00467 //   Frame N+6 (mouse button is released)   -             true             -               -                  true                 -
00468 //   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
00469 //------------------------------------------------------------------------------------------------------------------------------------------------
00470 // Note that some combinations are supported,
00471 // - PressedOnDragDropHold can generally be associated with any flag.
00472 // - PressedOnDoubleClick can be associated by PressedOnClickRelease/PressedOnRelease, in which case the second release event won't be reported.
00473 //------------------------------------------------------------------------------------------------------------------------------------------------
00474 // The behavior of the return-value changes when ImGuiButtonFlags_Repeat is set:
00475 //                                         Repeat+                  Repeat+           Repeat+             Repeat+
00476 //                                         PressedOnClickRelease    PressedOnClick    PressedOnRelease    PressedOnDoubleClick
00477 //-------------------------------------------------------------------------------------------------------------------------------------------------
00478 //   Frame N+0 (mouse button is down)       -                        true              -                   true
00479 //   ...                                    -                        -                 -                   -
00480 //   Frame N + RepeatDelay                  true                     true              -                   true
00481 //   ...                                    -                        -                 -                   -
00482 //   Frame N + RepeatDelay + RepeatRate*N   true                     true              -                   true
00483 //-------------------------------------------------------------------------------------------------------------------------------------------------
00484 
00485 // FIXME: For refactor we could output flags, incl mouse hovered vs nav keyboard vs nav triggered etc.
00486 // And better standardize how widgets use 'GetColor32((held && hovered) ? ... : hovered ? ...)' vs 'GetColor32(held ? ... : hovered ? ...);'
00487 // For mouse feedback we typically prefer the 'held && hovered' test, but for nav feedback not always. Outputting hovered=true on Activation may be misleading.
00488 bool ImGui::ButtonBehavior(const ImRect& bb, ImGuiID id, bool* out_hovered, bool* out_held, ImGuiButtonFlags flags)
00489 {
00490     ImGuiContext& g = *GImGui;
00491     ImGuiWindow* window = GetCurrentWindow();
00492 
00493     // Default only reacts to left mouse button
00494     if ((flags & ImGuiButtonFlags_MouseButtonMask_) == 0)
00495         flags |= ImGuiButtonFlags_MouseButtonLeft;
00496 
00497     // Default behavior requires click + release inside bounding box
00498     if ((flags & ImGuiButtonFlags_PressedOnMask_) == 0)
00499         flags |= ImGuiButtonFlags_PressedOnDefault_;
00500 
00501     // Default behavior inherited from item flags
00502     // Note that _both_ ButtonFlags and ItemFlags are valid sources, so copy one into the item_flags and only check that.
00503     ImGuiItemFlags item_flags = (g.LastItemData.ID == id ? g.LastItemData.InFlags : g.CurrentItemFlags);
00504     if (flags & ImGuiButtonFlags_AllowOverlap)
00505         item_flags |= ImGuiItemFlags_AllowOverlap;
00506     if (flags & ImGuiButtonFlags_Repeat)
00507         item_flags |= ImGuiItemFlags_ButtonRepeat;
00508 
00509     ImGuiWindow* backup_hovered_window = g.HoveredWindow;
00510     const bool flatten_hovered_children = (flags & ImGuiButtonFlags_FlattenChildren) && g.HoveredWindow && g.HoveredWindow->RootWindowDockTree == window->RootWindowDockTree;
00511     if (flatten_hovered_children)
00512         g.HoveredWindow = window;
00513 
00514 #ifdef IMGUI_ENABLE_TEST_ENGINE
00515     // Alternate registration spot, for when caller didn't use ItemAdd()
00516     if (g.LastItemData.ID != id)
00517         IMGUI_TEST_ENGINE_ITEM_ADD(id, bb, NULL);
00518 #endif
00519 
00520     bool pressed = false;
00521     bool hovered = ItemHoverable(bb, id, item_flags);
00522 
00523     // Special mode for Drag and Drop where holding button pressed for a long time while dragging another item triggers the button
00524     if (g.DragDropActive && (flags & ImGuiButtonFlags_PressedOnDragDropHold) && !(g.DragDropSourceFlags & ImGuiDragDropFlags_SourceNoHoldToOpenOthers))
00525         if (IsItemHovered(ImGuiHoveredFlags_AllowWhenBlockedByActiveItem))
00526         {
00527             hovered = true;
00528             SetHoveredID(id);
00529             if (g.HoveredIdTimer - g.IO.DeltaTime <= DRAGDROP_HOLD_TO_OPEN_TIMER && g.HoveredIdTimer >= DRAGDROP_HOLD_TO_OPEN_TIMER)
00530             {
00531                 pressed = true;
00532                 g.DragDropHoldJustPressedId = id;
00533                 FocusWindow(window);
00534             }
00535         }
00536 
00537     if (flatten_hovered_children)
00538         g.HoveredWindow = backup_hovered_window;
00539 
00540     // Mouse handling
00541     const ImGuiID test_owner_id = (flags & ImGuiButtonFlags_NoTestKeyOwner) ? ImGuiKeyOwner_Any : id;
00542     if (hovered)
00543     {
00544         IM_ASSERT(id != 0); // Lazily check inside rare path.
00545 
00546         // Poll mouse buttons
00547         // - 'mouse_button_clicked' is generally carried into ActiveIdMouseButton when setting ActiveId.
00548         // - Technically we only need some values in one code path, but since this is gated by hovered test this is fine.
00549         int mouse_button_clicked = -1;
00550         int mouse_button_released = -1;
00551         for (int button = 0; button < 3; button++)
00552             if (flags & (ImGuiButtonFlags_MouseButtonLeft << button)) // Handle ImGuiButtonFlags_MouseButtonRight and ImGuiButtonFlags_MouseButtonMiddle here.
00553             {
00554                 if (IsMouseClicked(button, ImGuiInputFlags_None, test_owner_id) && mouse_button_clicked == -1) { mouse_button_clicked = button; }
00555                 if (IsMouseReleased(button, test_owner_id) && mouse_button_released == -1) { mouse_button_released = button; }
00556             }
00557 
00558         // Process initial action
00559         if (!(flags & ImGuiButtonFlags_NoKeyModifiers) || (!g.IO.KeyCtrl && !g.IO.KeyShift && !g.IO.KeyAlt))
00560         {
00561             if (mouse_button_clicked != -1 && g.ActiveId != id)
00562             {
00563                 if (!(flags & ImGuiButtonFlags_NoSetKeyOwner))
00564                     SetKeyOwner(MouseButtonToKey(mouse_button_clicked), id);
00565                 if (flags & (ImGuiButtonFlags_PressedOnClickRelease | ImGuiButtonFlags_PressedOnClickReleaseAnywhere))
00566                 {
00567                     SetActiveID(id, window);
00568                     g.ActiveIdMouseButton = mouse_button_clicked;
00569                     if (!(flags & ImGuiButtonFlags_NoNavFocus))
00570                     {
00571                         SetFocusID(id, window);
00572                         FocusWindow(window);
00573                     }
00574                     else
00575                     {
00576                         FocusWindow(window, ImGuiFocusRequestFlags_RestoreFocusedChild); // Still need to focus and bring to front, but try to avoid losing NavId when navigating a child
00577                     }
00578                 }
00579                 if ((flags & ImGuiButtonFlags_PressedOnClick) || ((flags & ImGuiButtonFlags_PressedOnDoubleClick) && g.IO.MouseClickedCount[mouse_button_clicked] == 2))
00580                 {
00581                     pressed = true;
00582                     if (flags & ImGuiButtonFlags_NoHoldingActiveId)
00583                         ClearActiveID();
00584                     else
00585                         SetActiveID(id, window); // Hold on ID
00586                     g.ActiveIdMouseButton = mouse_button_clicked;
00587                     if (!(flags & ImGuiButtonFlags_NoNavFocus))
00588                     {
00589                         SetFocusID(id, window);
00590                         FocusWindow(window);
00591                     }
00592                     else
00593                     {
00594                         FocusWindow(window, ImGuiFocusRequestFlags_RestoreFocusedChild); // Still need to focus and bring to front, but try to avoid losing NavId when navigating a child
00595                     }
00596                 }
00597             }
00598             if (flags & ImGuiButtonFlags_PressedOnRelease)
00599             {
00600                 if (mouse_button_released != -1)
00601                 {
00602                     const bool has_repeated_at_least_once = (item_flags & ImGuiItemFlags_ButtonRepeat) && g.IO.MouseDownDurationPrev[mouse_button_released] >= g.IO.KeyRepeatDelay; // Repeat mode trumps on release behavior
00603                     if (!has_repeated_at_least_once)
00604                         pressed = true;
00605                     if (!(flags & ImGuiButtonFlags_NoNavFocus))
00606                         SetFocusID(id, window);
00607                     ClearActiveID();
00608                 }
00609             }
00610 
00611             // 'Repeat' mode acts when held regardless of _PressedOn flags (see table above).
00612             // Relies on repeat logic of IsMouseClicked() but we may as well do it ourselves if we end up exposing finer RepeatDelay/RepeatRate settings.
00613             if (g.ActiveId == id && (item_flags & ImGuiItemFlags_ButtonRepeat))
00614                 if (g.IO.MouseDownDuration[g.ActiveIdMouseButton] > 0.0f && IsMouseClicked(g.ActiveIdMouseButton, ImGuiInputFlags_Repeat, test_owner_id))
00615                     pressed = true;
00616         }
00617 
00618         if (pressed)
00619             g.NavDisableHighlight = true;
00620     }
00621 
00622     // Gamepad/Keyboard handling
00623     // We report navigated and navigation-activated items as hovered but we don't set g.HoveredId to not interfere with mouse.
00624     if (g.NavId == id && !g.NavDisableHighlight && g.NavDisableMouseHover)
00625         if (!(flags & ImGuiButtonFlags_NoHoveredOnFocus))
00626             hovered = true;
00627     if (g.NavActivateDownId == id)
00628     {
00629         bool nav_activated_by_code = (g.NavActivateId == id);
00630         bool nav_activated_by_inputs = (g.NavActivatePressedId == id);
00631         if (!nav_activated_by_inputs && (item_flags & ImGuiItemFlags_ButtonRepeat))
00632         {
00633             // Avoid pressing multiple keys from triggering excessive amount of repeat events
00634             const ImGuiKeyData* key1 = GetKeyData(ImGuiKey_Space);
00635             const ImGuiKeyData* key2 = GetKeyData(ImGuiKey_Enter);
00636             const ImGuiKeyData* key3 = GetKeyData(ImGuiKey_NavGamepadActivate);
00637             const float t1 = ImMax(ImMax(key1->DownDuration, key2->DownDuration), key3->DownDuration);
00638             nav_activated_by_inputs = CalcTypematicRepeatAmount(t1 - g.IO.DeltaTime, t1, g.IO.KeyRepeatDelay, g.IO.KeyRepeatRate) > 0;
00639         }
00640         if (nav_activated_by_code || nav_activated_by_inputs)
00641         {
00642             // Set active id so it can be queried by user via IsItemActive(), equivalent of holding the mouse button.
00643             pressed = true;
00644             SetActiveID(id, window);
00645             g.ActiveIdSource = g.NavInputSource;
00646             if (!(flags & ImGuiButtonFlags_NoNavFocus) && !(g.NavActivateFlags & ImGuiActivateFlags_FromShortcut))
00647                 SetFocusID(id, window);
00648             if (g.NavActivateFlags & ImGuiActivateFlags_FromShortcut)
00649                 g.ActiveIdFromShortcut = true;
00650         }
00651     }
00652 
00653     // Process while held
00654     bool held = false;
00655     if (g.ActiveId == id)
00656     {
00657         if (g.ActiveIdSource == ImGuiInputSource_Mouse)
00658         {
00659             if (g.ActiveIdIsJustActivated)
00660                 g.ActiveIdClickOffset = g.IO.MousePos - bb.Min;
00661 
00662             const int mouse_button = g.ActiveIdMouseButton;
00663             if (mouse_button == -1)
00664             {
00665                 // Fallback for the rare situation were g.ActiveId was set programmatically or from another widget (e.g. #6304).
00666                 ClearActiveID();
00667             }
00668             else if (IsMouseDown(mouse_button, test_owner_id))
00669             {
00670                 held = true;
00671             }
00672             else
00673             {
00674                 bool release_in = hovered && (flags & ImGuiButtonFlags_PressedOnClickRelease) != 0;
00675                 bool release_anywhere = (flags & ImGuiButtonFlags_PressedOnClickReleaseAnywhere) != 0;
00676                 if ((release_in || release_anywhere) && !g.DragDropActive)
00677                 {
00678                     // Report as pressed when releasing the mouse (this is the most common path)
00679                     bool is_double_click_release = (flags & ImGuiButtonFlags_PressedOnDoubleClick) && g.IO.MouseReleased[mouse_button] && g.IO.MouseClickedLastCount[mouse_button] == 2;
00680                     bool is_repeating_already = (item_flags & ImGuiItemFlags_ButtonRepeat) && g.IO.MouseDownDurationPrev[mouse_button] >= g.IO.KeyRepeatDelay; // Repeat mode trumps <on release>
00681                     bool is_button_avail_or_owned = TestKeyOwner(MouseButtonToKey(mouse_button), test_owner_id);
00682                     if (!is_double_click_release && !is_repeating_already && is_button_avail_or_owned)
00683                         pressed = true;
00684                 }
00685                 ClearActiveID();
00686             }
00687             if (!(flags & ImGuiButtonFlags_NoNavFocus))
00688                 g.NavDisableHighlight = true;
00689         }
00690         else if (g.ActiveIdSource == ImGuiInputSource_Keyboard || g.ActiveIdSource == ImGuiInputSource_Gamepad)
00691         {
00692             // When activated using Nav, we hold on the ActiveID until activation button is released
00693             if (g.NavActivateDownId == id)
00694                 held = true; // hovered == true not true as we are already likely hovered on direct activation.
00695             else
00696                 ClearActiveID();
00697         }
00698         if (pressed)
00699             g.ActiveIdHasBeenPressedBefore = true;
00700     }
00701 
00702     // Activation highlight (this may be a remote activation)
00703     if (g.NavHighlightActivatedId == id)
00704         hovered = true;
00705 
00706     if (out_hovered) *out_hovered = hovered;
00707     if (out_held) *out_held = held;
00708 
00709     return pressed;
00710 }
