00712 bool ImGui::ButtonEx(const char* label, const ImVec2& size_arg, ImGuiButtonFlags flags)
00713 {
00714     ImGuiWindow* window = GetCurrentWindow();
00715     if (window->SkipItems)
00716         return false;
00717 
00718     ImGuiContext& g = *GImGui;
00719     const ImGuiStyle& style = g.Style;
00720     const ImGuiID id = window->GetID(label);
00721     const ImVec2 label_size = CalcTextSize(label, NULL, true);
00722 
00723     ImVec2 pos = window->DC.CursorPos;
00724     if ((flags & ImGuiButtonFlags_AlignTextBaseLine) && style.FramePadding.y < window->DC.CurrLineTextBaseOffset) // Try to vertically align buttons that are smaller/have no padding so that text baseline matches (bit hacky, since it shouldn't be a flag)
00725         pos.y += window->DC.CurrLineTextBaseOffset - style.FramePadding.y;
00726     ImVec2 size = CalcItemSize(size_arg, label_size.x + style.FramePadding.x * 2.0f, label_size.y + style.FramePadding.y * 2.0f);
00727 
00728     const ImRect bb(pos, pos + size);
00729     ItemSize(size, style.FramePadding.y);
00730     if (!ItemAdd(bb, id))
00731         return false;
00732 
00733     bool hovered, held;
00734     bool pressed = ButtonBehavior(bb, id, &hovered, &held, flags);
00735 
00736     // Render
00737     const ImU32 col = GetColorU32((held && hovered) ? ImGuiCol_ButtonActive : hovered ? ImGuiCol_ButtonHovered : ImGuiCol_Button);
00738     RenderNavHighlight(bb, id);
00739     RenderFrame(bb.Min, bb.Max, col, true, style.FrameRounding);
00740 
00741     if (g.LogEnabled)
00742         LogSetNextTextDecoration("[", "]");
00743     RenderTextClipped(bb.Min + style.FramePadding, bb.Max - style.FramePadding, label, NULL, &label_size, style.ButtonTextAlign, &bb);
00744 
00745     // Automatically close popups
00746     //if (pressed && !(flags & ImGuiButtonFlags_DontClosePopups) && (window->Flags & ImGuiWindowFlags_Popup))
00747     //    CloseCurrentPopup();
00748 
00749     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags);
00750     return pressed;
00751 }
00752 
00753 bool ImGui::Button(const char* label, const ImVec2& size_arg)
00754 {
00755     return ButtonEx(label, size_arg, ImGuiButtonFlags_None);
