00769 // Tip: use ImGui::PushID()/PopID() to push indices or pointers in the ID stack.
00770 // Then you can keep 'str_id' empty or the same for all your buttons (instead of creating a string based on a non-string id)
00771 bool ImGui::InvisibleButton(const char* str_id, const ImVec2& size_arg, ImGuiButtonFlags flags)
00772 {
00773     ImGuiContext& g = *GImGui;
00774     ImGuiWindow* window = GetCurrentWindow();
00775     if (window->SkipItems)
00776         return false;
