00795 bool ImGui::ArrowButtonEx(const char* str_id, ImGuiDir dir, ImVec2 size, ImGuiButtonFlags flags)
00796 {
00797     ImGuiContext& g = *GImGui;
00798     ImGuiWindow* window = GetCurrentWindow();
