00800         return false;
00801 
00802     const ImGuiID id = window->GetID(str_id);
00803     const ImRect bb(window->DC.CursorPos, window->DC.CursorPos + size);
00804     const float default_size = GetFrameHeight();
00805     ItemSize(size, (size.y >= default_size) ? g.Style.FramePadding.y : -1.0f);
00806     if (!ItemAdd(bb, id))
00807         return false;
00808 
00809     bool hovered, held;
00810     bool pressed = ButtonBehavior(bb, id, &hovered, &held, flags);
00811 
00812     // Render
00813     const ImU32 bg_col = GetColorU32((held && hovered) ? ImGuiCol_ButtonActive : hovered ? ImGuiCol_ButtonHovered : ImGuiCol_Button);
00814     const ImU32 text_col = GetColorU32(ImGuiCol_Text);
00815     RenderNavHighlight(bb, id);
00816     RenderFrame(bb.Min, bb.Max, bg_col, true, g.Style.FrameRounding);
00817     RenderArrow(window->DrawList, bb.Min + ImVec2(ImMax(0.0f, (size.x - g.FontSize) * 0.5f), ImMax(0.0f, (size.y - g.FontSize) * 0.5f)), text_col, dir);
00818 
00819     IMGUI_TEST_ENGINE_ITEM_INFO(id, str_id, g.LastItemData.StatusFlags);
00820     return pressed;
