00829 // Button to close a window
00830 bool ImGui::CloseButton(ImGuiID id, const ImVec2& pos)
00831 {
00832     ImGuiContext& g = *GImGui;
00833     ImGuiWindow* window = g.CurrentWindow;
00834 
00835     // Tweak 1: Shrink hit-testing area if button covers an abnormally large proportion of the visible region. That's in order to facilitate moving the window away. (#3825)
00836     // This may better be applied as a general hit-rect reduction mechanism for all widgets to ensure the area to move window is always accessible?
00837     const ImRect bb(pos, pos + ImVec2(g.FontSize, g.FontSize));
00838     ImRect bb_interact = bb;
00839     const float area_to_visible_ratio = window->OuterRectClipped.GetArea() / bb.GetArea();
00840     if (area_to_visible_ratio < 1.5f)
00841         bb_interact.Expand(ImTrunc(bb_interact.GetSize() * -0.25f));
00842 
00843     // Tweak 2: We intentionally allow interaction when clipped so that a mechanical Alt,Right,Activate sequence can always close a window.
00844     // (this isn't the common behavior of buttons, but it doesn't affect the user because navigation tends to keep items visible in scrolling layer).
00845     bool is_clipped = !ItemAdd(bb_interact, id);
00846 
00847     bool hovered, held;
00848     bool pressed = ButtonBehavior(bb_interact, id, &hovered, &held);
00849     if (is_clipped)
00850         return pressed;
00851 
00852     // Render
00853     ImU32 bg_col = GetColorU32(held ? ImGuiCol_ButtonActive : ImGuiCol_ButtonHovered);
00854     if (hovered)
00855         window->DrawList->AddRectFilled(bb.Min, bb.Max, bg_col);
00856     RenderNavHighlight(bb, id, ImGuiNavHighlightFlags_Compact);
00857     ImU32 cross_col = GetColorU32(ImGuiCol_Text);
00858     ImVec2 cross_center = bb.GetCenter() - ImVec2(0.5f, 0.5f);
00859     float cross_extent = g.FontSize * 0.5f * 0.7071f - 1.0f;
00860     window->DrawList->AddLine(cross_center + ImVec2(+cross_extent, +cross_extent), cross_center + ImVec2(-cross_extent, -cross_extent), cross_col, 1.0f);
00861     window->DrawList->AddLine(cross_center + ImVec2(+cross_extent, -cross_extent), cross_center + ImVec2(-cross_extent, +cross_extent), cross_col, 1.0f);
00862 
00863     return pressed;
00864 }
