00866 // The Collapse button also functions as a Dock Menu button.
00867 bool ImGui::CollapseButton(ImGuiID id, const ImVec2& pos, ImGuiDockNode* dock_node)
00868 {
00869     ImGuiContext& g = *GImGui;
00870     ImGuiWindow* window = g.CurrentWindow;
00871 
00872     ImRect bb(pos, pos + ImVec2(g.FontSize, g.FontSize));
00873     bool is_clipped = !ItemAdd(bb, id);
00874     bool hovered, held;
00875     bool pressed = ButtonBehavior(bb, id, &hovered, &held, ImGuiButtonFlags_None);
00876     if (is_clipped)
00877         return pressed;
00878 
00879     // Render
00880     //bool is_dock_menu = (window->DockNodeAsHost && !window->Collapsed);
00881     ImU32 bg_col = GetColorU32((held && hovered) ? ImGuiCol_ButtonActive : hovered ? ImGuiCol_ButtonHovered : ImGuiCol_Button);
00882     ImU32 text_col = GetColorU32(ImGuiCol_Text);
00883     if (hovered || held)
00884         window->DrawList->AddRectFilled(bb.Min, bb.Max, bg_col);
00885     RenderNavHighlight(bb, id, ImGuiNavHighlightFlags_Compact);
00886 
00887     if (dock_node)
00888         RenderArrowDockMenu(window->DrawList, bb.Min, g.FontSize, text_col);
00889     else
00890         RenderArrow(window->DrawList, bb.Min, text_col, window->Collapsed ? ImGuiDir_Right : ImGuiDir_Down, 1.0f);
00891 
00892     // Switch to moving the window after mouse is moved beyond the initial drag threshold
00893     if (IsItemActive() && IsMouseDragging(0))
00894         StartMouseMovingWindowOrNode(window, dock_node, true); // Undock from window/collapse menu button
00895 
00896     return pressed;
00897 }
