00903 
00904 // Return scrollbar rectangle, must only be called for corresponding axis if window->ScrollbarX/Y is set.
00905 ImRect ImGui::GetWindowScrollbarRect(ImGuiWindow* window, ImGuiAxis axis)
00906 {
00907     const ImRect outer_rect = window->Rect();
00908     const ImRect inner_rect = window->InnerRect;
00909     const float border_size = window->WindowBorderSize;
00910     const float scrollbar_size = window->ScrollbarSizes[axis ^ 1]; // (ScrollbarSizes.x = width of Y scrollbar; ScrollbarSizes.y = height of X scrollbar)
00911     IM_ASSERT(scrollbar_size > 0.0f);
00912     if (axis == ImGuiAxis_X)
00913         return ImRect(inner_rect.Min.x, ImMax(outer_rect.Min.y, outer_rect.Max.y - border_size - scrollbar_size), inner_rect.Max.x - border_size, outer_rect.Max.y - border_size);
00914     else
00915         return ImRect(ImMax(outer_rect.Min.x, outer_rect.Max.x - border_size - scrollbar_size), inner_rect.Min.y, outer_rect.Max.x - border_size, inner_rect.Max.y - border_size);
00916 }
00917 
00918 void ImGui::Scrollbar(ImGuiAxis axis)
00919 {
00920     ImGuiContext& g = *GImGui;
00921     ImGuiWindow* window = g.CurrentWindow;
00922     const ImGuiID id = GetWindowScrollbarID(window, axis);
00923 
00924     // Calculate scrollbar bounding box
00925     ImRect bb = GetWindowScrollbarRect(window, axis);
00926     ImDrawFlags rounding_corners = ImDrawFlags_RoundCornersNone;
00927     if (axis == ImGuiAxis_X)
00928     {
00929         rounding_corners |= ImDrawFlags_RoundCornersBottomLeft;
00930         if (!window->ScrollbarY)
00931             rounding_corners |= ImDrawFlags_RoundCornersBottomRight;
00932     }
00933     else
00934     {
00935         if ((window->Flags & ImGuiWindowFlags_NoTitleBar) && !(window->Flags & ImGuiWindowFlags_MenuBar))
00936             rounding_corners |= ImDrawFlags_RoundCornersTopRight;
00937         if (!window->ScrollbarX)
00938             rounding_corners |= ImDrawFlags_RoundCornersBottomRight;
00939     }
00940     float size_visible = window->InnerRect.Max[axis] - window->InnerRect.Min[axis];
00941     float size_contents = window->ContentSize[axis] + window->WindowPadding[axis] * 2.0f;
00942     ImS64 scroll = (ImS64)window->Scroll[axis];
00943     ScrollbarEx(bb, id, axis, &scroll, (ImS64)size_visible, (ImS64)size_contents, rounding_corners);
00944     window->Scroll[axis] = (float)scroll;
00945 }
00946 
00947 // Vertical/Horizontal scrollbar
00948 // The entire piece of code below is rather confusing because:
00949 // - We handle absolute seeking (when first clicking outside the grab) and relative manipulation (afterward or when clicking inside the grab)
00950 // - We store values as normalized ratio and in a form that allows the window content to change while we are holding on a scrollbar
00951 // - We handle both horizontal and vertical scrollbars, which makes the terminology not ideal.
00952 // Still, the code should probably be made simpler..
00953 bool ImGui::ScrollbarEx(const ImRect& bb_frame, ImGuiID id, ImGuiAxis axis, ImS64* p_scroll_v, ImS64 size_visible_v, ImS64 size_contents_v, ImDrawFlags flags)
00954 {
00955     ImGuiContext& g = *GImGui;
00956     ImGuiWindow* window = g.CurrentWindow;
00957     if (window->SkipItems)
00958         return false;
00959 
00960     const float bb_frame_width = bb_frame.GetWidth();
00961     const float bb_frame_height = bb_frame.GetHeight();
00962     if (bb_frame_width <= 0.0f || bb_frame_height <= 0.0f)
00963         return false;
00964 
00965     // When we are too small, start hiding and disabling the grab (this reduce visual noise on very small window and facilitate using the window resize grab)
00966     float alpha = 1.0f;
00967     if ((axis == ImGuiAxis_Y) && bb_frame_height < g.FontSize + g.Style.FramePadding.y * 2.0f)
00968         alpha = ImSaturate((bb_frame_height - g.FontSize) / (g.Style.FramePadding.y * 2.0f));
00969     if (alpha <= 0.0f)
00970         return false;
00971 
00972     const ImGuiStyle& style = g.Style;
00973     const bool allow_interaction = (alpha >= 1.0f);
00974 
00975     ImRect bb = bb_frame;
00976     bb.Expand(ImVec2(-ImClamp(IM_TRUNC((bb_frame_width - 2.0f) * 0.5f), 0.0f, 3.0f), -ImClamp(IM_TRUNC((bb_frame_height - 2.0f) * 0.5f), 0.0f, 3.0f)));
00977 
00978     // V denote the main, longer axis of the scrollbar (= height for a vertical scrollbar)
00979     const float scrollbar_size_v = (axis == ImGuiAxis_X) ? bb.GetWidth() : bb.GetHeight();
00980 
00981     // Calculate the height of our grabbable box. It generally represent the amount visible (vs the total scrollable amount)
00982     // But we maintain a minimum size in pixel to allow for the user to still aim inside.
00983     IM_ASSERT(ImMax(size_contents_v, size_visible_v) > 0.0f); // Adding this assert to check if the ImMax(XXX,1.0f) is still needed. PLEASE CONTACT ME if this triggers.
00984     const ImS64 win_size_v = ImMax(ImMax(size_contents_v, size_visible_v), (ImS64)1);
00985     const float grab_h_pixels = ImClamp(scrollbar_size_v * ((float)size_visible_v / (float)win_size_v), style.GrabMinSize, scrollbar_size_v);
00986     const float grab_h_norm = grab_h_pixels / scrollbar_size_v;
00987 
00988     // Handle input right away. None of the code of Begin() is relying on scrolling position before calling Scrollbar().
00989     bool held = false;
00990     bool hovered = false;
00991     ItemAdd(bb_frame, id, NULL, ImGuiItemFlags_NoNav);
00992     ButtonBehavior(bb, id, &hovered, &held, ImGuiButtonFlags_NoNavFocus);
00993 
00994     const ImS64 scroll_max = ImMax((ImS64)1, size_contents_v - size_visible_v);
00995     float scroll_ratio = ImSaturate((float)*p_scroll_v / (float)scroll_max);
00996     float grab_v_norm = scroll_ratio * (scrollbar_size_v - grab_h_pixels) / scrollbar_size_v; // Grab position in normalized space
00997     if (held && allow_interaction && grab_h_norm < 1.0f)
00998     {
00999         const float scrollbar_pos_v = bb.Min[axis];
01000         const float mouse_pos_v = g.IO.MousePos[axis];
01001 
01002         // Click position in scrollbar normalized space (0.0f->1.0f)
01003         const float clicked_v_norm = ImSaturate((mouse_pos_v - scrollbar_pos_v) / scrollbar_size_v);
01004 
01005         const int held_dir = (clicked_v_norm < grab_v_norm) ? -1 : (clicked_v_norm > grab_v_norm + grab_h_norm) ? +1 : 0;
01006         if (g.ActiveIdIsJustActivated)
01007         {
01008             // On initial click calculate the distance between mouse and the center of the grab
01009             g.ScrollbarSeekMode = (short)held_dir;
01010             g.ScrollbarClickDeltaToGrabCenter = (g.ScrollbarSeekMode == 0.0f) ? clicked_v_norm - grab_v_norm - grab_h_norm * 0.5f : 0.0f;
01011         }
01012 
01013         // Apply scroll (p_scroll_v will generally point on one member of window->Scroll)
01014         // It is ok to modify Scroll here because we are being called in Begin() after the calculation of ContentSize and before setting up our starting position
01015         if (g.ScrollbarSeekMode == 0)
01016         {
01017             // Absolute seeking
01018             const float scroll_v_norm = ImSaturate((clicked_v_norm - g.ScrollbarClickDeltaToGrabCenter - grab_h_norm * 0.5f) / (1.0f - grab_h_norm));
01019             *p_scroll_v = (ImS64)(scroll_v_norm * scroll_max);
01020         }
01021         else
01022         {
01023             // Page by page
01024             if (IsMouseClicked(ImGuiMouseButton_Left, ImGuiInputFlags_Repeat) && held_dir == g.ScrollbarSeekMode)
01025             {
01026                 float page_dir = (g.ScrollbarSeekMode > 0.0f) ? +1.0f : -1.0f;
01027                 *p_scroll_v = ImClamp(*p_scroll_v + (ImS64)(page_dir * size_visible_v), (ImS64)0, scroll_max);
01028             }
01029         }
01030 
01031         // Update values for rendering
01032         scroll_ratio = ImSaturate((float)*p_scroll_v / (float)scroll_max);
01033         grab_v_norm = scroll_ratio * (scrollbar_size_v - grab_h_pixels) / scrollbar_size_v;
01034 
01035         // Update distance to grab now that we have seek'ed and saturated
01036         //if (seek_absolute)
01037         //    g.ScrollbarClickDeltaToGrabCenter = clicked_v_norm - grab_v_norm - grab_h_norm * 0.5f;
01038     }
01039 
01040     // Render
01041     const ImU32 bg_col = GetColorU32(ImGuiCol_ScrollbarBg);
01042     const ImU32 grab_col = GetColorU32(held ? ImGuiCol_ScrollbarGrabActive : hovered ? ImGuiCol_ScrollbarGrabHovered : ImGuiCol_ScrollbarGrab, alpha);
01043     window->DrawList->AddRectFilled(bb_frame.Min, bb_frame.Max, bg_col, window->WindowRounding, flags);
01044     ImRect grab_rect;
01045     if (axis == ImGuiAxis_X)
01046         grab_rect = ImRect(ImLerp(bb.Min.x, bb.Max.x, grab_v_norm), bb.Min.y, ImLerp(bb.Min.x, bb.Max.x, grab_v_norm) + grab_h_pixels, bb.Max.y);
01047     else
01048         grab_rect = ImRect(bb.Min.x, ImLerp(bb.Min.y, bb.Max.y, grab_v_norm), bb.Max.x, ImLerp(bb.Min.y, bb.Max.y, grab_v_norm) + grab_h_pixels);
01049     window->DrawList->AddRectFilled(grab_rect.Min, grab_rect.Max, grab_col, style.ScrollbarRounding);
01050 
01051     return held;
01052 }
