01054 // - Read about ImTextureID here: https://github.com/ocornut/imgui/wiki/Image-Loading-and-Displaying-Examples
01055 // - 'uv0' and 'uv1' are texture coordinates. Read about them from the same link above.
01056 void ImGui::Image(ImTextureID user_texture_id, const ImVec2& image_size, const ImVec2& uv0, const ImVec2& uv1, const ImVec4& tint_col, const ImVec4& border_col)
01057 {
01058     ImGuiWindow* window = GetCurrentWindow();
01059     if (window->SkipItems)
01060         return;
01061 
01062     const float border_size = (border_col.w > 0.0f) ? 1.0f : 0.0f;
01063     const ImVec2 padding(border_size, border_size);
01064     const ImRect bb(window->DC.CursorPos, window->DC.CursorPos + image_size + padding * 2.0f);
01065     ItemSize(bb);
01066     if (!ItemAdd(bb, 0))
01067         return;
01068 
01069     // Render
01070     if (border_size > 0.0f)
01071         window->DrawList->AddRect(bb.Min, bb.Max, GetColorU32(border_col), 0.0f, ImDrawFlags_None, border_size);
01072     window->DrawList->AddImage(user_texture_id, bb.Min + padding, bb.Max - padding, uv0, uv1, GetColorU32(tint_col));
01073 }
