01141 bool ImGui::Checkbox(const char* label, bool* v)
01142 {
01143     ImGuiWindow* window = GetCurrentWindow();
01144     if (window->SkipItems)
01145         return false;
01146 
01147     ImGuiContext& g = *GImGui;
01148     const ImGuiStyle& style = g.Style;
01149     const ImGuiID id = window->GetID(label);
01150     const ImVec2 label_size = CalcTextSize(label, NULL, true);
01151 
01152     const float square_sz = GetFrameHeight();
01153     const ImVec2 pos = window->DC.CursorPos;
01154     const ImRect total_bb(pos, pos + ImVec2(square_sz + (label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f), label_size.y + style.FramePadding.y * 2.0f));
01155     ItemSize(total_bb, style.FramePadding.y);
01156     const bool is_visible = ItemAdd(total_bb, id);
01157     const bool is_multi_select = (g.LastItemData.InFlags & ImGuiItemFlags_IsMultiSelect) != 0;
01158     if (!is_visible)
01159         if (!is_multi_select || !g.BoxSelectState.UnclipMode || !g.BoxSelectState.UnclipRect.Overlaps(total_bb)) // Extra layer of "no logic clip" for box-select support
01160         {
01161             IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Checkable | (*v ? ImGuiItemStatusFlags_Checked : 0));
01162             return false;
01163         }
01164 
01165     // Range-Selection/Multi-selection support (header)
01166     bool checked = *v;
01167     if (is_multi_select)
01168         MultiSelectItemHeader(id, &checked, NULL);
01169 
01170     bool hovered, held;
01171     bool pressed = ButtonBehavior(total_bb, id, &hovered, &held);
01172 
01173     // Range-Selection/Multi-selection support (footer)
01174     if (is_multi_select)
01175         MultiSelectItemFooter(id, &checked, &pressed);
01176     else if (pressed)
01177         checked = !checked;
01178 
01179     if (*v != checked)
01180     {
01181         *v = checked;
01182         pressed = true; // return value
01183         MarkItemEdited(id);
01184     }
01185 
01186     const ImRect check_bb(pos, pos + ImVec2(square_sz, square_sz));
01187     const bool mixed_value = (g.LastItemData.InFlags & ImGuiItemFlags_MixedValue) != 0;
01188     if (is_visible)
01189     {
01190         RenderNavHighlight(total_bb, id);
01191         RenderFrame(check_bb.Min, check_bb.Max, GetColorU32((held && hovered) ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg), true, style.FrameRounding);
01192         ImU32 check_col = GetColorU32(ImGuiCol_CheckMark);
01193         if (mixed_value)
01194         {
01195             // Undocumented tristate/mixed/indeterminate checkbox (#2644)
01196             // This may seem awkwardly designed because the aim is to make ImGuiItemFlags_MixedValue supported by all widgets (not just checkbox)
01197             ImVec2 pad(ImMax(1.0f, IM_TRUNC(square_sz / 3.6f)), ImMax(1.0f, IM_TRUNC(square_sz / 3.6f)));
01198             window->DrawList->AddRectFilled(check_bb.Min + pad, check_bb.Max - pad, check_col, style.FrameRounding);
01199         }
01200         else if (*v)
01201         {
01202             const float pad = ImMax(1.0f, IM_TRUNC(square_sz / 6.0f));
01203             RenderCheckMark(window->DrawList, check_bb.Min + ImVec2(pad, pad), check_col, square_sz - pad * 2.0f);
01204         }
01205     }
01206     const ImVec2 label_pos = ImVec2(check_bb.Max.x + style.ItemInnerSpacing.x, check_bb.Min.y + style.FramePadding.y);
01207     if (g.LogEnabled)
01208         LogRenderedText(&label_pos, mixed_value ? "[~]" : *v ? "[x]" : "[ ]");
01209     if (is_visible && label_size.x > 0.0f)
01210         RenderText(label_pos, label);
01211 
01212     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Checkable | (*v ? ImGuiItemStatusFlags_Checked : 0));
01213     return pressed;
01214 }
