01216 template<typename T>
01217 bool ImGui::CheckboxFlagsT(const char* label, T* flags, T flags_value)
01218 {
01219     bool all_on = (*flags & flags_value) == flags_value;
01220     bool any_on = (*flags & flags_value) != 0;
01221     bool pressed;
01222     if (!all_on && any_on)
01223     {
01224         ImGuiContext& g = *GImGui;
01225         g.NextItemData.ItemFlags |= ImGuiItemFlags_MixedValue;
01226         pressed = Checkbox(label, &all_on);
01227     }
01228     else
01229     {
01230         pressed = Checkbox(label, &all_on);
01231 
01232     }
01233     if (pressed)
01234     {
01235         if (all_on)
01236             *flags |= flags_value;
01237         else
01238             *flags &= ~flags_value;
01239     }
01240     return pressed;
01241 }
