01263 bool ImGui::RadioButton(const char* label, bool active)
01264 {
01265     ImGuiWindow* window = GetCurrentWindow();
01266     if (window->SkipItems)
01267         return false;
01268 
01269     ImGuiContext& g = *GImGui;
01270     const ImGuiStyle& style = g.Style;
01271     const ImGuiID id = window->GetID(label);
01272     const ImVec2 label_size = CalcTextSize(label, NULL, true);
01273 
01274     const float square_sz = GetFrameHeight();
01275     const ImVec2 pos = window->DC.CursorPos;
01276     const ImRect check_bb(pos, pos + ImVec2(square_sz, square_sz));
01277     const ImRect total_bb(pos, pos + ImVec2(square_sz + (label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f), label_size.y + style.FramePadding.y * 2.0f));
01278     ItemSize(total_bb, style.FramePadding.y);
01279     if (!ItemAdd(total_bb, id))
01280         return false;
01281 
01282     ImVec2 center = check_bb.GetCenter();
01283     center.x = IM_ROUND(center.x);
01284     center.y = IM_ROUND(center.y);
01285     const float radius = (square_sz - 1.0f) * 0.5f;
01286 
01287     bool hovered, held;
01288     bool pressed = ButtonBehavior(total_bb, id, &hovered, &held);
01289     if (pressed)
01290         MarkItemEdited(id);
01291 
01292     RenderNavHighlight(total_bb, id);
01293     const int num_segment = window->DrawList->_CalcCircleAutoSegmentCount(radius);
01294     window->DrawList->AddCircleFilled(center, radius, GetColorU32((held && hovered) ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg), num_segment);
01295     if (active)
01296     {
01297         const float pad = ImMax(1.0f, IM_TRUNC(square_sz / 6.0f));
01298         window->DrawList->AddCircleFilled(center, radius - pad, GetColorU32(ImGuiCol_CheckMark));
01299     }
01300 
01301     if (style.FrameBorderSize > 0.0f)
01302     {
01303         window->DrawList->AddCircle(center + ImVec2(1, 1), radius, GetColorU32(ImGuiCol_BorderShadow), num_segment, style.FrameBorderSize);
01304         window->DrawList->AddCircle(center, radius, GetColorU32(ImGuiCol_Border), num_segment, style.FrameBorderSize);
01305     }
01306 
01307     ImVec2 label_pos = ImVec2(check_bb.Max.x + style.ItemInnerSpacing.x, check_bb.Min.y + style.FramePadding.y);
01308     if (g.LogEnabled)
01309         LogRenderedText(&label_pos, active ? "(x)" : "( )");
01310     if (label_size.x > 0.0f)
01311         RenderText(label_pos, label);
01312 
01313     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags);
01314     return pressed;
01315 }
