01326 // size_arg (for each axis) < 0.0f: align to end, 0.0f: auto, > 0.0f: specified size
01327 void ImGui::ProgressBar(float fraction, const ImVec2& size_arg, const char* overlay)
01328 {
01329     ImGuiWindow* window = GetCurrentWindow();
01330     if (window->SkipItems)
01331         return;
01332 
01333     ImGuiContext& g = *GImGui;
01334     const ImGuiStyle& style = g.Style;
01335 
01336     ImVec2 pos = window->DC.CursorPos;
01337     ImVec2 size = CalcItemSize(size_arg, CalcItemWidth(), g.FontSize + style.FramePadding.y * 2.0f);
01338     ImRect bb(pos, pos + size);
01339     ItemSize(size, style.FramePadding.y);
01340     if (!ItemAdd(bb, 0))
01341         return;
01342 
01343     // Fraction < 0.0f will display an indeterminate progress bar animation
01344     // The value must be animated along with time, so e.g. passing '-1.0f * ImGui::GetTime()' as fraction works.
01345     const bool is_indeterminate = (fraction < 0.0f);
01346     if (!is_indeterminate)
01347         fraction = ImSaturate(fraction);
01348 
01349     // Out of courtesy we accept a NaN fraction without crashing
01350     float fill_n0 = 0.0f;
01351     float fill_n1 = (fraction == fraction) ? fraction : 0.0f;
01352 
01353     if (is_indeterminate)
01354     {
01355         const float fill_width_n = 0.2f;
01356         fill_n0 = ImFmod(-fraction, 1.0f) * (1.0f + fill_width_n) - fill_width_n;
01357         fill_n1 = ImSaturate(fill_n0 + fill_width_n);
01358         fill_n0 = ImSaturate(fill_n0);
01359     }
01360 
01361     // Render
01362     RenderFrame(bb.Min, bb.Max, GetColorU32(ImGuiCol_FrameBg), true, style.FrameRounding);
01363     bb.Expand(ImVec2(-style.FrameBorderSize, -style.FrameBorderSize));
01364     RenderRectFilledRangeH(window->DrawList, bb, GetColorU32(ImGuiCol_PlotHistogram), fill_n0, fill_n1, style.FrameRounding);
01365 
01366     // Default displaying the fraction as percentage string, but user can override it
01367     // Don't display text for indeterminate bars by default
01368     char overlay_buf[32];
01369     if (!is_indeterminate || overlay != NULL)
01370     {
01371         if (!overlay)
01372         {
01373             ImFormatString(overlay_buf, IM_ARRAYSIZE(overlay_buf), "%.0f%%", fraction * 100 + 0.01f);
01374             overlay = overlay_buf;
01375         }
01376 
01377         ImVec2 overlay_size = CalcTextSize(overlay, NULL);
01378         if (overlay_size.x > 0.0f)
01379         {
01380             float text_x = is_indeterminate ? (bb.Min.x + bb.Max.x - overlay_size.x) * 0.5f : ImLerp(bb.Min.x, bb.Max.x, fill_n1) + style.ItemSpacing.x;
01381             RenderTextClipped(ImVec2(ImClamp(text_x, bb.Min.x, bb.Max.x - overlay_size.x - style.ItemInnerSpacing.x), bb.Min.y), bb.Max, overlay, NULL, &overlay_size, ImVec2(0.0f, 0.5f), &bb);
01382         }
01383     }
01384 }
01385 
01386 void ImGui::Bullet()
01387 {
01388     ImGuiWindow* window = GetCurrentWindow();
01389     if (window->SkipItems)
01390         return;
01391 
01392     ImGuiContext& g = *GImGui;
01393     const ImGuiStyle& style = g.Style;
01394     const float line_height = ImMax(ImMin(window->DC.CurrLineSize.y, g.FontSize + style.FramePadding.y * 2), g.FontSize);
01395     const ImRect bb(window->DC.CursorPos, window->DC.CursorPos + ImVec2(g.FontSize, line_height));
01396     ItemSize(bb);
01397     if (!ItemAdd(bb, 0))
01398     {
01399         SameLine(0, style.FramePadding.x * 2);
01400         return;
01401     }
01402 
01403     // Render and stay on same line
01404     ImU32 text_col = GetColorU32(ImGuiCol_Text);
01405     RenderBullet(window->DrawList, bb.Min + ImVec2(style.FramePadding.x + g.FontSize * 0.5f, line_height * 0.5f), text_col);
01406     SameLine(0, style.FramePadding.x * 2.0f);
