01409 // This is provided as a convenience for being an often requested feature.
01410 // FIXME-STYLE: we delayed adding as there is a larger plan to revamp the styling system.
01411 // Because of this we currently don't provide many styling options for this widget
01412 // (e.g. hovered/active colors are automatically inferred from a single color).
01413 bool ImGui::TextLink(const char* label)
01414 {
01415     ImGuiWindow* window = GetCurrentWindow();
01416     if (window->SkipItems)
01417         return false;
01418 
01419     ImGuiContext& g = *GImGui;
01420     const ImGuiID id = window->GetID(label);
01421     const char* label_end = FindRenderedTextEnd(label);
01422 
01423     ImVec2 pos = window->DC.CursorPos;
01424     ImVec2 size = CalcTextSize(label, label_end, true);
01425     ImRect bb(pos, pos + size);
01426     ItemSize(size, 0.0f);
01427     if (!ItemAdd(bb, id))
01428         return false;
01429 
01430     bool hovered, held;
01431     bool pressed = ButtonBehavior(bb, id, &hovered, &held);
01432     RenderNavHighlight(bb, id, ImGuiNavHighlightFlags_None);
01433 
01434     ImVec4 text_colf = g.Style.Colors[ImGuiCol_TextLink];
01435     ImVec4 line_colf = text_colf;
01436     {
01437         // FIXME-STYLE: Read comments above. This widget is NOT written in the same style as some earlier widgets,
01438         // as we are currently experimenting/planning a different styling system.
01439         float h, s, v;
01440         ColorConvertRGBtoHSV(text_colf.x, text_colf.y, text_colf.z, h, s, v);
01441         if (held || hovered)
01442         {
01443             v = ImSaturate(v + (held ? 0.4f : 0.3f));
01444             h = ImFmod(h + 0.02f, 1.0f);
01445         }
01446         ColorConvertHSVtoRGB(h, s, v, text_colf.x, text_colf.y, text_colf.z);
01447         v = ImSaturate(v - 0.20f);
01448         ColorConvertHSVtoRGB(h, s, v, line_colf.x, line_colf.y, line_colf.z);
01449     }
01450 
01451     float line_y = bb.Max.y + ImFloor(g.Font->Descent * g.FontScale * 0.20f);
01452     window->DrawList->AddLine(ImVec2(bb.Min.x, line_y), ImVec2(bb.Max.x, line_y), GetColorU32(line_colf)); // FIXME-TEXT: Underline mode.
01453 
01454     PushStyleColor(ImGuiCol_Text, GetColorU32(text_colf));
01455     RenderText(bb.Min, label, label_end);
01456     PopStyleColor();
01457 
01458     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags);
01459     return pressed;
01460 }
