01539 // Horizontal/vertical separating line
01540 // FIXME: Surprisingly, this seemingly trivial widget is a victim of many different legacy/tricky layout issues.
01541 // Note how thickness == 1.0f is handled specifically as not moving CursorPos by 'thickness', but other values are.
01542 void ImGui::SeparatorEx(ImGuiSeparatorFlags flags, float thickness)
01543 {
01544     ImGuiWindow* window = GetCurrentWindow();
01545     if (window->SkipItems)
01546         return;
01547 
01548     ImGuiContext& g = *GImGui;
01549     IM_ASSERT(ImIsPowerOfTwo(flags & (ImGuiSeparatorFlags_Horizontal | ImGuiSeparatorFlags_Vertical)));   // Check that only 1 option is selected
01550     IM_ASSERT(thickness > 0.0f);
01551 
01552     if (flags & ImGuiSeparatorFlags_Vertical)
01553     {
01554         // Vertical separator, for menu bars (use current line height).
01555         float y1 = window->DC.CursorPos.y;
01556         float y2 = window->DC.CursorPos.y + window->DC.CurrLineSize.y;
01557         const ImRect bb(ImVec2(window->DC.CursorPos.x, y1), ImVec2(window->DC.CursorPos.x + thickness, y2));
01558         ItemSize(ImVec2(thickness, 0.0f));
01559         if (!ItemAdd(bb, 0))
01560             return;
01561 
01562         // Draw
01563         window->DrawList->AddRectFilled(bb.Min, bb.Max, GetColorU32(ImGuiCol_Separator));
01564         if (g.LogEnabled)
01565             LogText(" |");
01566     }
01567     else if (flags & ImGuiSeparatorFlags_Horizontal)
01568     {
01569         // Horizontal Separator
01570         float x1 = window->DC.CursorPos.x;
01571         float x2 = window->WorkRect.Max.x;
01572 
01573         // Preserve legacy behavior inside Columns()
01574         // Before Tables API happened, we relied on Separator() to span all columns of a Columns() set.
01575         // We currently don't need to provide the same feature for tables because tables naturally have border features.
01576         ImGuiOldColumns* columns = (flags & ImGuiSeparatorFlags_SpanAllColumns) ? window->DC.CurrentColumns : NULL;
01577         if (columns)
01578         {
01579             x1 = window->Pos.x + window->DC.Indent.x; // Used to be Pos.x before 2023/10/03
01580             x2 = window->Pos.x + window->Size.x;
01581             PushColumnsBackground();
01582         }
01583 
01584         // We don't provide our width to the layout so that it doesn't get feed back into AutoFit
01585         // FIXME: This prevents ->CursorMaxPos based bounding box evaluation from working (e.g. TableEndCell)
01586         const float thickness_for_layout = (thickness == 1.0f) ? 0.0f : thickness; // FIXME: See 1.70/1.71 Separator() change: makes legacy 1-px separator not affect layout yet. Should change.
01587         const ImRect bb(ImVec2(x1, window->DC.CursorPos.y), ImVec2(x2, window->DC.CursorPos.y + thickness));
01588         ItemSize(ImVec2(0.0f, thickness_for_layout));
01589 
01590         if (ItemAdd(bb, 0))
01591         {
01592             // Draw
01593             window->DrawList->AddRectFilled(bb.Min, bb.Max, GetColorU32(ImGuiCol_Separator));
01594             if (g.LogEnabled)
01595                 LogRenderedText(&bb.Min, "--------------------------------\n");
01596 
01597         }
01598         if (columns)
01599         {
01600             PopColumnsBackground();
01601             columns->LineMinY = window->DC.CursorPos.y;
01602         }
01603     }
01604 }
