01624 void ImGui::SeparatorTextEx(ImGuiID id, const char* label, const char* label_end, float extra_w)
01625 {
01626     ImGuiContext& g = *GImGui;
01627     ImGuiWindow* window = g.CurrentWindow;
01628     ImGuiStyle& style = g.Style;
01629 
01630     const ImVec2 label_size = CalcTextSize(label, label_end, false);
01631     const ImVec2 pos = window->DC.CursorPos;
01632     const ImVec2 padding = style.SeparatorTextPadding;
01633 
01634     const float separator_thickness = style.SeparatorTextBorderSize;
01635     const ImVec2 min_size(label_size.x + extra_w + padding.x * 2.0f, ImMax(label_size.y + padding.y * 2.0f, separator_thickness));
01636     const ImRect bb(pos, ImVec2(window->WorkRect.Max.x, pos.y + min_size.y));
01637     const float text_baseline_y = ImTrunc((bb.GetHeight() - label_size.y) * style.SeparatorTextAlign.y + 0.99999f); //ImMax(padding.y, ImTrunc((style.SeparatorTextSize - label_size.y) * 0.5f));
01638     ItemSize(min_size, text_baseline_y);
01639     if (!ItemAdd(bb, id))
01640         return;
01641 
01642     const float sep1_x1 = pos.x;
01643     const float sep2_x2 = bb.Max.x;
01644     const float seps_y = ImTrunc((bb.Min.y + bb.Max.y) * 0.5f + 0.99999f);
01645 
01646     const float label_avail_w = ImMax(0.0f, sep2_x2 - sep1_x1 - padding.x * 2.0f);
01647     const ImVec2 label_pos(pos.x + padding.x + ImMax(0.0f, (label_avail_w - label_size.x - extra_w) * style.SeparatorTextAlign.x), pos.y + text_baseline_y); // FIXME-ALIGN
01648 
01649     // This allows using SameLine() to position something in the 'extra_w'
01650     window->DC.CursorPosPrevLine.x = label_pos.x + label_size.x;
01651 
01652     const ImU32 separator_col = GetColorU32(ImGuiCol_Separator);
01653     if (label_size.x > 0.0f)
01654     {
01655         const float sep1_x2 = label_pos.x - style.ItemSpacing.x;
01656         const float sep2_x1 = label_pos.x + label_size.x + extra_w + style.ItemSpacing.x;
01657         if (sep1_x2 > sep1_x1 && separator_thickness > 0.0f)
01658             window->DrawList->AddLine(ImVec2(sep1_x1, seps_y), ImVec2(sep1_x2, seps_y), separator_col, separator_thickness);
01659         if (sep2_x2 > sep2_x1 && separator_thickness > 0.0f)
01660             window->DrawList->AddLine(ImVec2(sep2_x1, seps_y), ImVec2(sep2_x2, seps_y), separator_col, separator_thickness);
01661         if (g.LogEnabled)
01662             LogSetNextTextDecoration("---", NULL);
01663         RenderTextEllipsis(window->DrawList, label_pos, ImVec2(bb.Max.x, bb.Max.y + style.ItemSpacing.y), bb.Max.x, bb.Max.x, label, label_end, &label_size);
01664     }
01665     else
01666     {
01667         if (g.LogEnabled)
01668             LogText("---");
01669         if (separator_thickness > 0.0f)
01670             window->DrawList->AddLine(ImVec2(sep1_x1, seps_y), ImVec2(sep2_x2, seps_y), separator_col, separator_thickness);
01671     }
01672 }
