01674 void ImGui::SeparatorText(const char* label)
01675 {
01676     ImGuiWindow* window = GetCurrentWindow();
01677     if (window->SkipItems)
01678         return;
01679 
01680     // The SeparatorText() vs SeparatorTextEx() distinction is designed to be considerate that we may want:
01681     // - allow separator-text to be draggable items (would require a stable ID + a noticeable highlight)
01682     // - this high-level entry point to allow formatting? (which in turns may require ID separate from formatted string)
01683     // - because of this we probably can't turn 'const char* label' into 'const char* fmt, ...'
01684     // Otherwise, we can decide that users wanting to drag this would layout a dedicated drag-item,
01685     // and then we can turn this into a format function.
01686     SeparatorTextEx(0, label, FindRenderedTextEnd(label), 0.0f);
