01689 // Using 'hover_visibility_delay' allows us to hide the highlight and mouse cursor for a short time, which can be convenient to reduce visual noise.
01690 bool ImGui::SplitterBehavior(const ImRect& bb, ImGuiID id, ImGuiAxis axis, float* size1, float* size2, float min_size1, float min_size2, float hover_extend, float hover_visibility_delay, ImU32 bg_col)
01691 {
01692     ImGuiContext& g = *GImGui;
01693     ImGuiWindow* window = g.CurrentWindow;
01694 
01695     if (!ItemAdd(bb, id, NULL, ImGuiItemFlags_NoNav))
01696         return false;
01697 
01698     // FIXME: AFAIK the only leftover reason for passing ImGuiButtonFlags_AllowOverlap here is
01699     // to allow caller of SplitterBehavior() to call SetItemAllowOverlap() after the item.
01700     // Nowadays we would instead want to use SetNextItemAllowOverlap() before the item.
01701     ImGuiButtonFlags button_flags = ImGuiButtonFlags_FlattenChildren;
01702 #ifndef IMGUI_DISABLE_OBSOLETE_FUNCTIONS
01703     button_flags |= ImGuiButtonFlags_AllowOverlap;
01704 #endif
01705 
01706     bool hovered, held;
01707     ImRect bb_interact = bb;
01708     bb_interact.Expand(axis == ImGuiAxis_Y ? ImVec2(0.0f, hover_extend) : ImVec2(hover_extend, 0.0f));
01709     ButtonBehavior(bb_interact, id, &hovered, &held, button_flags);
01710     if (hovered)
01711         g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_HoveredRect; // for IsItemHovered(), because bb_interact is larger than bb
01712 
01713     if (held || (hovered && g.HoveredIdPreviousFrame == id && g.HoveredIdTimer >= hover_visibility_delay))
01714         SetMouseCursor(axis == ImGuiAxis_Y ? ImGuiMouseCursor_ResizeNS : ImGuiMouseCursor_ResizeEW);
01715 
01716     ImRect bb_render = bb;
01717     if (held)
01718     {
01719         float mouse_delta = (g.IO.MousePos - g.ActiveIdClickOffset - bb_interact.Min)[axis];
01720 
01721         // Minimum pane size
01722         float size_1_maximum_delta = ImMax(0.0f, *size1 - min_size1);
01723         float size_2_maximum_delta = ImMax(0.0f, *size2 - min_size2);
01724         if (mouse_delta < -size_1_maximum_delta)
01725             mouse_delta = -size_1_maximum_delta;
01726         if (mouse_delta > size_2_maximum_delta)
01727             mouse_delta = size_2_maximum_delta;
01728 
01729         // Apply resize
01730         if (mouse_delta != 0.0f)
01731         {
01732             *size1 = ImMax(*size1 + mouse_delta, min_size1);
01733             *size2 = ImMax(*size2 - mouse_delta, min_size2);
01734             bb_render.Translate((axis == ImGuiAxis_X) ? ImVec2(mouse_delta, 0.0f) : ImVec2(0.0f, mouse_delta));
01735             MarkItemEdited(id);
01736         }
01737     }
01738 
01739     // Render at new position
01740     if (bg_col & IM_COL32_A_MASK)
01741         window->DrawList->AddRectFilled(bb_render.Min, bb_render.Max, bg_col, 0.0f);
01742     const ImU32 col = GetColorU32(held ? ImGuiCol_SeparatorActive : (hovered && g.HoveredIdTimer >= hover_visibility_delay) ? ImGuiCol_SeparatorHovered : ImGuiCol_Separator);
01743     window->DrawList->AddRectFilled(bb_render.Min, bb_render.Max, col, 0.0f);
01744 
01745     return held;
01746 }
