01748 static int IMGUI_CDECL ShrinkWidthItemComparer(const void* lhs, const void* rhs)
01749 {
01750     const ImGuiShrinkWidthItem* a = (const ImGuiShrinkWidthItem*)lhs;
01751     const ImGuiShrinkWidthItem* b = (const ImGuiShrinkWidthItem*)rhs;
01752     if (int d = (int)(b->Width - a->Width))
01753         return d;
01754     return (b->Index - a->Index);
01755 }
01756 
01757 // Shrink excess width from a set of item, by removing width from the larger items first.
01758 // Set items Width to -1.0f to disable shrinking this item.
01759 void ImGui::ShrinkWidths(ImGuiShrinkWidthItem* items, int count, float width_excess)
01760 {
01761     if (count == 1)
01762     {
01763         if (items[0].Width >= 0.0f)
01764             items[0].Width = ImMax(items[0].Width - width_excess, 1.0f);
01765         return;
01766     }
01767     ImQsort(items, (size_t)count, sizeof(ImGuiShrinkWidthItem), ShrinkWidthItemComparer);
01768     int count_same_width = 1;
01769     while (width_excess > 0.0f && count_same_width < count)
01770     {
01771         while (count_same_width < count && items[0].Width <= items[count_same_width].Width)
01772             count_same_width++;
01773         float max_width_to_remove_per_item = (count_same_width < count && items[count_same_width].Width >= 0.0f) ? (items[0].Width - items[count_same_width].Width) : (items[0].Width - 1.0f);
01774         if (max_width_to_remove_per_item <= 0.0f)
01775             break;
01776         float width_to_remove_per_item = ImMin(width_excess / count_same_width, max_width_to_remove_per_item);
01777         for (int item_n = 0; item_n < count_same_width; item_n++)
01778             items[item_n].Width -= width_to_remove_per_item;
01779         width_excess -= width_to_remove_per_item * count_same_width;
01780     }
01781 
01782     // Round width and redistribute remainder
01783     // Ensure that e.g. the right-most tab of a shrunk tab-bar always reaches exactly at the same distance from the right-most edge of the tab bar separator.
01784     width_excess = 0.0f;
01785     for (int n = 0; n < count; n++)
01786     {
01787         float width_rounded = ImTrunc(items[n].Width);
01788         width_excess += items[n].Width - width_rounded;
01789         items[n].Width = width_rounded;
01790     }
01791     while (width_excess > 0.0f)
01792         for (int n = 0; n < count && width_excess > 0.0f; n++)
01793         {
01794             float width_to_add = ImMin(items[n].InitialWidth - items[n].Width, 1.0f);
01795             items[n].Width += width_to_add;
01796             width_excess -= width_to_add;
01797         }
01798 }
