01820 bool ImGui::BeginCombo(const char* label, const char* preview_value, ImGuiComboFlags flags)
01821 {
01822     ImGuiContext& g = *GImGui;
01823     ImGuiWindow* window = GetCurrentWindow();
01824 
01825     ImGuiNextWindowDataFlags backup_next_window_data_flags = g.NextWindowData.Flags;
01826     g.NextWindowData.ClearFlags(); // We behave like Begin() and need to consume those values
01827     if (window->SkipItems)
01828         return false;
01829 
01830     const ImGuiStyle& style = g.Style;
01831     const ImGuiID id = window->GetID(label);
01832     IM_ASSERT((flags & (ImGuiComboFlags_NoArrowButton | ImGuiComboFlags_NoPreview)) != (ImGuiComboFlags_NoArrowButton | ImGuiComboFlags_NoPreview)); // Can't use both flags together
01833     if (flags & ImGuiComboFlags_WidthFitPreview)
01834         IM_ASSERT((flags & (ImGuiComboFlags_NoPreview | (ImGuiComboFlags)ImGuiComboFlags_CustomPreview)) == 0);
01835 
01836     const float arrow_size = (flags & ImGuiComboFlags_NoArrowButton) ? 0.0f : GetFrameHeight();
01837     const ImVec2 label_size = CalcTextSize(label, NULL, true);
01838     const float preview_width = ((flags & ImGuiComboFlags_WidthFitPreview) && (preview_value != NULL)) ? CalcTextSize(preview_value, NULL, true).x : 0.0f;
01839     const float w = (flags & ImGuiComboFlags_NoPreview) ? arrow_size : ((flags & ImGuiComboFlags_WidthFitPreview) ? (arrow_size + preview_width + style.FramePadding.x * 2.0f) : CalcItemWidth());
01840     const ImRect bb(window->DC.CursorPos, window->DC.CursorPos + ImVec2(w, label_size.y + style.FramePadding.y * 2.0f));
01841     const ImRect total_bb(bb.Min, bb.Max + ImVec2(label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0.0f));
01842     ItemSize(total_bb, style.FramePadding.y);
01843     if (!ItemAdd(total_bb, id, &bb))
01844         return false;
01845 
01846     // Open on click
01847     bool hovered, held;
01848     bool pressed = ButtonBehavior(bb, id, &hovered, &held);
01849     const ImGuiID popup_id = ImHashStr("##ComboPopup", 0, id);
01850     bool popup_open = IsPopupOpen(popup_id, ImGuiPopupFlags_None);
01851     if (pressed && !popup_open)
01852     {
01853         OpenPopupEx(popup_id, ImGuiPopupFlags_None);
01854         popup_open = true;
01855     }
01856 
01857     // Render shape
01858     const ImU32 frame_col = GetColorU32(hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg);
01859     const float value_x2 = ImMax(bb.Min.x, bb.Max.x - arrow_size);
01860     RenderNavHighlight(bb, id);
01861     if (!(flags & ImGuiComboFlags_NoPreview))
01862         window->DrawList->AddRectFilled(bb.Min, ImVec2(value_x2, bb.Max.y), frame_col, style.FrameRounding, (flags & ImGuiComboFlags_NoArrowButton) ? ImDrawFlags_RoundCornersAll : ImDrawFlags_RoundCornersLeft);
01863     if (!(flags & ImGuiComboFlags_NoArrowButton))
01864     {
01865         ImU32 bg_col = GetColorU32((popup_open || hovered) ? ImGuiCol_ButtonHovered : ImGuiCol_Button);
01866         ImU32 text_col = GetColorU32(ImGuiCol_Text);
01867         window->DrawList->AddRectFilled(ImVec2(value_x2, bb.Min.y), bb.Max, bg_col, style.FrameRounding, (w <= arrow_size) ? ImDrawFlags_RoundCornersAll : ImDrawFlags_RoundCornersRight);
01868         if (value_x2 + arrow_size - style.FramePadding.x <= bb.Max.x)
01869             RenderArrow(window->DrawList, ImVec2(value_x2 + style.FramePadding.y, bb.Min.y + style.FramePadding.y), text_col, ImGuiDir_Down, 1.0f);
01870     }
01871     RenderFrameBorder(bb.Min, bb.Max, style.FrameRounding);
01872 
01873     // Custom preview
01874     if (flags & ImGuiComboFlags_CustomPreview)
01875     {
01876         g.ComboPreviewData.PreviewRect = ImRect(bb.Min.x, bb.Min.y, value_x2, bb.Max.y);
01877         IM_ASSERT(preview_value == NULL || preview_value[0] == 0);
01878         preview_value = NULL;
01879     }
01880 
01881     // Render preview and label
01882     if (preview_value != NULL && !(flags & ImGuiComboFlags_NoPreview))
01883     {
01884         if (g.LogEnabled)
01885             LogSetNextTextDecoration("{", "}");
01886         RenderTextClipped(bb.Min + style.FramePadding, ImVec2(value_x2, bb.Max.y), preview_value, NULL, NULL);
01887     }
01888     if (label_size.x > 0)
01889         RenderText(ImVec2(bb.Max.x + style.ItemInnerSpacing.x, bb.Min.y + style.FramePadding.y), label);
01890 
01891     if (!popup_open)
01892         return false;
01893 
01894     g.NextWindowData.Flags = backup_next_window_data_flags;
01895     return BeginComboPopup(popup_id, bb, flags);
01896 }
01897 
01898 bool ImGui::BeginComboPopup(ImGuiID popup_id, const ImRect& bb, ImGuiComboFlags flags)
01899 {
01900     ImGuiContext& g = *GImGui;
01901     if (!IsPopupOpen(popup_id, ImGuiPopupFlags_None))
01902     {
01903         g.NextWindowData.ClearFlags();
01904         return false;
01905     }
01906 
01907     // Set popup size
01908     float w = bb.GetWidth();
01909     if (g.NextWindowData.Flags & ImGuiNextWindowDataFlags_HasSizeConstraint)
01910     {
01911         g.NextWindowData.SizeConstraintRect.Min.x = ImMax(g.NextWindowData.SizeConstraintRect.Min.x, w);
01912     }
01913     else
01914     {
01915         if ((flags & ImGuiComboFlags_HeightMask_) == 0)
01916             flags |= ImGuiComboFlags_HeightRegular;
01917         IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiComboFlags_HeightMask_)); // Only one
01918         int popup_max_height_in_items = -1;
01919         if (flags & ImGuiComboFlags_HeightRegular)     popup_max_height_in_items = 8;
01920         else if (flags & ImGuiComboFlags_HeightSmall)  popup_max_height_in_items = 4;
01921         else if (flags & ImGuiComboFlags_HeightLarge)  popup_max_height_in_items = 20;
01922         ImVec2 constraint_min(0.0f, 0.0f), constraint_max(FLT_MAX, FLT_MAX);
01923         if ((g.NextWindowData.Flags & ImGuiNextWindowDataFlags_HasSize) == 0 || g.NextWindowData.SizeVal.x <= 0.0f) // Don't apply constraints if user specified a size
01924             constraint_min.x = w;
01925         if ((g.NextWindowData.Flags & ImGuiNextWindowDataFlags_HasSize) == 0 || g.NextWindowData.SizeVal.y <= 0.0f)
01926             constraint_max.y = CalcMaxPopupHeightFromItemCount(popup_max_height_in_items);
01927         SetNextWindowSizeConstraints(constraint_min, constraint_max);
01928     }
01929 
01930     // This is essentially a specialized version of BeginPopupEx()
01931     char name[16];
01932     ImFormatString(name, IM_ARRAYSIZE(name), "##Combo_%02d", g.BeginComboDepth); // Recycle windows based on depth
01933 
01934     // Set position given a custom constraint (peak into expected window size so we can position it)
01935     // FIXME: This might be easier to express with an hypothetical SetNextWindowPosConstraints() function?
01936     // FIXME: This might be moved to Begin() or at least around the same spot where Tooltips and other Popups are calling FindBestWindowPosForPopupEx()?
01937     if (ImGuiWindow* popup_window = FindWindowByName(name))
01938         if (popup_window->WasActive)
01939         {
01940             // Always override 'AutoPosLastDirection' to not leave a chance for a past value to affect us.
01941             ImVec2 size_expected = CalcWindowNextAutoFitSize(popup_window);
01942             popup_window->AutoPosLastDirection = (flags & ImGuiComboFlags_PopupAlignLeft) ? ImGuiDir_Left : ImGuiDir_Down; // Left = "Below, Toward Left", Down = "Below, Toward Right (default)"
01943             ImRect r_outer = GetPopupAllowedExtentRect(popup_window);
01944             ImVec2 pos = FindBestWindowPosForPopupEx(bb.GetBL(), size_expected, &popup_window->AutoPosLastDirection, r_outer, bb, ImGuiPopupPositionPolicy_ComboBox);
01945             SetNextWindowPos(pos);
01946         }
01947 
01948     // We don't use BeginPopupEx() solely because we have a custom name string, which we could make an argument to BeginPopupEx()
01949     ImGuiWindowFlags window_flags = ImGuiWindowFlags_AlwaysAutoResize | ImGuiWindowFlags_Popup | ImGuiWindowFlags_NoTitleBar | ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoSavedSettings | ImGuiWindowFlags_NoMove;
01950     PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(g.Style.FramePadding.x, g.Style.WindowPadding.y)); // Horizontally align ourselves with the framed text
01951     bool ret = Begin(name, NULL, window_flags);
01952     PopStyleVar();
01953     if (!ret)
01954     {
01955         EndPopup();
01956         IM_ASSERT(0);   // This should never happen as we tested for IsPopupOpen() above
01957         return false;
01958     }
01959     g.BeginComboDepth++;
01960     return true;
01961 }
01962 
01963 void ImGui::EndCombo()
01964 {
01965     ImGuiContext& g = *GImGui;
01966     EndPopup();
01967     g.BeginComboDepth--;
01968 }
