01999 void ImGui::EndComboPreview()
02000 {
02001     ImGuiContext& g = *GImGui;
02002     ImGuiWindow* window = g.CurrentWindow;
02003     ImGuiComboPreviewData* preview_data = &g.ComboPreviewData;
