02013     PopClipRect();
02014     window->DC.CursorPos = preview_data->BackupCursorPos;
02015     window->DC.CursorMaxPos = ImMax(window->DC.CursorMaxPos, preview_data->BackupCursorMaxPos);
02016     window->DC.CursorPosPrevLine = preview_data->BackupCursorPosPrevLine;
