02023 // Getter for the old Combo() API: const char*[]
02024 static const char* Items_ArrayGetter(void* data, int idx)
02025 {
02026     const char* const* items = (const char* const*)data;
02027     return items[idx];
02028 }
02029 
02030 // Getter for the old Combo() API: "item1\0item2\0item3\0"
02031 static const char* Items_SingleStringGetter(void* data, int idx)
02032 {
02033     const char* items_separated_by_zeros = (const char*)data;
02034     int items_count = 0;
02035     const char* p = items_separated_by_zeros;
02036     while (*p)
02037     {
02038         if (idx == items_count)
02039             break;
02040         p += strlen(p) + 1;
02041         items_count++;
02042     }
02043     return *p ? p : NULL;
02044 }
02045 
02046 // Old API, prefer using BeginCombo() nowadays if you can.
02047 bool ImGui::Combo(const char* label, int* current_item, const char* (*getter)(void* user_data, int idx), void* user_data, int items_count, int popup_max_height_in_items)
02048 {
02049     ImGuiContext& g = *GImGui;
02050 
02051     // Call the getter to obtain the preview string which is a parameter to BeginCombo()
02052     const char* preview_value = NULL;
02053     if (*current_item >= 0 && *current_item < items_count)
02054         preview_value = getter(user_data, *current_item);
02055 
02056     // The old Combo() API exposed "popup_max_height_in_items". The new more general BeginCombo() API doesn't have/need it, but we emulate it here.
02057     if (popup_max_height_in_items != -1 && !(g.NextWindowData.Flags & ImGuiNextWindowDataFlags_HasSizeConstraint))
02058         SetNextWindowSizeConstraints(ImVec2(0, 0), ImVec2(FLT_MAX, CalcMaxPopupHeightFromItemCount(popup_max_height_in_items)));
02059 
02060     if (!BeginCombo(label, preview_value, ImGuiComboFlags_None))
02061         return false;
02062 
02063     // Display items
02064     bool value_changed = false;
02065     ImGuiListClipper clipper;
02066     clipper.Begin(items_count);
02067     clipper.IncludeItemByIndex(*current_item);
02068     while (clipper.Step())
02069         for (int i = clipper.DisplayStart; i < clipper.DisplayEnd; i++)
02070         {
02071             const char* item_text = getter(user_data, i);
02072             if (item_text == NULL)
02073                 item_text = "*Unknown item*";
02074 
02075             PushID(i);
02076             const bool item_selected = (i == *current_item);
02077             if (Selectable(item_text, item_selected) && *current_item != i)
02078             {
02079                 value_changed = true;
02080                 *current_item = i;
02081             }
02082             if (item_selected)
02083                 SetItemDefaultFocus();
02084             PopID();
02085         }
02086 
02087     EndCombo();
02088     if (value_changed)
02089         MarkItemEdited(g.LastItemData.ID);
02090 
02091     return value_changed;
02092 }
02093 
02094 // Combo box helper allowing to pass an array of strings.
02095 bool ImGui::Combo(const char* label, int* current_item, const char* const items[], int items_count, int height_in_items)
02096 {
02097     const bool value_changed = Combo(label, current_item, Items_ArrayGetter, (void*)items, items_count, height_in_items);
02098     return value_changed;
02099 }
