02101 // Combo box helper allowing to pass all items in a single string literal holding multiple zero-terminated items "item1\0item2\0"
02102 bool ImGui::Combo(const char* label, int* current_item, const char* items_separated_by_zeros, int height_in_items)
02103 {
02104     int items_count = 0;
02105     const char* p = items_separated_by_zeros;       // FIXME-OPT: Avoid computing this, or at least only when combo is open
02106     while (*p)
02107     {
02108         p += strlen(p) + 1;
02109         items_count++;
02110     }
02111     bool value_changed = Combo(label, current_item, Items_SingleStringGetter, (void*)items_separated_by_zeros, items_count, height_in_items);
02112     return value_changed;
02113 }
