02179 int ImGui::DataTypeFormatString(char* buf, int buf_size, ImGuiDataType data_type, const void* p_data, const char* format)
02180 {
02181     // Signedness doesn't matter when pushing integer arguments
02182     if (data_type == ImGuiDataType_S32 || data_type == ImGuiDataType_U32)
02183         return ImFormatString(buf, buf_size, format, *(const ImU32*)p_data);
02184     if (data_type == ImGuiDataType_S64 || data_type == ImGuiDataType_U64)
02185         return ImFormatString(buf, buf_size, format, *(const ImU64*)p_data);
02186     if (data_type == ImGuiDataType_Float)
02187         return ImFormatString(buf, buf_size, format, *(const float*)p_data);
02188     if (data_type == ImGuiDataType_Double)
02189         return ImFormatString(buf, buf_size, format, *(const double*)p_data);
02190     if (data_type == ImGuiDataType_S8)
02191         return ImFormatString(buf, buf_size, format, *(const ImS8*)p_data);
02192     if (data_type == ImGuiDataType_U8)
02193         return ImFormatString(buf, buf_size, format, *(const ImU8*)p_data);
02194     if (data_type == ImGuiDataType_S16)
02195         return ImFormatString(buf, buf_size, format, *(const ImS16*)p_data);
02196     if (data_type == ImGuiDataType_U16)
02197         return ImFormatString(buf, buf_size, format, *(const ImU16*)p_data);
02198     IM_ASSERT(0);
02199     return 0;
02200 }
