02252 // User can input math operators (e.g. +100) to edit a numerical values.
02253 // NB: This is _not_ a full expression evaluator. We should probably add one and replace this dumb mess..
02254 bool ImGui::DataTypeApplyFromText(const char* buf, ImGuiDataType data_type, void* p_data, const char* format, void* p_data_when_empty)
02255 {
02256     // Copy the value in an opaque buffer so we can compare at the end of the function if it changed at all.
02257     const ImGuiDataTypeInfo* type_info = DataTypeGetInfo(data_type);
02258     ImGuiDataTypeStorage data_backup;
02259     memcpy(&data_backup, p_data, type_info->Size);
02260 
02261     while (ImCharIsBlankA(*buf))
02262         buf++;
02263     if (!buf[0])
02264     {
02265         if (p_data_when_empty != NULL)
02266         {
02267             memcpy(p_data, p_data_when_empty, type_info->Size);
02268             return memcmp(&data_backup, p_data, type_info->Size) != 0;
02269         }
02270         return false;
02271     }
02272 
02273     // Sanitize format
02274     // - For float/double we have to ignore format with precision (e.g. "%.2f") because sscanf doesn't take them in, so force them into %f and %lf
02275     // - In theory could treat empty format as using default, but this would only cover rare/bizarre case of using InputScalar() + integer + format string without %.
02276     char format_sanitized[32];
02277     if (data_type == ImGuiDataType_Float || data_type == ImGuiDataType_Double)
02278         format = type_info->ScanFmt;
02279     else
02280         format = ImParseFormatSanitizeForScanning(format, format_sanitized, IM_ARRAYSIZE(format_sanitized));
02281 
02282     // Small types need a 32-bit buffer to receive the result from scanf()
02283     int v32 = 0;
02284     if (sscanf(buf, format, type_info->Size >= 4 ? p_data : &v32) < 1)
02285         return false;
02286     if (type_info->Size < 4)
02287     {
02288         if (data_type == ImGuiDataType_S8)
02289             *(ImS8*)p_data = (ImS8)ImClamp(v32, (int)IM_S8_MIN, (int)IM_S8_MAX);
02290         else if (data_type == ImGuiDataType_U8)
02291             *(ImU8*)p_data = (ImU8)ImClamp(v32, (int)IM_U8_MIN, (int)IM_U8_MAX);
02292         else if (data_type == ImGuiDataType_S16)
02293             *(ImS16*)p_data = (ImS16)ImClamp(v32, (int)IM_S16_MIN, (int)IM_S16_MAX);
02294         else if (data_type == ImGuiDataType_U16)
02295             *(ImU16*)p_data = (ImU16)ImClamp(v32, (int)IM_U16_MIN, (int)IM_U16_MAX);
02296         else
02297             IM_ASSERT(0);
02298     }
02299 
02300     return memcmp(&data_backup, p_data, type_info->Size) != 0;
02301 }
02302 
02303 template<typename T>
02304 static int DataTypeCompareT(const T* lhs, const T* rhs)
02305 {
02306     if (*lhs < *rhs) return -1;
02307     if (*lhs > *rhs) return +1;
02308     return 0;
02309 }
02310 
02311 int ImGui::DataTypeCompare(ImGuiDataType data_type, const void* arg_1, const void* arg_2)
02312 {
02313     switch (data_type)
02314     {
02315     case ImGuiDataType_S8:     return DataTypeCompareT<ImS8  >((const ImS8*  )arg_1, (const ImS8*  )arg_2);
02316     case ImGuiDataType_U8:     return DataTypeCompareT<ImU8  >((const ImU8*  )arg_1, (const ImU8*  )arg_2);
02317     case ImGuiDataType_S16:    return DataTypeCompareT<ImS16 >((const ImS16* )arg_1, (const ImS16* )arg_2);
02318     case ImGuiDataType_U16:    return DataTypeCompareT<ImU16 >((const ImU16* )arg_1, (const ImU16* )arg_2);
02319     case ImGuiDataType_S32:    return DataTypeCompareT<ImS32 >((const ImS32* )arg_1, (const ImS32* )arg_2);
02320     case ImGuiDataType_U32:    return DataTypeCompareT<ImU32 >((const ImU32* )arg_1, (const ImU32* )arg_2);
02321     case ImGuiDataType_S64:    return DataTypeCompareT<ImS64 >((const ImS64* )arg_1, (const ImS64* )arg_2);
02322     case ImGuiDataType_U64:    return DataTypeCompareT<ImU64 >((const ImU64* )arg_1, (const ImU64* )arg_2);
02323     case ImGuiDataType_Float:  return DataTypeCompareT<float >((const float* )arg_1, (const float* )arg_2);
02324     case ImGuiDataType_Double: return DataTypeCompareT<double>((const double*)arg_1, (const double*)arg_2);
02325     case ImGuiDataType_COUNT:  break;
02326     }
02327     IM_ASSERT(0);
02328     return 0;
02329 }
02330 
02331 template<typename T>
02332 static bool DataTypeClampT(T* v, const T* v_min, const T* v_max)
02333 {
02334     // Clamp, both sides are optional, return true if modified
02335     if (v_min && *v < *v_min) { *v = *v_min; return true; }
02336     if (v_max && *v > *v_max) { *v = *v_max; return true; }
02337     return false;
02338 }
02339 
02340 bool ImGui::DataTypeClamp(ImGuiDataType data_type, void* p_data, const void* p_min, const void* p_max)
02341 {
02342     switch (data_type)
02343     {
02344     case ImGuiDataType_S8:     return DataTypeClampT<ImS8  >((ImS8*  )p_data, (const ImS8*  )p_min, (const ImS8*  )p_max);
02345     case ImGuiDataType_U8:     return DataTypeClampT<ImU8  >((ImU8*  )p_data, (const ImU8*  )p_min, (const ImU8*  )p_max);
02346     case ImGuiDataType_S16:    return DataTypeClampT<ImS16 >((ImS16* )p_data, (const ImS16* )p_min, (const ImS16* )p_max);
02347     case ImGuiDataType_U16:    return DataTypeClampT<ImU16 >((ImU16* )p_data, (const ImU16* )p_min, (const ImU16* )p_max);
02348     case ImGuiDataType_S32:    return DataTypeClampT<ImS32 >((ImS32* )p_data, (const ImS32* )p_min, (const ImS32* )p_max);
02349     case ImGuiDataType_U32:    return DataTypeClampT<ImU32 >((ImU32* )p_data, (const ImU32* )p_min, (const ImU32* )p_max);
02350     case ImGuiDataType_S64:    return DataTypeClampT<ImS64 >((ImS64* )p_data, (const ImS64* )p_min, (const ImS64* )p_max);
02351     case ImGuiDataType_U64:    return DataTypeClampT<ImU64 >((ImU64* )p_data, (const ImU64* )p_min, (const ImU64* )p_max);
02352     case ImGuiDataType_Float:  return DataTypeClampT<float >((float* )p_data, (const float* )p_min, (const float* )p_max);
02353     case ImGuiDataType_Double: return DataTypeClampT<double>((double*)p_data, (const double*)p_min, (const double*)p_max);
02354     case ImGuiDataType_COUNT:  break;
02355     }
02356     IM_ASSERT(0);
02357     return false;
02358 }
02359 
02360 static float GetMinimumStepAtDecimalPrecision(int decimal_precision)
02361 {
02362     static const float min_steps[10] = { 1.0f, 0.1f, 0.01f, 0.001f, 0.0001f, 0.00001f, 0.000001f, 0.0000001f, 0.00000001f, 0.000000001f };
02363     if (decimal_precision < 0)
02364         return FLT_MIN;
02365     return (decimal_precision < IM_ARRAYSIZE(min_steps)) ? min_steps[decimal_precision] : ImPow(10.0f, (float)-decimal_precision);
02366 }
02367 
02368 template<typename TYPE>
02369 TYPE ImGui::RoundScalarWithFormatT(const char* format, ImGuiDataType data_type, TYPE v)
02370 {
02371     IM_UNUSED(data_type);
02372     IM_ASSERT(data_type == ImGuiDataType_Float || data_type == ImGuiDataType_Double);
02373     const char* fmt_start = ImParseFormatFindStart(format);
02374     if (fmt_start[0] != '%' || fmt_start[1] == '%') // Don't apply if the value is not visible in the format string
02375         return v;
02376 
02377     // Sanitize format
02378     char fmt_sanitized[32];
02379     ImParseFormatSanitizeForPrinting(fmt_start, fmt_sanitized, IM_ARRAYSIZE(fmt_sanitized));
02380     fmt_start = fmt_sanitized;
02381 
02382     // Format value with our rounding, and read back
02383     char v_str[64];
02384     ImFormatString(v_str, IM_ARRAYSIZE(v_str), fmt_start, v);
02385     const char* p = v_str;
02386     while (*p == ' ')
02387         p++;
02388     v = (TYPE)ImAtof(p);
02389 
02390     return v;
02391 }
02392 
02393 //-------------------------------------------------------------------------
02394 // [SECTION] Widgets: DragScalar, DragFloat, DragInt, etc.
02395 //-------------------------------------------------------------------------
02396 // - DragBehaviorT<>() [Internal]
02397 // - DragBehavior() [Internal]
02398 // - DragScalar()
02399 // - DragScalarN()
02400 // - DragFloat()
02401 // - DragFloat2()
02402 // - DragFloat3()
02403 // - DragFloat4()
02404 // - DragFloatRange2()
02405 // - DragInt()
02406 // - DragInt2()
02407 // - DragInt3()
02408 // - DragInt4()
02409 // - DragIntRange2()
02410 //-------------------------------------------------------------------------
02411 
02412 // This is called by DragBehavior() when the widget is active (held by mouse or being manipulated with Nav controls)
02413 template<typename TYPE, typename SIGNEDTYPE, typename FLOATTYPE>
02414 bool ImGui::DragBehaviorT(ImGuiDataType data_type, TYPE* v, float v_speed, const TYPE v_min, const TYPE v_max, const char* format, ImGuiSliderFlags flags)
02415 {
02416     ImGuiContext& g = *GImGui;
02417     const ImGuiAxis axis = (flags & ImGuiSliderFlags_Vertical) ? ImGuiAxis_Y : ImGuiAxis_X;
02418     const bool is_bounded = (v_min < v_max);
02419     const bool is_wrapped = is_bounded && (flags & ImGuiSliderFlags_WrapAround);
02420     const bool is_logarithmic = (flags & ImGuiSliderFlags_Logarithmic) != 0;
02421     const bool is_floating_point = (data_type == ImGuiDataType_Float) || (data_type == ImGuiDataType_Double);
02422 
02423     // Default tweak speed
02424     if (v_speed == 0.0f && is_bounded && (v_max - v_min < FLT_MAX))
02425         v_speed = (float)((v_max - v_min) * g.DragSpeedDefaultRatio);
02426 
02427     // Inputs accumulates into g.DragCurrentAccum, which is flushed into the current value as soon as it makes a difference with our precision settings
02428     float adjust_delta = 0.0f;
02429     if (g.ActiveIdSource == ImGuiInputSource_Mouse && IsMousePosValid() && IsMouseDragPastThreshold(0, g.IO.MouseDragThreshold * DRAG_MOUSE_THRESHOLD_FACTOR))
02430     {
02431         adjust_delta = g.IO.MouseDelta[axis];
02432         if (g.IO.KeyAlt)
02433             adjust_delta *= 1.0f / 100.0f;
02434         if (g.IO.KeyShift)
02435             adjust_delta *= 10.0f;
02436     }
02437     else if (g.ActiveIdSource == ImGuiInputSource_Keyboard || g.ActiveIdSource == ImGuiInputSource_Gamepad)
02438     {
02439         const int decimal_precision = is_floating_point ? ImParseFormatPrecision(format, 3) : 0;
02440         const bool tweak_slow = IsKeyDown((g.NavInputSource == ImGuiInputSource_Gamepad) ? ImGuiKey_NavGamepadTweakSlow : ImGuiKey_NavKeyboardTweakSlow);
02441         const bool tweak_fast = IsKeyDown((g.NavInputSource == ImGuiInputSource_Gamepad) ? ImGuiKey_NavGamepadTweakFast : ImGuiKey_NavKeyboardTweakFast);
02442         const float tweak_factor = tweak_slow ? 1.0f / 10.0f : tweak_fast ? 10.0f : 1.0f;
02443         adjust_delta = GetNavTweakPressedAmount(axis) * tweak_factor;
02444         v_speed = ImMax(v_speed, GetMinimumStepAtDecimalPrecision(decimal_precision));
02445     }
02446     adjust_delta *= v_speed;
02447 
02448     // For vertical drag we currently assume that Up=higher value (like we do with vertical sliders). This may become a parameter.
02449     if (axis == ImGuiAxis_Y)
02450         adjust_delta = -adjust_delta;
02451 
02452     // For logarithmic use our range is effectively 0..1 so scale the delta into that range
02453     if (is_logarithmic && (v_max - v_min < FLT_MAX) && ((v_max - v_min) > 0.000001f)) // Epsilon to avoid /0
02454         adjust_delta /= (float)(v_max - v_min);
02455 
02456     // Clear current value on activation
02457     // Avoid altering values and clamping when we are _already_ past the limits and heading in the same direction, so e.g. if range is 0..255, current value is 300 and we are pushing to the right side, keep the 300.
02458     const bool is_just_activated = g.ActiveIdIsJustActivated;
02459     const bool is_already_past_limits_and_pushing_outward = is_bounded && !is_wrapped && ((*v >= v_max && adjust_delta > 0.0f) || (*v <= v_min && adjust_delta < 0.0f));
02460     if (is_just_activated || is_already_past_limits_and_pushing_outward)
02461     {
02462         g.DragCurrentAccum = 0.0f;
02463         g.DragCurrentAccumDirty = false;
02464     }
02465     else if (adjust_delta != 0.0f)
02466     {
02467         g.DragCurrentAccum += adjust_delta;
02468         g.DragCurrentAccumDirty = true;
02469     }
02470 
02471     if (!g.DragCurrentAccumDirty)
02472         return false;
02473 
02474     TYPE v_cur = *v;
02475     FLOATTYPE v_old_ref_for_accum_remainder = (FLOATTYPE)0.0f;
02476 
02477     float logarithmic_zero_epsilon = 0.0f; // Only valid when is_logarithmic is true
02478     const float zero_deadzone_halfsize = 0.0f; // Drag widgets have no deadzone (as it doesn't make sense)
02479     if (is_logarithmic)
02480     {
02481         // When using logarithmic sliders, we need to clamp to avoid hitting zero, but our choice of clamp value greatly affects slider precision. We attempt to use the specified precision to estimate a good lower bound.
02482         const int decimal_precision = is_floating_point ? ImParseFormatPrecision(format, 3) : 1;
02483         logarithmic_zero_epsilon = ImPow(0.1f, (float)decimal_precision);
02484 
02485         // Convert to parametric space, apply delta, convert back
02486         float v_old_parametric = ScaleRatioFromValueT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, v_cur, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
02487         float v_new_parametric = v_old_parametric + g.DragCurrentAccum;
02488         v_cur = ScaleValueFromRatioT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, v_new_parametric, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
02489         v_old_ref_for_accum_remainder = v_old_parametric;
02490     }
02491     else
02492     {
02493         v_cur += (SIGNEDTYPE)g.DragCurrentAccum;
02494     }
02495 
02496     // Round to user desired precision based on format string
02497     if (is_floating_point && !(flags & ImGuiSliderFlags_NoRoundToFormat))
02498         v_cur = RoundScalarWithFormatT<TYPE>(format, data_type, v_cur);
02499 
02500     // Preserve remainder after rounding has been applied. This also allow slow tweaking of values.
02501     g.DragCurrentAccumDirty = false;
02502     if (is_logarithmic)
02503     {
02504         // Convert to parametric space, apply delta, convert back
02505         float v_new_parametric = ScaleRatioFromValueT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, v_cur, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
02506         g.DragCurrentAccum -= (float)(v_new_parametric - v_old_ref_for_accum_remainder);
02507     }
02508     else
02509     {
02510         g.DragCurrentAccum -= (float)((SIGNEDTYPE)v_cur - (SIGNEDTYPE)*v);
02511     }
02512 
02513     // Lose zero sign for float/double
02514     if (v_cur == (TYPE)-0)
02515         v_cur = (TYPE)0;
02516 
02517     if (*v != v_cur && is_bounded)
02518     {
02519         if (is_wrapped)
02520         {
02521             // Wrap values
02522             if (v_cur < v_min)
02523                 v_cur += v_max - v_min + (is_floating_point ? 0 : 1);
02524             if (v_cur > v_max)
02525                 v_cur -= v_max - v_min + (is_floating_point ? 0 : 1);
02526         }
02527         else
02528         {
02529             // Clamp values + handle overflow/wrap-around for integer types.
02530             if (v_cur < v_min || (v_cur > *v && adjust_delta < 0.0f && !is_floating_point))
02531                 v_cur = v_min;
02532             if (v_cur > v_max || (v_cur < *v && adjust_delta > 0.0f && !is_floating_point))
02533                 v_cur = v_max;
02534         }
02535     }
02536 
02537     // Apply result
02538     if (*v == v_cur)
02539         return false;
02540     *v = v_cur;
02541     return true;
02542 }
02543 
02544 bool ImGui::DragBehavior(ImGuiID id, ImGuiDataType data_type, void* p_v, float v_speed, const void* p_min, const void* p_max, const char* format, ImGuiSliderFlags flags)
02545 {
02546     // Read imgui.cpp "API BREAKING CHANGES" section for 1.78 if you hit this assert.
02547     IM_ASSERT((flags == 1 || (flags & ImGuiSliderFlags_InvalidMask_) == 0) && "Invalid ImGuiSliderFlags flags! Has the legacy 'float power' argument been mistakenly cast to flags? Call function with ImGuiSliderFlags_Logarithmic flags instead.");
02548 
02549     ImGuiContext& g = *GImGui;
02550     if (g.ActiveId == id)
02551     {
02552         // Those are the things we can do easily outside the DragBehaviorT<> template, saves code generation.
02553         if (g.ActiveIdSource == ImGuiInputSource_Mouse && !g.IO.MouseDown[0])
02554             ClearActiveID();
02555         else if ((g.ActiveIdSource == ImGuiInputSource_Keyboard || g.ActiveIdSource == ImGuiInputSource_Gamepad) && g.NavActivatePressedId == id && !g.ActiveIdIsJustActivated)
02556             ClearActiveID();
02557     }
02558     if (g.ActiveId != id)
02559         return false;
02560     if ((g.LastItemData.InFlags & ImGuiItemFlags_ReadOnly) || (flags & ImGuiSliderFlags_ReadOnly))
02561         return false;
02562 
02563     switch (data_type)
02564     {
02565     case ImGuiDataType_S8:     { ImS32 v32 = (ImS32)*(ImS8*)p_v;  bool r = DragBehaviorT<ImS32, ImS32, float>(ImGuiDataType_S32, &v32, v_speed, p_min ? *(const ImS8*) p_min : IM_S8_MIN,  p_max ? *(const ImS8*)p_max  : IM_S8_MAX,  format, flags); if (r) *(ImS8*)p_v = (ImS8)v32; return r; }
02566     case ImGuiDataType_U8:     { ImU32 v32 = (ImU32)*(ImU8*)p_v;  bool r = DragBehaviorT<ImU32, ImS32, float>(ImGuiDataType_U32, &v32, v_speed, p_min ? *(const ImU8*) p_min : IM_U8_MIN,  p_max ? *(const ImU8*)p_max  : IM_U8_MAX,  format, flags); if (r) *(ImU8*)p_v = (ImU8)v32; return r; }
02567     case ImGuiDataType_S16:    { ImS32 v32 = (ImS32)*(ImS16*)p_v; bool r = DragBehaviorT<ImS32, ImS32, float>(ImGuiDataType_S32, &v32, v_speed, p_min ? *(const ImS16*)p_min : IM_S16_MIN, p_max ? *(const ImS16*)p_max : IM_S16_MAX, format, flags); if (r) *(ImS16*)p_v = (ImS16)v32; return r; }
02568     case ImGuiDataType_U16:    { ImU32 v32 = (ImU32)*(ImU16*)p_v; bool r = DragBehaviorT<ImU32, ImS32, float>(ImGuiDataType_U32, &v32, v_speed, p_min ? *(const ImU16*)p_min : IM_U16_MIN, p_max ? *(const ImU16*)p_max : IM_U16_MAX, format, flags); if (r) *(ImU16*)p_v = (ImU16)v32; return r; }
02569     case ImGuiDataType_S32:    return DragBehaviorT<ImS32, ImS32, float >(data_type, (ImS32*)p_v,  v_speed, p_min ? *(const ImS32* )p_min : IM_S32_MIN, p_max ? *(const ImS32* )p_max : IM_S32_MAX, format, flags);
02570     case ImGuiDataType_U32:    return DragBehaviorT<ImU32, ImS32, float >(data_type, (ImU32*)p_v,  v_speed, p_min ? *(const ImU32* )p_min : IM_U32_MIN, p_max ? *(const ImU32* )p_max : IM_U32_MAX, format, flags);
02571     case ImGuiDataType_S64:    return DragBehaviorT<ImS64, ImS64, double>(data_type, (ImS64*)p_v,  v_speed, p_min ? *(const ImS64* )p_min : IM_S64_MIN, p_max ? *(const ImS64* )p_max : IM_S64_MAX, format, flags);
02572     case ImGuiDataType_U64:    return DragBehaviorT<ImU64, ImS64, double>(data_type, (ImU64*)p_v,  v_speed, p_min ? *(const ImU64* )p_min : IM_U64_MIN, p_max ? *(const ImU64* )p_max : IM_U64_MAX, format, flags);
02573     case ImGuiDataType_Float:  return DragBehaviorT<float, float, float >(data_type, (float*)p_v,  v_speed, p_min ? *(const float* )p_min : -FLT_MAX,   p_max ? *(const float* )p_max : FLT_MAX,    format, flags);
02574     case ImGuiDataType_Double: return DragBehaviorT<double,double,double>(data_type, (double*)p_v, v_speed, p_min ? *(const double*)p_min : -DBL_MAX,   p_max ? *(const double*)p_max : DBL_MAX,    format, flags);
02575     case ImGuiDataType_COUNT:  break;
02576     }
02577     IM_ASSERT(0);
02578     return false;
02579 }
02580 
02581 // Note: p_data, p_min and p_max are _pointers_ to a memory address holding the data. For a Drag widget, p_min and p_max are optional.
02582 // Read code of e.g. DragFloat(), DragInt() etc. or examples in 'Demo->Widgets->Data Types' to understand how to use this function directly.
02583 bool ImGui::DragScalar(const char* label, ImGuiDataType data_type, void* p_data, float v_speed, const void* p_min, const void* p_max, const char* format, ImGuiSliderFlags flags)
02584 {
02585     ImGuiWindow* window = GetCurrentWindow();
02586     if (window->SkipItems)
02587         return false;
02588 
02589     ImGuiContext& g = *GImGui;
02590     const ImGuiStyle& style = g.Style;
02591     const ImGuiID id = window->GetID(label);
02592     const float w = CalcItemWidth();
02593 
02594     const ImVec2 label_size = CalcTextSize(label, NULL, true);
02595     const ImRect frame_bb(window->DC.CursorPos, window->DC.CursorPos + ImVec2(w, label_size.y + style.FramePadding.y * 2.0f));
02596     const ImRect total_bb(frame_bb.Min, frame_bb.Max + ImVec2(label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0.0f));
02597 
02598     const bool temp_input_allowed = (flags & ImGuiSliderFlags_NoInput) == 0;
02599     ItemSize(total_bb, style.FramePadding.y);
02600     if (!ItemAdd(total_bb, id, &frame_bb, temp_input_allowed ? ImGuiItemFlags_Inputable : 0))
02601         return false;
02602 
02603     // Default format string when passing NULL
02604     if (format == NULL)
02605         format = DataTypeGetInfo(data_type)->PrintFmt;
02606 
02607     const bool hovered = ItemHoverable(frame_bb, id, g.LastItemData.InFlags);
02608     bool temp_input_is_active = temp_input_allowed && TempInputIsActive(id);
02609     if (!temp_input_is_active)
02610     {
02611         // Tabbing or CTRL-clicking on Drag turns it into an InputText
02612         const bool clicked = hovered && IsMouseClicked(0, ImGuiInputFlags_None, id);
02613         const bool double_clicked = (hovered && g.IO.MouseClickedCount[0] == 2 && TestKeyOwner(ImGuiKey_MouseLeft, id));
02614         const bool make_active = (clicked || double_clicked || g.NavActivateId == id);
02615         if (make_active && (clicked || double_clicked))
02616             SetKeyOwner(ImGuiKey_MouseLeft, id);
02617         if (make_active && temp_input_allowed)
02618             if ((clicked && g.IO.KeyCtrl) || double_clicked || (g.NavActivateId == id && (g.NavActivateFlags & ImGuiActivateFlags_PreferInput)))
02619                 temp_input_is_active = true;
02620 
02621         // (Optional) simple click (without moving) turns Drag into an InputText
02622         if (g.IO.ConfigDragClickToInputText && temp_input_allowed && !temp_input_is_active)
02623             if (g.ActiveId == id && hovered && g.IO.MouseReleased[0] && !IsMouseDragPastThreshold(0, g.IO.MouseDragThreshold * DRAG_MOUSE_THRESHOLD_FACTOR))
02624             {
02625                 g.NavActivateId = id;
02626                 g.NavActivateFlags = ImGuiActivateFlags_PreferInput;
02627                 temp_input_is_active = true;
02628             }
02629 
02630         if (make_active && !temp_input_is_active)
02631         {
02632             SetActiveID(id, window);
02633             SetFocusID(id, window);
02634             FocusWindow(window);
02635             g.ActiveIdUsingNavDirMask = (1 << ImGuiDir_Left) | (1 << ImGuiDir_Right);
02636         }
02637     }
02638 
02639     if (temp_input_is_active)
02640     {
02641         // Only clamp CTRL+Click input when ImGuiSliderFlags_AlwaysClamp is set
02642         const bool is_clamp_input = (flags & ImGuiSliderFlags_AlwaysClamp) != 0 && (p_min == NULL || p_max == NULL || DataTypeCompare(data_type, p_min, p_max) < 0);
02643         return TempInputScalar(frame_bb, id, label, data_type, p_data, format, is_clamp_input ? p_min : NULL, is_clamp_input ? p_max : NULL);
02644     }
02645 
02646     // Draw frame
02647     const ImU32 frame_col = GetColorU32(g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg);
02648     RenderNavHighlight(frame_bb, id);
02649     RenderFrame(frame_bb.Min, frame_bb.Max, frame_col, true, style.FrameRounding);
02650 
02651     // Drag behavior
02652     const bool value_changed = DragBehavior(id, data_type, p_data, v_speed, p_min, p_max, format, flags);
02653     if (value_changed)
02654         MarkItemEdited(id);
02655 
02656     // Display value using user-provided display format so user can add prefix/suffix/decorations to the value.
02657     char value_buf[64];
02658     const char* value_buf_end = value_buf + DataTypeFormatString(value_buf, IM_ARRAYSIZE(value_buf), data_type, p_data, format);
02659     if (g.LogEnabled)
02660         LogSetNextTextDecoration("{", "}");
02661     RenderTextClipped(frame_bb.Min, frame_bb.Max, value_buf, value_buf_end, NULL, ImVec2(0.5f, 0.5f));
02662 
02663     if (label_size.x > 0.0f)
02664         RenderText(ImVec2(frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y), label);
02665 
02666     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | (temp_input_allowed ? ImGuiItemStatusFlags_Inputable : 0));
02667     return value_changed;
02668 }
