02674         return false;
02675 
02676     ImGuiContext& g = *GImGui;
02677     bool value_changed = false;
02678     BeginGroup();
02679     PushID(label);
02680     PushMultiItemsWidths(components, CalcItemWidth());
02681     size_t type_size = GDataTypeInfo[data_type].Size;
02682     for (int i = 0; i < components; i++)
02683     {
02684         PushID(i);
02685         if (i > 0)
02686             SameLine(0, g.Style.ItemInnerSpacing.x);
02687         value_changed |= DragScalar("", data_type, p_data, v_speed, p_min, p_max, format, flags);
02688         PopID();
02689         PopItemWidth();
02690         p_data = (void*)((char*)p_data + type_size);
02691     }
02692     PopID();
02693 
02694     const char* label_end = FindRenderedTextEnd(label);
02695     if (label != label_end)
02696     {
02697         SameLine(0, g.Style.ItemInnerSpacing.x);
02698         TextEx(label, label_end);
02699     }
02700 
02701     EndGroup();
02702     return value_changed;
02703 }
