02812 //-------------------------------------------------------------------------
02813 // [SECTION] Widgets: SliderScalar, SliderFloat, SliderInt, etc.
02814 //-------------------------------------------------------------------------
02815 // - ScaleRatioFromValueT<> [Internal]
02816 // - ScaleValueFromRatioT<> [Internal]
02817 // - SliderBehaviorT<>() [Internal]
02818 // - SliderBehavior() [Internal]
02819 // - SliderScalar()
02820 // - SliderScalarN()
02821 // - SliderFloat()
02822 // - SliderFloat2()
02823 // - SliderFloat3()
02824 // - SliderFloat4()
02825 // - SliderAngle()
02826 // - SliderInt()
02827 // - SliderInt2()
02828 // - SliderInt3()
02829 // - SliderInt4()
02830 // - VSliderScalar()
02831 // - VSliderFloat()
02832 // - VSliderInt()
02833 //-------------------------------------------------------------------------
02834 
02835 // Convert a value v in the output space of a slider into a parametric position on the slider itself (the logical opposite of ScaleValueFromRatioT)
02836 template<typename TYPE, typename SIGNEDTYPE, typename FLOATTYPE>
02837 float ImGui::ScaleRatioFromValueT(ImGuiDataType data_type, TYPE v, TYPE v_min, TYPE v_max, bool is_logarithmic, float logarithmic_zero_epsilon, float zero_deadzone_halfsize)
02838 {
02839     if (v_min == v_max)
02840         return 0.0f;
02841     IM_UNUSED(data_type);
02842 
02843     const TYPE v_clamped = (v_min < v_max) ? ImClamp(v, v_min, v_max) : ImClamp(v, v_max, v_min);
02844     if (is_logarithmic)
02845     {
02846         bool flipped = v_max < v_min;
02847 
02848         if (flipped) // Handle the case where the range is backwards
02849             ImSwap(v_min, v_max);
02850 
02851         // Fudge min/max to avoid getting close to log(0)
02852         FLOATTYPE v_min_fudged = (ImAbs((FLOATTYPE)v_min) < logarithmic_zero_epsilon) ? ((v_min < 0.0f) ? -logarithmic_zero_epsilon : logarithmic_zero_epsilon) : (FLOATTYPE)v_min;
02853         FLOATTYPE v_max_fudged = (ImAbs((FLOATTYPE)v_max) < logarithmic_zero_epsilon) ? ((v_max < 0.0f) ? -logarithmic_zero_epsilon : logarithmic_zero_epsilon) : (FLOATTYPE)v_max;
02854 
02855         // Awkward special cases - we need ranges of the form (-100 .. 0) to convert to (-100 .. -epsilon), not (-100 .. epsilon)
02856         if ((v_min == 0.0f) && (v_max < 0.0f))
02857             v_min_fudged = -logarithmic_zero_epsilon;
02858         else if ((v_max == 0.0f) && (v_min < 0.0f))
02859             v_max_fudged = -logarithmic_zero_epsilon;
02860 
02861         float result;
02862         if (v_clamped <= v_min_fudged)
02863             result = 0.0f; // Workaround for values that are in-range but below our fudge
02864         else if (v_clamped >= v_max_fudged)
02865             result = 1.0f; // Workaround for values that are in-range but above our fudge
02866         else if ((v_min * v_max) < 0.0f) // Range crosses zero, so split into two portions
02867         {
02868             float zero_point_center = (-(float)v_min) / ((float)v_max - (float)v_min); // The zero point in parametric space.  There's an argument we should take the logarithmic nature into account when calculating this, but for now this should do (and the most common case of a symmetrical range works fine)
02869             float zero_point_snap_L = zero_point_center - zero_deadzone_halfsize;
02870             float zero_point_snap_R = zero_point_center + zero_deadzone_halfsize;
02871             if (v == 0.0f)
02872                 result = zero_point_center; // Special case for exactly zero
02873             else if (v < 0.0f)
02874                 result = (1.0f - (float)(ImLog(-(FLOATTYPE)v_clamped / logarithmic_zero_epsilon) / ImLog(-v_min_fudged / logarithmic_zero_epsilon))) * zero_point_snap_L;
02875             else
02876                 result = zero_point_snap_R + ((float)(ImLog((FLOATTYPE)v_clamped / logarithmic_zero_epsilon) / ImLog(v_max_fudged / logarithmic_zero_epsilon)) * (1.0f - zero_point_snap_R));
02877         }
02878         else if ((v_min < 0.0f) || (v_max < 0.0f)) // Entirely negative slider
02879             result = 1.0f - (float)(ImLog(-(FLOATTYPE)v_clamped / -v_max_fudged) / ImLog(-v_min_fudged / -v_max_fudged));
02880         else
02881             result = (float)(ImLog((FLOATTYPE)v_clamped / v_min_fudged) / ImLog(v_max_fudged / v_min_fudged));
02882 
02883         return flipped ? (1.0f - result) : result;
02884     }
02885     else
02886     {
02887         // Linear slider
02888         return (float)((FLOATTYPE)(SIGNEDTYPE)(v_clamped - v_min) / (FLOATTYPE)(SIGNEDTYPE)(v_max - v_min));
02889     }
02890 }
02891 
02892 // Convert a parametric position on a slider into a value v in the output space (the logical opposite of ScaleRatioFromValueT)
02893 template<typename TYPE, typename SIGNEDTYPE, typename FLOATTYPE>
02894 TYPE ImGui::ScaleValueFromRatioT(ImGuiDataType data_type, float t, TYPE v_min, TYPE v_max, bool is_logarithmic, float logarithmic_zero_epsilon, float zero_deadzone_halfsize)
02895 {
02896     // We special-case the extents because otherwise our logarithmic fudging can lead to "mathematically correct"
02897     // but non-intuitive behaviors like a fully-left slider not actually reaching the minimum value. Also generally simpler.
02898     if (t <= 0.0f || v_min == v_max)
02899         return v_min;
02900     if (t >= 1.0f)
02901         return v_max;
02902 
02903     TYPE result = (TYPE)0;
02904     if (is_logarithmic)
02905     {
02906         // Fudge min/max to avoid getting silly results close to zero
02907         FLOATTYPE v_min_fudged = (ImAbs((FLOATTYPE)v_min) < logarithmic_zero_epsilon) ? ((v_min < 0.0f) ? -logarithmic_zero_epsilon : logarithmic_zero_epsilon) : (FLOATTYPE)v_min;
02908         FLOATTYPE v_max_fudged = (ImAbs((FLOATTYPE)v_max) < logarithmic_zero_epsilon) ? ((v_max < 0.0f) ? -logarithmic_zero_epsilon : logarithmic_zero_epsilon) : (FLOATTYPE)v_max;
02909 
02910         const bool flipped = v_max < v_min; // Check if range is "backwards"
02911         if (flipped)
02912             ImSwap(v_min_fudged, v_max_fudged);
02913 
02914         // Awkward special case - we need ranges of the form (-100 .. 0) to convert to (-100 .. -epsilon), not (-100 .. epsilon)
02915         if ((v_max == 0.0f) && (v_min < 0.0f))
02916             v_max_fudged = -logarithmic_zero_epsilon;
02917 
02918         float t_with_flip = flipped ? (1.0f - t) : t; // t, but flipped if necessary to account for us flipping the range
02919 
02920         if ((v_min * v_max) < 0.0f) // Range crosses zero, so we have to do this in two parts
02921         {
02922             float zero_point_center = (-(float)ImMin(v_min, v_max)) / ImAbs((float)v_max - (float)v_min); // The zero point in parametric space
02923             float zero_point_snap_L = zero_point_center - zero_deadzone_halfsize;
02924             float zero_point_snap_R = zero_point_center + zero_deadzone_halfsize;
02925             if (t_with_flip >= zero_point_snap_L && t_with_flip <= zero_point_snap_R)
02926                 result = (TYPE)0.0f; // Special case to make getting exactly zero possible (the epsilon prevents it otherwise)
02927             else if (t_with_flip < zero_point_center)
02928                 result = (TYPE)-(logarithmic_zero_epsilon * ImPow(-v_min_fudged / logarithmic_zero_epsilon, (FLOATTYPE)(1.0f - (t_with_flip / zero_point_snap_L))));
02929             else
02930                 result = (TYPE)(logarithmic_zero_epsilon * ImPow(v_max_fudged / logarithmic_zero_epsilon, (FLOATTYPE)((t_with_flip - zero_point_snap_R) / (1.0f - zero_point_snap_R))));
02931         }
02932         else if ((v_min < 0.0f) || (v_max < 0.0f)) // Entirely negative slider
02933             result = (TYPE)-(-v_max_fudged * ImPow(-v_min_fudged / -v_max_fudged, (FLOATTYPE)(1.0f - t_with_flip)));
02934         else
02935             result = (TYPE)(v_min_fudged * ImPow(v_max_fudged / v_min_fudged, (FLOATTYPE)t_with_flip));
02936     }
02937     else
02938     {
02939         // Linear slider
02940         const bool is_floating_point = (data_type == ImGuiDataType_Float) || (data_type == ImGuiDataType_Double);
02941         if (is_floating_point)
02942         {
02943             result = ImLerp(v_min, v_max, t);
02944         }
02945         else if (t < 1.0)
02946         {
02947             // - For integer values we want the clicking position to match the grab box so we round above
02948             //   This code is carefully tuned to work with large values (e.g. high ranges of U64) while preserving this property..
02949             // - Not doing a *1.0 multiply at the end of a range as it tends to be lossy. While absolute aiming at a large s64/u64
02950             //   range is going to be imprecise anyway, with this check we at least make the edge values matches expected limits.
02951             FLOATTYPE v_new_off_f = (SIGNEDTYPE)(v_max - v_min) * t;
02952             result = (TYPE)((SIGNEDTYPE)v_min + (SIGNEDTYPE)(v_new_off_f + (FLOATTYPE)(v_min > v_max ? -0.5 : 0.5)));
02953         }
02954     }
02955 
02956     return result;
02957 }
02958 
02959 // FIXME: Try to move more of the code into shared SliderBehavior()
02960 template<typename TYPE, typename SIGNEDTYPE, typename FLOATTYPE>
02961 bool ImGui::SliderBehaviorT(const ImRect& bb, ImGuiID id, ImGuiDataType data_type, TYPE* v, const TYPE v_min, const TYPE v_max, const char* format, ImGuiSliderFlags flags, ImRect* out_grab_bb)
02962 {
02963     ImGuiContext& g = *GImGui;
02964     const ImGuiStyle& style = g.Style;
02965 
02966     const ImGuiAxis axis = (flags & ImGuiSliderFlags_Vertical) ? ImGuiAxis_Y : ImGuiAxis_X;
02967     const bool is_logarithmic = (flags & ImGuiSliderFlags_Logarithmic) != 0;
02968     const bool is_floating_point = (data_type == ImGuiDataType_Float) || (data_type == ImGuiDataType_Double);
02969     const float v_range_f = (float)(v_min < v_max ? v_max - v_min : v_min - v_max); // We don't need high precision for what we do with it.
02970 
02971     // Calculate bounds
02972     const float grab_padding = 2.0f; // FIXME: Should be part of style.
02973     const float slider_sz = (bb.Max[axis] - bb.Min[axis]) - grab_padding * 2.0f;
02974     float grab_sz = style.GrabMinSize;
02975     if (!is_floating_point && v_range_f >= 0.0f)                         // v_range_f < 0 may happen on integer overflows
02976         grab_sz = ImMax(slider_sz / (v_range_f + 1), style.GrabMinSize); // For integer sliders: if possible have the grab size represent 1 unit
02977     grab_sz = ImMin(grab_sz, slider_sz);
02978     const float slider_usable_sz = slider_sz - grab_sz;
02979     const float slider_usable_pos_min = bb.Min[axis] + grab_padding + grab_sz * 0.5f;
02980     const float slider_usable_pos_max = bb.Max[axis] - grab_padding - grab_sz * 0.5f;
02981 
02982     float logarithmic_zero_epsilon = 0.0f; // Only valid when is_logarithmic is true
02983     float zero_deadzone_halfsize = 0.0f; // Only valid when is_logarithmic is true
02984     if (is_logarithmic)
02985     {
02986         // When using logarithmic sliders, we need to clamp to avoid hitting zero, but our choice of clamp value greatly affects slider precision. We attempt to use the specified precision to estimate a good lower bound.
02987         const int decimal_precision = is_floating_point ? ImParseFormatPrecision(format, 3) : 1;
02988         logarithmic_zero_epsilon = ImPow(0.1f, (float)decimal_precision);
02989         zero_deadzone_halfsize = (style.LogSliderDeadzone * 0.5f) / ImMax(slider_usable_sz, 1.0f);
02990     }
02991 
02992     // Process interacting with the slider
02993     bool value_changed = false;
02994     if (g.ActiveId == id)
02995     {
02996         bool set_new_value = false;
02997         float clicked_t = 0.0f;
02998         if (g.ActiveIdSource == ImGuiInputSource_Mouse)
02999         {
03000             if (!g.IO.MouseDown[0])
03001             {
03002                 ClearActiveID();
03003             }
03004             else
03005             {
03006                 const float mouse_abs_pos = g.IO.MousePos[axis];
03007                 if (g.ActiveIdIsJustActivated)
03008                 {
03009                     float grab_t = ScaleRatioFromValueT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, *v, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
03010                     if (axis == ImGuiAxis_Y)
03011                         grab_t = 1.0f - grab_t;
03012                     const float grab_pos = ImLerp(slider_usable_pos_min, slider_usable_pos_max, grab_t);
03013                     const bool clicked_around_grab = (mouse_abs_pos >= grab_pos - grab_sz * 0.5f - 1.0f) && (mouse_abs_pos <= grab_pos + grab_sz * 0.5f + 1.0f); // No harm being extra generous here.
03014                     g.SliderGrabClickOffset = (clicked_around_grab && is_floating_point) ? mouse_abs_pos - grab_pos : 0.0f;
03015                 }
03016                 if (slider_usable_sz > 0.0f)
03017                     clicked_t = ImSaturate((mouse_abs_pos - g.SliderGrabClickOffset - slider_usable_pos_min) / slider_usable_sz);
03018                 if (axis == ImGuiAxis_Y)
03019                     clicked_t = 1.0f - clicked_t;
03020                 set_new_value = true;
03021             }
03022         }
03023         else if (g.ActiveIdSource == ImGuiInputSource_Keyboard || g.ActiveIdSource == ImGuiInputSource_Gamepad)
03024         {
03025             if (g.ActiveIdIsJustActivated)
03026             {
03027                 g.SliderCurrentAccum = 0.0f; // Reset any stored nav delta upon activation
03028                 g.SliderCurrentAccumDirty = false;
03029             }
03030 
03031             float input_delta = (axis == ImGuiAxis_X) ? GetNavTweakPressedAmount(axis) : -GetNavTweakPressedAmount(axis);
03032             if (input_delta != 0.0f)
03033             {
03034                 const bool tweak_slow = IsKeyDown((g.NavInputSource == ImGuiInputSource_Gamepad) ? ImGuiKey_NavGamepadTweakSlow : ImGuiKey_NavKeyboardTweakSlow);
03035                 const bool tweak_fast = IsKeyDown((g.NavInputSource == ImGuiInputSource_Gamepad) ? ImGuiKey_NavGamepadTweakFast : ImGuiKey_NavKeyboardTweakFast);
03036                 const int decimal_precision = is_floating_point ? ImParseFormatPrecision(format, 3) : 0;
03037                 if (decimal_precision > 0)
03038                 {
03039                     input_delta /= 100.0f;    // Gamepad/keyboard tweak speeds in % of slider bounds
03040                     if (tweak_slow)
03041                         input_delta /= 10.0f;
03042                 }
03043                 else
03044                 {
03045                     if ((v_range_f >= -100.0f && v_range_f <= 100.0f && v_range_f != 0.0f) || tweak_slow)
03046                         input_delta = ((input_delta < 0.0f) ? -1.0f : +1.0f) / v_range_f; // Gamepad/keyboard tweak speeds in integer steps
03047                     else
03048                         input_delta /= 100.0f;
03049                 }
03050                 if (tweak_fast)
03051                     input_delta *= 10.0f;
03052 
03053                 g.SliderCurrentAccum += input_delta;
03054                 g.SliderCurrentAccumDirty = true;
03055             }
03056 
03057             float delta = g.SliderCurrentAccum;
03058             if (g.NavActivatePressedId == id && !g.ActiveIdIsJustActivated)
03059             {
03060                 ClearActiveID();
03061             }
03062             else if (g.SliderCurrentAccumDirty)
03063             {
03064                 clicked_t = ScaleRatioFromValueT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, *v, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
03065 
03066                 if ((clicked_t >= 1.0f && delta > 0.0f) || (clicked_t <= 0.0f && delta < 0.0f)) // This is to avoid applying the saturation when already past the limits
03067                 {
03068                     set_new_value = false;
03069                     g.SliderCurrentAccum = 0.0f; // If pushing up against the limits, don't continue to accumulate
03070                 }
03071                 else
03072                 {
03073                     set_new_value = true;
03074                     float old_clicked_t = clicked_t;
03075                     clicked_t = ImSaturate(clicked_t + delta);
03076 
03077                     // Calculate what our "new" clicked_t will be, and thus how far we actually moved the slider, and subtract this from the accumulator
03078                     TYPE v_new = ScaleValueFromRatioT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, clicked_t, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
03079                     if (is_floating_point && !(flags & ImGuiSliderFlags_NoRoundToFormat))
03080                         v_new = RoundScalarWithFormatT<TYPE>(format, data_type, v_new);
03081                     float new_clicked_t = ScaleRatioFromValueT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, v_new, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
03082 
03083                     if (delta > 0)
03084                         g.SliderCurrentAccum -= ImMin(new_clicked_t - old_clicked_t, delta);
03085                     else
03086                         g.SliderCurrentAccum -= ImMax(new_clicked_t - old_clicked_t, delta);
03087                 }
03088 
03089                 g.SliderCurrentAccumDirty = false;
03090             }
03091         }
03092 
03093         if (set_new_value)
03094             if ((g.LastItemData.InFlags & ImGuiItemFlags_ReadOnly) || (flags & ImGuiSliderFlags_ReadOnly))
03095                 set_new_value = false;
03096 
03097         if (set_new_value)
03098         {
03099             TYPE v_new = ScaleValueFromRatioT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, clicked_t, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
03100 
03101             // Round to user desired precision based on format string
03102             if (is_floating_point && !(flags & ImGuiSliderFlags_NoRoundToFormat))
03103                 v_new = RoundScalarWithFormatT<TYPE>(format, data_type, v_new);
03104 
03105             // Apply result
03106             if (*v != v_new)
03107             {
03108                 *v = v_new;
03109                 value_changed = true;
03110             }
03111         }
03112     }
03113 
03114     if (slider_sz < 1.0f)
03115     {
03116         *out_grab_bb = ImRect(bb.Min, bb.Min);
03117     }
03118     else
03119     {
03120         // Output grab position so it can be displayed by the caller
03121         float grab_t = ScaleRatioFromValueT<TYPE, SIGNEDTYPE, FLOATTYPE>(data_type, *v, v_min, v_max, is_logarithmic, logarithmic_zero_epsilon, zero_deadzone_halfsize);
03122         if (axis == ImGuiAxis_Y)
03123             grab_t = 1.0f - grab_t;
03124         const float grab_pos = ImLerp(slider_usable_pos_min, slider_usable_pos_max, grab_t);
03125         if (axis == ImGuiAxis_X)
03126             *out_grab_bb = ImRect(grab_pos - grab_sz * 0.5f, bb.Min.y + grab_padding, grab_pos + grab_sz * 0.5f, bb.Max.y - grab_padding);
03127         else
03128             *out_grab_bb = ImRect(bb.Min.x + grab_padding, grab_pos - grab_sz * 0.5f, bb.Max.x - grab_padding, grab_pos + grab_sz * 0.5f);
03129     }
03130 
03131     return value_changed;
03132 }
03133 
03134 // For 32-bit and larger types, slider bounds are limited to half the natural type range.
03135 // So e.g. an integer Slider between INT_MAX-10 and INT_MAX will fail, but an integer Slider between INT_MAX/2-10 and INT_MAX/2 will be ok.
03136 // It would be possible to lift that limitation with some work but it doesn't seem to be worth it for sliders.
03137 bool ImGui::SliderBehavior(const ImRect& bb, ImGuiID id, ImGuiDataType data_type, void* p_v, const void* p_min, const void* p_max, const char* format, ImGuiSliderFlags flags, ImRect* out_grab_bb)
03138 {
03139     // Read imgui.cpp "API BREAKING CHANGES" section for 1.78 if you hit this assert.
03140     IM_ASSERT((flags == 1 || (flags & ImGuiSliderFlags_InvalidMask_) == 0) && "Invalid ImGuiSliderFlags flags! Has the legacy 'float power' argument been mistakenly cast to flags? Call function with ImGuiSliderFlags_Logarithmic flags instead.");
03141     IM_ASSERT((flags & ImGuiSliderFlags_WrapAround) == 0); // Not supported by SliderXXX(), only by DragXXX()
03142 
03143     switch (data_type)
03144     {
03145     case ImGuiDataType_S8:  { ImS32 v32 = (ImS32)*(ImS8*)p_v;  bool r = SliderBehaviorT<ImS32, ImS32, float>(bb, id, ImGuiDataType_S32, &v32, *(const ImS8*)p_min,  *(const ImS8*)p_max,  format, flags, out_grab_bb); if (r) *(ImS8*)p_v  = (ImS8)v32;  return r; }
03146     case ImGuiDataType_U8:  { ImU32 v32 = (ImU32)*(ImU8*)p_v;  bool r = SliderBehaviorT<ImU32, ImS32, float>(bb, id, ImGuiDataType_U32, &v32, *(const ImU8*)p_min,  *(const ImU8*)p_max,  format, flags, out_grab_bb); if (r) *(ImU8*)p_v  = (ImU8)v32;  return r; }
03147     case ImGuiDataType_S16: { ImS32 v32 = (ImS32)*(ImS16*)p_v; bool r = SliderBehaviorT<ImS32, ImS32, float>(bb, id, ImGuiDataType_S32, &v32, *(const ImS16*)p_min, *(const ImS16*)p_max, format, flags, out_grab_bb); if (r) *(ImS16*)p_v = (ImS16)v32; return r; }
03148     case ImGuiDataType_U16: { ImU32 v32 = (ImU32)*(ImU16*)p_v; bool r = SliderBehaviorT<ImU32, ImS32, float>(bb, id, ImGuiDataType_U32, &v32, *(const ImU16*)p_min, *(const ImU16*)p_max, format, flags, out_grab_bb); if (r) *(ImU16*)p_v = (ImU16)v32; return r; }
03149     case ImGuiDataType_S32:
03150         IM_ASSERT(*(const ImS32*)p_min >= IM_S32_MIN / 2 && *(const ImS32*)p_max <= IM_S32_MAX / 2);
03151         return SliderBehaviorT<ImS32, ImS32, float >(bb, id, data_type, (ImS32*)p_v,  *(const ImS32*)p_min,  *(const ImS32*)p_max,  format, flags, out_grab_bb);
03152     case ImGuiDataType_U32:
03153         IM_ASSERT(*(const ImU32*)p_max <= IM_U32_MAX / 2);
03154         return SliderBehaviorT<ImU32, ImS32, float >(bb, id, data_type, (ImU32*)p_v,  *(const ImU32*)p_min,  *(const ImU32*)p_max,  format, flags, out_grab_bb);
03155     case ImGuiDataType_S64:
03156         IM_ASSERT(*(const ImS64*)p_min >= IM_S64_MIN / 2 && *(const ImS64*)p_max <= IM_S64_MAX / 2);
03157         return SliderBehaviorT<ImS64, ImS64, double>(bb, id, data_type, (ImS64*)p_v,  *(const ImS64*)p_min,  *(const ImS64*)p_max,  format, flags, out_grab_bb);
03158     case ImGuiDataType_U64:
03159         IM_ASSERT(*(const ImU64*)p_max <= IM_U64_MAX / 2);
03160         return SliderBehaviorT<ImU64, ImS64, double>(bb, id, data_type, (ImU64*)p_v,  *(const ImU64*)p_min,  *(const ImU64*)p_max,  format, flags, out_grab_bb);
03161     case ImGuiDataType_Float:
03162         IM_ASSERT(*(const float*)p_min >= -FLT_MAX / 2.0f && *(const float*)p_max <= FLT_MAX / 2.0f);
03163         return SliderBehaviorT<float, float, float >(bb, id, data_type, (float*)p_v,  *(const float*)p_min,  *(const float*)p_max,  format, flags, out_grab_bb);
03164     case ImGuiDataType_Double:
03165         IM_ASSERT(*(const double*)p_min >= -DBL_MAX / 2.0f && *(const double*)p_max <= DBL_MAX / 2.0f);
03166         return SliderBehaviorT<double, double, double>(bb, id, data_type, (double*)p_v, *(const double*)p_min, *(const double*)p_max, format, flags, out_grab_bb);
03167     case ImGuiDataType_COUNT: break;
03168     }
03169     IM_ASSERT(0);
03170     return false;
03171 }
