03173 // Note: p_data, p_min and p_max are _pointers_ to a memory address holding the data. For a slider, they are all required.
03174 // Read code of e.g. SliderFloat(), SliderInt() etc. or examples in 'Demo->Widgets->Data Types' to understand how to use this function directly.
03175 bool ImGui::SliderScalar(const char* label, ImGuiDataType data_type, void* p_data, const void* p_min, const void* p_max, const char* format, ImGuiSliderFlags flags)
03176 {
03177     ImGuiWindow* window = GetCurrentWindow();
03178     if (window->SkipItems)
03179         return false;
03180 
03181     ImGuiContext& g = *GImGui;
03182     const ImGuiStyle& style = g.Style;
03183     const ImGuiID id = window->GetID(label);
03184     const float w = CalcItemWidth();
03185 
03186     const ImVec2 label_size = CalcTextSize(label, NULL, true);
03187     const ImRect frame_bb(window->DC.CursorPos, window->DC.CursorPos + ImVec2(w, label_size.y + style.FramePadding.y * 2.0f));
03188     const ImRect total_bb(frame_bb.Min, frame_bb.Max + ImVec2(label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0.0f));
03189 
03190     const bool temp_input_allowed = (flags & ImGuiSliderFlags_NoInput) == 0;
03191     ItemSize(total_bb, style.FramePadding.y);
03192     if (!ItemAdd(total_bb, id, &frame_bb, temp_input_allowed ? ImGuiItemFlags_Inputable : 0))
03193         return false;
03194 
03195     // Default format string when passing NULL
03196     if (format == NULL)
03197         format = DataTypeGetInfo(data_type)->PrintFmt;
03198 
03199     const bool hovered = ItemHoverable(frame_bb, id, g.LastItemData.InFlags);
03200     bool temp_input_is_active = temp_input_allowed && TempInputIsActive(id);
03201     if (!temp_input_is_active)
03202     {
03203         // Tabbing or CTRL-clicking on Slider turns it into an input box
03204         const bool clicked = hovered && IsMouseClicked(0, ImGuiInputFlags_None, id);
03205         const bool make_active = (clicked || g.NavActivateId == id);
03206         if (make_active && clicked)
03207             SetKeyOwner(ImGuiKey_MouseLeft, id);
03208         if (make_active && temp_input_allowed)
03209             if ((clicked && g.IO.KeyCtrl) || (g.NavActivateId == id && (g.NavActivateFlags & ImGuiActivateFlags_PreferInput)))
03210                 temp_input_is_active = true;
03211 
03212         if (make_active && !temp_input_is_active)
03213         {
03214             SetActiveID(id, window);
03215             SetFocusID(id, window);
03216             FocusWindow(window);
03217             g.ActiveIdUsingNavDirMask |= (1 << ImGuiDir_Left) | (1 << ImGuiDir_Right);
03218         }
03219     }
03220 
03221     if (temp_input_is_active)
03222     {
03223         // Only clamp CTRL+Click input when ImGuiSliderFlags_AlwaysClamp is set
03224         const bool is_clamp_input = (flags & ImGuiSliderFlags_AlwaysClamp) != 0;
03225         return TempInputScalar(frame_bb, id, label, data_type, p_data, format, is_clamp_input ? p_min : NULL, is_clamp_input ? p_max : NULL);
03226     }
03227 
03228     // Draw frame
03229     const ImU32 frame_col = GetColorU32(g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg);
03230     RenderNavHighlight(frame_bb, id);
03231     RenderFrame(frame_bb.Min, frame_bb.Max, frame_col, true, g.Style.FrameRounding);
03232 
03233     // Slider behavior
03234     ImRect grab_bb;
03235     const bool value_changed = SliderBehavior(frame_bb, id, data_type, p_data, p_min, p_max, format, flags, &grab_bb);
03236     if (value_changed)
03237         MarkItemEdited(id);
03238 
03239     // Render grab
03240     if (grab_bb.Max.x > grab_bb.Min.x)
03241         window->DrawList->AddRectFilled(grab_bb.Min, grab_bb.Max, GetColorU32(g.ActiveId == id ? ImGuiCol_SliderGrabActive : ImGuiCol_SliderGrab), style.GrabRounding);
03242 
03243     // Display value using user-provided display format so user can add prefix/suffix/decorations to the value.
03244     char value_buf[64];
03245     const char* value_buf_end = value_buf + DataTypeFormatString(value_buf, IM_ARRAYSIZE(value_buf), data_type, p_data, format);
03246     if (g.LogEnabled)
03247         LogSetNextTextDecoration("{", "}");
03248     RenderTextClipped(frame_bb.Min, frame_bb.Max, value_buf, value_buf_end, NULL, ImVec2(0.5f, 0.5f));
03249 
03250     if (label_size.x > 0.0f)
03251         RenderText(ImVec2(frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y), label);
03252 
03253     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | (temp_input_allowed ? ImGuiItemStatusFlags_Inputable : 0));
03254     return value_changed;
03255 }
