03257 // Add multiple sliders on 1 line for compact edition of multiple components
03258 bool ImGui::SliderScalarN(const char* label, ImGuiDataType data_type, void* v, int components, const void* v_min, const void* v_max, const char* format, ImGuiSliderFlags flags)
03259 {
03260     ImGuiWindow* window = GetCurrentWindow();
03261     if (window->SkipItems)
03262         return false;
03263 
03264     ImGuiContext& g = *GImGui;
03265     bool value_changed = false;
03266     BeginGroup();
03267     PushID(label);
03268     PushMultiItemsWidths(components, CalcItemWidth());
03269     size_t type_size = GDataTypeInfo[data_type].Size;
03270     for (int i = 0; i < components; i++)
03271     {
03272         PushID(i);
03273         if (i > 0)
03274             SameLine(0, g.Style.ItemInnerSpacing.x);
03275         value_changed |= SliderScalar("", data_type, v, v_min, v_max, format, flags);
03276         PopID();
03277         PopItemWidth();
03278         v = (void*)((char*)v + type_size);
03279     }
03280     PopID();
03281 
03282     const char* label_end = FindRenderedTextEnd(label);
03283     if (label != label_end)
03284     {
03285         SameLine(0, g.Style.ItemInnerSpacing.x);
03286         TextEx(label, label_end);
03287     }
03288 
03289     EndGroup();
03290     return value_changed;
03291 }
