03414 // [SECTION] Widgets: InputScalar, InputFloat, InputInt, etc.
03415 //-------------------------------------------------------------------------
03416 // - ImParseFormatFindStart() [Internal]
03417 // - ImParseFormatFindEnd() [Internal]
03418 // - ImParseFormatTrimDecorations() [Internal]
03419 // - ImParseFormatSanitizeForPrinting() [Internal]
03420 // - ImParseFormatSanitizeForScanning() [Internal]
03421 // - ImParseFormatPrecision() [Internal]
03422 // - TempInputTextScalar() [Internal]
03423 // - InputScalar()
03424 // - InputScalarN()
03425 // - InputFloat()
03426 // - InputFloat2()
03427 // - InputFloat3()
03428 // - InputFloat4()
03429 // - InputInt()
