03436 // We don't use strchr() because our strings are usually very short and often start with '%'
03437 const char* ImParseFormatFindStart(const char* fmt)
03438 {
03439     while (char c = fmt[0])
03440     {
03441         if (c == '%' && fmt[1] != '%')
03442             return fmt;
03443         else if (c == '%')
03444             fmt++;
03445         fmt++;
03446     }
03447     return fmt;
03448 }
03449 
03450 const char* ImParseFormatFindEnd(const char* fmt)
03451 {
03452     // Printf/scanf types modifiers: I/L/h/j/l/t/w/z. Other uppercase letters qualify as types aka end of the format.
03453     if (fmt[0] != '%')
03454         return fmt;
03455     const unsigned int ignored_uppercase_mask = (1 << ('I'-'A')) | (1 << ('L'-'A'));
03456     const unsigned int ignored_lowercase_mask = (1 << ('h'-'a')) | (1 << ('j'-'a')) | (1 << ('l'-'a')) | (1 << ('t'-'a')) | (1 << ('w'-'a')) | (1 << ('z'-'a'));
03457     for (char c; (c = *fmt) != 0; fmt++)
03458     {
03459         if (c >= 'A' && c <= 'Z' && ((1 << (c - 'A')) & ignored_uppercase_mask) == 0)
03460             return fmt + 1;
03461         if (c >= 'a' && c <= 'z' && ((1 << (c - 'a')) & ignored_lowercase_mask) == 0)
03462             return fmt + 1;
03463     }
03464     return fmt;
03465 }
03466 
03467 // Extract the format out of a format string with leading or trailing decorations
03468 //  fmt = "blah blah"  -> return ""
03469 //  fmt = "%.3f"       -> return fmt
03470 //  fmt = "hello %.3f" -> return fmt + 6
03471 //  fmt = "%.3f hello" -> return buf written with "%.3f"
03472 const char* ImParseFormatTrimDecorations(const char* fmt, char* buf, size_t buf_size)
03473 {
03474     const char* fmt_start = ImParseFormatFindStart(fmt);
03475     if (fmt_start[0] != '%')
03476         return "";
03477     const char* fmt_end = ImParseFormatFindEnd(fmt_start);
03478     if (fmt_end[0] == 0) // If we only have leading decoration, we don't need to copy the data.
03479         return fmt_start;
03480     ImStrncpy(buf, fmt_start, ImMin((size_t)(fmt_end - fmt_start) + 1, buf_size));
03481     return buf;
03482 }
03483 
03484 // Sanitize format
03485 // - Zero terminate so extra characters after format (e.g. "%f123") don't confuse atof/atoi
03486 // - stb_sprintf.h supports several new modifiers which format numbers in a way that also makes them incompatible atof/atoi.
03487 void ImParseFormatSanitizeForPrinting(const char* fmt_in, char* fmt_out, size_t fmt_out_size)
03488 {
03489     const char* fmt_end = ImParseFormatFindEnd(fmt_in);
03490     IM_UNUSED(fmt_out_size);
03491     IM_ASSERT((size_t)(fmt_end - fmt_in + 1) < fmt_out_size); // Format is too long, let us know if this happens to you!
03492     while (fmt_in < fmt_end)
03493     {
03494         char c = *fmt_in++;
03495         if (c != '\'' && c != '$' && c != '_') // Custom flags provided by stb_sprintf.h. POSIX 2008 also supports '.
03496             *(fmt_out++) = c;
03497     }
03498     *fmt_out = 0; // Zero-terminate
03499 }
03500 
03501 // - For scanning we need to remove all width and precision fields and flags "%+3.7f" -> "%f". BUT don't strip types like "%I64d" which includes digits. ! "%07I64d" -> "%I64d"
03502 const char* ImParseFormatSanitizeForScanning(const char* fmt_in, char* fmt_out, size_t fmt_out_size)
03503 {
03504     const char* fmt_end = ImParseFormatFindEnd(fmt_in);
03505     const char* fmt_out_begin = fmt_out;
03506     IM_UNUSED(fmt_out_size);
03507     IM_ASSERT((size_t)(fmt_end - fmt_in + 1) < fmt_out_size); // Format is too long, let us know if this happens to you!
03508     bool has_type = false;
03509     while (fmt_in < fmt_end)
03510     {
03511         char c = *fmt_in++;
03512         if (!has_type && ((c >= '0' && c <= '9') || c == '.' || c == '+' || c == '#'))
03513             continue;
03514         has_type |= ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')); // Stop skipping digits
03515         if (c != '\'' && c != '$' && c != '_') // Custom flags provided by stb_sprintf.h. POSIX 2008 also supports '.
03516             *(fmt_out++) = c;
03517     }
03518     *fmt_out = 0; // Zero-terminate
03519     return fmt_out_begin;
03520 }
03521 
03522 template<typename TYPE>
03523 static const char* ImAtoi(const char* src, TYPE* output)
03524 {
03525     int negative = 0;
03526     if (*src == '-') { negative = 1; src++; }
03527     if (*src == '+') { src++; }
03528     TYPE v = 0;
03529     while (*src >= '0' && *src <= '9')
03530         v = (v * 10) + (*src++ - '0');
03531     *output = negative ? -v : v;
03532     return src;
03533 }
03534 
03535 // Parse display precision back from the display format string
03536 // FIXME: This is still used by some navigation code path to infer a minimum tweak step, but we should aim to rework widgets so it isn't needed.
03537 int ImParseFormatPrecision(const char* fmt, int default_precision)
03538 {
03539     fmt = ImParseFormatFindStart(fmt);
03540     if (fmt[0] != '%')
03541         return default_precision;
03542     fmt++;
03543     while (*fmt >= '0' && *fmt <= '9')
03544         fmt++;
03545     int precision = INT_MAX;
03546     if (*fmt == '.')
03547     {
03548         fmt = ImAtoi<int>(fmt + 1, &precision);
03549         if (precision < 0 || precision > 99)
03550             precision = default_precision;
03551     }
03552     if (*fmt == 'e' || *fmt == 'E') // Maximum precision with scientific notation
03553         precision = -1;
03554     if ((*fmt == 'g' || *fmt == 'G') && precision == INT_MAX)
03555         precision = -1;
03556     return (precision == INT_MAX) ? default_precision : precision;
03557 }
