03561 bool ImGui::TempInputText(const ImRect& bb, ImGuiID id, const char* label, char* buf, int buf_size, ImGuiInputTextFlags flags)
03562 {
03563     // On the first frame, g.TempInputTextId == 0, then on subsequent frames it becomes == id.
03564     // We clear ActiveID on the first frame to allow the InputText() taking it back.
03565     ImGuiContext& g = *GImGui;
