03567     if (init)
03568         ClearActiveID();
03569 
03570     g.CurrentWindow->DC.CursorPos = bb.Min;
03571     bool value_changed = InputTextEx(label, NULL, buf, buf_size, bb.GetSize(), flags | ImGuiInputTextFlags_MergedItem);
03572     if (init)
03573     {
03574         // First frame we started displaying the InputText widget, we expect it to take the active id.
