03581 // Note that Drag/Slider functions are only forwarding the min/max values clamping values if the ImGuiSliderFlags_AlwaysClamp flag is set!
03582 // This is intended: this way we allow CTRL+Click manual input to set a value out of bounds, for maximum flexibility.
03583 // However this may not be ideal for all uses, as some user code may break on out of bound values.
03584 bool ImGui::TempInputScalar(const ImRect& bb, ImGuiID id, const char* label, ImGuiDataType data_type, void* p_data, const char* format, const void* p_clamp_min, const void* p_clamp_max)
03585 {
03586     // FIXME: May need to clarify display behavior if format doesn't contain %.
03587     // "%d" -> "%d" / "There are %d items" -> "%d" / "items" -> "%d" (fallback). Also see #6405
03588     const ImGuiDataTypeInfo* type_info = DataTypeGetInfo(data_type);
03589     char fmt_buf[32];
03590     char data_buf[32];
03591     format = ImParseFormatTrimDecorations(format, fmt_buf, IM_ARRAYSIZE(fmt_buf));
03592     if (format[0] == 0)
03593         format = type_info->PrintFmt;
03594     DataTypeFormatString(data_buf, IM_ARRAYSIZE(data_buf), data_type, p_data, format);
03595     ImStrTrimBlanks(data_buf);
03596 
03597     ImGuiInputTextFlags flags = ImGuiInputTextFlags_AutoSelectAll | (ImGuiInputTextFlags)ImGuiInputTextFlags_NoMarkEdited | (ImGuiInputTextFlags)ImGuiInputTextFlags_LocalizeDecimalPoint;
03598 
03599     bool value_changed = false;
03600     if (TempInputText(bb, id, label, data_buf, IM_ARRAYSIZE(data_buf), flags))
03601     {
03602         // Backup old value
03603         size_t data_type_size = type_info->Size;
03604         ImGuiDataTypeStorage data_backup;
03605         memcpy(&data_backup, p_data, data_type_size);
03606 
03607         // Apply new value (or operations) then clamp
03608         DataTypeApplyFromText(data_buf, data_type, p_data, format, NULL);
03609         if (p_clamp_min || p_clamp_max)
03610         {
03611             if (p_clamp_min && p_clamp_max && DataTypeCompare(data_type, p_clamp_min, p_clamp_max) > 0)
03612                 ImSwap(p_clamp_min, p_clamp_max);
03613             DataTypeClamp(data_type, p_data, p_clamp_min, p_clamp_max);
03614         }
03615 
03616         // Only mark as edited if new value is different
03617         value_changed = memcmp(&data_backup, p_data, data_type_size) != 0;
03618         if (value_changed)
03619             MarkItemEdited(id);
03620     }
03621     return value_changed;
03622 }
