03631 // Note: p_data, p_step, p_step_fast are _pointers_ to a memory address holding the data. For an Input widget, p_step and p_step_fast are optional.
03632 // Read code of e.g. InputFloat(), InputInt() etc. or examples in 'Demo->Widgets->Data Types' to understand how to use this function directly.
03633 bool ImGui::InputScalar(const char* label, ImGuiDataType data_type, void* p_data, const void* p_step, const void* p_step_fast, const char* format, ImGuiInputTextFlags flags)
03634 {
03635     ImGuiWindow* window = GetCurrentWindow();
03636     if (window->SkipItems)
03637         return false;
03638 
03639     ImGuiContext& g = *GImGui;
03640     ImGuiStyle& style = g.Style;
03641 
03642     if (format == NULL)
03643         format = DataTypeGetInfo(data_type)->PrintFmt;
03644 
03645     void* p_data_default = (g.NextItemData.Flags & ImGuiNextItemDataFlags_HasRefVal) ? &g.NextItemData.RefVal : &g.DataTypeZeroValue;
03646 
03647     char buf[64];
03648     if ((flags & ImGuiInputTextFlags_DisplayEmptyRefVal) && DataTypeCompare(data_type, p_data, p_data_default) == 0)
03649         buf[0] = 0;
03650     else
03651         DataTypeFormatString(buf, IM_ARRAYSIZE(buf), data_type, p_data, format);
03652 
03653     flags |= ImGuiInputTextFlags_AutoSelectAll | (ImGuiInputTextFlags)ImGuiInputTextFlags_NoMarkEdited; // We call MarkItemEdited() ourselves by comparing the actual data rather than the string.
03654     flags |= (ImGuiInputTextFlags)ImGuiInputTextFlags_LocalizeDecimalPoint;
03655 
03656     bool value_changed = false;
03657     if (p_step == NULL)
03658     {
03659         if (InputText(label, buf, IM_ARRAYSIZE(buf), flags))
03660             value_changed = DataTypeApplyFromText(buf, data_type, p_data, format, (flags & ImGuiInputTextFlags_ParseEmptyRefVal) ? p_data_default : NULL);
03661     }
03662     else
03663     {
03664         const float button_size = GetFrameHeight();
03665 
03666         BeginGroup(); // The only purpose of the group here is to allow the caller to query item data e.g. IsItemActive()
03667         PushID(label);
03668         SetNextItemWidth(ImMax(1.0f, CalcItemWidth() - (button_size + style.ItemInnerSpacing.x) * 2));
03669         if (InputText("", buf, IM_ARRAYSIZE(buf), flags)) // PushId(label) + "" gives us the expected ID from outside point of view
03670             value_changed = DataTypeApplyFromText(buf, data_type, p_data, format, (flags & ImGuiInputTextFlags_ParseEmptyRefVal) ? p_data_default : NULL);
03671         IMGUI_TEST_ENGINE_ITEM_INFO(g.LastItemData.ID, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Inputable);
03672 
03673         // Step buttons
03674         const ImVec2 backup_frame_padding = style.FramePadding;
03675         style.FramePadding.x = style.FramePadding.y;
03676         ImGuiButtonFlags button_flags = ImGuiButtonFlags_Repeat | ImGuiButtonFlags_DontClosePopups;
03677         if (flags & ImGuiInputTextFlags_ReadOnly)
03678             BeginDisabled();
03679         SameLine(0, style.ItemInnerSpacing.x);
03680         if (ButtonEx("-", ImVec2(button_size, button_size), button_flags))
03681         {
03682             DataTypeApplyOp(data_type, '-', p_data, p_data, g.IO.KeyCtrl && p_step_fast ? p_step_fast : p_step);
03683             value_changed = true;
03684         }
03685         SameLine(0, style.ItemInnerSpacing.x);
03686         if (ButtonEx("+", ImVec2(button_size, button_size), button_flags))
03687         {
03688             DataTypeApplyOp(data_type, '+', p_data, p_data, g.IO.KeyCtrl && p_step_fast ? p_step_fast : p_step);
03689             value_changed = true;
03690         }
03691         if (flags & ImGuiInputTextFlags_ReadOnly)
03692             EndDisabled();
03693 
03694         const char* label_end = FindRenderedTextEnd(label);
03695         if (label != label_end)
03696         {
03697             SameLine(0, style.ItemInnerSpacing.x);
03698             TextEx(label, label_end);
03699         }
03700         style.FramePadding = backup_frame_padding;
03701 
03702         PopID();
03703         EndGroup();
03704     }
03705     if (value_changed)
03706         MarkItemEdited(g.LastItemData.ID);
03707 
03708     return value_changed;
03709 }
