03711 bool ImGui::InputScalarN(const char* label, ImGuiDataType data_type, void* p_data, int components, const void* p_step, const void* p_step_fast, const char* format, ImGuiInputTextFlags flags)
03712 {
03713     ImGuiWindow* window = GetCurrentWindow();
03714     if (window->SkipItems)
03715         return false;
03716 
03717     ImGuiContext& g = *GImGui;
03718     bool value_changed = false;
03719     BeginGroup();
03720     PushID(label);
03721     PushMultiItemsWidths(components, CalcItemWidth());
03722     size_t type_size = GDataTypeInfo[data_type].Size;
03723     for (int i = 0; i < components; i++)
03724     {
03725         PushID(i);
03726         if (i > 0)
03727             SameLine(0, g.Style.ItemInnerSpacing.x);
03728         value_changed |= InputScalar("", data_type, p_data, p_step, p_step_fast, format, flags);
03729         PopID();
03730         PopItemWidth();
03731         p_data = (void*)((char*)p_data + type_size);
03732     }
03733     PopID();
03734 
03735     const char* label_end = FindRenderedTextEnd(label);
03736     if (label != label_end)
03737     {
03738         SameLine(0.0f, g.Style.ItemInnerSpacing.x);
03739         TextEx(label, label_end);
03740     }
03741 
03742     EndGroup();
03743     return value_changed;
03744 }
