03823 static int InputTextCalcTextLenAndLineCount(const char* text_begin, const char** out_text_end)
03824 {
03825     int line_count = 0;
03826     const char* s = text_begin;
03827     while (char c = *s++) // We are only matching for \n so we can ignore UTF-8 decoding
03828         if (c == '\n')
03829             line_count++;
03830     s--;
03831     if (s[0] != '\n' && s[0] != '\r')
03832         line_count++;
03833     *out_text_end = s;
03834     return line_count;
03835 }
03836 
03837 static ImVec2 InputTextCalcTextSizeW(ImGuiContext* ctx, const ImWchar* text_begin, const ImWchar* text_end, const ImWchar** remaining, ImVec2* out_offset, bool stop_on_new_line)
03838 {
03839     ImGuiContext& g = *ctx;
03840     ImFont* font = g.Font;
03841     const float line_height = g.FontSize;
03842     const float scale = line_height / font->FontSize;
03843 
03844     ImVec2 text_size = ImVec2(0, 0);
03845     float line_width = 0.0f;
03846 
03847     const ImWchar* s = text_begin;
03848     while (s < text_end)
03849     {
03850         unsigned int c = (unsigned int)(*s++);
03851         if (c == '\n')
03852         {
03853             text_size.x = ImMax(text_size.x, line_width);
03854             text_size.y += line_height;
03855             line_width = 0.0f;
03856             if (stop_on_new_line)
03857                 break;
03858             continue;
03859         }
03860         if (c == '\r')
03861             continue;
03862 
03863         const float char_width = font->GetCharAdvance((ImWchar)c) * scale;
03864         line_width += char_width;
03865     }
03866 
03867     if (text_size.x < line_width)
03868         text_size.x = line_width;
03869 
03870     if (out_offset)
03871         *out_offset = ImVec2(line_width, text_size.y + line_height);  // offset allow for the possibility of sitting after a trailing \n
03872 
03873     if (line_width > 0 || text_size.y == 0.0f)                        // whereas size.y will ignore the trailing \n
03874         text_size.y += line_height;
03875 
03876     if (remaining)
03877         *remaining = s;
03878 
03879     return text_size;
03880 }
