03882 // Wrapper for stb_textedit.h to edit text (our wrapper is for: statically sized buffer, single-line, wchar characters. InputText converts between UTF-8 and wchar)
03883 namespace ImStb
03884 {
03885 
03886 static int     STB_TEXTEDIT_STRINGLEN(const ImGuiInputTextState* obj)                             { return obj->CurLenW; }
03887 static ImWchar STB_TEXTEDIT_GETCHAR(const ImGuiInputTextState* obj, int idx)                      { IM_ASSERT(idx <= obj->CurLenW); return obj->TextW[idx]; }
03888 static float   STB_TEXTEDIT_GETWIDTH(ImGuiInputTextState* obj, int line_start_idx, int char_idx)  { ImWchar c = obj->TextW[line_start_idx + char_idx]; if (c == '\n') return IMSTB_TEXTEDIT_GETWIDTH_NEWLINE; ImGuiContext& g = *obj->Ctx; return g.Font->GetCharAdvance(c) * g.FontScale; }
03889 static int     STB_TEXTEDIT_KEYTOTEXT(int key)                                                    { return key >= 0x200000 ? 0 : key; }
03890 static ImWchar STB_TEXTEDIT_NEWLINE = '\n';
03891 static void    STB_TEXTEDIT_LAYOUTROW(StbTexteditRow* r, ImGuiInputTextState* obj, int line_start_idx)
03892 {
03893     const ImWchar* text = obj->TextW.Data;
03894     const ImWchar* text_remaining = NULL;
03895     const ImVec2 size = InputTextCalcTextSizeW(obj->Ctx, text + line_start_idx, text + obj->CurLenW, &text_remaining, NULL, true);
03896     r->x0 = 0.0f;
03897     r->x1 = size.x;
03898     r->baseline_y_delta = size.y;
03899     r->ymin = 0.0f;
03900     r->ymax = size.y;
03901     r->num_chars = (int)(text_remaining - (text + line_start_idx));
03902 }
03903 
03904 static bool is_separator(unsigned int c)
03905 {
03906     return c==',' || c==';' || c=='(' || c==')' || c=='{' || c=='}' || c=='[' || c==']' || c=='|' || c=='\n' || c=='\r' || c=='.' || c=='!' || c=='\\' || c=='/';
03907 }
03908 
03909 static int is_word_boundary_from_right(ImGuiInputTextState* obj, int idx)
03910 {
03911     // When ImGuiInputTextFlags_Password is set, we don't want actions such as CTRL+Arrow to leak the fact that underlying data are blanks or separators.
03912     if ((obj->Flags & ImGuiInputTextFlags_Password) || idx <= 0)
03913         return 0;
03914 
03915     bool prev_white = ImCharIsBlankW(obj->TextW[idx - 1]);
03916     bool prev_separ = is_separator(obj->TextW[idx - 1]);
03917     bool curr_white = ImCharIsBlankW(obj->TextW[idx]);
03918     bool curr_separ = is_separator(obj->TextW[idx]);
03919     return ((prev_white || prev_separ) && !(curr_separ || curr_white)) || (curr_separ && !prev_separ);
03920 }
03921 static int is_word_boundary_from_left(ImGuiInputTextState* obj, int idx)
03922 {
03923     if ((obj->Flags & ImGuiInputTextFlags_Password) || idx <= 0)
03924         return 0;
03925 
03926     bool prev_white = ImCharIsBlankW(obj->TextW[idx]);
03927     bool prev_separ = is_separator(obj->TextW[idx]);
03928     bool curr_white = ImCharIsBlankW(obj->TextW[idx - 1]);
03929     bool curr_separ = is_separator(obj->TextW[idx - 1]);
03930     return ((prev_white) && !(curr_separ || curr_white)) || (curr_separ && !prev_separ);
03931 }
03932 static int  STB_TEXTEDIT_MOVEWORDLEFT_IMPL(ImGuiInputTextState* obj, int idx)   { idx--; while (idx >= 0 && !is_word_boundary_from_right(obj, idx)) idx--; return idx < 0 ? 0 : idx; }
03933 static int  STB_TEXTEDIT_MOVEWORDRIGHT_MAC(ImGuiInputTextState* obj, int idx)   { idx++; int len = obj->CurLenW; while (idx < len && !is_word_boundary_from_left(obj, idx)) idx++; return idx > len ? len : idx; }
03934 static int  STB_TEXTEDIT_MOVEWORDRIGHT_WIN(ImGuiInputTextState* obj, int idx)   { idx++; int len = obj->CurLenW; while (idx < len && !is_word_boundary_from_right(obj, idx)) idx++; return idx > len ? len : idx; }
03935 static int  STB_TEXTEDIT_MOVEWORDRIGHT_IMPL(ImGuiInputTextState* obj, int idx)  { ImGuiContext& g = *obj->Ctx; if (g.IO.ConfigMacOSXBehaviors) return STB_TEXTEDIT_MOVEWORDRIGHT_MAC(obj, idx); else return STB_TEXTEDIT_MOVEWORDRIGHT_WIN(obj, idx); }
03936 #define STB_TEXTEDIT_MOVEWORDLEFT   STB_TEXTEDIT_MOVEWORDLEFT_IMPL  // They need to be #define for stb_textedit.h
03937 #define STB_TEXTEDIT_MOVEWORDRIGHT  STB_TEXTEDIT_MOVEWORDRIGHT_IMPL
03938 
03939 static void STB_TEXTEDIT_DELETECHARS(ImGuiInputTextState* obj, int pos, int n)
03940 {
03941     ImWchar* dst = obj->TextW.Data + pos;
03942 
03943     // We maintain our buffer length in both UTF-8 and wchar formats
03944     obj->Edited = true;
03945     obj->CurLenA -= ImTextCountUtf8BytesFromStr(dst, dst + n);
03946     obj->CurLenW -= n;
03947 
03948     // Offset remaining text (FIXME-OPT: Use memmove)
03949     const ImWchar* src = obj->TextW.Data + pos + n;
03950     while (ImWchar c = *src++)
03951         *dst++ = c;
03952     *dst = '\0';
03953 }
03954 
03955 static bool STB_TEXTEDIT_INSERTCHARS(ImGuiInputTextState* obj, int pos, const ImWchar* new_text, int new_text_len)
03956 {
03957     const bool is_resizable = (obj->Flags & ImGuiInputTextFlags_CallbackResize) != 0;
03958     const int text_len = obj->CurLenW;
03959     IM_ASSERT(pos <= text_len);
03960 
03961     const int new_text_len_utf8 = ImTextCountUtf8BytesFromStr(new_text, new_text + new_text_len);
03962     if (!is_resizable && (new_text_len_utf8 + obj->CurLenA + 1 > obj->BufCapacityA))
03963         return false;
03964 
03965     // Grow internal buffer if needed
03966     if (new_text_len + text_len + 1 > obj->TextW.Size)
03967     {
03968         if (!is_resizable)
03969             return false;
03970         IM_ASSERT(text_len < obj->TextW.Size);
03971         obj->TextW.resize(text_len + ImClamp(new_text_len * 4, 32, ImMax(256, new_text_len)) + 1);
03972     }
03973 
03974     ImWchar* text = obj->TextW.Data;
03975     if (pos != text_len)
03976         memmove(text + pos + new_text_len, text + pos, (size_t)(text_len - pos) * sizeof(ImWchar));
03977     memcpy(text + pos, new_text, (size_t)new_text_len * sizeof(ImWchar));
03978 
03979     obj->Edited = true;
03980     obj->CurLenW += new_text_len;
03981     obj->CurLenA += new_text_len_utf8;
03982     obj->TextW[obj->CurLenW] = '\0';
03983 
03984     return true;
03985 }
