04010 // stb_textedit internally allows for a single undo record to do addition and deletion, but somehow, calling
04011 // the stb_textedit_paste() function creates two separate records, so we perform it manually. (FIXME: Report to nothings/stb?)
04012 static void stb_textedit_replace(ImGuiInputTextState* str, STB_TexteditState* state, const IMSTB_TEXTEDIT_CHARTYPE* text, int text_len)
04013 {
04014     stb_text_makeundo_replace(str, state, 0, str->CurLenW, text_len);
04015     ImStb::STB_TEXTEDIT_DELETECHARS(str, 0, str->CurLenW);
04016     state->cursor = state->select_start = state->select_end = 0;
04017     if (text_len <= 0)
04018         return;
04019     if (ImStb::STB_TEXTEDIT_INSERTCHARS(str, 0, text, text_len))
04020     {
04021         state->cursor = state->select_start = state->select_end = text_len;
04022         state->has_preferred_x = 0;
04023         return;
04024     }
04025     IM_ASSERT(0); // Failed to insert character, normally shouldn't happen because of how we currently use stb_textedit_replace()
04026 }
