04042 // Public API to manipulate UTF-8 text
04043 // We expose UTF-8 to the user (unlike the STB_TEXTEDIT_* functions which are manipulating wchar)
04044 // FIXME: The existence of this rarely exercised code path is a bit of a nuisance.
04045 void ImGuiInputTextCallbackData::DeleteChars(int pos, int bytes_count)
04046 {
04047     IM_ASSERT(pos + bytes_count <= BufTextLen);
04048     char* dst = Buf + pos;
04049     const char* src = Buf + pos + bytes_count;
04050     while (char c = *src++)
04051         *dst++ = c;
04052     *dst = '\0';
04053 
04054     if (CursorPos >= pos + bytes_count)
04055         CursorPos -= bytes_count;
04056     else if (CursorPos >= pos)
04057         CursorPos = pos;
04058     SelectionStart = SelectionEnd = CursorPos;
04059     BufDirty = true;
04060     BufTextLen -= bytes_count;
04061 }
04062 
04063 void ImGuiInputTextCallbackData::InsertChars(int pos, const char* new_text, const char* new_text_end)
04064 {
04065     // Accept null ranges
04066     if (new_text == new_text_end)
04067         return;
04068 
04069     const bool is_resizable = (Flags & ImGuiInputTextFlags_CallbackResize) != 0;
04070     const int new_text_len = new_text_end ? (int)(new_text_end - new_text) : (int)strlen(new_text);
04071     if (new_text_len + BufTextLen >= BufSize)
04072     {
04073         if (!is_resizable)
04074             return;
04075 
04076         // Contrary to STB_TEXTEDIT_INSERTCHARS() this is working in the UTF8 buffer, hence the mildly similar code (until we remove the U16 buffer altogether!)
04077         ImGuiContext& g = *Ctx;
04078         ImGuiInputTextState* edit_state = &g.InputTextState;
04079         IM_ASSERT(edit_state->ID != 0 && g.ActiveId == edit_state->ID);
04080         IM_ASSERT(Buf == edit_state->TextA.Data);
04081         int new_buf_size = BufTextLen + ImClamp(new_text_len * 4, 32, ImMax(256, new_text_len)) + 1;
04082         edit_state->TextA.reserve(new_buf_size + 1);
04083         Buf = edit_state->TextA.Data;
04084         BufSize = edit_state->BufCapacityA = new_buf_size;
04085     }
04086 
04087     if (BufTextLen != pos)
04088         memmove(Buf + pos + new_text_len, Buf + pos, (size_t)(BufTextLen - pos));
04089     memcpy(Buf + pos, new_text, (size_t)new_text_len * sizeof(char));
04090     Buf[BufTextLen + new_text_len] = '\0';
04091 
04092     if (CursorPos >= pos)
04093         CursorPos += new_text_len;
04094     SelectionStart = SelectionEnd = CursorPos;
04095     BufDirty = true;
04096     BufTextLen += new_text_len;
04097 }
