04099 // Return false to discard a character.
04100 static bool InputTextFilterCharacter(ImGuiContext* ctx, unsigned int* p_char, ImGuiInputTextFlags flags, ImGuiInputTextCallback callback, void* user_data, bool input_source_is_clipboard)
04101 {
04102     unsigned int c = *p_char;
04103 
04104     // Filter non-printable (NB: isprint is unreliable! see #2467)
04105     bool apply_named_filters = true;
04106     if (c < 0x20)
04107     {
04108         bool pass = false;
04109         pass |= (c == '\n') && (flags & ImGuiInputTextFlags_Multiline) != 0; // Note that an Enter KEY will emit \r and be ignored (we poll for KEY in InputText() code)
04110         pass |= (c == '\t') && (flags & ImGuiInputTextFlags_AllowTabInput) != 0;
04111         if (!pass)
04112             return false;
04113         apply_named_filters = false; // Override named filters below so newline and tabs can still be inserted.
04114     }
04115 
04116     if (input_source_is_clipboard == false)
04117     {
04118         // We ignore Ascii representation of delete (emitted from Backspace on OSX, see #2578, #2817)
04119         if (c == 127)
04120             return false;
04121 
04122         // Filter private Unicode range. GLFW on OSX seems to send private characters for special keys like arrow keys (FIXME)
04123         if (c >= 0xE000 && c <= 0xF8FF)
04124             return false;
04125     }
04126 
04127     // Filter Unicode ranges we are not handling in this build
04128     if (c > IM_UNICODE_CODEPOINT_MAX)
04129         return false;
04130 
04131     // Generic named filters
04132     if (apply_named_filters && (flags & (ImGuiInputTextFlags_CharsDecimal | ImGuiInputTextFlags_CharsHexadecimal | ImGuiInputTextFlags_CharsUppercase | ImGuiInputTextFlags_CharsNoBlank | ImGuiInputTextFlags_CharsScientific | (ImGuiInputTextFlags)ImGuiInputTextFlags_LocalizeDecimalPoint)))
04133     {
04134         // The libc allows overriding locale, with e.g. 'setlocale(LC_NUMERIC, "de_DE.UTF-8");' which affect the output/input of printf/scanf to use e.g. ',' instead of '.'.
04135         // The standard mandate that programs starts in the "C" locale where the decimal point is '.'.
04136         // We don't really intend to provide widespread support for it, but out of empathy for people stuck with using odd API, we support the bare minimum aka overriding the decimal point.
04137         // Change the default decimal_point with:
04138         //   ImGui::GetIO()->PlatformLocaleDecimalPoint = *localeconv()->decimal_point;
04139         // Users of non-default decimal point (in particular ',') may be affected by word-selection logic (is_word_boundary_from_right/is_word_boundary_from_left) functions.
04140         ImGuiContext& g = *ctx;
04141         const unsigned c_decimal_point = (unsigned int)g.IO.PlatformLocaleDecimalPoint;
04142         if (flags & (ImGuiInputTextFlags_CharsDecimal | ImGuiInputTextFlags_CharsScientific | (ImGuiInputTextFlags)ImGuiInputTextFlags_LocalizeDecimalPoint))
04143             if (c == '.' || c == ',')
04144                 c = c_decimal_point;
04145 
04146         // Full-width -> half-width conversion for numeric fields (https://en.wikipedia.org/wiki/Halfwidth_and_Fullwidth_Forms_(Unicode_block)
04147         // While this is mostly convenient, this has the side-effect for uninformed users accidentally inputting full-width characters that they may
04148         // scratch their head as to why it works in numerical fields vs in generic text fields it would require support in the font.
04149         if (flags & (ImGuiInputTextFlags_CharsDecimal | ImGuiInputTextFlags_CharsScientific | ImGuiInputTextFlags_CharsHexadecimal))
04150             if (c >= 0xFF01 && c <= 0xFF5E)
04151                 c = c - 0xFF01 + 0x21;
04152 
04153         // Allow 0-9 . - + * /
04154         if (flags & ImGuiInputTextFlags_CharsDecimal)
04155             if (!(c >= '0' && c <= '9') && (c != c_decimal_point) && (c != '-') && (c != '+') && (c != '*') && (c != '/'))
04156                 return false;
04157 
04158         // Allow 0-9 . - + * / e E
04159         if (flags & ImGuiInputTextFlags_CharsScientific)
04160             if (!(c >= '0' && c <= '9') && (c != c_decimal_point) && (c != '-') && (c != '+') && (c != '*') && (c != '/') && (c != 'e') && (c != 'E'))
04161                 return false;
04162 
04163         // Allow 0-9 a-F A-F
04164         if (flags & ImGuiInputTextFlags_CharsHexadecimal)
04165             if (!(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') && !(c >= 'A' && c <= 'F'))
04166                 return false;
04167 
04168         // Turn a-z into A-Z
04169         if (flags & ImGuiInputTextFlags_CharsUppercase)
04170             if (c >= 'a' && c <= 'z')
04171                 c += (unsigned int)('A' - 'a');
04172 
04173         if (flags & ImGuiInputTextFlags_CharsNoBlank)
04174             if (ImCharIsBlankW(c))
04175                 return false;
04176 
04177         *p_char = c;
04178     }
04179 
04180     // Custom callback filter
04181     if (flags & ImGuiInputTextFlags_CallbackCharFilter)
04182     {
04183         ImGuiContext& g = *GImGui;
04184         ImGuiInputTextCallbackData callback_data;
04185         callback_data.Ctx = &g;
04186         callback_data.EventFlag = ImGuiInputTextFlags_CallbackCharFilter;
04187         callback_data.EventChar = (ImWchar)c;
04188         callback_data.Flags = flags;
04189         callback_data.UserData = user_data;
04190         if (callback(&callback_data) != 0)
04191             return false;
04192         *p_char = callback_data.EventChar;
04193         if (!callback_data.EventChar)
04194             return false;
04195     }
04196 
04197     return true;
04198 }
04199 
04200 // Find the shortest single replacement we can make to get the new text from the old text.
04201 // Important: needs to be run before TextW is rewritten with the new characters because calling STB_TEXTEDIT_GETCHAR() at the end.
04202 // FIXME: Ideally we should transition toward (1) making InsertChars()/DeleteChars() update undo-stack (2) discourage (and keep reconcile) or obsolete (and remove reconcile) accessing buffer directly.
04203 static void InputTextReconcileUndoStateAfterUserCallback(ImGuiInputTextState* state, const char* new_buf_a, int new_length_a)
04204 {
04205     ImGuiContext& g = *GImGui;
04206     const ImWchar* old_buf = state->TextW.Data;
04207     const int old_length = state->CurLenW;
04208     const int new_length = ImTextCountCharsFromUtf8(new_buf_a, new_buf_a + new_length_a);
04209     g.TempBuffer.reserve_discard((new_length + 1) * sizeof(ImWchar));
04210     ImWchar* new_buf = (ImWchar*)(void*)g.TempBuffer.Data;
04211     ImTextStrFromUtf8(new_buf, new_length + 1, new_buf_a, new_buf_a + new_length_a);
04212 
04213     const int shorter_length = ImMin(old_length, new_length);
04214     int first_diff;
04215     for (first_diff = 0; first_diff < shorter_length; first_diff++)
04216         if (old_buf[first_diff] != new_buf[first_diff])
04217             break;
04218     if (first_diff == old_length && first_diff == new_length)
04219         return;
04220 
04221     int old_last_diff = old_length - 1;
04222     int new_last_diff = new_length - 1;
04223     for (; old_last_diff >= first_diff && new_last_diff >= first_diff; old_last_diff--, new_last_diff--)
04224         if (old_buf[old_last_diff] != new_buf[new_last_diff])
04225             break;
04226 
04227     const int insert_len = new_last_diff - first_diff + 1;
04228     const int delete_len = old_last_diff - first_diff + 1;
04229     if (insert_len > 0 || delete_len > 0)
04230         if (IMSTB_TEXTEDIT_CHARTYPE* p = stb_text_createundo(&state->Stb.undostate, first_diff, delete_len, insert_len))
04231             for (int i = 0; i < delete_len; i++)
04232                 p[i] = ImStb::STB_TEXTEDIT_GETCHAR(state, first_diff + i);
04233 }
