04235 // As InputText() retain textual data and we currently provide a path for user to not retain it (via local variables)
04236 // we need some form of hook to reapply data back to user buffer on deactivation frame. (#4714)
04237 // It would be more desirable that we discourage users from taking advantage of the "user not retaining data" trick,
04238 // but that more likely be attractive when we do have _NoLiveEdit flag available.
04239 void ImGui::InputTextDeactivateHook(ImGuiID id)
04240 {
04241     ImGuiContext& g = *GImGui;
04242     ImGuiInputTextState* state = &g.InputTextState;
04243     if (id == 0 || state->ID != id)
04244         return;
04245     g.InputTextDeactivatedState.ID = state->ID;
04246     if (state->Flags & ImGuiInputTextFlags_ReadOnly)
04247     {
04248         g.InputTextDeactivatedState.TextA.resize(0); // In theory this data won't be used, but clear to be neat.
04249     }
04250     else
04251     {
04252         IM_ASSERT(state->TextA.Data != 0);
04253         g.InputTextDeactivatedState.TextA.resize(state->CurLenA + 1);
04254         memcpy(g.InputTextDeactivatedState.TextA.Data, state->TextA.Data, state->CurLenA + 1);
04255     }
04256 }
