04258 // Edit a string of text
04259 // - buf_size account for the zero-terminator, so a buf_size of 6 can hold "Hello" but not "Hello!".
04260 //   This is so we can easily call InputText() on static arrays using ARRAYSIZE() and to match
04261 //   Note that in std::string world, capacity() would omit 1 byte used by the zero-terminator.
04262 // - When active, hold on a privately held copy of the text (and apply back to 'buf'). So changing 'buf' while the InputText is active has no effect.
04263 // - If you want to use ImGui::InputText() with std::string, see misc/cpp/imgui_stdlib.h
04264 // (FIXME: Rather confusing and messy function, among the worse part of our codebase, expecting to rewrite a V2 at some point.. Partly because we are
04265 //  doing UTF8 > U16 > UTF8 conversions on the go to easily interface with stb_textedit. Ideally should stay in UTF-8 all the time. See https://github.com/nothings/stb/issues/188)
04266 bool ImGui::InputTextEx(const char* label, const char* hint, char* buf, int buf_size, const ImVec2& size_arg, ImGuiInputTextFlags flags, ImGuiInputTextCallback callback, void* callback_user_data)
04267 {
04268     ImGuiWindow* window = GetCurrentWindow();
04269     if (window->SkipItems)
04270         return false;
04271 
04272     IM_ASSERT(buf != NULL && buf_size >= 0);
04273     IM_ASSERT(!((flags & ImGuiInputTextFlags_CallbackHistory) && (flags & ImGuiInputTextFlags_Multiline)));        // Can't use both together (they both use up/down keys)
04274     IM_ASSERT(!((flags & ImGuiInputTextFlags_CallbackCompletion) && (flags & ImGuiInputTextFlags_AllowTabInput))); // Can't use both together (they both use tab key)
04275 
04276     ImGuiContext& g = *GImGui;
04277     ImGuiIO& io = g.IO;
04278     const ImGuiStyle& style = g.Style;
04279 
04280     const bool RENDER_SELECTION_WHEN_INACTIVE = false;
04281     const bool is_multiline = (flags & ImGuiInputTextFlags_Multiline) != 0;
04282 
04283     if (is_multiline) // Open group before calling GetID() because groups tracks id created within their scope (including the scrollbar)
04284         BeginGroup();
04285     const ImGuiID id = window->GetID(label);
04286     const ImVec2 label_size = CalcTextSize(label, NULL, true);
04287     const ImVec2 frame_size = CalcItemSize(size_arg, CalcItemWidth(), (is_multiline ? g.FontSize * 8.0f : label_size.y) + style.FramePadding.y * 2.0f); // Arbitrary default of 8 lines high for multi-line
04288     const ImVec2 total_size = ImVec2(frame_size.x + (label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f), frame_size.y);
04289 
04290     const ImRect frame_bb(window->DC.CursorPos, window->DC.CursorPos + frame_size);
04291     const ImRect total_bb(frame_bb.Min, frame_bb.Min + total_size);
04292 
04293     ImGuiWindow* draw_window = window;
04294     ImVec2 inner_size = frame_size;
04295     ImGuiLastItemData item_data_backup;
04296     if (is_multiline)
04297     {
04298         ImVec2 backup_pos = window->DC.CursorPos;
04299         ItemSize(total_bb, style.FramePadding.y);
04300         if (!ItemAdd(total_bb, id, &frame_bb, ImGuiItemFlags_Inputable))
04301         {
04302             EndGroup();
04303             return false;
04304         }
04305         item_data_backup = g.LastItemData;
04306         window->DC.CursorPos = backup_pos;
04307 
04308         // Prevent NavActivation from Tabbing when our widget accepts Tab inputs: this allows cycling through widgets without stopping.
04309         if (g.NavActivateId == id && (g.NavActivateFlags & ImGuiActivateFlags_FromTabbing) && (flags & ImGuiInputTextFlags_AllowTabInput))
04310             g.NavActivateId = 0;
04311 
04312         // Prevent NavActivate reactivating in BeginChild() when we are already active.
04313         const ImGuiID backup_activate_id = g.NavActivateId;
04314         if (g.ActiveId == id) // Prevent reactivation
04315             g.NavActivateId = 0;
04316 
04317         // We reproduce the contents of BeginChildFrame() in order to provide 'label' so our window internal data are easier to read/debug.
04318         PushStyleColor(ImGuiCol_ChildBg, style.Colors[ImGuiCol_FrameBg]);
04319         PushStyleVar(ImGuiStyleVar_ChildRounding, style.FrameRounding);
04320         PushStyleVar(ImGuiStyleVar_ChildBorderSize, style.FrameBorderSize);
04321         PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(0, 0)); // Ensure no clip rect so mouse hover can reach FramePadding edges
04322         bool child_visible = BeginChildEx(label, id, frame_bb.GetSize(), ImGuiChildFlags_Border, ImGuiWindowFlags_NoMove);
04323         g.NavActivateId = backup_activate_id;
04324         PopStyleVar(3);
04325         PopStyleColor();
04326         if (!child_visible)
04327         {
04328             EndChild();
04329             EndGroup();
04330             return false;
04331         }
04332         draw_window = g.CurrentWindow; // Child window
04333         draw_window->DC.NavLayersActiveMaskNext |= (1 << draw_window->DC.NavLayerCurrent); // This is to ensure that EndChild() will display a navigation highlight so we can "enter" into it.
04334         draw_window->DC.CursorPos += style.FramePadding;
04335         inner_size.x -= draw_window->ScrollbarSizes.x;
04336     }
04337     else
04338     {
04339         // Support for internal ImGuiInputTextFlags_MergedItem flag, which could be redesigned as an ItemFlags if needed (with test performed in ItemAdd)
04340         ItemSize(total_bb, style.FramePadding.y);
04341         if (!(flags & ImGuiInputTextFlags_MergedItem))
04342             if (!ItemAdd(total_bb, id, &frame_bb, ImGuiItemFlags_Inputable))
04343                 return false;
04344     }
04345     const bool hovered = ItemHoverable(frame_bb, id, g.LastItemData.InFlags);
04346     if (hovered)
04347         g.MouseCursor = ImGuiMouseCursor_TextInput;
04348 
04349     // We are only allowed to access the state if we are already the active widget.
04350     ImGuiInputTextState* state = GetInputTextState(id);
04351 
04352     if (g.LastItemData.InFlags & ImGuiItemFlags_ReadOnly)
04353         flags |= ImGuiInputTextFlags_ReadOnly;
04354     const bool is_readonly = (flags & ImGuiInputTextFlags_ReadOnly) != 0;
04355     const bool is_password = (flags & ImGuiInputTextFlags_Password) != 0;
04356     const bool is_undoable = (flags & ImGuiInputTextFlags_NoUndoRedo) == 0;
04357     const bool is_resizable = (flags & ImGuiInputTextFlags_CallbackResize) != 0;
04358     if (is_resizable)
