04768                 // Filter pasted buffer
04769                 const int clipboard_len = (int)strlen(clipboard);
04770                 ImWchar* clipboard_filtered = (ImWchar*)IM_ALLOC((clipboard_len + 1) * sizeof(ImWchar));
04771                 int clipboard_filtered_len = 0;
04772                 for (const char* s = clipboard; *s != 0; )
04773                 {
04774                     unsigned int c;
04775                     s += ImTextCharFromUtf8(&c, s, NULL);
04776                     if (!InputTextFilterCharacter(&g, &c, flags, callback, callback_user_data, true))
04777                         continue;
04778                     clipboard_filtered[clipboard_filtered_len++] = (ImWchar)c;
04779                 }
04780                 clipboard_filtered[clipboard_filtered_len] = 0;
04781                 if (clipboard_filtered_len > 0) // If everything was filtered, ignore the pasting operation
04782                 {
04783                     stb_textedit_paste(state, &state->Stb, clipboard_filtered, clipboard_filtered_len);
04784                     state->CursorFollow = true;
04785                 }
04786                 MemFree(clipboard_filtered);
04787             }
04788         }
04789 
04790         // Update render selection flag after events have been handled, so selection highlight can be displayed during the same frame.
04791         render_selection |= state->HasSelection() && (RENDER_SELECTION_WHEN_INACTIVE || render_cursor);
04792     }
04793 
04794     // Process callbacks and apply result back to user's buffer.
04795     const char* apply_new_text = NULL;
04796     int apply_new_text_length = 0;
04797     if (g.ActiveId == id)
04798     {
04799         IM_ASSERT(state != NULL);
04800         if (revert_edit && !is_readonly)
04801         {
04802             if (flags & ImGuiInputTextFlags_EscapeClearsAll)
04803             {
04804                 // Clear input
04805                 IM_ASSERT(buf[0] != 0);
04806                 apply_new_text = "";
04807                 apply_new_text_length = 0;
04808                 value_changed = true;
04809                 IMSTB_TEXTEDIT_CHARTYPE empty_string;
04810                 stb_textedit_replace(state, &state->Stb, &empty_string, 0);
04811             }
04812             else if (strcmp(buf, state->InitialTextA.Data) != 0)
04813             {
04814                 // Restore initial value. Only return true if restoring to the initial value changes the current buffer contents.
04815                 // Push records into the undo stack so we can CTRL+Z the revert operation itself
04816                 apply_new_text = state->InitialTextA.Data;
04817                 apply_new_text_length = state->InitialTextA.Size - 1;
04818                 value_changed = true;
04819                 ImVector<ImWchar> w_text;
04820                 if (apply_new_text_length > 0)
04821                 {
04822                     w_text.resize(ImTextCountCharsFromUtf8(apply_new_text, apply_new_text + apply_new_text_length) + 1);
04823                     ImTextStrFromUtf8(w_text.Data, w_text.Size, apply_new_text, apply_new_text + apply_new_text_length);
04824                 }
04825                 stb_textedit_replace(state, &state->Stb, w_text.Data, (apply_new_text_length > 0) ? (w_text.Size - 1) : 0);
04826             }
04827         }
04828 
04829         // Apply ASCII value
04830         if (!is_readonly)
04831         {
04832             state->TextAIsValid = true;
04833             state->TextA.resize(state->TextW.Size * 4 + 1);
04834             ImTextStrToUtf8(state->TextA.Data, state->TextA.Size, state->TextW.Data, NULL);
04835         }
04836 
04837         // When using 'ImGuiInputTextFlags_EnterReturnsTrue' as a special case we reapply the live buffer back to the input buffer
04838         // before clearing ActiveId, even though strictly speaking it wasn't modified on this frame.
04839         // If we didn't do that, code like InputInt() with ImGuiInputTextFlags_EnterReturnsTrue would fail.
04840         // This also allows the user to use InputText() with ImGuiInputTextFlags_EnterReturnsTrue without maintaining any user-side storage
04841         // (please note that if you use this property along ImGuiInputTextFlags_CallbackResize you can end up with your temporary string object
04842         // unnecessarily allocating once a frame, either store your string data, either if you don't then don't use ImGuiInputTextFlags_CallbackResize).
04843         const bool apply_edit_back_to_user_buffer = !revert_edit || (validated && (flags & ImGuiInputTextFlags_EnterReturnsTrue) != 0);
04844         if (apply_edit_back_to_user_buffer)
04845         {
04846             // Apply new value immediately - copy modified buffer back
04847             // Note that as soon as the input box is active, the in-widget value gets priority over any underlying modification of the input buffer
04848             // FIXME: We actually always render 'buf' when calling DrawList->AddText, making the comment above incorrect.
04849             // FIXME-OPT: CPU waste to do this every time the widget is active, should mark dirty state from the stb_textedit callbacks.
04850 
04851             // User callback
04852             if ((flags & (ImGuiInputTextFlags_CallbackCompletion | ImGuiInputTextFlags_CallbackHistory | ImGuiInputTextFlags_CallbackEdit | ImGuiInputTextFlags_CallbackAlways)) != 0)
04853             {
04854                 IM_ASSERT(callback != NULL);
04855 
04856                 // The reason we specify the usage semantic (Completion/History) is that Completion needs to disable keyboard TABBING at the moment.
04857                 ImGuiInputTextFlags event_flag = 0;
04858                 ImGuiKey event_key = ImGuiKey_None;
04859                 if ((flags & ImGuiInputTextFlags_CallbackCompletion) != 0 && Shortcut(ImGuiKey_Tab, 0, id))
04860                 {
04861                     event_flag = ImGuiInputTextFlags_CallbackCompletion;
04862                     event_key = ImGuiKey_Tab;
04863                 }
04864                 else if ((flags & ImGuiInputTextFlags_CallbackHistory) != 0 && IsKeyPressed(ImGuiKey_UpArrow))
04865                 {
04866                     event_flag = ImGuiInputTextFlags_CallbackHistory;
04867                     event_key = ImGuiKey_UpArrow;
04868                 }
04869                 else if ((flags & ImGuiInputTextFlags_CallbackHistory) != 0 && IsKeyPressed(ImGuiKey_DownArrow))
04870                 {
04871                     event_flag = ImGuiInputTextFlags_CallbackHistory;
04872                     event_key = ImGuiKey_DownArrow;
04873                 }
04874                 else if ((flags & ImGuiInputTextFlags_CallbackEdit) && state->Edited)
04875                 {
04876                     event_flag = ImGuiInputTextFlags_CallbackEdit;
04877                 }
04878                 else if (flags & ImGuiInputTextFlags_CallbackAlways)
04879                 {
04880                     event_flag = ImGuiInputTextFlags_CallbackAlways;
04881                 }
04882 
04883                 if (event_flag)
04884                 {
04885                     ImGuiInputTextCallbackData callback_data;
04886                     callback_data.Ctx = &g;
04887                     callback_data.EventFlag = event_flag;
04888                     callback_data.Flags = flags;
04889                     callback_data.UserData = callback_user_data;
04890 
04891                     char* callback_buf = is_readonly ? buf : state->TextA.Data;
04892                     callback_data.EventKey = event_key;
04893                     callback_data.Buf = callback_buf;
04894                     callback_data.BufTextLen = state->CurLenA;
04895                     callback_data.BufSize = state->BufCapacityA;
04896                     callback_data.BufDirty = false;
04897 
04898                     // We have to convert from wchar-positions to UTF-8-positions, which can be pretty slow (an incentive to ditch the ImWchar buffer, see https://github.com/nothings/stb/issues/188)
04899                     ImWchar* text = state->TextW.Data;
04900                     const int utf8_cursor_pos = callback_data.CursorPos = ImTextCountUtf8BytesFromStr(text, text + state->Stb.cursor);
04901                     const int utf8_selection_start = callback_data.SelectionStart = ImTextCountUtf8BytesFromStr(text, text + state->Stb.select_start);
04902                     const int utf8_selection_end = callback_data.SelectionEnd = ImTextCountUtf8BytesFromStr(text, text + state->Stb.select_end);
04903 
04904                     // Call user code
04905                     callback(&callback_data);
04906 
04907                     // Read back what user may have modified
04908                     callback_buf = is_readonly ? buf : state->TextA.Data; // Pointer may have been invalidated by a resize callback
04909                     IM_ASSERT(callback_data.Buf == callback_buf);         // Invalid to modify those fields
04910                     IM_ASSERT(callback_data.BufSize == state->BufCapacityA);
04911                     IM_ASSERT(callback_data.Flags == flags);
04912                     const bool buf_dirty = callback_data.BufDirty;
04913                     if (callback_data.CursorPos != utf8_cursor_pos || buf_dirty)            { state->Stb.cursor = ImTextCountCharsFromUtf8(callback_data.Buf, callback_data.Buf + callback_data.CursorPos); state->CursorFollow = true; }
04914                     if (callback_data.SelectionStart != utf8_selection_start || buf_dirty)  { state->Stb.select_start = (callback_data.SelectionStart == callback_data.CursorPos) ? state->Stb.cursor : ImTextCountCharsFromUtf8(callback_data.Buf, callback_data.Buf + callback_data.SelectionStart); }
04915                     if (callback_data.SelectionEnd != utf8_selection_end || buf_dirty)      { state->Stb.select_end = (callback_data.SelectionEnd == callback_data.SelectionStart) ? state->Stb.select_start : ImTextCountCharsFromUtf8(callback_data.Buf, callback_data.Buf + callback_data.SelectionEnd); }
04916                     if (buf_dirty)
04917                     {
04918                         IM_ASSERT(!is_readonly);
04919                         IM_ASSERT(callback_data.BufTextLen == (int)strlen(callback_data.Buf)); // You need to maintain BufTextLen if you change the text!
04920                         InputTextReconcileUndoStateAfterUserCallback(state, callback_data.Buf, callback_data.BufTextLen); // FIXME: Move the rest of this block inside function and rename to InputTextReconcileStateAfterUserCallback() ?
04921                         if (callback_data.BufTextLen > backup_current_text_length && is_resizable)
04922                             state->TextW.resize(state->TextW.Size + (callback_data.BufTextLen - backup_current_text_length)); // Worse case scenario resize
04923                         state->CurLenW = ImTextStrFromUtf8(state->TextW.Data, state->TextW.Size, callback_data.Buf, NULL);
04924                         state->CurLenA = callback_data.BufTextLen;  // Assume correct length and valid UTF-8 from user, saves us an extra strlen()
04925                         state->CursorAnimReset();
04926                     }
04927                 }
04928             }
04929 
04930             // Will copy result string if modified
04931             if (!is_readonly && strcmp(state->TextA.Data, buf) != 0)
04932             {
04933                 apply_new_text = state->TextA.Data;
04934                 apply_new_text_length = state->CurLenA;
04935                 value_changed = true;
04936             }
04937         }
04938     }
04939 
04940     // Handle reapplying final data on deactivation (see InputTextDeactivateHook() for details)
04941     if (g.InputTextDeactivatedState.ID == id)
04942     {
04943         if (g.ActiveId != id && IsItemDeactivatedAfterEdit() && !is_readonly && strcmp(g.InputTextDeactivatedState.TextA.Data, buf) != 0)
04944         {
04945             apply_new_text = g.InputTextDeactivatedState.TextA.Data;
04946             apply_new_text_length = g.InputTextDeactivatedState.TextA.Size - 1;
04947             value_changed = true;
04948             //IMGUI_DEBUG_LOG("InputText(): apply Deactivated data for 0x%08X: \"%.*s\".\n", id, apply_new_text_length, apply_new_text);
04949         }
04950         g.InputTextDeactivatedState.ID = 0;
04951     }
04952 
04953     // Copy result to user buffer. This can currently only happen when (g.ActiveId == id)
04954     if (apply_new_text != NULL)
04955     {
04956         // We cannot test for 'backup_current_text_length != apply_new_text_length' here because we have no guarantee that the size
04957         // of our owned buffer matches the size of the string object held by the user, and by design we allow InputText() to be used
04958         // without any storage on user's side.
04959         IM_ASSERT(apply_new_text_length >= 0);
04960         if (is_resizable)
04961         {
04962             ImGuiInputTextCallbackData callback_data;
04963             callback_data.Ctx = &g;
04964             callback_data.EventFlag = ImGuiInputTextFlags_CallbackResize;
04965             callback_data.Flags = flags;
04966             callback_data.Buf = buf;
04967             callback_data.BufTextLen = apply_new_text_length;
04968             callback_data.BufSize = ImMax(buf_size, apply_new_text_length + 1);
04969             callback_data.UserData = callback_user_data;
04970             callback(&callback_data);
04971             buf = callback_data.Buf;
04972             buf_size = callback_data.BufSize;
04973             apply_new_text_length = ImMin(callback_data.BufTextLen, buf_size - 1);
04974             IM_ASSERT(apply_new_text_length <= buf_size);
04975         }
04976         //IMGUI_DEBUG_PRINT("InputText(\"%s\"): apply_new_text length %d\n", label, apply_new_text_length);
04977 
04978         // If the underlying buffer resize was denied or not carried to the next frame, apply_new_text_length+1 may be >= buf_size.
04979         ImStrncpy(buf, apply_new_text, ImMin(apply_new_text_length + 1, buf_size));
04980     }
04981 
04982     // Release active ID at the end of the function (so e.g. pressing Return still does a final application of the value)
04983     // Otherwise request text input ahead for next frame.
04984     if (g.ActiveId == id && clear_active_id)
04985         ClearActiveID();
04986     else if (g.ActiveId == id)
04987         g.WantTextInputNextFrame = 1;
04988 
04989     // Render frame
04990     if (!is_multiline)
04991     {
04992         RenderNavHighlight(frame_bb, id);
04993         RenderFrame(frame_bb.Min, frame_bb.Max, GetColorU32(ImGuiCol_FrameBg), true, style.FrameRounding);
04994     }
04995 
04996     const ImVec4 clip_rect(frame_bb.Min.x, frame_bb.Min.y, frame_bb.Min.x + inner_size.x, frame_bb.Min.y + inner_size.y); // Not using frame_bb.Max because we have adjusted size
04997     ImVec2 draw_pos = is_multiline ? draw_window->DC.CursorPos : frame_bb.Min + style.FramePadding;
04998     ImVec2 text_size(0.0f, 0.0f);
04999 
05000     // Set upper limit of single-line InputTextEx() at 2 million characters strings. The current pathological worst case is a long line
05001     // without any carriage return, which would makes ImFont::RenderText() reserve too many vertices and probably crash. Avoid it altogether.
05002     // Note that we only use this limit on single-line InputText(), so a pathologically large line on a InputTextMultiline() would still crash.
05003     const int buf_display_max_length = 2 * 1024 * 1024;
05004     const char* buf_display = buf_display_from_state ? state->TextA.Data : buf; //-V595
05005     const char* buf_display_end = NULL; // We have specialized paths below for setting the length
05006     if (is_displaying_hint)
05007     {
05008         buf_display = hint;
05009         buf_display_end = hint + strlen(hint);
05010     }
05011 
05012     // Render text. We currently only render selection when the widget is active or while scrolling.
05013     // FIXME: We could remove the '&& render_cursor' to keep rendering selection when inactive.
05014     if (render_cursor || render_selection)
05015     {
05016         IM_ASSERT(state != NULL);
05017         if (!is_displaying_hint)
05018             buf_display_end = buf_display + state->CurLenA;
05019 
05020         // Render text (with cursor and selection)
05021         // This is going to be messy. We need to:
05022         // - Display the text (this alone can be more easily clipped)
05023         // - Handle scrolling, highlight selection, display cursor (those all requires some form of 1d->2d cursor position calculation)
05024         // - Measure text height (for scrollbar)
05025         // We are attempting to do most of that in **one main pass** to minimize the computation cost (non-negligible for large amount of text) + 2nd pass for selection rendering (we could merge them by an extra refactoring effort)
05026         // FIXME: This should occur on buf_display but we'd need to maintain cursor/select_start/select_end for UTF-8.
05027         const ImWchar* text_begin = state->TextW.Data;
05028         ImVec2 cursor_offset, select_start_offset;
05029 
05030         {
05031             // Find lines numbers straddling 'cursor' (slot 0) and 'select_start' (slot 1) positions.
05032             const ImWchar* searches_input_ptr[2] = { NULL, NULL };
05033             int searches_result_line_no[2] = { -1000, -1000 };
05034             int searches_remaining = 0;
05035             if (render_cursor)
05036             {
05037                 searches_input_ptr[0] = text_begin + state->Stb.cursor;
05038                 searches_result_line_no[0] = -1;
05039                 searches_remaining++;
05040             }
05041             if (render_selection)
05042             {
05043                 searches_input_ptr[1] = text_begin + ImMin(state->Stb.select_start, state->Stb.select_end);
05044                 searches_result_line_no[1] = -1;
05045                 searches_remaining++;
05046             }
05047 
05048             // Iterate all lines to find our line numbers
05049             // In multi-line mode, we never exit the loop until all lines are counted, so add one extra to the searches_remaining counter.
05050             searches_remaining += is_multiline ? 1 : 0;
05051             int line_count = 0;
05052             //for (const ImWchar* s = text_begin; (s = (const ImWchar*)wcschr((const wchar_t*)s, (wchar_t)'\n')) != NULL; s++)  // FIXME-OPT: Could use this when wchar_t are 16-bit
05053             for (const ImWchar* s = text_begin; *s != 0; s++)
05054                 if (*s == '\n')
05055                 {
05056                     line_count++;
05057                     if (searches_result_line_no[0] == -1 && s >= searches_input_ptr[0]) { searches_result_line_no[0] = line_count; if (--searches_remaining <= 0) break; }
05058                     if (searches_result_line_no[1] == -1 && s >= searches_input_ptr[1]) { searches_result_line_no[1] = line_count; if (--searches_remaining <= 0) break; }
05059                 }
05060             line_count++;
05061             if (searches_result_line_no[0] == -1)
05062                 searches_result_line_no[0] = line_count;
05063             if (searches_result_line_no[1] == -1)
05064                 searches_result_line_no[1] = line_count;
05065 
05066             // Calculate 2d position by finding the beginning of the line and measuring distance
05067             cursor_offset.x = InputTextCalcTextSizeW(&g, ImStrbolW(searches_input_ptr[0], text_begin), searches_input_ptr[0]).x;
05068             cursor_offset.y = searches_result_line_no[0] * g.FontSize;
05069             if (searches_result_line_no[1] >= 0)
05070             {
05071                 select_start_offset.x = InputTextCalcTextSizeW(&g, ImStrbolW(searches_input_ptr[1], text_begin), searches_input_ptr[1]).x;
05072                 select_start_offset.y = searches_result_line_no[1] * g.FontSize;
05073             }
05074 
05075             // Store text height (note that we haven't calculated text width at all, see GitHub issues #383, #1224)
05076             if (is_multiline)
05077                 text_size = ImVec2(inner_size.x, line_count * g.FontSize);
05078         }
05079 
05080         // Scroll
05081         if (render_cursor && state->CursorFollow)
05082         {
05083             // Horizontal scroll in chunks of quarter width
05084             if (!(flags & ImGuiInputTextFlags_NoHorizontalScroll))
05085             {
05086                 const float scroll_increment_x = inner_size.x * 0.25f;
05087                 const float visible_width = inner_size.x - style.FramePadding.x;
05088                 if (cursor_offset.x < state->ScrollX)
05089                     state->ScrollX = IM_TRUNC(ImMax(0.0f, cursor_offset.x - scroll_increment_x));
05090                 else if (cursor_offset.x - visible_width >= state->ScrollX)
05091                     state->ScrollX = IM_TRUNC(cursor_offset.x - visible_width + scroll_increment_x);
05092             }
05093             else
05094             {
05095                 state->ScrollX = 0.0f;
05096             }
05097 
05098             // Vertical scroll
05099             if (is_multiline)
05100             {
05101                 // Test if cursor is vertically visible
05102                 if (cursor_offset.y - g.FontSize < scroll_y)
05103                     scroll_y = ImMax(0.0f, cursor_offset.y - g.FontSize);
05104                 else if (cursor_offset.y - (inner_size.y - style.FramePadding.y * 2.0f) >= scroll_y)
05105                     scroll_y = cursor_offset.y - inner_size.y + style.FramePadding.y * 2.0f;
05106                 const float scroll_max_y = ImMax((text_size.y + style.FramePadding.y * 2.0f) - inner_size.y, 0.0f);
05107                 scroll_y = ImClamp(scroll_y, 0.0f, scroll_max_y);
05108                 draw_pos.y += (draw_window->Scroll.y - scroll_y);   // Manipulate cursor pos immediately avoid a frame of lag
05109                 draw_window->Scroll.y = scroll_y;
05110             }
05111 
05112             state->CursorFollow = false;
05113         }
05114 
05115         // Draw selection
05116         const ImVec2 draw_scroll = ImVec2(state->ScrollX, 0.0f);
