05118         {
05119             const ImWchar* text_selected_begin = text_begin + ImMin(state->Stb.select_start, state->Stb.select_end);
05120             const ImWchar* text_selected_end = text_begin + ImMax(state->Stb.select_start, state->Stb.select_end);
05121 
05122             ImU32 bg_color = GetColorU32(ImGuiCol_TextSelectedBg, render_cursor ? 1.0f : 0.6f); // FIXME: current code flow mandate that render_cursor is always true here, we are leaving the transparent one for tests.
05123             float bg_offy_up = is_multiline ? 0.0f : -1.0f;    // FIXME: those offsets should be part of the style? they don't play so well with multi-line selection.
05124             float bg_offy_dn = is_multiline ? 0.0f : 2.0f;
05125             ImVec2 rect_pos = draw_pos + select_start_offset - draw_scroll;
05126             for (const ImWchar* p = text_selected_begin; p < text_selected_end; )
05127             {
05128                 if (rect_pos.y > clip_rect.w + g.FontSize)
05129                     break;
05130                 if (rect_pos.y < clip_rect.y)
05131                 {
05132                     //p = (const ImWchar*)wmemchr((const wchar_t*)p, '\n', text_selected_end - p);  // FIXME-OPT: Could use this when wchar_t are 16-bit
05133                     //p = p ? p + 1 : text_selected_end;
05134                     while (p < text_selected_end)
05135                         if (*p++ == '\n')
05136                             break;
05137                 }
05138                 else
05139                 {
05140                     ImVec2 rect_size = InputTextCalcTextSizeW(&g, p, text_selected_end, &p, NULL, true);
05141                     if (rect_size.x <= 0.0f) rect_size.x = IM_TRUNC(g.Font->GetCharAdvance((ImWchar)' ') * 0.50f); // So we can see selected empty lines
05142                     ImRect rect(rect_pos + ImVec2(0.0f, bg_offy_up - g.FontSize), rect_pos + ImVec2(rect_size.x, bg_offy_dn));
05143                     rect.ClipWith(clip_rect);
05144                     if (rect.Overlaps(clip_rect))
05145                         draw_window->DrawList->AddRectFilled(rect.Min, rect.Max, bg_color);
05146                 }
05147                 rect_pos.x = draw_pos.x - draw_scroll.x;
05148                 rect_pos.y += g.FontSize;
05149             }
05150         }
05151 
05152         // We test for 'buf_display_max_length' as a way to avoid some pathological cases (e.g. single-line 1 MB string) which would make ImDrawList crash.
05153         if (is_multiline || (buf_display_end - buf_display) < buf_display_max_length)
05154         {
05155             ImU32 col = GetColorU32(is_displaying_hint ? ImGuiCol_TextDisabled : ImGuiCol_Text);
05156             draw_window->DrawList->AddText(g.Font, g.FontSize, draw_pos - draw_scroll, col, buf_display, buf_display_end, 0.0f, is_multiline ? NULL : &clip_rect);
05157         }
05158 
05159         // Draw blinking cursor
05160         if (render_cursor)
05161         {
05162             state->CursorAnim += io.DeltaTime;
05163             bool cursor_is_visible = (!g.IO.ConfigInputTextCursorBlink) || (state->CursorAnim <= 0.0f) || ImFmod(state->CursorAnim, 1.20f) <= 0.80f;
05164             ImVec2 cursor_screen_pos = ImTrunc(draw_pos + cursor_offset - draw_scroll);
05165             ImRect cursor_screen_rect(cursor_screen_pos.x, cursor_screen_pos.y - g.FontSize + 0.5f, cursor_screen_pos.x + 1.0f, cursor_screen_pos.y - 1.5f);
05166             if (cursor_is_visible && cursor_screen_rect.Overlaps(clip_rect))
05167                 draw_window->DrawList->AddLine(cursor_screen_rect.Min, cursor_screen_rect.GetBL(), GetColorU32(ImGuiCol_Text));
05168 
05169             // Notify OS of text input position for advanced IME (-1 x offset so that Windows IME can cover our cursor. Bit of an extra nicety.)
05170             if (!is_readonly)
05171             {
05172                 g.PlatformImeData.WantVisible = true;
05173                 g.PlatformImeData.InputPos = ImVec2(cursor_screen_pos.x - 1.0f, cursor_screen_pos.y - g.FontSize);
05174                 g.PlatformImeData.InputLineHeight = g.FontSize;
05175                 g.PlatformImeViewport = window->Viewport->ID;
05176             }
05177         }
05178     }
05179     else
05180     {
05181         // Render text only (no selection, no cursor)
05182         if (is_multiline)
05183             text_size = ImVec2(inner_size.x, InputTextCalcTextLenAndLineCount(buf_display, &buf_display_end) * g.FontSize); // We don't need width
05184         else if (!is_displaying_hint && g.ActiveId == id)
05185             buf_display_end = buf_display + state->CurLenA;
05186         else if (!is_displaying_hint)
05187             buf_display_end = buf_display + strlen(buf_display);
05188 
05189         if (is_multiline || (buf_display_end - buf_display) < buf_display_max_length)
05190         {
05191             ImU32 col = GetColorU32(is_displaying_hint ? ImGuiCol_TextDisabled : ImGuiCol_Text);
05192             draw_window->DrawList->AddText(g.Font, g.FontSize, draw_pos, col, buf_display, buf_display_end, 0.0f, is_multiline ? NULL : &clip_rect);
05193         }
05194     }
05195 
05196     if (is_password && !is_displaying_hint)
05197         PopFont();
05198 
05199     if (is_multiline)
05200     {
05201         // For focus requests to work on our multiline we need to ensure our child ItemAdd() call specifies the ImGuiItemFlags_Inputable (ref issue #4761)...
05202         Dummy(ImVec2(text_size.x, text_size.y + style.FramePadding.y));
05203         g.NextItemData.ItemFlags |= ImGuiItemFlags_Inputable | ImGuiItemFlags_NoTabStop;
05204         EndChild();
05205         item_data_backup.StatusFlags |= (g.LastItemData.StatusFlags & ImGuiItemStatusFlags_HoveredWindow);
05206 
05207         // ...and then we need to undo the group overriding last item data, which gets a bit messy as EndGroup() tries to forward scrollbar being active...
05208         // FIXME: This quite messy/tricky, should attempt to get rid of the child window.
05209         EndGroup();
05210         if (g.LastItemData.ID == 0)
05211         {
05212             g.LastItemData.ID = id;
05213             g.LastItemData.InFlags = item_data_backup.InFlags;
05214             g.LastItemData.StatusFlags = item_data_backup.StatusFlags;
05215         }
05216     }
05217 
05218     // Log as text
05219     if (g.LogEnabled && (!is_password || is_displaying_hint))
05220     {
05221         LogSetNextTextDecoration("{", "}");
05222         LogRenderedText(&draw_pos, buf_display, buf_display_end);
05223     }
05224 
05225     if (label_size.x > 0)
05226         RenderText(ImVec2(frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y), label);
05227 
05228     if (value_changed && !(flags & ImGuiInputTextFlags_NoMarkEdited))
05229         MarkItemEdited(id);
05230 
05231     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Inputable);
05232     if ((flags & ImGuiInputTextFlags_EnterReturnsTrue) != 0)
05233         return validated;
05234     else
05235         return value_changed;
05236 }
