05238 void ImGui::DebugNodeInputTextState(ImGuiInputTextState* state)
05239 {
05240 #ifndef IMGUI_DISABLE_DEBUG_TOOLS
05241     ImGuiContext& g = *GImGui;
05242     ImStb::STB_TexteditState* stb_state = &state->Stb;
05243     ImStb::StbUndoState* undo_state = &stb_state->undostate;
05244     Text("ID: 0x%08X, ActiveID: 0x%08X", state->ID, g.ActiveId);
05245     DebugLocateItemOnHover(state->ID);
05246     Text("CurLenW: %d, CurLenA: %d, Cursor: %d, Selection: %d..%d", state->CurLenW, state->CurLenA, stb_state->cursor, stb_state->select_start, stb_state->select_end);
05247     Text("has_preferred_x: %d (%.2f)", stb_state->has_preferred_x, stb_state->preferred_x);
05248     Text("undo_point: %d, redo_point: %d, undo_char_point: %d, redo_char_point: %d", undo_state->undo_point, undo_state->redo_point, undo_state->undo_char_point, undo_state->redo_char_point);
05249     if (BeginChild("undopoints", ImVec2(0.0f, GetTextLineHeight() * 10), ImGuiChildFlags_Border | ImGuiChildFlags_ResizeY)) // Visualize undo state
05250     {
05251         PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0, 0));
05252         for (int n = 0; n < IMSTB_TEXTEDIT_UNDOSTATECOUNT; n++)
05253         {
05254             ImStb::StbUndoRecord* undo_rec = &undo_state->undo_rec[n];
05255             const char undo_rec_type = (n < undo_state->undo_point) ? 'u' : (n >= undo_state->redo_point) ? 'r' : ' ';
05256             if (undo_rec_type == ' ')
05257                 BeginDisabled();
05258             char buf[64] = "";
05259             if (undo_rec_type != ' ' && undo_rec->char_storage != -1)
05260                 ImTextStrToUtf8(buf, IM_ARRAYSIZE(buf), undo_state->undo_char + undo_rec->char_storage, undo_state->undo_char + undo_rec->char_storage + undo_rec->insert_length);
05261             Text("%c [%02d] where %03d, insert %03d, delete %03d, char_storage %03d \"%s\"",
05262                 undo_rec_type, n, undo_rec->where, undo_rec->insert_length, undo_rec->delete_length, undo_rec->char_storage, buf);
05263             if (undo_rec_type == ' ')
05264                 EndDisabled();
05265         }
05266         PopStyleVar();
05267     }
05268     EndChild();
05269 #else
05270     IM_UNUSED(state);
05271 #endif
05272 }
