05289 bool ImGui::ColorEdit3(const char* label, float col[3], ImGuiColorEditFlags flags)
05290 {
05291     return ColorEdit4(label, col, flags | ImGuiColorEditFlags_NoAlpha);
05292 }
05293 
05294 static void ColorEditRestoreH(const float* col, float* H)
05295 {
05296     ImGuiContext& g = *GImGui;
05297     IM_ASSERT(g.ColorEditCurrentID != 0);
05298     if (g.ColorEditSavedID != g.ColorEditCurrentID || g.ColorEditSavedColor != ImGui::ColorConvertFloat4ToU32(ImVec4(col[0], col[1], col[2], 0)))
05299         return;
05300     *H = g.ColorEditSavedHue;
05301 }
05302 
05303 // ColorEdit supports RGB and HSV inputs. In case of RGB input resulting color may have undefined hue and/or saturation.
05304 // Since widget displays both RGB and HSV values we must preserve hue and saturation to prevent these values resetting.
05305 static void ColorEditRestoreHS(const float* col, float* H, float* S, float* V)
05306 {
05307     ImGuiContext& g = *GImGui;
05308     IM_ASSERT(g.ColorEditCurrentID != 0);
05309     if (g.ColorEditSavedID != g.ColorEditCurrentID || g.ColorEditSavedColor != ImGui::ColorConvertFloat4ToU32(ImVec4(col[0], col[1], col[2], 0)))
05310         return;
05311 
05312     // When S == 0, H is undefined.
05313     // When H == 1 it wraps around to 0.
05314     if (*S == 0.0f || (*H == 0.0f && g.ColorEditSavedHue == 1))
05315         *H = g.ColorEditSavedHue;
05316 
05317     // When V == 0, S is undefined.
05318     if (*V == 0.0f)
05319         *S = g.ColorEditSavedSat;
05320 }
05321 
05322 // Edit colors components (each component in 0.0f..1.0f range).
05323 // See enum ImGuiColorEditFlags_ for available options. e.g. Only access 3 floats if ImGuiColorEditFlags_NoAlpha flag is set.
05324 // With typical options: Left-click on color square to open color picker. Right-click to open option menu. CTRL-Click over input fields to edit them and TAB to go to next item.
05325 bool ImGui::ColorEdit4(const char* label, float col[4], ImGuiColorEditFlags flags)
05326 {
05327     ImGuiWindow* window = GetCurrentWindow();
05328     if (window->SkipItems)
05329         return false;
05330 
05331     ImGuiContext& g = *GImGui;
05332     const ImGuiStyle& style = g.Style;
05333     const float square_sz = GetFrameHeight();
05334     const char* label_display_end = FindRenderedTextEnd(label);
05335     float w_full = CalcItemWidth();
05336     g.NextItemData.ClearFlags();
05337 
05338     BeginGroup();
05339     PushID(label);
05340     const bool set_current_color_edit_id = (g.ColorEditCurrentID == 0);
05341     if (set_current_color_edit_id)
05342         g.ColorEditCurrentID = window->IDStack.back();
05343 
05344     // If we're not showing any slider there's no point in doing any HSV conversions
05345     const ImGuiColorEditFlags flags_untouched = flags;
05346     if (flags & ImGuiColorEditFlags_NoInputs)
05347         flags = (flags & (~ImGuiColorEditFlags_DisplayMask_)) | ImGuiColorEditFlags_DisplayRGB | ImGuiColorEditFlags_NoOptions;
05348 
05349     // Context menu: display and modify options (before defaults are applied)
05350     if (!(flags & ImGuiColorEditFlags_NoOptions))
05351         ColorEditOptionsPopup(col, flags);
05352 
05353     // Read stored options
05354     if (!(flags & ImGuiColorEditFlags_DisplayMask_))
05355         flags |= (g.ColorEditOptions & ImGuiColorEditFlags_DisplayMask_);
05356     if (!(flags & ImGuiColorEditFlags_DataTypeMask_))
05357         flags |= (g.ColorEditOptions & ImGuiColorEditFlags_DataTypeMask_);
05358     if (!(flags & ImGuiColorEditFlags_PickerMask_))
05359         flags |= (g.ColorEditOptions & ImGuiColorEditFlags_PickerMask_);
05360     if (!(flags & ImGuiColorEditFlags_InputMask_))
05361         flags |= (g.ColorEditOptions & ImGuiColorEditFlags_InputMask_);
05362     flags |= (g.ColorEditOptions & ~(ImGuiColorEditFlags_DisplayMask_ | ImGuiColorEditFlags_DataTypeMask_ | ImGuiColorEditFlags_PickerMask_ | ImGuiColorEditFlags_InputMask_));
05363     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_DisplayMask_)); // Check that only 1 is selected
05364     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_InputMask_));   // Check that only 1 is selected
05365 
05366     const bool alpha = (flags & ImGuiColorEditFlags_NoAlpha) == 0;
05367     const bool hdr = (flags & ImGuiColorEditFlags_HDR) != 0;
05368     const int components = alpha ? 4 : 3;
05369     const float w_button = (flags & ImGuiColorEditFlags_NoSmallPreview) ? 0.0f : (square_sz + style.ItemInnerSpacing.x);
05370     const float w_inputs = ImMax(w_full - w_button, 1.0f);
05371     w_full = w_inputs + w_button;
05372 
05373     // Convert to the formats we need
05374     float f[4] = { col[0], col[1], col[2], alpha ? col[3] : 1.0f };
05375     if ((flags & ImGuiColorEditFlags_InputHSV) && (flags & ImGuiColorEditFlags_DisplayRGB))
05376         ColorConvertHSVtoRGB(f[0], f[1], f[2], f[0], f[1], f[2]);
05377     else if ((flags & ImGuiColorEditFlags_InputRGB) && (flags & ImGuiColorEditFlags_DisplayHSV))
05378     {
05379         // Hue is lost when converting from grayscale rgb (saturation=0). Restore it.
05380         ColorConvertRGBtoHSV(f[0], f[1], f[2], f[0], f[1], f[2]);
05381         ColorEditRestoreHS(col, &f[0], &f[1], &f[2]);
05382     }
05383     int i[4] = { IM_F32_TO_INT8_UNBOUND(f[0]), IM_F32_TO_INT8_UNBOUND(f[1]), IM_F32_TO_INT8_UNBOUND(f[2]), IM_F32_TO_INT8_UNBOUND(f[3]) };
05384 
05385     bool value_changed = false;
05386     bool value_changed_as_float = false;
05387 
05388     const ImVec2 pos = window->DC.CursorPos;
05389     const float inputs_offset_x = (style.ColorButtonPosition == ImGuiDir_Left) ? w_button : 0.0f;
05390     window->DC.CursorPos.x = pos.x + inputs_offset_x;
05391 
05392     if ((flags & (ImGuiColorEditFlags_DisplayRGB | ImGuiColorEditFlags_DisplayHSV)) != 0 && (flags & ImGuiColorEditFlags_NoInputs) == 0)
05393     {
05394         // RGB/HSV 0..255 Sliders
05395         const float w_items = w_inputs - style.ItemInnerSpacing.x * (components - 1);
05396 
05397         const bool hide_prefix = (IM_TRUNC(w_items / components) <= CalcTextSize((flags & ImGuiColorEditFlags_Float) ? "M:0.000" : "M:000").x);
05398         static const char* ids[4] = { "##X", "##Y", "##Z", "##W" };
05399         static const char* fmt_table_int[3][4] =
05400         {
05401             {   "%3d",   "%3d",   "%3d",   "%3d" }, // Short display
05402             { "R:%3d", "G:%3d", "B:%3d", "A:%3d" }, // Long display for RGBA
05403             { "H:%3d", "S:%3d", "V:%3d", "A:%3d" }  // Long display for HSVA
05404         };
05405         static const char* fmt_table_float[3][4] =
05406         {
05407             {   "%0.3f",   "%0.3f",   "%0.3f",   "%0.3f" }, // Short display
05408             { "R:%0.3f", "G:%0.3f", "B:%0.3f", "A:%0.3f" }, // Long display for RGBA
05409             { "H:%0.3f", "S:%0.3f", "V:%0.3f", "A:%0.3f" }  // Long display for HSVA
05410         };
05411         const int fmt_idx = hide_prefix ? 0 : (flags & ImGuiColorEditFlags_DisplayHSV) ? 2 : 1;
05412 
05413         float prev_split = 0.0f;
05414         for (int n = 0; n < components; n++)
05415         {
05416             if (n > 0)
05417                 SameLine(0, style.ItemInnerSpacing.x);
05418             float next_split = IM_TRUNC(w_items * (n + 1) / components);
05419             SetNextItemWidth(ImMax(next_split - prev_split, 1.0f));
05420             prev_split = next_split;
05421 
05422             // FIXME: When ImGuiColorEditFlags_HDR flag is passed HS values snap in weird ways when SV values go below 0.
05423             if (flags & ImGuiColorEditFlags_Float)
05424             {
05425                 value_changed |= DragFloat(ids[n], &f[n], 1.0f / 255.0f, 0.0f, hdr ? 0.0f : 1.0f, fmt_table_float[fmt_idx][n]);
05426                 value_changed_as_float |= value_changed;
05427             }
05428             else
05429             {
05430                 value_changed |= DragInt(ids[n], &i[n], 1.0f, 0, hdr ? 0 : 255, fmt_table_int[fmt_idx][n]);
05431             }
05432             if (!(flags & ImGuiColorEditFlags_NoOptions))
05433                 OpenPopupOnItemClick("context", ImGuiPopupFlags_MouseButtonRight);
05434         }
05435     }
05436     else if ((flags & ImGuiColorEditFlags_DisplayHex) != 0 && (flags & ImGuiColorEditFlags_NoInputs) == 0)
05437     {
05438         // RGB Hexadecimal Input
05439         char buf[64];
05440         if (alpha)
05441             ImFormatString(buf, IM_ARRAYSIZE(buf), "#%02X%02X%02X%02X", ImClamp(i[0], 0, 255), ImClamp(i[1], 0, 255), ImClamp(i[2], 0, 255), ImClamp(i[3], 0, 255));
05442         else
05443             ImFormatString(buf, IM_ARRAYSIZE(buf), "#%02X%02X%02X", ImClamp(i[0], 0, 255), ImClamp(i[1], 0, 255), ImClamp(i[2], 0, 255));
05444         SetNextItemWidth(w_inputs);
05445         if (InputText("##Text", buf, IM_ARRAYSIZE(buf), ImGuiInputTextFlags_CharsUppercase))
05446         {
05447             value_changed = true;
05448             char* p = buf;
05449             while (*p == '#' || ImCharIsBlankA(*p))
05450                 p++;
05451             i[0] = i[1] = i[2] = 0;
05452             i[3] = 0xFF; // alpha default to 255 is not parsed by scanf (e.g. inputting #FFFFFF omitting alpha)
05453             int r;
05454             if (alpha)
05455                 r = sscanf(p, "%02X%02X%02X%02X", (unsigned int*)&i[0], (unsigned int*)&i[1], (unsigned int*)&i[2], (unsigned int*)&i[3]); // Treat at unsigned (%X is unsigned)
05456             else
05457                 r = sscanf(p, "%02X%02X%02X", (unsigned int*)&i[0], (unsigned int*)&i[1], (unsigned int*)&i[2]);
05458             IM_UNUSED(r); // Fixes C6031: Return value ignored: 'sscanf'.
05459         }
05460         if (!(flags & ImGuiColorEditFlags_NoOptions))
05461             OpenPopupOnItemClick("context", ImGuiPopupFlags_MouseButtonRight);
05462     }
05463 
05464     ImGuiWindow* picker_active_window = NULL;
05465     if (!(flags & ImGuiColorEditFlags_NoSmallPreview))
05466     {
05467         const float button_offset_x = ((flags & ImGuiColorEditFlags_NoInputs) || (style.ColorButtonPosition == ImGuiDir_Left)) ? 0.0f : w_inputs + style.ItemInnerSpacing.x;
05468         window->DC.CursorPos = ImVec2(pos.x + button_offset_x, pos.y);
05469 
05470         const ImVec4 col_v4(col[0], col[1], col[2], alpha ? col[3] : 1.0f);
05471         if (ColorButton("##ColorButton", col_v4, flags))
05472         {
05473             if (!(flags & ImGuiColorEditFlags_NoPicker))
05474             {
05475                 // Store current color and open a picker
05476                 g.ColorPickerRef = col_v4;
05477                 OpenPopup("picker");
05478                 SetNextWindowPos(g.LastItemData.Rect.GetBL() + ImVec2(0.0f, style.ItemSpacing.y));
05479             }
05480         }
05481         if (!(flags & ImGuiColorEditFlags_NoOptions))
05482             OpenPopupOnItemClick("context", ImGuiPopupFlags_MouseButtonRight);
05483 
05484         if (BeginPopup("picker"))
05485         {
05486             if (g.CurrentWindow->BeginCount == 1)
05487             {
05488                 picker_active_window = g.CurrentWindow;
05489                 if (label != label_display_end)
05490                 {
05491                     TextEx(label, label_display_end);
05492                     Spacing();
05493                 }
05494                 ImGuiColorEditFlags picker_flags_to_forward = ImGuiColorEditFlags_DataTypeMask_ | ImGuiColorEditFlags_PickerMask_ | ImGuiColorEditFlags_InputMask_ | ImGuiColorEditFlags_HDR | ImGuiColorEditFlags_NoAlpha | ImGuiColorEditFlags_AlphaBar;
05495                 ImGuiColorEditFlags picker_flags = (flags_untouched & picker_flags_to_forward) | ImGuiColorEditFlags_DisplayMask_ | ImGuiColorEditFlags_NoLabel | ImGuiColorEditFlags_AlphaPreviewHalf;
05496                 SetNextItemWidth(square_sz * 12.0f); // Use 256 + bar sizes?
05497                 value_changed |= ColorPicker4("##picker", col, picker_flags, &g.ColorPickerRef.x);
05498             }
05499             EndPopup();
05500         }
05501     }
05502 
05503     if (label != label_display_end && !(flags & ImGuiColorEditFlags_NoLabel))
05504     {
05505         // Position not necessarily next to last submitted button (e.g. if style.ColorButtonPosition == ImGuiDir_Left),
05506         // but we need to use SameLine() to setup baseline correctly. Might want to refactor SameLine() to simplify this.
05507         SameLine(0.0f, style.ItemInnerSpacing.x);
05508         window->DC.CursorPos.x = pos.x + ((flags & ImGuiColorEditFlags_NoInputs) ? w_button : w_full + style.ItemInnerSpacing.x);
05509         TextEx(label, label_display_end);
05510     }
05511 
05512     // Convert back
05513     if (value_changed && picker_active_window == NULL)
05514     {
05515         if (!value_changed_as_float)
05516             for (int n = 0; n < 4; n++)
05517                 f[n] = i[n] / 255.0f;
05518         if ((flags & ImGuiColorEditFlags_DisplayHSV) && (flags & ImGuiColorEditFlags_InputRGB))
05519         {
05520             g.ColorEditSavedHue = f[0];
05521             g.ColorEditSavedSat = f[1];
05522             ColorConvertHSVtoRGB(f[0], f[1], f[2], f[0], f[1], f[2]);
05523             g.ColorEditSavedID = g.ColorEditCurrentID;
05524             g.ColorEditSavedColor = ColorConvertFloat4ToU32(ImVec4(f[0], f[1], f[2], 0));
05525         }
05526         if ((flags & ImGuiColorEditFlags_DisplayRGB) && (flags & ImGuiColorEditFlags_InputHSV))
05527             ColorConvertRGBtoHSV(f[0], f[1], f[2], f[0], f[1], f[2]);
05528 
05529         col[0] = f[0];
05530         col[1] = f[1];
05531         col[2] = f[2];
05532         if (alpha)
05533             col[3] = f[3];
05534     }
05535 
05536     if (set_current_color_edit_id)
05537         g.ColorEditCurrentID = 0;
05538     PopID();
05539     EndGroup();
05540 
05541     // Drag and Drop Target
05542     // NB: The flag test is merely an optional micro-optimization, BeginDragDropTarget() does the same test.
05543     if ((g.LastItemData.StatusFlags & ImGuiItemStatusFlags_HoveredRect) && !(g.LastItemData.InFlags & ImGuiItemFlags_ReadOnly) && !(flags & ImGuiColorEditFlags_NoDragDrop) && BeginDragDropTarget())
05544     {
05545         bool accepted_drag_drop = false;
05546         if (const ImGuiPayload* payload = AcceptDragDropPayload(IMGUI_PAYLOAD_TYPE_COLOR_3F))
05547         {
05548             memcpy((float*)col, payload->Data, sizeof(float) * 3); // Preserve alpha if any //-V512 //-V1086
05549             value_changed = accepted_drag_drop = true;
05550         }
05551         if (const ImGuiPayload* payload = AcceptDragDropPayload(IMGUI_PAYLOAD_TYPE_COLOR_4F))
05552         {
05553             memcpy((float*)col, payload->Data, sizeof(float) * components);
05554             value_changed = accepted_drag_drop = true;
05555         }
05556 
05557         // Drag-drop payloads are always RGB
05558         if (accepted_drag_drop && (flags & ImGuiColorEditFlags_InputHSV))
05559             ColorConvertRGBtoHSV(col[0], col[1], col[2], col[0], col[1], col[2]);
05560         EndDragDropTarget();
05561     }
05562 
05563     // When picker is being actively used, use its active id so IsItemActive() will function on ColorEdit4().
05564     if (picker_active_window && g.ActiveId != 0 && g.ActiveIdWindow == picker_active_window)
05565         g.LastItemData.ID = g.ActiveId;
05566 
05567     if (value_changed && g.LastItemData.ID != 0) // In case of ID collision, the second EndGroup() won't catch g.ActiveId
05568         MarkItemEdited(g.LastItemData.ID);
05569 
05570     return value_changed;
05571 }
05572 
05573 bool ImGui::ColorPicker3(const char* label, float col[3], ImGuiColorEditFlags flags)
05574 {
05575     float col4[4] = { col[0], col[1], col[2], 1.0f };
05576     if (!ColorPicker4(label, col4, flags | ImGuiColorEditFlags_NoAlpha))
05577         return false;
05578     col[0] = col4[0]; col[1] = col4[1]; col[2] = col4[2];
05579     return true;
05580 }
05581 
05582 // Helper for ColorPicker4()
05583 static void RenderArrowsForVerticalBar(ImDrawList* draw_list, ImVec2 pos, ImVec2 half_sz, float bar_w, float alpha)
05584 {
05585     ImU32 alpha8 = IM_F32_TO_INT8_SAT(alpha);
05586     ImGui::RenderArrowPointingAt(draw_list, ImVec2(pos.x + half_sz.x + 1,         pos.y), ImVec2(half_sz.x + 2, half_sz.y + 1), ImGuiDir_Right, IM_COL32(0,0,0,alpha8));
05587     ImGui::RenderArrowPointingAt(draw_list, ImVec2(pos.x + half_sz.x,             pos.y), half_sz,                              ImGuiDir_Right, IM_COL32(255,255,255,alpha8));
05588     ImGui::RenderArrowPointingAt(draw_list, ImVec2(pos.x + bar_w - half_sz.x - 1, pos.y), ImVec2(half_sz.x + 2, half_sz.y + 1), ImGuiDir_Left,  IM_COL32(0,0,0,alpha8));
05589     ImGui::RenderArrowPointingAt(draw_list, ImVec2(pos.x + bar_w - half_sz.x,     pos.y), half_sz,                              ImGuiDir_Left,  IM_COL32(255,255,255,alpha8));
05590 }
05591 
05592 // Note: ColorPicker4() only accesses 3 floats if ImGuiColorEditFlags_NoAlpha flag is set.
05593 // (In C++ the 'float col[4]' notation for a function argument is equivalent to 'float* col', we only specify a size to facilitate understanding of the code.)
05594 // FIXME: we adjust the big color square height based on item width, which may cause a flickering feedback loop (if automatic height makes a vertical scrollbar appears, affecting automatic width..)
05595 // FIXME: this is trying to be aware of style.Alpha but not fully correct. Also, the color wheel will have overlapping glitches with (style.Alpha < 1.0)
05596 bool ImGui::ColorPicker4(const char* label, float col[4], ImGuiColorEditFlags flags, const float* ref_col)
05597 {
05598     ImGuiContext& g = *GImGui;
05599     ImGuiWindow* window = GetCurrentWindow();
05600     if (window->SkipItems)
05601         return false;
05602 
05603     ImDrawList* draw_list = window->DrawList;
05604     ImGuiStyle& style = g.Style;
05605     ImGuiIO& io = g.IO;
05606 
05607     const float width = CalcItemWidth();
05608     const bool is_readonly = ((g.NextItemData.ItemFlags | g.CurrentItemFlags) & ImGuiItemFlags_ReadOnly) != 0;
05609     g.NextItemData.ClearFlags();
05610 
05611     PushID(label);
05612     const bool set_current_color_edit_id = (g.ColorEditCurrentID == 0);
05613     if (set_current_color_edit_id)
05614         g.ColorEditCurrentID = window->IDStack.back();
05615     BeginGroup();
05616 
05617     if (!(flags & ImGuiColorEditFlags_NoSidePreview))
05618         flags |= ImGuiColorEditFlags_NoSmallPreview;
05619 
05620     // Context menu: display and store options.
05621     if (!(flags & ImGuiColorEditFlags_NoOptions))
05622         ColorPickerOptionsPopup(col, flags);
05623 
05624     // Read stored options
05625     if (!(flags & ImGuiColorEditFlags_PickerMask_))
05626         flags |= ((g.ColorEditOptions & ImGuiColorEditFlags_PickerMask_) ? g.ColorEditOptions : ImGuiColorEditFlags_DefaultOptions_) & ImGuiColorEditFlags_PickerMask_;
05627     if (!(flags & ImGuiColorEditFlags_InputMask_))
05628         flags |= ((g.ColorEditOptions & ImGuiColorEditFlags_InputMask_) ? g.ColorEditOptions : ImGuiColorEditFlags_DefaultOptions_) & ImGuiColorEditFlags_InputMask_;
05629     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_PickerMask_)); // Check that only 1 is selected
05630     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_InputMask_));  // Check that only 1 is selected
05631     if (!(flags & ImGuiColorEditFlags_NoOptions))
05632         flags |= (g.ColorEditOptions & ImGuiColorEditFlags_AlphaBar);
05633 
05634     // Setup
05635     int components = (flags & ImGuiColorEditFlags_NoAlpha) ? 3 : 4;
05636     bool alpha_bar = (flags & ImGuiColorEditFlags_AlphaBar) && !(flags & ImGuiColorEditFlags_NoAlpha);
05637     ImVec2 picker_pos = window->DC.CursorPos;
05638     float square_sz = GetFrameHeight();
05639     float bars_width = square_sz; // Arbitrary smallish width of Hue/Alpha picking bars
05640     float sv_picker_size = ImMax(bars_width * 1, width - (alpha_bar ? 2 : 1) * (bars_width + style.ItemInnerSpacing.x)); // Saturation/Value picking box
05641     float bar0_pos_x = picker_pos.x + sv_picker_size + style.ItemInnerSpacing.x;
05642     float bar1_pos_x = bar0_pos_x + bars_width + style.ItemInnerSpacing.x;
05643     float bars_triangles_half_sz = IM_TRUNC(bars_width * 0.20f);
05644 
05645     float backup_initial_col[4];
05646     memcpy(backup_initial_col, col, components * sizeof(float));
05647 
05648     float wheel_thickness = sv_picker_size * 0.08f;
05649     float wheel_r_outer = sv_picker_size * 0.50f;
05650     float wheel_r_inner = wheel_r_outer - wheel_thickness;
05651     ImVec2 wheel_center(picker_pos.x + (sv_picker_size + bars_width)*0.5f, picker_pos.y + sv_picker_size * 0.5f);
05652 
05653     // Note: the triangle is displayed rotated with triangle_pa pointing to Hue, but most coordinates stays unrotated for logic.
05654     float triangle_r = wheel_r_inner - (int)(sv_picker_size * 0.027f);
05655     ImVec2 triangle_pa = ImVec2(triangle_r, 0.0f); // Hue point.
05656     ImVec2 triangle_pb = ImVec2(triangle_r * -0.5f, triangle_r * -0.866025f); // Black point.
05657     ImVec2 triangle_pc = ImVec2(triangle_r * -0.5f, triangle_r * +0.866025f); // White point.
05658 
05659     float H = col[0], S = col[1], V = col[2];
05660     float R = col[0], G = col[1], B = col[2];
05661     if (flags & ImGuiColorEditFlags_InputRGB)
05662     {
05663         // Hue is lost when converting from grayscale rgb (saturation=0). Restore it.
05664         ColorConvertRGBtoHSV(R, G, B, H, S, V);
05665         ColorEditRestoreHS(col, &H, &S, &V);
05666     }
05667     else if (flags & ImGuiColorEditFlags_InputHSV)
05668     {
05669         ColorConvertHSVtoRGB(H, S, V, R, G, B);
05670     }
05671 
05672     bool value_changed = false, value_changed_h = false, value_changed_sv = false;
05673 
05674     PushItemFlag(ImGuiItemFlags_NoNav, true);
05675     if (flags & ImGuiColorEditFlags_PickerHueWheel)
05676     {
05677         // Hue wheel + SV triangle logic
05678         InvisibleButton("hsv", ImVec2(sv_picker_size + style.ItemInnerSpacing.x + bars_width, sv_picker_size));
05679         if (IsItemActive() && !is_readonly)
05680         {
05681             ImVec2 initial_off = g.IO.MouseClickedPos[0] - wheel_center;
05682             ImVec2 current_off = g.IO.MousePos - wheel_center;
05683             float initial_dist2 = ImLengthSqr(initial_off);
05684             if (initial_dist2 >= (wheel_r_inner - 1) * (wheel_r_inner - 1) && initial_dist2 <= (wheel_r_outer + 1) * (wheel_r_outer + 1))
05685             {
05686                 // Interactive with Hue wheel
05687                 H = ImAtan2(current_off.y, current_off.x) / IM_PI * 0.5f;
05688                 if (H < 0.0f)
05689                     H += 1.0f;
05690                 value_changed = value_changed_h = true;
05691             }
05692             float cos_hue_angle = ImCos(-H * 2.0f * IM_PI);
05693             float sin_hue_angle = ImSin(-H * 2.0f * IM_PI);
05694             if (ImTriangleContainsPoint(triangle_pa, triangle_pb, triangle_pc, ImRotate(initial_off, cos_hue_angle, sin_hue_angle)))
05695             {
05696                 // Interacting with SV triangle
05697                 ImVec2 current_off_unrotated = ImRotate(current_off, cos_hue_angle, sin_hue_angle);
05698                 if (!ImTriangleContainsPoint(triangle_pa, triangle_pb, triangle_pc, current_off_unrotated))
05699                     current_off_unrotated = ImTriangleClosestPoint(triangle_pa, triangle_pb, triangle_pc, current_off_unrotated);
05700                 float uu, vv, ww;
05701                 ImTriangleBarycentricCoords(triangle_pa, triangle_pb, triangle_pc, current_off_unrotated, uu, vv, ww);
05702                 V = ImClamp(1.0f - vv, 0.0001f, 1.0f);
05703                 S = ImClamp(uu / V, 0.0001f, 1.0f);
05704                 value_changed = value_changed_sv = true;
05705             }
05706         }
05707         if (!(flags & ImGuiColorEditFlags_NoOptions))
05708             OpenPopupOnItemClick("context", ImGuiPopupFlags_MouseButtonRight);
05709     }
05710     else if (flags & ImGuiColorEditFlags_PickerHueBar)
05711     {
05712         // SV rectangle logic
05713         InvisibleButton("sv", ImVec2(sv_picker_size, sv_picker_size));
05714         if (IsItemActive() && !is_readonly)
05715         {
05716             S = ImSaturate((io.MousePos.x - picker_pos.x) / (sv_picker_size - 1));
05717             V = 1.0f - ImSaturate((io.MousePos.y - picker_pos.y) / (sv_picker_size - 1));
05718             ColorEditRestoreH(col, &H); // Greatly reduces hue jitter and reset to 0 when hue == 255 and color is rapidly modified using SV square.
05719             value_changed = value_changed_sv = true;
05720         }
05721         if (!(flags & ImGuiColorEditFlags_NoOptions))
05722             OpenPopupOnItemClick("context", ImGuiPopupFlags_MouseButtonRight);
05723 
05724         // Hue bar logic
05725         SetCursorScreenPos(ImVec2(bar0_pos_x, picker_pos.y));
05726         InvisibleButton("hue", ImVec2(bars_width, sv_picker_size));
05727         if (IsItemActive() && !is_readonly)
05728         {
05729             H = ImSaturate((io.MousePos.y - picker_pos.y) / (sv_picker_size - 1));
05730             value_changed = value_changed_h = true;
05731         }
05732     }
05733 
05734     // Alpha bar logic
05735     if (alpha_bar)
05736     {
05737         SetCursorScreenPos(ImVec2(bar1_pos_x, picker_pos.y));
05738         InvisibleButton("alpha", ImVec2(bars_width, sv_picker_size));
05739         if (IsItemActive())
05740         {
05741             col[3] = 1.0f - ImSaturate((io.MousePos.y - picker_pos.y) / (sv_picker_size - 1));
05742             value_changed = true;
05743         }
05744     }
05745     PopItemFlag(); // ImGuiItemFlags_NoNav
05746 
05747     if (!(flags & ImGuiColorEditFlags_NoSidePreview))
05748     {
05749         SameLine(0, style.ItemInnerSpacing.x);
05750         BeginGroup();
05751     }
05752 
05753     if (!(flags & ImGuiColorEditFlags_NoLabel))
05754     {
05755         const char* label_display_end = FindRenderedTextEnd(label);
05756         if (label != label_display_end)
05757         {
05758             if ((flags & ImGuiColorEditFlags_NoSidePreview))
05759                 SameLine(0, style.ItemInnerSpacing.x);
05760             TextEx(label, label_display_end);
05761         }
05762     }
05763 
05764     if (!(flags & ImGuiColorEditFlags_NoSidePreview))
05765     {
05766         PushItemFlag(ImGuiItemFlags_NoNavDefaultFocus, true);
05767         ImVec4 col_v4(col[0], col[1], col[2], (flags & ImGuiColorEditFlags_NoAlpha) ? 1.0f : col[3]);
05768         if ((flags & ImGuiColorEditFlags_NoLabel))
05769             Text("Current");
05770 
05771         ImGuiColorEditFlags sub_flags_to_forward = ImGuiColorEditFlags_InputMask_ | ImGuiColorEditFlags_HDR | ImGuiColorEditFlags_AlphaPreview | ImGuiColorEditFlags_AlphaPreviewHalf | ImGuiColorEditFlags_NoTooltip;
05772         ColorButton("##current", col_v4, (flags & sub_flags_to_forward), ImVec2(square_sz * 3, square_sz * 2));
05773         if (ref_col != NULL)
05774         {
05775             Text("Original");
05776             ImVec4 ref_col_v4(ref_col[0], ref_col[1], ref_col[2], (flags & ImGuiColorEditFlags_NoAlpha) ? 1.0f : ref_col[3]);
05777             if (ColorButton("##original", ref_col_v4, (flags & sub_flags_to_forward), ImVec2(square_sz * 3, square_sz * 2)))
05778             {
05779                 memcpy(col, ref_col, components * sizeof(float));
05780                 value_changed = true;
05781             }
05782         }
05783         PopItemFlag();
05784         EndGroup();
05785     }
05786 
05787     // Convert back color to RGB
05788     if (value_changed_h || value_changed_sv)
05789     {
05790         if (flags & ImGuiColorEditFlags_InputRGB)
05791         {
05792             ColorConvertHSVtoRGB(H, S, V, col[0], col[1], col[2]);
05793             g.ColorEditSavedHue = H;
05794             g.ColorEditSavedSat = S;
05795             g.ColorEditSavedID = g.ColorEditCurrentID;
05796             g.ColorEditSavedColor = ColorConvertFloat4ToU32(ImVec4(col[0], col[1], col[2], 0));
05797         }
05798         else if (flags & ImGuiColorEditFlags_InputHSV)
05799         {
05800             col[0] = H;
05801             col[1] = S;
05802             col[2] = V;
05803         }
05804     }
05805 
05806     // R,G,B and H,S,V slider color editor
05807     bool value_changed_fix_hue_wrap = false;
05808     if ((flags & ImGuiColorEditFlags_NoInputs) == 0)
05809     {
05810         PushItemWidth((alpha_bar ? bar1_pos_x : bar0_pos_x) + bars_width - picker_pos.x);
05811         ImGuiColorEditFlags sub_flags_to_forward = ImGuiColorEditFlags_DataTypeMask_ | ImGuiColorEditFlags_InputMask_ | ImGuiColorEditFlags_HDR | ImGuiColorEditFlags_NoAlpha | ImGuiColorEditFlags_NoOptions | ImGuiColorEditFlags_NoTooltip | ImGuiColorEditFlags_NoSmallPreview | ImGuiColorEditFlags_AlphaPreview | ImGuiColorEditFlags_AlphaPreviewHalf;
05812         ImGuiColorEditFlags sub_flags = (flags & sub_flags_to_forward) | ImGuiColorEditFlags_NoPicker;
05813         if (flags & ImGuiColorEditFlags_DisplayRGB || (flags & ImGuiColorEditFlags_DisplayMask_) == 0)
05814             if (ColorEdit4("##rgb", col, sub_flags | ImGuiColorEditFlags_DisplayRGB))
05815             {
05816                 // FIXME: Hackily differentiating using the DragInt (ActiveId != 0 && !ActiveIdAllowOverlap) vs. using the InputText or DropTarget.
05817                 // For the later we don't want to run the hue-wrap canceling code. If you are well versed in HSV picker please provide your input! (See #2050)
05818                 value_changed_fix_hue_wrap = (g.ActiveId != 0 && !g.ActiveIdAllowOverlap);
05819                 value_changed = true;
05820             }
05821         if (flags & ImGuiColorEditFlags_DisplayHSV || (flags & ImGuiColorEditFlags_DisplayMask_) == 0)
05822             value_changed |= ColorEdit4("##hsv", col, sub_flags | ImGuiColorEditFlags_DisplayHSV);
05823         if (flags & ImGuiColorEditFlags_DisplayHex || (flags & ImGuiColorEditFlags_DisplayMask_) == 0)
05824             value_changed |= ColorEdit4("##hex", col, sub_flags | ImGuiColorEditFlags_DisplayHex);
05825         PopItemWidth();
05826     }
05827 
05828     // Try to cancel hue wrap (after ColorEdit4 call), if any
05829     if (value_changed_fix_hue_wrap && (flags & ImGuiColorEditFlags_InputRGB))
05830     {
05831         float new_H, new_S, new_V;
05832         ColorConvertRGBtoHSV(col[0], col[1], col[2], new_H, new_S, new_V);
05833         if (new_H <= 0 && H > 0)
05834         {
05835             if (new_V <= 0 && V != new_V)
05836                 ColorConvertHSVtoRGB(H, S, new_V <= 0 ? V * 0.5f : new_V, col[0], col[1], col[2]);
05837             else if (new_S <= 0)
05838                 ColorConvertHSVtoRGB(H, new_S <= 0 ? S * 0.5f : new_S, new_V, col[0], col[1], col[2]);
05839         }
05840     }
05841 
05842     if (value_changed)
05843     {
05844         if (flags & ImGuiColorEditFlags_InputRGB)
05845         {
05846             R = col[0];
05847             G = col[1];
05848             B = col[2];
05849             ColorConvertRGBtoHSV(R, G, B, H, S, V);
05850             ColorEditRestoreHS(col, &H, &S, &V);   // Fix local Hue as display below will use it immediately.
05851         }
05852         else if (flags & ImGuiColorEditFlags_InputHSV)
05853         {
05854             H = col[0];
05855             S = col[1];
05856             V = col[2];
05857             ColorConvertHSVtoRGB(H, S, V, R, G, B);
05858         }
05859     }
05860 
05861     const int style_alpha8 = IM_F32_TO_INT8_SAT(style.Alpha);
05862     const ImU32 col_black = IM_COL32(0,0,0,style_alpha8);
05863     const ImU32 col_white = IM_COL32(255,255,255,style_alpha8);
05864     const ImU32 col_midgrey = IM_COL32(128,128,128,style_alpha8);
05865     const ImU32 col_hues[6 + 1] = { IM_COL32(255,0,0,style_alpha8), IM_COL32(255,255,0,style_alpha8), IM_COL32(0,255,0,style_alpha8), IM_COL32(0,255,255,style_alpha8), IM_COL32(0,0,255,style_alpha8), IM_COL32(255,0,255,style_alpha8), IM_COL32(255,0,0,style_alpha8) };
05866 
05867     ImVec4 hue_color_f(1, 1, 1, style.Alpha); ColorConvertHSVtoRGB(H, 1, 1, hue_color_f.x, hue_color_f.y, hue_color_f.z);
05868     ImU32 hue_color32 = ColorConvertFloat4ToU32(hue_color_f);
05869     ImU32 user_col32_striped_of_alpha = ColorConvertFloat4ToU32(ImVec4(R, G, B, style.Alpha)); // Important: this is still including the main rendering/style alpha!!
05870 
05871     ImVec2 sv_cursor_pos;
05872 
05873     if (flags & ImGuiColorEditFlags_PickerHueWheel)
05874     {
05875         // Render Hue Wheel
05876         const float aeps = 0.5f / wheel_r_outer; // Half a pixel arc length in radians (2pi cancels out).
05877         const int segment_per_arc = ImMax(4, (int)wheel_r_outer / 12);
05878         for (int n = 0; n < 6; n++)
05879         {
05880             const float a0 = (n)     /6.0f * 2.0f * IM_PI - aeps;
05881             const float a1 = (n+1.0f)/6.0f * 2.0f * IM_PI + aeps;
05882             const int vert_start_idx = draw_list->VtxBuffer.Size;
05883             draw_list->PathArcTo(wheel_center, (wheel_r_inner + wheel_r_outer)*0.5f, a0, a1, segment_per_arc);
05884             draw_list->PathStroke(col_white, 0, wheel_thickness);
05885             const int vert_end_idx = draw_list->VtxBuffer.Size;
05886 
05887             // Paint colors over existing vertices
05888             ImVec2 gradient_p0(wheel_center.x + ImCos(a0) * wheel_r_inner, wheel_center.y + ImSin(a0) * wheel_r_inner);
05889             ImVec2 gradient_p1(wheel_center.x + ImCos(a1) * wheel_r_inner, wheel_center.y + ImSin(a1) * wheel_r_inner);
05890             ShadeVertsLinearColorGradientKeepAlpha(draw_list, vert_start_idx, vert_end_idx, gradient_p0, gradient_p1, col_hues[n], col_hues[n + 1]);
05891         }
05892 
05893         // Render Cursor + preview on Hue Wheel
05894         float cos_hue_angle = ImCos(H * 2.0f * IM_PI);
05895         float sin_hue_angle = ImSin(H * 2.0f * IM_PI);
05896         ImVec2 hue_cursor_pos(wheel_center.x + cos_hue_angle * (wheel_r_inner + wheel_r_outer) * 0.5f, wheel_center.y + sin_hue_angle * (wheel_r_inner + wheel_r_outer) * 0.5f);
05897         float hue_cursor_rad = value_changed_h ? wheel_thickness * 0.65f : wheel_thickness * 0.55f;
05898         int hue_cursor_segments = draw_list->_CalcCircleAutoSegmentCount(hue_cursor_rad); // Lock segment count so the +1 one matches others.
05899         draw_list->AddCircleFilled(hue_cursor_pos, hue_cursor_rad, hue_color32, hue_cursor_segments);
05900         draw_list->AddCircle(hue_cursor_pos, hue_cursor_rad + 1, col_midgrey, hue_cursor_segments);
05901         draw_list->AddCircle(hue_cursor_pos, hue_cursor_rad, col_white, hue_cursor_segments);
05902 
05903         // Render SV triangle (rotated according to hue)
05904         ImVec2 tra = wheel_center + ImRotate(triangle_pa, cos_hue_angle, sin_hue_angle);
05905         ImVec2 trb = wheel_center + ImRotate(triangle_pb, cos_hue_angle, sin_hue_angle);
05906         ImVec2 trc = wheel_center + ImRotate(triangle_pc, cos_hue_angle, sin_hue_angle);
05907         ImVec2 uv_white = GetFontTexUvWhitePixel();
05908         draw_list->PrimReserve(3, 3);
05909         draw_list->PrimVtx(tra, uv_white, hue_color32);
05910         draw_list->PrimVtx(trb, uv_white, col_black);
05911         draw_list->PrimVtx(trc, uv_white, col_white);
05912         draw_list->AddTriangle(tra, trb, trc, col_midgrey, 1.5f);
05913         sv_cursor_pos = ImLerp(ImLerp(trc, tra, ImSaturate(S)), trb, ImSaturate(1 - V));
05914     }
05915     else if (flags & ImGuiColorEditFlags_PickerHueBar)
05916     {
05917         // Render SV Square
05918         draw_list->AddRectFilledMultiColor(picker_pos, picker_pos + ImVec2(sv_picker_size, sv_picker_size), col_white, hue_color32, hue_color32, col_white);
05919         draw_list->AddRectFilledMultiColor(picker_pos, picker_pos + ImVec2(sv_picker_size, sv_picker_size), 0, 0, col_black, col_black);
05920         RenderFrameBorder(picker_pos, picker_pos + ImVec2(sv_picker_size, sv_picker_size), 0.0f);
05921         sv_cursor_pos.x = ImClamp(IM_ROUND(picker_pos.x + ImSaturate(S)     * sv_picker_size), picker_pos.x + 2, picker_pos.x + sv_picker_size - 2); // Sneakily prevent the circle to stick out too much
05922         sv_cursor_pos.y = ImClamp(IM_ROUND(picker_pos.y + ImSaturate(1 - V) * sv_picker_size), picker_pos.y + 2, picker_pos.y + sv_picker_size - 2);
05923 
05924         // Render Hue Bar
05925         for (int i = 0; i < 6; ++i)
05926             draw_list->AddRectFilledMultiColor(ImVec2(bar0_pos_x, picker_pos.y + i * (sv_picker_size / 6)), ImVec2(bar0_pos_x + bars_width, picker_pos.y + (i + 1) * (sv_picker_size / 6)), col_hues[i], col_hues[i], col_hues[i + 1], col_hues[i + 1]);
05927         float bar0_line_y = IM_ROUND(picker_pos.y + H * sv_picker_size);
05928         RenderFrameBorder(ImVec2(bar0_pos_x, picker_pos.y), ImVec2(bar0_pos_x + bars_width, picker_pos.y + sv_picker_size), 0.0f);
05929         RenderArrowsForVerticalBar(draw_list, ImVec2(bar0_pos_x - 1, bar0_line_y), ImVec2(bars_triangles_half_sz + 1, bars_triangles_half_sz), bars_width + 2.0f, style.Alpha);
05930     }
05931 
05932     // Render cursor/preview circle (clamp S/V within 0..1 range because floating points colors may lead HSV values to be out of range)
05933     float sv_cursor_rad = value_changed_sv ? wheel_thickness * 0.55f : wheel_thickness * 0.40f;
05934     int sv_cursor_segments = draw_list->_CalcCircleAutoSegmentCount(sv_cursor_rad); // Lock segment count so the +1 one matches others.
05935     draw_list->AddCircleFilled(sv_cursor_pos, sv_cursor_rad, user_col32_striped_of_alpha, sv_cursor_segments);
05936     draw_list->AddCircle(sv_cursor_pos, sv_cursor_rad + 1, col_midgrey, sv_cursor_segments);
05937     draw_list->AddCircle(sv_cursor_pos, sv_cursor_rad, col_white, sv_cursor_segments);
05938 
05939     // Render alpha bar
05940     if (alpha_bar)
05941     {
05942         float alpha = ImSaturate(col[3]);
05943         ImRect bar1_bb(bar1_pos_x, picker_pos.y, bar1_pos_x + bars_width, picker_pos.y + sv_picker_size);
05944         RenderColorRectWithAlphaCheckerboard(draw_list, bar1_bb.Min, bar1_bb.Max, 0, bar1_bb.GetWidth() / 2.0f, ImVec2(0.0f, 0.0f));
05945         draw_list->AddRectFilledMultiColor(bar1_bb.Min, bar1_bb.Max, user_col32_striped_of_alpha, user_col32_striped_of_alpha, user_col32_striped_of_alpha & ~IM_COL32_A_MASK, user_col32_striped_of_alpha & ~IM_COL32_A_MASK);
05946         float bar1_line_y = IM_ROUND(picker_pos.y + (1.0f - alpha) * sv_picker_size);
05947         RenderFrameBorder(bar1_bb.Min, bar1_bb.Max, 0.0f);
05948         RenderArrowsForVerticalBar(draw_list, ImVec2(bar1_pos_x - 1, bar1_line_y), ImVec2(bars_triangles_half_sz + 1, bars_triangles_half_sz), bars_width + 2.0f, style.Alpha);
05949     }
05950 
05951     EndGroup();
05952 
05953     if (value_changed && memcmp(backup_initial_col, col, components * sizeof(float)) == 0)
05954         value_changed = false;
05955     if (value_changed && g.LastItemData.ID != 0) // In case of ID collision, the second EndGroup() won't catch g.ActiveId
05956         MarkItemEdited(g.LastItemData.ID);
05957 
05958     if (set_current_color_edit_id)
05959         g.ColorEditCurrentID = 0;
05960     PopID();
05961 
05962     return value_changed;
05963 }
05964 
05965 // A little color square. Return true when clicked.
05966 // FIXME: May want to display/ignore the alpha component in the color display? Yet show it in the tooltip.
05967 // 'desc_id' is not called 'label' because we don't display it next to the button, but only in the tooltip.
05968 // Note that 'col' may be encoded in HSV if ImGuiColorEditFlags_InputHSV is set.
05969 bool ImGui::ColorButton(const char* desc_id, const ImVec4& col, ImGuiColorEditFlags flags, const ImVec2& size_arg)
05970 {
05971     ImGuiWindow* window = GetCurrentWindow();
05972     if (window->SkipItems)
05973         return false;
05974 
05975     ImGuiContext& g = *GImGui;
05976     const ImGuiID id = window->GetID(desc_id);
05977     const float default_size = GetFrameHeight();
05978     const ImVec2 size(size_arg.x == 0.0f ? default_size : size_arg.x, size_arg.y == 0.0f ? default_size : size_arg.y);
05979     const ImRect bb(window->DC.CursorPos, window->DC.CursorPos + size);
05980     ItemSize(bb, (size.y >= default_size) ? g.Style.FramePadding.y : 0.0f);
05981     if (!ItemAdd(bb, id))
05982         return false;
05983 
05984     bool hovered, held;
05985     bool pressed = ButtonBehavior(bb, id, &hovered, &held);
05986 
05987     if (flags & ImGuiColorEditFlags_NoAlpha)
05988         flags &= ~(ImGuiColorEditFlags_AlphaPreview | ImGuiColorEditFlags_AlphaPreviewHalf);
05989 
05990     ImVec4 col_rgb = col;
05991     if (flags & ImGuiColorEditFlags_InputHSV)
05992         ColorConvertHSVtoRGB(col_rgb.x, col_rgb.y, col_rgb.z, col_rgb.x, col_rgb.y, col_rgb.z);
05993 
05994     ImVec4 col_rgb_without_alpha(col_rgb.x, col_rgb.y, col_rgb.z, 1.0f);
05995     float grid_step = ImMin(size.x, size.y) / 2.99f;
05996     float rounding = ImMin(g.Style.FrameRounding, grid_step * 0.5f);
05997     ImRect bb_inner = bb;
05998     float off = 0.0f;
05999     if ((flags & ImGuiColorEditFlags_NoBorder) == 0)
06000     {
06001         off = -0.75f; // The border (using Col_FrameBg) tends to look off when color is near-opaque and rounding is enabled. This offset seemed like a good middle ground to reduce those artifacts.
06002         bb_inner.Expand(off);
06003     }
06004     if ((flags & ImGuiColorEditFlags_AlphaPreviewHalf) && col_rgb.w < 1.0f)
06005     {
06006         float mid_x = IM_ROUND((bb_inner.Min.x + bb_inner.Max.x) * 0.5f);
06007         RenderColorRectWithAlphaCheckerboard(window->DrawList, ImVec2(bb_inner.Min.x + grid_step, bb_inner.Min.y), bb_inner.Max, GetColorU32(col_rgb), grid_step, ImVec2(-grid_step + off, off), rounding, ImDrawFlags_RoundCornersRight);
06008         window->DrawList->AddRectFilled(bb_inner.Min, ImVec2(mid_x, bb_inner.Max.y), GetColorU32(col_rgb_without_alpha), rounding, ImDrawFlags_RoundCornersLeft);
06009     }
06010     else
06011     {
06012         // Because GetColorU32() multiplies by the global style Alpha and we don't want to display a checkerboard if the source code had no alpha
06013         ImVec4 col_source = (flags & ImGuiColorEditFlags_AlphaPreview) ? col_rgb : col_rgb_without_alpha;
06014         if (col_source.w < 1.0f)
06015             RenderColorRectWithAlphaCheckerboard(window->DrawList, bb_inner.Min, bb_inner.Max, GetColorU32(col_source), grid_step, ImVec2(off, off), rounding);
06016         else
06017             window->DrawList->AddRectFilled(bb_inner.Min, bb_inner.Max, GetColorU32(col_source), rounding);
06018     }
06019     RenderNavHighlight(bb, id);
06020     if ((flags & ImGuiColorEditFlags_NoBorder) == 0)
06021     {
06022         if (g.Style.FrameBorderSize > 0.0f)
06023             RenderFrameBorder(bb.Min, bb.Max, rounding);
06024         else
06025             window->DrawList->AddRect(bb.Min, bb.Max, GetColorU32(ImGuiCol_FrameBg), rounding); // Color button are often in need of some sort of border
06026     }
06027 
06028     // Drag and Drop Source
06029     // NB: The ActiveId test is merely an optional micro-optimization, BeginDragDropSource() does the same test.
06030     if (g.ActiveId == id && !(flags & ImGuiColorEditFlags_NoDragDrop) && BeginDragDropSource())
06031     {
06032         if (flags & ImGuiColorEditFlags_NoAlpha)
06033             SetDragDropPayload(IMGUI_PAYLOAD_TYPE_COLOR_3F, &col_rgb, sizeof(float) * 3, ImGuiCond_Once);
06034         else
06035             SetDragDropPayload(IMGUI_PAYLOAD_TYPE_COLOR_4F, &col_rgb, sizeof(float) * 4, ImGuiCond_Once);
06036         ColorButton(desc_id, col, flags);
06037         SameLine();
06038         TextEx("Color");
06039         EndDragDropSource();
06040     }
06041 
06042     // Tooltip
06043     if (!(flags & ImGuiColorEditFlags_NoTooltip) && hovered && IsItemHovered(ImGuiHoveredFlags_ForTooltip))
06044         ColorTooltip(desc_id, &col.x, flags & (ImGuiColorEditFlags_InputMask_ | ImGuiColorEditFlags_NoAlpha | ImGuiColorEditFlags_AlphaPreview | ImGuiColorEditFlags_AlphaPreviewHalf));
06045 
06046     return pressed;
06047 }
