06049 // Initialize/override default color options
06050 void ImGui::SetColorEditOptions(ImGuiColorEditFlags flags)
06051 {
06052     ImGuiContext& g = *GImGui;
06053     if ((flags & ImGuiColorEditFlags_DisplayMask_) == 0)
06054         flags |= ImGuiColorEditFlags_DefaultOptions_ & ImGuiColorEditFlags_DisplayMask_;
06055     if ((flags & ImGuiColorEditFlags_DataTypeMask_) == 0)
06056         flags |= ImGuiColorEditFlags_DefaultOptions_ & ImGuiColorEditFlags_DataTypeMask_;
06057     if ((flags & ImGuiColorEditFlags_PickerMask_) == 0)
06058         flags |= ImGuiColorEditFlags_DefaultOptions_ & ImGuiColorEditFlags_PickerMask_;
06059     if ((flags & ImGuiColorEditFlags_InputMask_) == 0)
06060         flags |= ImGuiColorEditFlags_DefaultOptions_ & ImGuiColorEditFlags_InputMask_;
06061     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_DisplayMask_));    // Check only 1 option is selected
06062     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_DataTypeMask_));   // Check only 1 option is selected
06063     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_PickerMask_));     // Check only 1 option is selected
06064     IM_ASSERT(ImIsPowerOfTwo(flags & ImGuiColorEditFlags_InputMask_));      // Check only 1 option is selected
06065     g.ColorEditOptions = flags;
06066 }
