06068 // Note: only access 3 floats if ImGuiColorEditFlags_NoAlpha flag is set.
06069 void ImGui::ColorTooltip(const char* text, const float* col, ImGuiColorEditFlags flags)
06070 {
06071     ImGuiContext& g = *GImGui;
06072 
06073     if (!BeginTooltipEx(ImGuiTooltipFlags_OverridePrevious, ImGuiWindowFlags_None))
06074         return;
06075     const char* text_end = text ? FindRenderedTextEnd(text, NULL) : text;
06076     if (text_end > text)
06077     {
06078         TextEx(text, text_end);
06079         Separator();
06080     }
06081 
06082     ImVec2 sz(g.FontSize * 3 + g.Style.FramePadding.y * 2, g.FontSize * 3 + g.Style.FramePadding.y * 2);
06083     ImVec4 cf(col[0], col[1], col[2], (flags & ImGuiColorEditFlags_NoAlpha) ? 1.0f : col[3]);
06084     int cr = IM_F32_TO_INT8_SAT(col[0]), cg = IM_F32_TO_INT8_SAT(col[1]), cb = IM_F32_TO_INT8_SAT(col[2]), ca = (flags & ImGuiColorEditFlags_NoAlpha) ? 255 : IM_F32_TO_INT8_SAT(col[3]);
06085     ColorButton("##preview", cf, (flags & (ImGuiColorEditFlags_InputMask_ | ImGuiColorEditFlags_NoAlpha | ImGuiColorEditFlags_AlphaPreview | ImGuiColorEditFlags_AlphaPreviewHalf)) | ImGuiColorEditFlags_NoTooltip, sz);
06086     SameLine();
06087     if ((flags & ImGuiColorEditFlags_InputRGB) || !(flags & ImGuiColorEditFlags_InputMask_))
06088     {
06089         if (flags & ImGuiColorEditFlags_NoAlpha)
06090             Text("#%02X%02X%02X\nR: %d, G: %d, B: %d\n(%.3f, %.3f, %.3f)", cr, cg, cb, cr, cg, cb, col[0], col[1], col[2]);
06091         else
06092             Text("#%02X%02X%02X%02X\nR:%d, G:%d, B:%d, A:%d\n(%.3f, %.3f, %.3f, %.3f)", cr, cg, cb, ca, cr, cg, cb, ca, col[0], col[1], col[2], col[3]);
06093     }
06094     else if (flags & ImGuiColorEditFlags_InputHSV)
06095     {
06096         if (flags & ImGuiColorEditFlags_NoAlpha)
06097             Text("H: %.3f, S: %.3f, V: %.3f", col[0], col[1], col[2]);
06098         else
06099             Text("H: %.3f, S: %.3f, V: %.3f, A: %.3f", col[0], col[1], col[2], col[3]);
06100     }
06101     EndTooltip();
06102 }
