06104 void ImGui::ColorEditOptionsPopup(const float* col, ImGuiColorEditFlags flags)
06105 {
06106     bool allow_opt_inputs = !(flags & ImGuiColorEditFlags_DisplayMask_);
06107     bool allow_opt_datatype = !(flags & ImGuiColorEditFlags_DataTypeMask_);
06108     if ((!allow_opt_inputs && !allow_opt_datatype) || !BeginPopup("context"))
06109         return;
06110     ImGuiContext& g = *GImGui;
06111     g.LockMarkEdited++;
06112     ImGuiColorEditFlags opts = g.ColorEditOptions;
06113     if (allow_opt_inputs)
06114     {
06115         if (RadioButton("RGB", (opts & ImGuiColorEditFlags_DisplayRGB) != 0)) opts = (opts & ~ImGuiColorEditFlags_DisplayMask_) | ImGuiColorEditFlags_DisplayRGB;
06116         if (RadioButton("HSV", (opts & ImGuiColorEditFlags_DisplayHSV) != 0)) opts = (opts & ~ImGuiColorEditFlags_DisplayMask_) | ImGuiColorEditFlags_DisplayHSV;
06117         if (RadioButton("Hex", (opts & ImGuiColorEditFlags_DisplayHex) != 0)) opts = (opts & ~ImGuiColorEditFlags_DisplayMask_) | ImGuiColorEditFlags_DisplayHex;
06118     }
06119     if (allow_opt_datatype)
06120     {
06121         if (allow_opt_inputs) Separator();
06122         if (RadioButton("0..255",     (opts & ImGuiColorEditFlags_Uint8) != 0)) opts = (opts & ~ImGuiColorEditFlags_DataTypeMask_) | ImGuiColorEditFlags_Uint8;
06123         if (RadioButton("0.00..1.00", (opts & ImGuiColorEditFlags_Float) != 0)) opts = (opts & ~ImGuiColorEditFlags_DataTypeMask_) | ImGuiColorEditFlags_Float;
06124     }
06125 
06126     if (allow_opt_inputs || allow_opt_datatype)
06127         Separator();
06128     if (Button("Copy as..", ImVec2(-1, 0)))
06129         OpenPopup("Copy");
06130     if (BeginPopup("Copy"))
06131     {
06132         int cr = IM_F32_TO_INT8_SAT(col[0]), cg = IM_F32_TO_INT8_SAT(col[1]), cb = IM_F32_TO_INT8_SAT(col[2]), ca = (flags & ImGuiColorEditFlags_NoAlpha) ? 255 : IM_F32_TO_INT8_SAT(col[3]);
06133         char buf[64];
06134         ImFormatString(buf, IM_ARRAYSIZE(buf), "(%.3ff, %.3ff, %.3ff, %.3ff)", col[0], col[1], col[2], (flags & ImGuiColorEditFlags_NoAlpha) ? 1.0f : col[3]);
06135         if (Selectable(buf))
06136             SetClipboardText(buf);
06137         ImFormatString(buf, IM_ARRAYSIZE(buf), "(%d,%d,%d,%d)", cr, cg, cb, ca);
06138         if (Selectable(buf))
06139             SetClipboardText(buf);
06140         ImFormatString(buf, IM_ARRAYSIZE(buf), "#%02X%02X%02X", cr, cg, cb);
06141         if (Selectable(buf))
06142             SetClipboardText(buf);
06143         if (!(flags & ImGuiColorEditFlags_NoAlpha))
06144         {
06145             ImFormatString(buf, IM_ARRAYSIZE(buf), "#%02X%02X%02X%02X", cr, cg, cb, ca);
06146             if (Selectable(buf))
06147                 SetClipboardText(buf);
06148         }
06149         EndPopup();
06150     }
06151 
06152     g.ColorEditOptions = opts;
06153     EndPopup();
06154     g.LockMarkEdited--;
06155 }
