06157 void ImGui::ColorPickerOptionsPopup(const float* ref_col, ImGuiColorEditFlags flags)
06158 {
06159     bool allow_opt_picker = !(flags & ImGuiColorEditFlags_PickerMask_);
06160     bool allow_opt_alpha_bar = !(flags & ImGuiColorEditFlags_NoAlpha) && !(flags & ImGuiColorEditFlags_AlphaBar);
06161     if ((!allow_opt_picker && !allow_opt_alpha_bar) || !BeginPopup("context"))
06162         return;
06163     ImGuiContext& g = *GImGui;
06164     g.LockMarkEdited++;
06165     if (allow_opt_picker)
06166     {
06167         ImVec2 picker_size(g.FontSize * 8, ImMax(g.FontSize * 8 - (GetFrameHeight() + g.Style.ItemInnerSpacing.x), 1.0f)); // FIXME: Picker size copied from main picker function
06168         PushItemWidth(picker_size.x);
06169         for (int picker_type = 0; picker_type < 2; picker_type++)
06170         {
06171             // Draw small/thumbnail version of each picker type (over an invisible button for selection)
06172             if (picker_type > 0) Separator();
06173             PushID(picker_type);
06174             ImGuiColorEditFlags picker_flags = ImGuiColorEditFlags_NoInputs | ImGuiColorEditFlags_NoOptions | ImGuiColorEditFlags_NoLabel | ImGuiColorEditFlags_NoSidePreview | (flags & ImGuiColorEditFlags_NoAlpha);
06175             if (picker_type == 0) picker_flags |= ImGuiColorEditFlags_PickerHueBar;
06176             if (picker_type == 1) picker_flags |= ImGuiColorEditFlags_PickerHueWheel;
06177             ImVec2 backup_pos = GetCursorScreenPos();
06178             if (Selectable("##selectable", false, 0, picker_size)) // By default, Selectable() is closing popup
06179                 g.ColorEditOptions = (g.ColorEditOptions & ~ImGuiColorEditFlags_PickerMask_) | (picker_flags & ImGuiColorEditFlags_PickerMask_);
06180             SetCursorScreenPos(backup_pos);
06181             ImVec4 previewing_ref_col;
06182             memcpy(&previewing_ref_col, ref_col, sizeof(float) * ((picker_flags & ImGuiColorEditFlags_NoAlpha) ? 3 : 4));
06183             ColorPicker4("##previewing_picker", &previewing_ref_col.x, picker_flags);
06184             PopID();
06185         }
06186         PopItemWidth();
06187     }
06188     if (allow_opt_alpha_bar)
06189     {
06190         if (allow_opt_picker) Separator();
06191         CheckboxFlags("Alpha Bar", &g.ColorEditOptions, ImGuiColorEditFlags_AlphaBar);
06192     }
06193     EndPopup();
06194     g.LockMarkEdited--;
06195 }
