06314 bool ImGui::TreeNodeUpdateNextOpen(ImGuiID storage_id, ImGuiTreeNodeFlags flags)
06315 {
06316     if (flags & ImGuiTreeNodeFlags_Leaf)
06317         return true;
06318 
06319     // We only write to the tree storage if the user clicks, or explicitly use the SetNextItemOpen function
06320     ImGuiContext& g = *GImGui;
06321     ImGuiWindow* window = g.CurrentWindow;
06322     ImGuiStorage* storage = window->DC.StateStorage;
06323 
06324     bool is_open;
06325     if (g.NextItemData.Flags & ImGuiNextItemDataFlags_HasOpen)
06326     {
06327         if (g.NextItemData.OpenCond & ImGuiCond_Always)
06328         {
06329             is_open = g.NextItemData.OpenVal;
06330             TreeNodeSetOpen(storage_id, is_open);
06331         }
06332         else
06333         {
06334             // We treat ImGuiCond_Once and ImGuiCond_FirstUseEver the same because tree node state are not saved persistently.
06335             const int stored_value = storage->GetInt(storage_id, -1);
06336             if (stored_value == -1)
06337             {
06338                 is_open = g.NextItemData.OpenVal;
06339                 TreeNodeSetOpen(storage_id, is_open);
06340             }
06341             else
06342             {
06343                 is_open = stored_value != 0;
06344             }
06345         }
06346     }
06347     else
06348     {
06349         is_open = storage->GetInt(storage_id, (flags & ImGuiTreeNodeFlags_DefaultOpen) ? 1 : 0) != 0;
06350     }
06351 
06352     // When logging is enabled, we automatically expand tree nodes (but *NOT* collapsing headers.. seems like sensible behavior).
06353     // NB- If we are above max depth we still allow manually opened nodes to be logged.
06354     if (g.LogEnabled && !(flags & ImGuiTreeNodeFlags_NoAutoOpenOnLog) && (window->DC.TreeDepth - g.LogDepthRef) < g.LogDepthToExpand)
06355         is_open = true;
06356 
06357     return is_open;
06358 }
