06360 // Store ImGuiTreeNodeStackData for just submitted node.
06361 // Currently only supports 32 level deep and we are fine with (1 << Depth) overflowing into a zero, easy to increase.
06362 static void TreeNodeStoreStackData(ImGuiTreeNodeFlags flags)
06363 {
06364     ImGuiContext& g = *GImGui;
06365     ImGuiWindow* window = g.CurrentWindow;
06366 
06367     g.TreeNodeStack.resize(g.TreeNodeStack.Size + 1);
06368     ImGuiTreeNodeStackData* tree_node_data = &g.TreeNodeStack.back();
06369     tree_node_data->ID = g.LastItemData.ID;
06370     tree_node_data->TreeFlags = flags;
06371     tree_node_data->InFlags = g.LastItemData.InFlags;
06372     tree_node_data->NavRect = g.LastItemData.NavRect;
06373     window->DC.TreeHasStackDataDepthMask |= (1 << window->DC.TreeDepth);
06374 }
06375 
06376 // When using public API, currently 'id == storage_id' is always true, but we separate the values to facilitate advanced user code doing storage queries outside of UI loop.
06377 bool ImGui::TreeNodeBehavior(ImGuiID id, ImGuiTreeNodeFlags flags, const char* label, const char* label_end)
06378 {
06379     ImGuiWindow* window = GetCurrentWindow();
06380     if (window->SkipItems)
06381         return false;
06382 
06383     ImGuiContext& g = *GImGui;
06384     const ImGuiStyle& style = g.Style;
06385     const bool display_frame = (flags & ImGuiTreeNodeFlags_Framed) != 0;
06386     const ImVec2 padding = (display_frame || (flags & ImGuiTreeNodeFlags_FramePadding)) ? style.FramePadding : ImVec2(style.FramePadding.x, ImMin(window->DC.CurrLineTextBaseOffset, style.FramePadding.y));
06387 
06388     if (!label_end)
06389         label_end = FindRenderedTextEnd(label);
06390     const ImVec2 label_size = CalcTextSize(label, label_end, false);
06391 
06392     const float text_offset_x = g.FontSize + (display_frame ? padding.x * 3 : padding.x * 2);   // Collapsing arrow width + Spacing
06393     const float text_offset_y = ImMax(padding.y, window->DC.CurrLineTextBaseOffset);            // Latch before ItemSize changes it
06394     const float text_width = g.FontSize + label_size.x + padding.x * 2;                         // Include collapsing arrow
06395 
06396     // We vertically grow up to current line height up the typical widget height.
06397     const float frame_height = ImMax(ImMin(window->DC.CurrLineSize.y, g.FontSize + style.FramePadding.y * 2), label_size.y + padding.y * 2);
06398     const bool span_all_columns = (flags & ImGuiTreeNodeFlags_SpanAllColumns) != 0 && (g.CurrentTable != NULL);
06399     ImRect frame_bb;
06400     frame_bb.Min.x = span_all_columns ? window->ParentWorkRect.Min.x : (flags & ImGuiTreeNodeFlags_SpanFullWidth) ? window->WorkRect.Min.x : window->DC.CursorPos.x;
06401     frame_bb.Min.y = window->DC.CursorPos.y;
06402     frame_bb.Max.x = span_all_columns ? window->ParentWorkRect.Max.x : (flags & ImGuiTreeNodeFlags_SpanTextWidth) ? window->DC.CursorPos.x + text_width + padding.x : window->WorkRect.Max.x;
06403     frame_bb.Max.y = window->DC.CursorPos.y + frame_height;
06404     if (display_frame)
06405     {
06406         const float outer_extend = IM_TRUNC(window->WindowPadding.x * 0.5f); // Framed header expand a little outside of current limits
06407         frame_bb.Min.x -= outer_extend;
06408         frame_bb.Max.x += outer_extend;
06409     }
06410 
06411     ImVec2 text_pos(window->DC.CursorPos.x + text_offset_x, window->DC.CursorPos.y + text_offset_y);
06412     ItemSize(ImVec2(text_width, frame_height), padding.y);
06413 
06414     // For regular tree nodes, we arbitrary allow to click past 2 worth of ItemSpacing
06415     ImRect interact_bb = frame_bb;
06416     if ((flags & (ImGuiTreeNodeFlags_Framed | ImGuiTreeNodeFlags_SpanAvailWidth | ImGuiTreeNodeFlags_SpanFullWidth | ImGuiTreeNodeFlags_SpanTextWidth | ImGuiTreeNodeFlags_SpanAllColumns)) == 0)
06417         interact_bb.Max.x = frame_bb.Min.x + text_width + (label_size.x > 0.0f ? style.ItemSpacing.x * 2.0f : 0.0f);
06418 
06419     // Compute open and multi-select states before ItemAdd() as it clear NextItem data.
06420     ImGuiID storage_id = (g.NextItemData.Flags & ImGuiNextItemDataFlags_HasStorageID) ? g.NextItemData.StorageId : id;
06421     bool is_open = TreeNodeUpdateNextOpen(storage_id, flags);
06422 
06423     bool is_visible;
06424     if (span_all_columns)
06425     {
06426         // Modify ClipRect for the ItemAdd(), faster than doing a PushColumnsBackground/PushTableBackgroundChannel for every Selectable..
06427         const float backup_clip_rect_min_x = window->ClipRect.Min.x;
06428         const float backup_clip_rect_max_x = window->ClipRect.Max.x;
06429         window->ClipRect.Min.x = window->ParentWorkRect.Min.x;
06430         window->ClipRect.Max.x = window->ParentWorkRect.Max.x;
06431         is_visible = ItemAdd(interact_bb, id);
06432         window->ClipRect.Min.x = backup_clip_rect_min_x;
06433         window->ClipRect.Max.x = backup_clip_rect_max_x;
06434     }
06435     else
06436     {
06437         is_visible = ItemAdd(interact_bb, id);
06438     }
06439     g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_HasDisplayRect;
06440     g.LastItemData.DisplayRect = frame_bb;
06441 
06442     // If a NavLeft request is happening and ImGuiTreeNodeFlags_NavLeftJumpsBackHere enabled:
06443     // Store data for the current depth to allow returning to this node from any child item.
06444     // For this purpose we essentially compare if g.NavIdIsAlive went from 0 to 1 between TreeNode() and TreePop().
06445     // It will become tempting to enable ImGuiTreeNodeFlags_NavLeftJumpsBackHere by default or move it to ImGuiStyle.
06446     bool store_tree_node_stack_data = false;
06447     if (!(flags & ImGuiTreeNodeFlags_NoTreePushOnOpen))
06448     {
06449         if ((flags & ImGuiTreeNodeFlags_NavLeftJumpsBackHere) && is_open && !g.NavIdIsAlive)
06450             if (g.NavMoveDir == ImGuiDir_Left && g.NavWindow == window && NavMoveRequestButNoResultYet())
06451                 store_tree_node_stack_data = true;
06452     }
06453 
06454     const bool is_leaf = (flags & ImGuiTreeNodeFlags_Leaf) != 0;
06455     if (!is_visible)
06456     {
06457         if (store_tree_node_stack_data && is_open)
06458             TreeNodeStoreStackData(flags); // Call before TreePushOverrideID()
06459         if (is_open && !(flags & ImGuiTreeNodeFlags_NoTreePushOnOpen))
06460             TreePushOverrideID(id);
06461         IMGUI_TEST_ENGINE_ITEM_INFO(g.LastItemData.ID, label, g.LastItemData.StatusFlags | (is_leaf ? 0 : ImGuiItemStatusFlags_Openable) | (is_open ? ImGuiItemStatusFlags_Opened : 0));
06462         return is_open;
06463     }
06464 
06465     if (span_all_columns)
06466     {
06467         TablePushBackgroundChannel();
06468         g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_HasClipRect;
06469         g.LastItemData.ClipRect = window->ClipRect;
06470     }
06471 
06472     ImGuiButtonFlags button_flags = ImGuiTreeNodeFlags_None;
06473     if ((flags & ImGuiTreeNodeFlags_AllowOverlap) || (g.LastItemData.InFlags & ImGuiItemFlags_AllowOverlap))
06474         button_flags |= ImGuiButtonFlags_AllowOverlap;
06475     if (!is_leaf)
06476         button_flags |= ImGuiButtonFlags_PressedOnDragDropHold;
06477 
06478     // We allow clicking on the arrow section with keyboard modifiers held, in order to easily
06479     // allow browsing a tree while preserving selection with code implementing multi-selection patterns.
06480     // When clicking on the rest of the tree node we always disallow keyboard modifiers.
06481     const float arrow_hit_x1 = (text_pos.x - text_offset_x) - style.TouchExtraPadding.x;
06482     const float arrow_hit_x2 = (text_pos.x - text_offset_x) + (g.FontSize + padding.x * 2.0f) + style.TouchExtraPadding.x;
06483     const bool is_mouse_x_over_arrow = (g.IO.MousePos.x >= arrow_hit_x1 && g.IO.MousePos.x < arrow_hit_x2);
06484 
06485     const bool is_multi_select = (g.LastItemData.InFlags & ImGuiItemFlags_IsMultiSelect) != 0;
06486     if (is_multi_select) // We absolutely need to distinguish open vs select so _OpenOnArrow comes by default
06487         flags |= (flags & ImGuiTreeNodeFlags_OpenOnMask_) == 0 ? ImGuiTreeNodeFlags_OpenOnArrow | ImGuiTreeNodeFlags_OpenOnDoubleClick : ImGuiTreeNodeFlags_OpenOnArrow;
06488 
06489     // Open behaviors can be altered with the _OpenOnArrow and _OnOnDoubleClick flags.
06490     // Some alteration have subtle effects (e.g. toggle on MouseUp vs MouseDown events) due to requirements for multi-selection and drag and drop support.
06491     // - Single-click on label = Toggle on MouseUp (default, when _OpenOnArrow=0)
06492     // - Single-click on arrow = Toggle on MouseDown (when _OpenOnArrow=0)
06493     // - Single-click on arrow = Toggle on MouseDown (when _OpenOnArrow=1)
06494     // - Double-click on label = Toggle on MouseDoubleClick (when _OpenOnDoubleClick=1)
06495     // - Double-click on arrow = Toggle on MouseDoubleClick (when _OpenOnDoubleClick=1 and _OpenOnArrow=0)
06496     // It is rather standard that arrow click react on Down rather than Up.
06497     // We set ImGuiButtonFlags_PressedOnClickRelease on OpenOnDoubleClick because we want the item to be active on the initial MouseDown in order for drag and drop to work.
06498     if (is_mouse_x_over_arrow)
06499         button_flags |= ImGuiButtonFlags_PressedOnClick;
06500     else if (flags & ImGuiTreeNodeFlags_OpenOnDoubleClick)
06501         button_flags |= ImGuiButtonFlags_PressedOnClickRelease | ImGuiButtonFlags_PressedOnDoubleClick;
06502     else
06503         button_flags |= ImGuiButtonFlags_PressedOnClickRelease;
06504 
06505     bool selected = (flags & ImGuiTreeNodeFlags_Selected) != 0;
06506     const bool was_selected = selected;
06507 
06508     // Multi-selection support (header)
06509     if (is_multi_select)
06510     {
06511         // Handle multi-select + alter button flags for it
06512         MultiSelectItemHeader(id, &selected, &button_flags);
06513         if (is_mouse_x_over_arrow)
06514             button_flags = (button_flags | ImGuiButtonFlags_PressedOnClick) & ~ImGuiButtonFlags_PressedOnClickRelease;
06515     }
06516     else
06517     {
06518         if (window != g.HoveredWindow || !is_mouse_x_over_arrow)
06519             button_flags |= ImGuiButtonFlags_NoKeyModifiers;
06520     }
06521 
06522     bool hovered, held;
06523     bool pressed = ButtonBehavior(interact_bb, id, &hovered, &held, button_flags);
06524     bool toggled = false;
06525     if (!is_leaf)
06526     {
06527         if (pressed && g.DragDropHoldJustPressedId != id)
06528         {
06529             if ((flags & ImGuiTreeNodeFlags_OpenOnMask_) == 0 || (g.NavActivateId == id && !is_multi_select))
06530                 toggled = true; // Single click
06531             if (flags & ImGuiTreeNodeFlags_OpenOnArrow)
06532                 toggled |= is_mouse_x_over_arrow && !g.NavDisableMouseHover; // Lightweight equivalent of IsMouseHoveringRect() since ButtonBehavior() already did the job
06533             if ((flags & ImGuiTreeNodeFlags_OpenOnDoubleClick) && g.IO.MouseClickedCount[0] == 2)
06534                 toggled = true; // Double click
06535         }
06536         else if (pressed && g.DragDropHoldJustPressedId == id)
06537         {
06538             IM_ASSERT(button_flags & ImGuiButtonFlags_PressedOnDragDropHold);
06539             if (!is_open) // When using Drag and Drop "hold to open" we keep the node highlighted after opening, but never close it again.
06540                 toggled = true;
06541             else
06542                 pressed = false; // Cancel press so it doesn't trigger selection.
06543         }
06544 
06545         if (g.NavId == id && g.NavMoveDir == ImGuiDir_Left && is_open)
06546         {
06547             toggled = true;
06548             NavClearPreferredPosForAxis(ImGuiAxis_X);
06549             NavMoveRequestCancel();
06550         }
06551         if (g.NavId == id && g.NavMoveDir == ImGuiDir_Right && !is_open) // If there's something upcoming on the line we may want to give it the priority?
06552         {
06553             toggled = true;
06554             NavClearPreferredPosForAxis(ImGuiAxis_X);
06555             NavMoveRequestCancel();
06556         }
06557 
06558         if (toggled)
06559         {
06560             is_open = !is_open;
06561             window->DC.StateStorage->SetInt(storage_id, is_open);
06562             g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_ToggledOpen;
06563         }
06564     }
06565 
06566     // Multi-selection support (footer)
06567     if (is_multi_select)
06568     {
06569         bool pressed_copy = pressed && !toggled;
06570         MultiSelectItemFooter(id, &selected, &pressed_copy);
06571         if (pressed)
06572             SetNavID(id, window->DC.NavLayerCurrent, g.CurrentFocusScopeId, interact_bb);
06573     }
06574 
06575     if (selected != was_selected)
06576         g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_ToggledSelection;
06577 
06578     // Render
06579     {
06580         const ImU32 text_col = GetColorU32(ImGuiCol_Text);
06581         ImGuiNavHighlightFlags nav_highlight_flags = ImGuiNavHighlightFlags_Compact;
06582         if (is_multi_select)
06583             nav_highlight_flags |= ImGuiNavHighlightFlags_AlwaysDraw; // Always show the nav rectangle
06584         if (display_frame)
06585         {
06586             // Framed type
06587             const ImU32 bg_col = GetColorU32((held && hovered) ? ImGuiCol_HeaderActive : hovered ? ImGuiCol_HeaderHovered : ImGuiCol_Header);
06588             RenderFrame(frame_bb.Min, frame_bb.Max, bg_col, true, style.FrameRounding);
06589             RenderNavHighlight(frame_bb, id, nav_highlight_flags);
06590             if (flags & ImGuiTreeNodeFlags_Bullet)
06591                 RenderBullet(window->DrawList, ImVec2(text_pos.x - text_offset_x * 0.60f, text_pos.y + g.FontSize * 0.5f), text_col);
06592             else if (!is_leaf)
06593                 RenderArrow(window->DrawList, ImVec2(text_pos.x - text_offset_x + padding.x, text_pos.y), text_col, is_open ? ((flags & ImGuiTreeNodeFlags_UpsideDownArrow) ? ImGuiDir_Up : ImGuiDir_Down) : ImGuiDir_Right, 1.0f);
06594             else // Leaf without bullet, left-adjusted text
06595                 text_pos.x -= text_offset_x - padding.x;
06596             if (flags & ImGuiTreeNodeFlags_ClipLabelForTrailingButton)
06597                 frame_bb.Max.x -= g.FontSize + style.FramePadding.x;
06598             if (g.LogEnabled)
06599                 LogSetNextTextDecoration("###", "###");
06600         }
06601         else
06602         {
06603             // Unframed typed for tree nodes
06604             if (hovered || selected)
06605             {
06606                 const ImU32 bg_col = GetColorU32((held && hovered) ? ImGuiCol_HeaderActive : hovered ? ImGuiCol_HeaderHovered : ImGuiCol_Header);
06607                 RenderFrame(frame_bb.Min, frame_bb.Max, bg_col, false);
06608             }
06609             RenderNavHighlight(frame_bb, id, nav_highlight_flags);
06610             if (flags & ImGuiTreeNodeFlags_Bullet)
06611                 RenderBullet(window->DrawList, ImVec2(text_pos.x - text_offset_x * 0.5f, text_pos.y + g.FontSize * 0.5f), text_col);
06612             else if (!is_leaf)
06613                 RenderArrow(window->DrawList, ImVec2(text_pos.x - text_offset_x + padding.x, text_pos.y + g.FontSize * 0.15f), text_col, is_open ? ((flags & ImGuiTreeNodeFlags_UpsideDownArrow) ? ImGuiDir_Up : ImGuiDir_Down) : ImGuiDir_Right, 0.70f);
06614             if (g.LogEnabled)
06615                 LogSetNextTextDecoration(">", NULL);
06616         }
06617 
06618         if (span_all_columns)
06619             TablePopBackgroundChannel();
06620 
06621         // Label
06622         if (display_frame)
06623             RenderTextClipped(text_pos, frame_bb.Max, label, label_end, &label_size);
06624         else
06625             RenderText(text_pos, label, label_end, false);
06626     }
06627 
06628     if (store_tree_node_stack_data && is_open)
06629         TreeNodeStoreStackData(flags); // Call before TreePushOverrideID()
06630     if (is_open && !(flags & ImGuiTreeNodeFlags_NoTreePushOnOpen))
06631         TreePushOverrideID(id); // Could use TreePush(label) but this avoid computing twice
06632 
06633     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | (is_leaf ? 0 : ImGuiItemStatusFlags_Openable) | (is_open ? ImGuiItemStatusFlags_Opened : 0));
06634     return is_open;
06635 }
06636 
06637 void ImGui::TreePush(const char* str_id)
06638 {
06639     ImGuiWindow* window = GetCurrentWindow();
06640     Indent();
06641     window->DC.TreeDepth++;
06642     PushID(str_id);
06643 }
06644 
06645 void ImGui::TreePush(const void* ptr_id)
06646 {
06647     ImGuiWindow* window = GetCurrentWindow();
06648     Indent();
06649     window->DC.TreeDepth++;
06650     PushID(ptr_id);
06651 }
06652 
06653 void ImGui::TreePushOverrideID(ImGuiID id)
06654 {
06655     ImGuiContext& g = *GImGui;
06656     ImGuiWindow* window = g.CurrentWindow;
06657     Indent();
06658     window->DC.TreeDepth++;
06659     PushOverrideID(id);
06660 }
06661 
06662 void ImGui::TreePop()
06663 {
06664     ImGuiContext& g = *GImGui;
06665     ImGuiWindow* window = g.CurrentWindow;
06666     Unindent();
06667 
06668     window->DC.TreeDepth--;
06669     ImU32 tree_depth_mask = (1 << window->DC.TreeDepth);
06670 
06671     if (window->DC.TreeHasStackDataDepthMask & tree_depth_mask) // Only set during request
06672     {
06673         ImGuiTreeNodeStackData* data = &g.TreeNodeStack.back();
06674         IM_ASSERT(data->ID == window->IDStack.back());
06675         if (data->TreeFlags & ImGuiTreeNodeFlags_NavLeftJumpsBackHere)
06676         {
06677             // Handle Left arrow to move to parent tree node (when ImGuiTreeNodeFlags_NavLeftJumpsBackHere is enabled)
06678             if (g.NavIdIsAlive && g.NavMoveDir == ImGuiDir_Left && g.NavWindow == window && NavMoveRequestButNoResultYet())
06679                 NavMoveRequestResolveWithPastTreeNode(&g.NavMoveResultLocal, data);
06680         }
06681         g.TreeNodeStack.pop_back();
06682         window->DC.TreeHasStackDataDepthMask &= ~tree_depth_mask;
06683     }
06684 
06685     IM_ASSERT(window->IDStack.Size > 1); // There should always be 1 element in the IDStack (pushed during window creation). If this triggers you called TreePop/PopID too much.
06686     PopID();
06687 }
06688 
06689 // Horizontal distance preceding label when using TreeNode() or Bullet()
06690 float ImGui::GetTreeNodeToLabelSpacing()
06691 {
06692     ImGuiContext& g = *GImGui;
06693     return g.FontSize + (g.Style.FramePadding.x * 2.0f);
06694 }
