06696 // Set next TreeNode/CollapsingHeader open state.
06697 void ImGui::SetNextItemOpen(bool is_open, ImGuiCond cond)
06698 {
06699     ImGuiContext& g = *GImGui;
06700     if (g.CurrentWindow->SkipItems)
06701         return;
06702     g.NextItemData.Flags |= ImGuiNextItemDataFlags_HasOpen;
06703     g.NextItemData.OpenVal = is_open;
