06706 
06707 // Set next TreeNode/CollapsingHeader storage id.
06708 void ImGui::SetNextItemStorageID(ImGuiID storage_id)
06709 {
06710     ImGuiContext& g = *GImGui;
06711     if (g.CurrentWindow->SkipItems)
06712         return;
06713     g.NextItemData.Flags |= ImGuiNextItemDataFlags_HasStorageID;
06714     g.NextItemData.StorageId = storage_id;
06715 }
06716 
06717 // CollapsingHeader returns true when opened but do not indent nor push into the ID stack (because of the ImGuiTreeNodeFlags_NoTreePushOnOpen flag).
06718 // This is basically the same as calling TreeNodeEx(label, ImGuiTreeNodeFlags_CollapsingHeader). You can remove the _NoTreePushOnOpen flag if you want behavior closer to normal TreeNode().
06719 bool ImGui::CollapsingHeader(const char* label, ImGuiTreeNodeFlags flags)
06720 {
06721     ImGuiWindow* window = GetCurrentWindow();
06722     if (window->SkipItems)
06723         return false;
06724     ImGuiID id = window->GetID(label);
06725     return TreeNodeBehavior(id, flags | ImGuiTreeNodeFlags_CollapsingHeader, label);
06726 }
06727 
06728 // p_visible == NULL                        : regular collapsing header
06729 // p_visible != NULL && *p_visible == true  : show a small close button on the corner of the header, clicking the button will set *p_visible = false
06730 // p_visible != NULL && *p_visible == false : do not show the header at all
06731 // Do not mistake this with the Open state of the header itself, which you can adjust with SetNextItemOpen() or ImGuiTreeNodeFlags_DefaultOpen.
06732 bool ImGui::CollapsingHeader(const char* label, bool* p_visible, ImGuiTreeNodeFlags flags)
06733 {
06734     ImGuiWindow* window = GetCurrentWindow();
06735     if (window->SkipItems)
06736         return false;
06737 
06738     if (p_visible && !*p_visible)
06739         return false;
06740 
06741     ImGuiID id = window->GetID(label);
06742     flags |= ImGuiTreeNodeFlags_CollapsingHeader;
06743     if (p_visible)
06744         flags |= ImGuiTreeNodeFlags_AllowOverlap | (ImGuiTreeNodeFlags)ImGuiTreeNodeFlags_ClipLabelForTrailingButton;
06745     bool is_open = TreeNodeBehavior(id, flags, label);
06746     if (p_visible != NULL)
06747     {
06748         // Create a small overlapping close button
06749         // FIXME: We can evolve this into user accessible helpers to add extra buttons on title bars, headers, etc.
06750         // FIXME: CloseButton can overlap into text, need find a way to clip the text somehow.
06751         ImGuiContext& g = *GImGui;
06752         ImGuiLastItemData last_item_backup = g.LastItemData;
06753         float button_size = g.FontSize;
06754         float button_x = ImMax(g.LastItemData.Rect.Min.x, g.LastItemData.Rect.Max.x - g.Style.FramePadding.x - button_size);
06755         float button_y = g.LastItemData.Rect.Min.y + g.Style.FramePadding.y;
06756         ImGuiID close_button_id = GetIDWithSeed("#CLOSE", NULL, id);
06757         if (CloseButton(close_button_id, ImVec2(button_x, button_y)))
06758             *p_visible = false;
06759         g.LastItemData = last_item_backup;
06760     }
06761 
06762     return is_open;
06763 }
06764 
06765 //-------------------------------------------------------------------------
06766 // [SECTION] Widgets: Selectable
06767 //-------------------------------------------------------------------------
06768 // - Selectable()
06769 //-------------------------------------------------------------------------
06770 
06771 // Tip: pass a non-visible label (e.g. "##hello") then you can use the space to draw other text or image.
06772 // But you need to make sure the ID is unique, e.g. enclose calls in PushID/PopID or use ##unique_id.
06773 // With this scheme, ImGuiSelectableFlags_SpanAllColumns and ImGuiSelectableFlags_AllowOverlap are also frequently used flags.
06774 // FIXME: Selectable() with (size.x == 0.0f) and (SelectableTextAlign.x > 0.0f) followed by SameLine() is currently not supported.
06775 bool ImGui::Selectable(const char* label, bool selected, ImGuiSelectableFlags flags, const ImVec2& size_arg)
06776 {
06777     ImGuiWindow* window = GetCurrentWindow();
06778     if (window->SkipItems)
06779         return false;
06780 
06781     ImGuiContext& g = *GImGui;
06782     const ImGuiStyle& style = g.Style;
06783 
06784     // Submit label or explicit size to ItemSize(), whereas ItemAdd() will submit a larger/spanning rectangle.
06785     ImGuiID id = window->GetID(label);
06786     ImVec2 label_size = CalcTextSize(label, NULL, true);
06787     ImVec2 size(size_arg.x != 0.0f ? size_arg.x : label_size.x, size_arg.y != 0.0f ? size_arg.y : label_size.y);
06788     ImVec2 pos = window->DC.CursorPos;
06789     pos.y += window->DC.CurrLineTextBaseOffset;
06790     ItemSize(size, 0.0f);
06791 
06792     // Fill horizontal space
06793     // We don't support (size < 0.0f) in Selectable() because the ItemSpacing extension would make explicitly right-aligned sizes not visibly match other widgets.
06794     const bool span_all_columns = (flags & ImGuiSelectableFlags_SpanAllColumns) != 0;
06795     const float min_x = span_all_columns ? window->ParentWorkRect.Min.x : pos.x;
06796     const float max_x = span_all_columns ? window->ParentWorkRect.Max.x : window->WorkRect.Max.x;
06797     if (size_arg.x == 0.0f || (flags & ImGuiSelectableFlags_SpanAvailWidth))
06798         size.x = ImMax(label_size.x, max_x - min_x);
06799 
06800     // Text stays at the submission position, but bounding box may be extended on both sides
06801     const ImVec2 text_min = pos;
06802     const ImVec2 text_max(min_x + size.x, pos.y + size.y);
06803 
06804     // Selectables are meant to be tightly packed together with no click-gap, so we extend their box to cover spacing between selectable.
06805     // FIXME: Not part of layout so not included in clipper calculation, but ItemSize currently doesn't allow offsetting CursorPos.
06806     ImRect bb(min_x, pos.y, text_max.x, text_max.y);
06807     if ((flags & ImGuiSelectableFlags_NoPadWithHalfSpacing) == 0)
06808     {
06809         const float spacing_x = span_all_columns ? 0.0f : style.ItemSpacing.x;
06810         const float spacing_y = style.ItemSpacing.y;
06811         const float spacing_L = IM_TRUNC(spacing_x * 0.50f);
06812         const float spacing_U = IM_TRUNC(spacing_y * 0.50f);
06813         bb.Min.x -= spacing_L;
06814         bb.Min.y -= spacing_U;
06815         bb.Max.x += (spacing_x - spacing_L);
06816         bb.Max.y += (spacing_y - spacing_U);
06817     }
06818     //if (g.IO.KeyCtrl) { GetForegroundDrawList()->AddRect(bb.Min, bb.Max, IM_COL32(0, 255, 0, 255)); }
06819 
06820     const bool disabled_item = (flags & ImGuiSelectableFlags_Disabled) != 0;
06821     const ImGuiItemFlags extra_item_flags = disabled_item ? (ImGuiItemFlags)ImGuiItemFlags_Disabled : ImGuiItemFlags_None;
06822     bool is_visible;
06823     if (span_all_columns)
06824     {
06825         // Modify ClipRect for the ItemAdd(), faster than doing a PushColumnsBackground/PushTableBackgroundChannel for every Selectable..
06826         const float backup_clip_rect_min_x = window->ClipRect.Min.x;
06827         const float backup_clip_rect_max_x = window->ClipRect.Max.x;
06828         window->ClipRect.Min.x = window->ParentWorkRect.Min.x;
06829         window->ClipRect.Max.x = window->ParentWorkRect.Max.x;
06830         is_visible = ItemAdd(bb, id, NULL, extra_item_flags);
06831         window->ClipRect.Min.x = backup_clip_rect_min_x;
06832         window->ClipRect.Max.x = backup_clip_rect_max_x;
06833     }
06834     else
06835     {
06836         is_visible = ItemAdd(bb, id, NULL, extra_item_flags);
06837     }
06838 
06839     const bool is_multi_select = (g.LastItemData.InFlags & ImGuiItemFlags_IsMultiSelect) != 0;
06840     if (!is_visible)
06841         if (!is_multi_select || !g.BoxSelectState.UnclipMode || !g.BoxSelectState.UnclipRect.Overlaps(bb)) // Extra layer of "no logic clip" for box-select support (would be more overhead to add to ItemAdd)
06842             return false;
06843 
06844     const bool disabled_global = (g.CurrentItemFlags & ImGuiItemFlags_Disabled) != 0;
06845     if (disabled_item && !disabled_global) // Only testing this as an optimization
06846         BeginDisabled();
06847 
06848     // FIXME: We can standardize the behavior of those two, we could also keep the fast path of override ClipRect + full push on render only,
06849     // which would be advantageous since most selectable are not selected.
06850     if (span_all_columns)
06851     {
06852         if (g.CurrentTable)
06853             TablePushBackgroundChannel();
06854         else if (window->DC.CurrentColumns)
06855             PushColumnsBackground();
06856         g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_HasClipRect;
06857         g.LastItemData.ClipRect = window->ClipRect;
06858     }
06859 
06860     // We use NoHoldingActiveID on menus so user can click and _hold_ on a menu then drag to browse child entries
06861     ImGuiButtonFlags button_flags = 0;
06862     if (flags & ImGuiSelectableFlags_NoHoldingActiveID) { button_flags |= ImGuiButtonFlags_NoHoldingActiveId; }
06863     if (flags & ImGuiSelectableFlags_NoSetKeyOwner)     { button_flags |= ImGuiButtonFlags_NoSetKeyOwner; }
06864     if (flags & ImGuiSelectableFlags_SelectOnClick)     { button_flags |= ImGuiButtonFlags_PressedOnClick; }
06865     if (flags & ImGuiSelectableFlags_SelectOnRelease)   { button_flags |= ImGuiButtonFlags_PressedOnRelease; }
06866     if (flags & ImGuiSelectableFlags_AllowDoubleClick)  { button_flags |= ImGuiButtonFlags_PressedOnClickRelease | ImGuiButtonFlags_PressedOnDoubleClick; }
06867     if ((flags & ImGuiSelectableFlags_AllowOverlap) || (g.LastItemData.InFlags & ImGuiItemFlags_AllowOverlap)) { button_flags |= ImGuiButtonFlags_AllowOverlap; }
06868 
06869     // Multi-selection support (header)
06870     const bool was_selected = selected;
06871     if (is_multi_select)
06872     {
06873         // Handle multi-select + alter button flags for it
06874         MultiSelectItemHeader(id, &selected, &button_flags);
06875     }
06876 
06877     bool hovered, held;
06878     bool pressed = ButtonBehavior(bb, id, &hovered, &held, button_flags);
06879 
06880     // Multi-selection support (footer)
06881     if (is_multi_select)
06882     {
06883         MultiSelectItemFooter(id, &selected, &pressed);
06884     }
06885     else
06886     {
06887         // Auto-select when moved into
06888         // - This will be more fully fleshed in the range-select branch
06889         // - This is not exposed as it won't nicely work with some user side handling of shift/control
06890         // - We cannot do 'if (g.NavJustMovedToId != id) { selected = false; pressed = was_selected; }' for two reasons
06891         //   - (1) it would require focus scope to be set, need exposing PushFocusScope() or equivalent (e.g. BeginSelection() calling PushFocusScope())
06892         //   - (2) usage will fail with clipped items
06893         //   The multi-select API aim to fix those issues, e.g. may be replaced with a BeginSelection() API.
06894         if ((flags & ImGuiSelectableFlags_SelectOnNav) && g.NavJustMovedToId != 0 && g.NavJustMovedToFocusScopeId == g.CurrentFocusScopeId)
06895             if (g.NavJustMovedToId == id)
06896                 selected = pressed = true;
06897     }
06898 
06899     // Update NavId when clicking or when Hovering (this doesn't happen on most widgets), so navigation can be resumed with gamepad/keyboard
06900     if (pressed || (hovered && (flags & ImGuiSelectableFlags_SetNavIdOnHover)))
06901     {
06902         if (!g.NavDisableMouseHover && g.NavWindow == window && g.NavLayer == window->DC.NavLayerCurrent)
06903         {
06904             SetNavID(id, window->DC.NavLayerCurrent, g.CurrentFocusScopeId, WindowRectAbsToRel(window, bb)); // (bb == NavRect)
06905             g.NavDisableHighlight = true;
06906         }
06907     }
06908     if (pressed)
06909         MarkItemEdited(id);
06910 
06911     if (selected != was_selected)
06912         g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_ToggledSelection;
06913 
06914     // Render
06915     if (is_visible)
06916     {
06917         const bool highlighted = hovered || (flags & ImGuiSelectableFlags_Highlight);
06918         if (highlighted || selected)
06919         {
06920             // FIXME-MULTISELECT: Styling: Color for 'selected' elements? ImGuiCol_HeaderSelected
06921             ImU32 col;
06922             if (selected && !highlighted)
06923                 col = GetColorU32(ImLerp(GetStyleColorVec4(ImGuiCol_Header), GetStyleColorVec4(ImGuiCol_HeaderHovered), 0.5f));
06924             else
06925                 col = GetColorU32((held && highlighted) ? ImGuiCol_HeaderActive : highlighted ? ImGuiCol_HeaderHovered : ImGuiCol_Header);
06926             RenderFrame(bb.Min, bb.Max, col, false, 0.0f);
06927         }
06928         if (g.NavId == id)
06929         {
06930             ImGuiNavHighlightFlags nav_highlight_flags = ImGuiNavHighlightFlags_Compact | ImGuiNavHighlightFlags_NoRounding;
06931             if (is_multi_select)
06932                 nav_highlight_flags |= ImGuiNavHighlightFlags_AlwaysDraw; // Always show the nav rectangle
06933             RenderNavHighlight(bb, id, nav_highlight_flags);
06934         }
06935     }
06936 
06937     if (span_all_columns)
06938     {
06939         if (g.CurrentTable)
06940             TablePopBackgroundChannel();
06941         else if (window->DC.CurrentColumns)
06942             PopColumnsBackground();
06943     }
06944 
06945     if (is_visible)
06946         RenderTextClipped(text_min, text_max, label, NULL, &label_size, style.SelectableTextAlign, &bb);
06947 
06948     // Automatically close popups
06949     if (pressed && (window->Flags & ImGuiWindowFlags_Popup) && !(flags & ImGuiSelectableFlags_NoAutoClosePopups) && (g.LastItemData.InFlags & ImGuiItemFlags_AutoClosePopups))
06950         CloseCurrentPopup();
06951 
06952     if (disabled_item && !disabled_global)
06953         EndDisabled();
06954 
06955     // Selectable() always returns a pressed state!
06956     // Users of BeginMultiSelect()/EndMultiSelect() scope: you may call ImGui::IsItemToggledSelection() to retrieve
06957     // selection toggle, only useful if you need that state updated (e.g. for rendering purpose) before reaching EndMultiSelect().
06958     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags);
06959     return pressed; //-V1020
06960 }
06961 
06962 bool ImGui::Selectable(const char* label, bool* p_selected, ImGuiSelectableFlags flags, const ImVec2& size_arg)
06963 {
06964     if (Selectable(label, *p_selected, flags, size_arg))
06965     {
06966         *p_selected = !*p_selected;
06967         return true;
06968     }
06969     return false;
06970 }
