06973 //-------------------------------------------------------------------------
06974 // [SECTION] Widgets: Typing-Select support
06975 //-------------------------------------------------------------------------
06976 
06977 // [Experimental] Currently not exposed in public API.
06978 // Consume character inputs and return search request, if any.
06979 // This would typically only be called on the focused window or location you want to grab inputs for, e.g.
06980 //   if (ImGui::IsWindowFocused(...))
06981 //       if (ImGuiTypingSelectRequest* req = ImGui::GetTypingSelectRequest())
06982 //           focus_idx = ImGui::TypingSelectFindMatch(req, my_items.size(), [](void*, int n) { return my_items[n]->Name; }, &my_items, -1);
06983 // However the code is written in a way where calling it from multiple locations is safe (e.g. to obtain buffer).
06984 ImGuiTypingSelectRequest* ImGui::GetTypingSelectRequest(ImGuiTypingSelectFlags flags)
06985 {
06986     ImGuiContext& g = *GImGui;
06987     ImGuiTypingSelectState* data = &g.TypingSelectState;
06988     ImGuiTypingSelectRequest* out_request = &data->Request;
06989 
06990     // Clear buffer
06991     const float TYPING_SELECT_RESET_TIMER = 1.80f;          // FIXME: Potentially move to IO config.
06992     const int TYPING_SELECT_SINGLE_CHAR_COUNT_FOR_LOCK = 4; // Lock single char matching when repeating same char 4 times
06993     if (data->SearchBuffer[0] != 0)
06994     {
06995         bool clear_buffer = false;
06996         clear_buffer |= (g.NavFocusScopeId != data->FocusScope);
06997         clear_buffer |= (data->LastRequestTime + TYPING_SELECT_RESET_TIMER < g.Time);
06998         clear_buffer |= g.NavAnyRequest;
06999         clear_buffer |= g.ActiveId != 0 && g.NavActivateId == 0; // Allow temporary SPACE activation to not interfere
07000         clear_buffer |= IsKeyPressed(ImGuiKey_Escape) || IsKeyPressed(ImGuiKey_Enter);
07001         clear_buffer |= IsKeyPressed(ImGuiKey_Backspace) && (flags & ImGuiTypingSelectFlags_AllowBackspace) == 0;
07002         //if (clear_buffer) { IMGUI_DEBUG_LOG("GetTypingSelectRequest(): Clear SearchBuffer.\n"); }
07003         if (clear_buffer)
07004             data->Clear();
07005     }
07006 
07007     // Append to buffer
07008     const int buffer_max_len = IM_ARRAYSIZE(data->SearchBuffer) - 1;
07009     int buffer_len = (int)strlen(data->SearchBuffer);
07010     bool select_request = false;
07011     for (ImWchar w : g.IO.InputQueueCharacters)
07012     {
07013         const int w_len = ImTextCountUtf8BytesFromStr(&w, &w + 1);
07014         if (w < 32 || (buffer_len == 0 && ImCharIsBlankW(w)) || (buffer_len + w_len > buffer_max_len)) // Ignore leading blanks
07015             continue;
07016         char w_buf[5];
07017         ImTextCharToUtf8(w_buf, (unsigned int)w);
07018         if (data->SingleCharModeLock && w_len == out_request->SingleCharSize && memcmp(w_buf, data->SearchBuffer, w_len) == 0)
07019         {
07020             select_request = true; // Same character: don't need to append to buffer.
07021             continue;
07022         }
07023         if (data->SingleCharModeLock)
07024         {
07025             data->Clear(); // Different character: clear
07026             buffer_len = 0;
07027         }
07028         memcpy(data->SearchBuffer + buffer_len, w_buf, w_len + 1); // Append
07029         buffer_len += w_len;
07030         select_request = true;
07031     }
07032     g.IO.InputQueueCharacters.resize(0);
07033 
07034     // Handle backspace
07035     if ((flags & ImGuiTypingSelectFlags_AllowBackspace) && IsKeyPressed(ImGuiKey_Backspace, ImGuiInputFlags_Repeat))
07036     {
07037         char* p = (char*)(void*)ImTextFindPreviousUtf8Codepoint(data->SearchBuffer, data->SearchBuffer + buffer_len);
07038         *p = 0;
07039         buffer_len = (int)(p - data->SearchBuffer);
07040     }
07041 
07042     // Return request if any
07043     if (buffer_len == 0)
07044         return NULL;
07045     if (select_request)
07046     {
07047         data->FocusScope = g.NavFocusScopeId;
07048         data->LastRequestFrame = g.FrameCount;
07049         data->LastRequestTime = (float)g.Time;
07050     }
07051     out_request->Flags = flags;
07052     out_request->SearchBufferLen = buffer_len;
07053     out_request->SearchBuffer = data->SearchBuffer;
07054     out_request->SelectRequest = (data->LastRequestFrame == g.FrameCount);
07055     out_request->SingleCharMode = false;
07056     out_request->SingleCharSize = 0;
07057 
07058     // Calculate if buffer contains the same character repeated.
07059     // - This can be used to implement a special search mode on first character.
07060     // - Performed on UTF-8 codepoint for correctness.
07061     // - SingleCharMode is always set for first input character, because it usually leads to a "next".
07062     if (flags & ImGuiTypingSelectFlags_AllowSingleCharMode)
07063     {
07064         const char* buf_begin = out_request->SearchBuffer;
07065         const char* buf_end = out_request->SearchBuffer + out_request->SearchBufferLen;
07066         const int c0_len = ImTextCountUtf8BytesFromChar(buf_begin, buf_end);
07067         const char* p = buf_begin + c0_len;
07068         for (; p < buf_end; p += c0_len)
07069             if (memcmp(buf_begin, p, (size_t)c0_len) != 0)
07070                 break;
07071         const int single_char_count = (p == buf_end) ? (out_request->SearchBufferLen / c0_len) : 0;
07072         out_request->SingleCharMode = (single_char_count > 0 || data->SingleCharModeLock);
07073         out_request->SingleCharSize = (ImS8)c0_len;
07074         data->SingleCharModeLock |= (single_char_count >= TYPING_SELECT_SINGLE_CHAR_COUNT_FOR_LOCK); // From now on we stop search matching to lock to single char mode.
07075     }
07076 
07077     return out_request;
07078 }
07079 
07080 static int ImStrimatchlen(const char* s1, const char* s1_end, const char* s2)
07081 {
07082     int match_len = 0;
07083     while (s1 < s1_end && ImToUpper(*s1++) == ImToUpper(*s2++))
07084         match_len++;
07085     return match_len;
07086 }
07087 
07088 // Default handler for finding a result for typing-select. You may implement your own.
07089 // You might want to display a tooltip to visualize the current request SearchBuffer
07090 // When SingleCharMode is set:
07091 // - it is better to NOT display a tooltip of other on-screen display indicator.
07092 // - the index of the currently focused item is required.
07093 //   if your SetNextItemSelectionUserData() values are indices, you can obtain it from ImGuiMultiSelectIO::NavIdItem, otherwise from g.NavLastValidSelectionUserData.
07094 int ImGui::TypingSelectFindMatch(ImGuiTypingSelectRequest* req, int items_count, const char* (*get_item_name_func)(void*, int), void* user_data, int nav_item_idx)
07095 {
07096     if (req == NULL || req->SelectRequest == false) // Support NULL parameter so both calls can be done from same spot.
07097         return -1;
07098     int idx = -1;
07099     if (req->SingleCharMode && (req->Flags & ImGuiTypingSelectFlags_AllowSingleCharMode))
07100         idx = TypingSelectFindNextSingleCharMatch(req, items_count, get_item_name_func, user_data, nav_item_idx);
07101     else
07102         idx = TypingSelectFindBestLeadingMatch(req, items_count, get_item_name_func, user_data);
07103     if (idx != -1)
07104         NavRestoreHighlightAfterMove();
07105     return idx;
07106 }
07107 
07108 // Special handling when a single character is repeated: perform search on a single letter and goes to next.
07109 int ImGui::TypingSelectFindNextSingleCharMatch(ImGuiTypingSelectRequest* req, int items_count, const char* (*get_item_name_func)(void*, int), void* user_data, int nav_item_idx)
07110 {
07111     // FIXME: Assume selection user data is index. Would be extremely practical.
07112     //if (nav_item_idx == -1)
07113     //    nav_item_idx = (int)g.NavLastValidSelectionUserData;
07114 
07115     int first_match_idx = -1;
07116     bool return_next_match = false;
07117     for (int idx = 0; idx < items_count; idx++)
07118     {
07119         const char* item_name = get_item_name_func(user_data, idx);
07120         if (ImStrimatchlen(req->SearchBuffer, req->SearchBuffer + req->SingleCharSize, item_name) < req->SingleCharSize)
07121             continue;
07122         if (return_next_match)                           // Return next matching item after current item.
07123             return idx;
07124         if (first_match_idx == -1 && nav_item_idx == -1) // Return first match immediately if we don't have a nav_item_idx value.
07125             return idx;
07126         if (first_match_idx == -1)                       // Record first match for wrapping.
07127             first_match_idx = idx;
07128         if (nav_item_idx == idx)                         // Record that we encountering nav_item so we can return next match.
07129             return_next_match = true;
07130     }
07131     return first_match_idx; // First result
07132 }
07133 
07134 int ImGui::TypingSelectFindBestLeadingMatch(ImGuiTypingSelectRequest* req, int items_count, const char* (*get_item_name_func)(void*, int), void* user_data)
07135 {
07136     int longest_match_idx = -1;
07137     int longest_match_len = 0;
07138     for (int idx = 0; idx < items_count; idx++)
07139     {
07140         const char* item_name = get_item_name_func(user_data, idx);
07141         const int match_len = ImStrimatchlen(req->SearchBuffer, req->SearchBuffer + req->SearchBufferLen, item_name);
07142         if (match_len <= longest_match_len)
07143             continue;
07144         longest_match_idx = idx;
07145         longest_match_len = match_len;
07146         if (match_len == req->SearchBufferLen)
07147             break;
07148     }
07149     return longest_match_idx;
07150 }
