07163 //-------------------------------------------------------------------------
07164 // [SECTION] Widgets: Box-Select support
07165 // This has been extracted away from Multi-Select logic in the hope that it could eventually be used elsewhere, but hasn't been yet.
07166 //-------------------------------------------------------------------------
07167 // Extra logic in MultiSelectItemFooter() and ImGuiListClipper::Step()
07168 //-------------------------------------------------------------------------
07169 // - BoxSelectPreStartDrag() [Internal]
07170 // - BoxSelectActivateDrag() [Internal]
07171 // - BoxSelectDeactivateDrag() [Internal]
07172 // - BoxSelectScrollWithMouseDrag() [Internal]
07173 // - BeginBoxSelect() [Internal]
07174 // - EndBoxSelect() [Internal]
07175 //-------------------------------------------------------------------------
07176 
07177 // Call on the initial click.
07178 static void BoxSelectPreStartDrag(ImGuiID id, ImGuiSelectionUserData clicked_item)
07179 {
07180     ImGuiContext& g = *GImGui;
07181     ImGuiBoxSelectState* bs = &g.BoxSelectState;
07182     bs->ID = id;
07183     bs->IsStarting = true; // Consider starting box-select.
07184     bs->IsStartedFromVoid = (clicked_item == ImGuiSelectionUserData_Invalid);
07185     bs->IsStartedSetNavIdOnce = bs->IsStartedFromVoid;
07186     bs->KeyMods = g.IO.KeyMods;
07187     bs->StartPosRel = bs->EndPosRel = ImGui::WindowPosAbsToRel(g.CurrentWindow, g.IO.MousePos);
07188     bs->ScrollAccum = ImVec2(0.0f, 0.0f);
07189 }
07190 
07191 static void BoxSelectActivateDrag(ImGuiBoxSelectState* bs, ImGuiWindow* window)
07192 {
07193     ImGuiContext& g = *GImGui;
07194     IMGUI_DEBUG_LOG_SELECTION("[selection] BeginBoxSelect() 0X%08X: Activate\n", bs->ID);
07195     bs->IsActive = true;
07196     bs->Window = window;
07197     bs->IsStarting = false;
07198     ImGui::SetActiveID(bs->ID, window);
07199     ImGui::SetActiveIdUsingAllKeyboardKeys();
07200     if (bs->IsStartedFromVoid && (bs->KeyMods & (ImGuiMod_Ctrl | ImGuiMod_Shift)) == 0)
07201         bs->RequestClear = true;
07202 }
07203 
07204 static void BoxSelectDeactivateDrag(ImGuiBoxSelectState* bs)
07205 {
07206     ImGuiContext& g = *GImGui;
07207     bs->IsActive = bs->IsStarting = false;
07208     if (g.ActiveId == bs->ID)
07209     {
07210         IMGUI_DEBUG_LOG_SELECTION("[selection] BeginBoxSelect() 0X%08X: Deactivate\n", bs->ID);
07211         ImGui::ClearActiveID();
07212     }
07213     bs->ID = 0;
07214 }
07215 
07216 static void BoxSelectScrollWithMouseDrag(ImGuiBoxSelectState* bs, ImGuiWindow* window, const ImRect& inner_r)
07217 {
07218     ImGuiContext& g = *GImGui;
07219     IM_ASSERT(bs->Window == window);
07220     for (int n = 0; n < 2; n++) // each axis
07221     {
07222         const float mouse_pos = g.IO.MousePos[n];
07223         const float dist = (mouse_pos > inner_r.Max[n]) ? mouse_pos - inner_r.Max[n] : (mouse_pos < inner_r.Min[n]) ? mouse_pos - inner_r.Min[n] : 0.0f;
07224         const float scroll_curr = window->Scroll[n];
07225         if (dist == 0.0f || (dist < 0.0f && scroll_curr < 0.0f) || (dist > 0.0f && scroll_curr >= window->ScrollMax[n]))
07226             continue;
07227 
07228         const float speed_multiplier = ImLinearRemapClamp(g.FontSize, g.FontSize * 5.0f, 1.0f, 4.0f, ImAbs(dist)); // x1 to x4 depending on distance
07229         const float scroll_step = g.FontSize * 35.0f * speed_multiplier * ImSign(dist) * g.IO.DeltaTime;
07230         bs->ScrollAccum[n] += scroll_step;
07231 
07232         // Accumulate into a stored value so we can handle high-framerate
07233         const float scroll_step_i = ImFloor(bs->ScrollAccum[n]);
07234         if (scroll_step_i == 0.0f)
07235             continue;
07236         if (n == 0)
07237             ImGui::SetScrollX(window, scroll_curr + scroll_step_i);
07238         else
07239             ImGui::SetScrollY(window, scroll_curr + scroll_step_i);
07240         bs->ScrollAccum[n] -= scroll_step_i;
07241     }
07242 }
07243 
07244 bool ImGui::BeginBoxSelect(const ImRect& scope_rect, ImGuiWindow* window, ImGuiID box_select_id, ImGuiMultiSelectFlags ms_flags)
07245 {
07246     ImGuiContext& g = *GImGui;
07247     ImGuiBoxSelectState* bs = &g.BoxSelectState;
07248     KeepAliveID(box_select_id);
07249     if (bs->ID != box_select_id)
07250         return false;
07251 
07252     // IsStarting is set by MultiSelectItemFooter() when considering a possible box-select. We validate it here and lock geometry.
07253     bs->UnclipMode = false;
07254     bs->RequestClear = false;
07255     if (bs->IsStarting && IsMouseDragPastThreshold(0))
07256         BoxSelectActivateDrag(bs, window);
07257     else if ((bs->IsStarting || bs->IsActive) && g.IO.MouseDown[0] == false)
07258         BoxSelectDeactivateDrag(bs);
07259     if (!bs->IsActive)
07260         return false;
07261 
07262     // Current frame absolute prev/current rectangles are used to toggle selection.
07263     // They are derived from positions relative to scrolling space.
07264     ImVec2 start_pos_abs = WindowPosRelToAbs(window, bs->StartPosRel);
07265     ImVec2 prev_end_pos_abs = WindowPosRelToAbs(window, bs->EndPosRel); // Clamped already
07266     ImVec2 curr_end_pos_abs = g.IO.MousePos;
07267     if (ms_flags & ImGuiMultiSelectFlags_ScopeWindow) // Box-select scrolling only happens with ScopeWindow
07268         curr_end_pos_abs = ImClamp(curr_end_pos_abs, scope_rect.Min, scope_rect.Max);
07269     bs->BoxSelectRectPrev.Min = ImMin(start_pos_abs, prev_end_pos_abs);
07270     bs->BoxSelectRectPrev.Max = ImMax(start_pos_abs, prev_end_pos_abs);
07271     bs->BoxSelectRectCurr.Min = ImMin(start_pos_abs, curr_end_pos_abs);
07272     bs->BoxSelectRectCurr.Max = ImMax(start_pos_abs, curr_end_pos_abs);
07273 
07274     // Box-select 2D mode detects horizontal changes (vertical ones are already picked by Clipper)
07275     // Storing an extra rect used by widgets supporting box-select.
07276     if (ms_flags & ImGuiMultiSelectFlags_BoxSelect2d)
07277         if (bs->BoxSelectRectPrev.Min.x != bs->BoxSelectRectCurr.Min.x || bs->BoxSelectRectPrev.Max.x != bs->BoxSelectRectCurr.Max.x)
07278         {
07279             bs->UnclipMode = true;
07280             bs->UnclipRect = bs->BoxSelectRectPrev; // FIXME-OPT: UnclipRect x coordinates could be intersection of Prev and Curr rect on X axis.
07281             bs->UnclipRect.Add(bs->BoxSelectRectCurr);
07282         }
07283 
07284     //GetForegroundDrawList()->AddRect(bs->UnclipRect.Min, bs->UnclipRect.Max, IM_COL32(255,0,0,200), 0.0f, 0, 3.0f);
07285     //GetForegroundDrawList()->AddRect(bs->BoxSelectRectPrev.Min, bs->BoxSelectRectPrev.Max, IM_COL32(255,0,0,200), 0.0f, 0, 3.0f);
07286     //GetForegroundDrawList()->AddRect(bs->BoxSelectRectCurr.Min, bs->BoxSelectRectCurr.Max, IM_COL32(0,255,0,200), 0.0f, 0, 1.0f);
07287     return true;
07288 }
07289 
07290 void ImGui::EndBoxSelect(const ImRect& scope_rect, ImGuiMultiSelectFlags ms_flags)
07291 {
07292     ImGuiContext& g = *GImGui;
07293     ImGuiWindow* window = g.CurrentWindow;
07294     ImGuiBoxSelectState* bs = &g.BoxSelectState;
07295     IM_ASSERT(bs->IsActive);
07296     bs->UnclipMode = false;
07297 
07298     // Render selection rectangle
07299     bs->EndPosRel = WindowPosAbsToRel(window, ImClamp(g.IO.MousePos, scope_rect.Min, scope_rect.Max)); // Clamp stored position according to current scrolling view
07300     ImRect box_select_r = bs->BoxSelectRectCurr;
07301     box_select_r.ClipWith(scope_rect);
07302     window->DrawList->AddRectFilled(box_select_r.Min, box_select_r.Max, GetColorU32(ImGuiCol_SeparatorHovered, 0.30f)); // FIXME-MULTISELECT: Styling
07303     window->DrawList->AddRect(box_select_r.Min, box_select_r.Max, GetColorU32(ImGuiCol_NavHighlight)); // FIXME-MULTISELECT: Styling
07304 
07305     // Scroll
07306     const bool enable_scroll = (ms_flags & ImGuiMultiSelectFlags_ScopeWindow) && (ms_flags & ImGuiMultiSelectFlags_BoxSelectNoScroll) == 0;
07307     if (enable_scroll)
07308     {
07309         ImRect scroll_r = scope_rect;
07310         scroll_r.Expand(-g.FontSize);
07311         //GetForegroundDrawList()->AddRect(scroll_r.Min, scroll_r.Max, IM_COL32(0, 255, 0, 255));
07312         if (!scroll_r.Contains(g.IO.MousePos))
07313             BoxSelectScrollWithMouseDrag(bs, window, scroll_r);
07314     }
07315 }
