07339 
07340 static ImRect CalcScopeRect(ImGuiMultiSelectTempData* ms, ImGuiWindow* window)
07341 {
07342     if (ms->Flags & ImGuiMultiSelectFlags_ScopeRect)
07343     {
07344         // Warning: this depends on CursorMaxPos so it means to be called by EndMultiSelect() only
07345         return ImRect(ms->ScopeRectMin, ImMax(window->DC.CursorMaxPos, ms->ScopeRectMin));
07346     }
07347     else
07348     {
07349         // Add inner table decoration (#7821) // FIXME: Why not baking in InnerClipRect?
07350         ImRect scope_rect = window->InnerClipRect;
07351         scope_rect.Min = ImMin(scope_rect.Min + ImVec2(window->DecoInnerSizeX1, window->DecoInnerSizeY1), scope_rect.Max);
07352         return scope_rect;
07353     }
07354 }
07355 
07356 // Return ImGuiMultiSelectIO structure.
07357 // Lifetime: don't hold on ImGuiMultiSelectIO* pointers over multiple frames or past any subsequent call to BeginMultiSelect() or EndMultiSelect().
07358 // Passing 'selection_size' and 'items_count' parameters is currently optional.
07359 // - 'selection_size' is useful to disable some shortcut routing: e.g. ImGuiMultiSelectFlags_ClearOnEscape won't claim Escape key when selection_size 0,
07360 //    allowing a first press to clear selection THEN the second press to leave child window and return to parent.
07361 // - 'items_count' is stored in ImGuiMultiSelectIO which makes it a convenient way to pass the information to your ApplyRequest() handler (but you may pass it differently).
07362 // - If they are costly for you to compute (e.g. external intrusive selection without maintaining size), you may avoid them and pass -1.
07363 //   - If you can easily tell if your selection is empty or not, you may pass 0/1, or you may enable ImGuiMultiSelectFlags_ClearOnEscape flag dynamically.
07364 ImGuiMultiSelectIO* ImGui::BeginMultiSelect(ImGuiMultiSelectFlags flags, int selection_size, int items_count)
07365 {
07366     ImGuiContext& g = *GImGui;
07367     ImGuiWindow* window = g.CurrentWindow;
07368 
07369     if (++g.MultiSelectTempDataStacked > g.MultiSelectTempData.Size)
07370         g.MultiSelectTempData.resize(g.MultiSelectTempDataStacked, ImGuiMultiSelectTempData());
07371     ImGuiMultiSelectTempData* ms = &g.MultiSelectTempData[g.MultiSelectTempDataStacked - 1];
07372     IM_STATIC_ASSERT(offsetof(ImGuiMultiSelectTempData, IO) == 0); // Clear() relies on that.
07373     g.CurrentMultiSelect = ms;
07374     if ((flags & (ImGuiMultiSelectFlags_ScopeWindow | ImGuiMultiSelectFlags_ScopeRect)) == 0)
07375         flags |= ImGuiMultiSelectFlags_ScopeWindow;
07376     if (flags & ImGuiMultiSelectFlags_SingleSelect)
07377         flags &= ~(ImGuiMultiSelectFlags_BoxSelect2d | ImGuiMultiSelectFlags_BoxSelect1d);
07378     if (flags & ImGuiMultiSelectFlags_BoxSelect2d)
07379         flags &= ~ImGuiMultiSelectFlags_BoxSelect1d;
07380 
07381     // FIXME: BeginFocusScope()
07382     const ImGuiID id = window->IDStack.back();
07383     ms->Clear();
07384     ms->FocusScopeId = id;
07385     ms->Flags = flags;
07386     ms->IsFocused = (ms->FocusScopeId == g.NavFocusScopeId);
07387     ms->BackupCursorMaxPos = window->DC.CursorMaxPos;
07388     ms->ScopeRectMin = window->DC.CursorMaxPos = window->DC.CursorPos;
07389     PushFocusScope(ms->FocusScopeId);
07390     if (flags & ImGuiMultiSelectFlags_ScopeWindow) // Mark parent child window as navigable into, with highlight. Assume user will always submit interactive items.
07391         window->DC.NavLayersActiveMask |= 1 << ImGuiNavLayer_Main;
07392 
07393     // Use copy of keyboard mods at the time of the request, otherwise we would requires mods to be held for an extra frame.
07394     ms->KeyMods = g.NavJustMovedToId ? (g.NavJustMovedToIsTabbing ? 0 : g.NavJustMovedToKeyMods) : g.IO.KeyMods;
07395     if (flags & ImGuiMultiSelectFlags_NoRangeSelect)
07396         ms->KeyMods &= ~ImGuiMod_Shift;
07397 
07398     // Bind storage
07399     ImGuiMultiSelectState* storage = g.MultiSelectStorage.GetOrAddByKey(id);
07400     storage->ID = id;
07401     storage->LastFrameActive = g.FrameCount;
07402     storage->LastSelectionSize = selection_size;
07403     storage->Window = window;
07404     ms->Storage = storage;
07405 
07406     // Output to user
07407     ms->IO.Requests.resize(0);
07408     ms->IO.RangeSrcItem = storage->RangeSrcItem;
07409     ms->IO.NavIdItem = storage->NavIdItem;
07410     ms->IO.NavIdSelected = (storage->NavIdSelected == 1) ? true : false;
07411     ms->IO.ItemsCount = items_count;
07412 
07413     // Clear when using Navigation to move within the scope
07414     // (we compare FocusScopeId so it possible to use multiple selections inside a same window)
07415     bool request_clear = false;
07416     bool request_select_all = false;
07417     if (g.NavJustMovedToId != 0 && g.NavJustMovedToFocusScopeId == ms->FocusScopeId && g.NavJustMovedToHasSelectionData)
07418     {
07419         if (ms->KeyMods & ImGuiMod_Shift)
07420             ms->IsKeyboardSetRange = true;
07421         if (ms->IsKeyboardSetRange)
07422             IM_ASSERT(storage->RangeSrcItem != ImGuiSelectionUserData_Invalid); // Not ready -> could clear?
07423         if ((ms->KeyMods & (ImGuiMod_Ctrl | ImGuiMod_Shift)) == 0 && (flags & (ImGuiMultiSelectFlags_NoAutoClear | ImGuiMultiSelectFlags_NoAutoSelect)) == 0)
07424             request_clear = true;
07425     }
07426     else if (g.NavJustMovedFromFocusScopeId == ms->FocusScopeId)
07427     {
07428         // Also clear on leaving scope (may be optional?)
07429         if ((ms->KeyMods & (ImGuiMod_Ctrl | ImGuiMod_Shift)) == 0 && (flags & (ImGuiMultiSelectFlags_NoAutoClear | ImGuiMultiSelectFlags_NoAutoSelect)) == 0)
07430             request_clear = true;
07431     }
07432 
07433     // Box-select handling: update active state.
07434     ImGuiBoxSelectState* bs = &g.BoxSelectState;
07435     if (flags & (ImGuiMultiSelectFlags_BoxSelect1d | ImGuiMultiSelectFlags_BoxSelect2d))
07436     {
07437         ms->BoxSelectId = GetID("##BoxSelect");
07438         if (BeginBoxSelect(CalcScopeRect(ms, window), window, ms->BoxSelectId, flags))
07439             request_clear |= bs->RequestClear;
07440     }
07441 
07442     if (ms->IsFocused)
07443     {
07444         // Shortcut: Clear selection (Escape)
07445         // - Only claim shortcut if selection is not empty, allowing further presses on Escape to e.g. leave current child window.
07446         // - Box select also handle Escape and needs to pass an id to bypass ActiveIdUsingAllKeyboardKeys lock.
07447         if (flags & ImGuiMultiSelectFlags_ClearOnEscape)
07448         {
07449             if (selection_size != 0 || bs->IsActive)
07450                 if (Shortcut(ImGuiKey_Escape, ImGuiInputFlags_None, bs->IsActive ? bs->ID : 0))
07451                 {
07452                     request_clear = true;
07453                     if (bs->IsActive)
07454                         BoxSelectDeactivateDrag(bs);
07455                 }
07456         }
07457 
07458         // Shortcut: Select all (CTRL+A)
07459         if (!(flags & ImGuiMultiSelectFlags_SingleSelect) && !(flags & ImGuiMultiSelectFlags_NoSelectAll))
07460             if (Shortcut(ImGuiMod_Ctrl | ImGuiKey_A))
07461                 request_select_all = true;
07462     }
07463 
07464     if (request_clear || request_select_all)
07465     {
07466         MultiSelectAddSetAll(ms, request_select_all);
07467         if (!request_select_all)
07468             storage->LastSelectionSize = 0;
07469     }
07470     ms->LoopRequestSetAll = request_select_all ? 1 : request_clear ? 0 : -1;
07471     ms->LastSubmittedItem = ImGuiSelectionUserData_Invalid;
07472 
07473     if (g.DebugLogFlags & ImGuiDebugLogFlags_EventSelection)
07474         DebugLogMultiSelectRequests("BeginMultiSelect", &ms->IO);
07475 
07476     return &ms->IO;
07477 }
07478 
07479 // Return updated ImGuiMultiSelectIO structure.
07480 // Lifetime: don't hold on ImGuiMultiSelectIO* pointers over multiple frames or past any subsequent call to BeginMultiSelect() or EndMultiSelect().
07481 ImGuiMultiSelectIO* ImGui::EndMultiSelect()
07482 {
07483     ImGuiContext& g = *GImGui;
07484     ImGuiMultiSelectTempData* ms = g.CurrentMultiSelect;
07485     ImGuiMultiSelectState* storage = ms->Storage;
07486     ImGuiWindow* window = g.CurrentWindow;
07487     IM_ASSERT(ms->FocusScopeId == g.CurrentFocusScopeId);
07488     IM_ASSERT(g.CurrentMultiSelect != NULL && storage->Window == g.CurrentWindow);
07489     IM_ASSERT(g.MultiSelectTempDataStacked > 0 && &g.MultiSelectTempData[g.MultiSelectTempDataStacked - 1] == g.CurrentMultiSelect);
07490 
07491     ImRect scope_rect = CalcScopeRect(ms, window);
07492     if (ms->IsFocused)
07493     {
07494         // We currently don't allow user code to modify RangeSrcItem by writing to BeginIO's version, but that would be an easy change here.
07495         if (ms->IO.RangeSrcReset || (ms->RangeSrcPassedBy == false && ms->IO.RangeSrcItem != ImGuiSelectionUserData_Invalid)) // Can't read storage->RangeSrcItem here -> we want the state at begining of the scope (see tests for easy failure)
07496         {
07497             IMGUI_DEBUG_LOG_SELECTION("[selection] EndMultiSelect: Reset RangeSrcItem.\n"); // Will set be to NavId.
07498             storage->RangeSrcItem = ImGuiSelectionUserData_Invalid;
07499         }
07500         if (ms->NavIdPassedBy == false && storage->NavIdItem != ImGuiSelectionUserData_Invalid)
07501         {
07502             IMGUI_DEBUG_LOG_SELECTION("[selection] EndMultiSelect: Reset NavIdItem.\n");
07503             storage->NavIdItem = ImGuiSelectionUserData_Invalid;
07504             storage->NavIdSelected = -1;
07505         }
07506 
07507         if ((ms->Flags & (ImGuiMultiSelectFlags_BoxSelect1d | ImGuiMultiSelectFlags_BoxSelect2d)) && GetBoxSelectState(ms->BoxSelectId))
07508             EndBoxSelect(scope_rect, ms->Flags);
07509     }
07510 
07511     if (ms->IsEndIO == false)
07512         ms->IO.Requests.resize(0);
07513 
07514     // Clear selection when clicking void?
07515     // We specifically test for IsMouseDragPastThreshold(0) == false to allow box-selection!
07516     // The InnerRect test is necessary for non-child/decorated windows.
07517     bool scope_hovered = IsWindowHovered() && window->InnerRect.Contains(g.IO.MousePos);
07518     if (scope_hovered && (ms->Flags & ImGuiMultiSelectFlags_ScopeRect))
07519         scope_hovered &= scope_rect.Contains(g.IO.MousePos);
07520     if (scope_hovered && g.HoveredId == 0 && g.ActiveId == 0)
07521     {
07522         if (ms->Flags & (ImGuiMultiSelectFlags_BoxSelect1d | ImGuiMultiSelectFlags_BoxSelect2d))
07523         {
07524             if (!g.BoxSelectState.IsActive && !g.BoxSelectState.IsStarting && g.IO.MouseClickedCount[0] == 1)
07525             {
07526                 BoxSelectPreStartDrag(ms->BoxSelectId, ImGuiSelectionUserData_Invalid);
07527                 FocusWindow(window, ImGuiFocusRequestFlags_UnlessBelowModal);
07528                 SetHoveredID(ms->BoxSelectId);
07529                 if (ms->Flags & ImGuiMultiSelectFlags_ScopeRect)
07530                     SetNavID(0, ImGuiNavLayer_Main, ms->FocusScopeId, ImRect(g.IO.MousePos, g.IO.MousePos)); // Automatically switch FocusScope for initial click from void to box-select.
07531             }
07532         }
07533 
07534         if (ms->Flags & ImGuiMultiSelectFlags_ClearOnClickVoid)
07535             if (IsMouseReleased(0) && IsMouseDragPastThreshold(0) == false && g.IO.KeyMods == ImGuiMod_None)
07536                 MultiSelectAddSetAll(ms, false);
07537     }
07538 
07539     // Courtesy nav wrapping helper flag
07540     if (ms->Flags & ImGuiMultiSelectFlags_NavWrapX)
07541     {
07542         IM_ASSERT(ms->Flags & ImGuiMultiSelectFlags_ScopeWindow); // Only supported at window scope
07543         ImGui::NavMoveRequestTryWrapping(ImGui::GetCurrentWindow(), ImGuiNavMoveFlags_WrapX);
07544     }
07545 
07546     // Unwind
07547     window->DC.CursorMaxPos = ImMax(ms->BackupCursorMaxPos, window->DC.CursorMaxPos);
07548     PopFocusScope();
07549 
07550     if (g.DebugLogFlags & ImGuiDebugLogFlags_EventSelection)
07551         DebugLogMultiSelectRequests("EndMultiSelect", &ms->IO);
07552 
07553     ms->FocusScopeId = 0;
07554     ms->Flags = ImGuiMultiSelectFlags_None;
07555     g.CurrentMultiSelect = (--g.MultiSelectTempDataStacked > 0) ? &g.MultiSelectTempData[g.MultiSelectTempDataStacked - 1] : NULL;
07556 
07557     return &ms->IO;
07558 }
07559 
07560 void ImGui::SetNextItemSelectionUserData(ImGuiSelectionUserData selection_user_data)
07561 {
07562     // Note that flags will be cleared by ItemAdd(), so it's only useful for Navigation code!
07563     // This designed so widgets can also cheaply set this before calling ItemAdd(), so we are not tied to MultiSelect api.
07564     ImGuiContext& g = *GImGui;
07565     g.NextItemData.SelectionUserData = selection_user_data;
07566     g.NextItemData.FocusScopeId = g.CurrentFocusScopeId;
07567 
07568     if (ImGuiMultiSelectTempData* ms = g.CurrentMultiSelect)
07569     {
07570         // Auto updating RangeSrcPassedBy for cases were clipper is not used (done before ItemAdd() clipping)
07571         g.NextItemData.ItemFlags |= ImGuiItemFlags_HasSelectionUserData | ImGuiItemFlags_IsMultiSelect;
07572         if (ms->IO.RangeSrcItem == selection_user_data)
07573             ms->RangeSrcPassedBy = true;
07574     }
07575     else
07576     {
07577         g.NextItemData.ItemFlags |= ImGuiItemFlags_HasSelectionUserData;
07578     }
07579 }
07580 
07581 // In charge of:
07582 // - Applying SetAll for submitted items.
07583 // - Applying SetRange for submitted items and record end points.
07584 // - Altering button behavior flags to facilitate use with drag and drop.
07585 void ImGui::MultiSelectItemHeader(ImGuiID id, bool* p_selected, ImGuiButtonFlags* p_button_flags)
07586 {
07587     ImGuiContext& g = *GImGui;
07588     ImGuiMultiSelectTempData* ms = g.CurrentMultiSelect;
07589 
07590     bool selected = *p_selected;
07591     if (ms->IsFocused)
07592     {
07593         ImGuiMultiSelectState* storage = ms->Storage;
07594         ImGuiSelectionUserData item_data = g.NextItemData.SelectionUserData;
07595         IM_ASSERT(g.NextItemData.FocusScopeId == g.CurrentFocusScopeId && "Forgot to call SetNextItemSelectionUserData() prior to item, required in BeginMultiSelect()/EndMultiSelect() scope");
07596 
07597         // Apply SetAll (Clear/SelectAll) requests requested by BeginMultiSelect().
07598         // This is only useful if the user hasn't processed them already, and this only works if the user isn't using the clipper.
07599         // If you are using a clipper you need to process the SetAll request after calling BeginMultiSelect()
07600         if (ms->LoopRequestSetAll != -1)
07601             selected = (ms->LoopRequestSetAll == 1);
07602 
07603         // When using SHIFT+Nav: because it can incur scrolling we cannot afford a frame of lag with the selection highlight (otherwise scrolling would happen before selection)
07604         // For this to work, we need someone to set 'RangeSrcPassedBy = true' at some point (either clipper either SetNextItemSelectionUserData() function)
07605         if (ms->IsKeyboardSetRange)
07606         {
07607             IM_ASSERT(id != 0 && (ms->KeyMods & ImGuiMod_Shift) != 0);
07608             const bool is_range_dst = (ms->RangeDstPassedBy == false) && g.NavJustMovedToId == id;     // Assume that g.NavJustMovedToId is not clipped.
07609             if (is_range_dst)
07610                 ms->RangeDstPassedBy = true;
07611             if (is_range_dst && storage->RangeSrcItem == ImGuiSelectionUserData_Invalid) // If we don't have RangeSrc, assign RangeSrc = RangeDst
07612             {
07613                 storage->RangeSrcItem = item_data;
07614                 storage->RangeSelected = selected ? 1 : 0;
07615             }
07616             const bool is_range_src = storage->RangeSrcItem == item_data;
07617             if (is_range_src || is_range_dst || ms->RangeSrcPassedBy != ms->RangeDstPassedBy)
07618             {
07619                 // Apply range-select value to visible items
07620                 IM_ASSERT(storage->RangeSrcItem != ImGuiSelectionUserData_Invalid && storage->RangeSelected != -1);
07621                 selected = (storage->RangeSelected != 0);
07622             }
07623             else if ((ms->KeyMods & ImGuiMod_Ctrl) == 0 && (ms->Flags & ImGuiMultiSelectFlags_NoAutoClear) == 0)
07624             {
07625                 // Clear other items
07626                 selected = false;
07627             }
07628         }
07629         *p_selected = selected;
07630     }
07631 
07632     // Alter button behavior flags
07633     // To handle drag and drop of multiple items we need to avoid clearing selection on click.
07634     // Enabling this test makes actions using CTRL+SHIFT delay their effect on MouseUp which is annoying, but it allows drag and drop of multiple items.
07635     if (p_button_flags != NULL)
07636     {
07637         ImGuiButtonFlags button_flags = *p_button_flags;
07638         button_flags |= ImGuiButtonFlags_NoHoveredOnFocus;
07639         if ((!selected || (g.ActiveId == id && g.ActiveIdHasBeenPressedBefore)) && !(ms->Flags & ImGuiMultiSelectFlags_SelectOnClickRelease))
07640             button_flags = (button_flags | ImGuiButtonFlags_PressedOnClick) & ~ImGuiButtonFlags_PressedOnClickRelease;
07641         else
07642             button_flags |= ImGuiButtonFlags_PressedOnClickRelease;
07643         *p_button_flags = button_flags;
07644     }
07645 }
07646 
07647 // In charge of:
07648 // - Auto-select on navigation.
07649 // - Box-select toggle handling.
07650 // - Right-click handling.
07651 // - Altering selection based on Ctrl/Shift modifiers, both for keyboard and mouse.
07652 // - Record current selection state for RangeSrc
07653 // This is all rather complex, best to run and refer to "widgets_multiselect_xxx" tests in imgui_test_suite.
07654 void ImGui::MultiSelectItemFooter(ImGuiID id, bool* p_selected, bool* p_pressed)
07655 {
07656     ImGuiContext& g = *GImGui;
07657     ImGuiWindow* window = g.CurrentWindow;
07658 
07659     bool selected = *p_selected;
07660     bool pressed = *p_pressed;
07661     ImGuiMultiSelectTempData* ms = g.CurrentMultiSelect;
07662     ImGuiMultiSelectState* storage = ms->Storage;
07663     if (pressed)
07664         ms->IsFocused = true;
07665 
07666     bool hovered = false;
07667     if (g.LastItemData.StatusFlags & ImGuiItemStatusFlags_HoveredRect)
07668         hovered = IsItemHovered(ImGuiHoveredFlags_AllowWhenBlockedByPopup);
07669     if (!ms->IsFocused && !hovered)
07670         return;
07671 
07672     ImGuiSelectionUserData item_data = g.NextItemData.SelectionUserData;
07673 
07674     ImGuiMultiSelectFlags flags = ms->Flags;
07675     const bool is_singleselect = (flags & ImGuiMultiSelectFlags_SingleSelect) != 0;
07676     bool is_ctrl = (ms->KeyMods & ImGuiMod_Ctrl) != 0;
07677     bool is_shift = (ms->KeyMods & ImGuiMod_Shift) != 0;
07678 
07679     bool apply_to_range_src = false;
07680 
07681     if (g.NavId == id && storage->RangeSrcItem == ImGuiSelectionUserData_Invalid)
07682         apply_to_range_src = true;
07683     if (ms->IsEndIO == false)
07684     {
07685         ms->IO.Requests.resize(0);
07686         ms->IsEndIO = true;
07687     }
07688 
07689     // Auto-select as you navigate a list
07690     if (g.NavJustMovedToId == id)
07691     {
07692         if ((flags & ImGuiMultiSelectFlags_NoAutoSelect) == 0)
07693         {
07694             if (is_ctrl && is_shift)
07695                 pressed = true;
07696             else if (!is_ctrl)
07697                 selected = pressed = true;
07698         }
07699         else
07700         {
07701             // With NoAutoSelect, using Shift+keyboard performs a write/copy
07702             if (is_shift)
07703                 pressed = true;
07704             else if (!is_ctrl)
07705                 apply_to_range_src = true; // Since if (pressed) {} main block is not running we update this
07706         }
07707     }
07708 
07709     if (apply_to_range_src)
07710     {
07711         storage->RangeSrcItem = item_data;
07712         storage->RangeSelected = selected; // Will be updated at the end of this function anyway.
07713     }
07714 
07715     // Box-select toggle handling
07716     if (ms->BoxSelectId != 0)
07717         if (ImGuiBoxSelectState* bs = GetBoxSelectState(ms->BoxSelectId))
07718         {
07719             const bool rect_overlap_curr = bs->BoxSelectRectCurr.Overlaps(g.LastItemData.Rect);
07720             const bool rect_overlap_prev = bs->BoxSelectRectPrev.Overlaps(g.LastItemData.Rect);
07721             if ((rect_overlap_curr && !rect_overlap_prev && !selected) || (rect_overlap_prev && !rect_overlap_curr))
07722             {
07723                 if (storage->LastSelectionSize <= 0 && bs->IsStartedSetNavIdOnce)
07724                 {
07725                     pressed = true; // First item act as a pressed: code below will emit selection request and set NavId (whatever we emit here will be overridden anyway)
07726                     bs->IsStartedSetNavIdOnce = false;
07727                 }
07728                 else
07729                 {
07730                     selected = !selected;
07731                     MultiSelectAddSetRange(ms, selected, +1, item_data, item_data);
07732                 }
07733                 storage->LastSelectionSize = ImMax(storage->LastSelectionSize + 1, 1);
07734             }
07735         }
07736 
07737     // Right-click handling.
07738     // FIXME-MULTISELECT: Currently filtered out by ImGuiMultiSelectFlags_NoAutoSelect but maybe should be moved to Selectable(). See https://github.com/ocornut/imgui/pull/5816
07739     if (hovered && IsMouseClicked(1) && (flags & ImGuiMultiSelectFlags_NoAutoSelect) == 0)
07740     {
07741         if (g.ActiveId != 0 && g.ActiveId != id)
07742             ClearActiveID();
07743         SetFocusID(id, window);
07744         if (!pressed && !selected)
07745         {
07746             pressed = true;
07747             is_ctrl = is_shift = false;
07748         }
07749     }
07750 
07751     // Unlike Space, Enter doesn't alter selection (but can still return a press) unless current item is not selected.
07752     // The later, "unless current item is not select", may become optional? It seems like a better default if Enter doesn't necessarily open something
07753     // (unlike e.g. Windows explorer). For use case where Enter always open something, we might decide to make this optional?
07754     const bool enter_pressed = pressed && (g.NavActivateId == id) && (g.NavActivateFlags & ImGuiActivateFlags_PreferInput);
07755 
07756     // Alter selection
07757     if (pressed && (!enter_pressed || !selected))
07758     {
07759         // Box-select
07760         ImGuiInputSource input_source = (g.NavJustMovedToId == id || g.NavActivateId == id) ? g.NavInputSource : ImGuiInputSource_Mouse;
07761         if (flags & (ImGuiMultiSelectFlags_BoxSelect1d | ImGuiMultiSelectFlags_BoxSelect2d))
07762             if (selected == false && !g.BoxSelectState.IsActive && !g.BoxSelectState.IsStarting && input_source == ImGuiInputSource_Mouse && g.IO.MouseClickedCount[0] == 1)
07763                 BoxSelectPreStartDrag(ms->BoxSelectId, item_data);
07764 
07765         //----------------------------------------------------------------------------------------
07766         // ACTION                      | Begin  | Pressed/Activated  | End
07767         //----------------------------------------------------------------------------------------
07768         // Keys Navigated:             | Clear  | Src=item, Sel=1               SetRange 1
07769         // Keys Navigated: Ctrl        | n/a    | n/a
07770         // Keys Navigated:      Shift  | n/a    | Dst=item, Sel=1,   => Clear + SetRange 1
07771         // Keys Navigated: Ctrl+Shift  | n/a    | Dst=item, Sel=Src  => Clear + SetRange Src-Dst
07772         // Keys Activated:             | n/a    | Src=item, Sel=1    => Clear + SetRange 1
07773         // Keys Activated: Ctrl        | n/a    | Src=item, Sel=!Sel =>         SetSange 1
07774         // Keys Activated:      Shift  | n/a    | Dst=item, Sel=1    => Clear + SetSange 1
07775         //----------------------------------------------------------------------------------------
07776         // Mouse Pressed:              | n/a    | Src=item, Sel=1,   => Clear + SetRange 1
07777         // Mouse Pressed:  Ctrl        | n/a    | Src=item, Sel=!Sel =>         SetRange 1
07778         // Mouse Pressed:       Shift  | n/a    | Dst=item, Sel=1,   => Clear + SetRange 1
07779         // Mouse Pressed:  Ctrl+Shift  | n/a    | Dst=item, Sel=!Sel =>         SetRange Src-Dst
07780         //----------------------------------------------------------------------------------------
07781 
07782         if ((flags & ImGuiMultiSelectFlags_NoAutoClear) == 0)
07783         {
07784             bool request_clear = false;
07785             if (is_singleselect)
07786                 request_clear = true;
07787             else if ((input_source == ImGuiInputSource_Mouse || g.NavActivateId == id) && !is_ctrl)
07788                 request_clear = (flags & ImGuiMultiSelectFlags_NoAutoClearOnReselect) ? !selected : true;
07789             else if ((input_source == ImGuiInputSource_Keyboard || input_source == ImGuiInputSource_Gamepad) && is_shift && !is_ctrl)
07790                 request_clear = true; // With is_shift==false the RequestClear was done in BeginIO, not necessary to do again.
07791             if (request_clear)
07792                 MultiSelectAddSetAll(ms, false);
07793         }
07794 
07795         int range_direction;
07796         bool range_selected;
07797         if (is_shift && !is_singleselect)
07798         {
07799             //IM_ASSERT(storage->HasRangeSrc && storage->HasRangeValue);
07800             if (storage->RangeSrcItem == ImGuiSelectionUserData_Invalid)
07801                 storage->RangeSrcItem = item_data;
07802             if ((flags & ImGuiMultiSelectFlags_NoAutoSelect) == 0)
07803             {
07804                 // Shift+Arrow always select
07805                 // Ctrl+Shift+Arrow copy source selection state (already stored by BeginMultiSelect() in storage->RangeSelected)
07806                 range_selected = (is_ctrl && storage->RangeSelected != -1) ? (storage->RangeSelected != 0) : true;
07807             }
07808             else
07809             {
07810                 // Shift+Arrow copy source selection state
07811                 // Shift+Click always copy from target selection state
07812                 if (ms->IsKeyboardSetRange)
07813                     range_selected = (storage->RangeSelected != -1) ? (storage->RangeSelected != 0) : true;
07814                 else
07815                     range_selected = !selected;
07816             }
07817             range_direction = ms->RangeSrcPassedBy ? +1 : -1;
07818         }
07819         else
07820         {
07821             // Ctrl inverts selection, otherwise always select
07822             if ((flags & ImGuiMultiSelectFlags_NoAutoSelect) == 0)
07823                 selected = is_ctrl ? !selected : true;
07824             else
07825                 selected = !selected;
07826             storage->RangeSrcItem = item_data;
07827             range_selected = selected;
07828             range_direction = +1;
07829         }
07830         MultiSelectAddSetRange(ms, range_selected, range_direction, storage->RangeSrcItem, item_data);
07831     }
07832 
07833     // Update/store the selection state of the Source item (used by CTRL+SHIFT, when Source is unselected we perform a range unselect)
07834     if (storage->RangeSrcItem == item_data)
07835         storage->RangeSelected = selected ? 1 : 0;
07836 
07837     // Update/store the selection state of focused item
07838     if (g.NavId == id)
07839     {
07840         storage->NavIdItem = item_data;
07841         storage->NavIdSelected = selected ? 1 : 0;
07842     }
07843     if (storage->NavIdItem == item_data)
07844         ms->NavIdPassedBy = true;
07845     ms->LastSubmittedItem = item_data;
07846 
07847     *p_selected = selected;
07848     *p_pressed = pressed;
07849 }
07850 
07851 void ImGui::MultiSelectAddSetAll(ImGuiMultiSelectTempData* ms, bool selected)
07852 {
07853     ImGuiSelectionRequest req = { ImGuiSelectionRequestType_SetAll, selected, 0, ImGuiSelectionUserData_Invalid, ImGuiSelectionUserData_Invalid };
07854     ms->IO.Requests.resize(0);      // Can always clear previous requests
07855     ms->IO.Requests.push_back(req); // Add new request
07856 }
07857 
07858 void ImGui::MultiSelectAddSetRange(ImGuiMultiSelectTempData* ms, bool selected, int range_dir, ImGuiSelectionUserData first_item, ImGuiSelectionUserData last_item)
07859 {
07860     // Merge contiguous spans into same request (unless NoRangeSelect is set which guarantees single-item ranges)
07861     if (ms->IO.Requests.Size > 0 && first_item == last_item && (ms->Flags & ImGuiMultiSelectFlags_NoRangeSelect) == 0)
07862     {
07863         ImGuiSelectionRequest* prev = &ms->IO.Requests.Data[ms->IO.Requests.Size - 1];
07864         if (prev->Type == ImGuiSelectionRequestType_SetRange && prev->RangeLastItem == ms->LastSubmittedItem && prev->Selected == selected)
07865         {
07866             prev->RangeLastItem = last_item;
07867             return;
07868         }
07869     }
07870 
07871     ImGuiSelectionRequest req = { ImGuiSelectionRequestType_SetRange, selected, (ImS8)range_dir, (range_dir > 0) ? first_item : last_item, (range_dir > 0) ? last_item : first_item };
07872     ms->IO.Requests.push_back(req); // Add new request
07873 }
