07885     Text("NavIdItem = %" IM_PRId64 " (0x%" IM_PRIX64 "), NavIdSelected = %d", storage->NavIdItem, storage->NavIdItem, storage->NavIdSelected);
07886     Text("LastSelectionSize = %d", storage->LastSelectionSize); // Provided by user
07887     TreePop();
