07928 static int IMGUI_CDECL PairComparerByValueInt(const void* lhs, const void* rhs)
07929 {
07930     int lhs_v = ((const ImGuiStoragePair*)lhs)->val_i;
07931     int rhs_v = ((const ImGuiStoragePair*)rhs)->val_i;
07932     return (lhs_v > rhs_v ? +1 : lhs_v < rhs_v ? -1 : 0);
07933 }
07934 
07935 // GetNextSelectedItem() is an abstraction allowing us to change our underlying actual storage system without impacting user.
07936 // (e.g. store unselected vs compact down, compact down on demand, use raw ImVector<ImGuiID> instead of ImGuiStorage...)
07937 bool ImGuiSelectionBasicStorage::GetNextSelectedItem(void** opaque_it, ImGuiID* out_id)
07938 {
07939     ImGuiStoragePair* it = (ImGuiStoragePair*)*opaque_it;
07940     ImGuiStoragePair* it_end = _Storage.Data.Data + _Storage.Data.Size;
07941     if (PreserveOrder && it == NULL && it_end != NULL)
07942         ImQsort(_Storage.Data.Data, (size_t)_Storage.Data.Size, sizeof(ImGuiStoragePair), PairComparerByValueInt); // ~ImGuiStorage::BuildSortByValueInt()
07943     if (it == NULL)
07944         it = _Storage.Data.Data;
07945     IM_ASSERT(it >= _Storage.Data.Data && it <= it_end);
07946     if (it != it_end)
07947         while (it->val_i == 0 && it < it_end)
07948             it++;
07949     const bool has_more = (it != it_end);
07950     *opaque_it = has_more ? (void**)(it + 1) : (void**)(it);
07951     *out_id = has_more ? it->key : 0;
07952     if (PreserveOrder && !has_more)
07953         _Storage.BuildSortByKey();
07954     return has_more;
07955 }
