07957 void ImGuiSelectionBasicStorage::SetItemSelected(ImGuiID id, bool selected)
07958 {
07959     int* p_int = _Storage.GetIntRef(id, 0);
07960     if (selected && *p_int == 0) { *p_int = _SelectionOrder++; Size++; }
07961     else if (!selected && *p_int != 0) { *p_int = 0; Size--; }
07962 }
07963 
07964 // Optimized for batch edits (with same value of 'selected')
07965 static void ImGuiSelectionBasicStorage_BatchSetItemSelected(ImGuiSelectionBasicStorage* selection, ImGuiID id, bool selected, int size_before_amends, int selection_order)
07966 {
07967     ImGuiStorage* storage = &selection->_Storage;
07968     ImGuiStoragePair* it = ImLowerBound(storage->Data.Data, storage->Data.Data + size_before_amends, id);
07969     const bool is_contained = (it != storage->Data.Data + size_before_amends) && (it->key == id);
07970     if (selected == (is_contained && it->val_i != 0))
07971         return;
07972     if (selected && !is_contained)
07973         storage->Data.push_back(ImGuiStoragePair(id, selection_order)); // Push unsorted at end of vector, will be sorted in SelectionMultiAmendsFinish()
07974     else if (is_contained)
07975         it->val_i = selected ? selection_order : 0; // Modify in-place.
07976     selection->Size += selected ? +1 : -1;
07977 }
07978 
07979 static void ImGuiSelectionBasicStorage_BatchFinish(ImGuiSelectionBasicStorage* selection, bool selected, int size_before_amends)
07980 {
07981     ImGuiStorage* storage = &selection->_Storage;
07982     if (selected && selection->Size != size_before_amends)
07983         storage->BuildSortByKey(); // When done selecting: sort everything
07984 }
07985 
07986 // Apply requests coming from BeginMultiSelect() and EndMultiSelect().
07987 // - Enable 'Demo->Tools->Debug Log->Selection' to see selection requests as they happen.
07988 // - Honoring SetRange requests requires that you can iterate/interpolate between RangeFirstItem and RangeLastItem.
07989 //   - In this demo we often submit indices to SetNextItemSelectionUserData() + store the same indices in persistent selection.
07990 //   - Your code may do differently. If you store pointers or objects ID in ImGuiSelectionUserData you may need to perform
07991 //     a lookup in order to have some way to iterate/interpolate between two items.
07992 // - A full-featured application is likely to allow search/filtering which is likely to lead to using indices
07993 //   and constructing a view index <> object id/ptr data structure anyway.
07994 // WHEN YOUR APPLICATION SETTLES ON A CHOICE, YOU WILL PROBABLY PREFER TO GET RID OF THIS UNNECESSARY 'ImGuiSelectionBasicStorage' INDIRECTION LOGIC.
07995 // Notice that with the simplest adapter (using indices everywhere), all functions return their parameters.
07996 // The most simple implementation (using indices everywhere) would look like:
07997 //   for (ImGuiSelectionRequest& req : ms_io->Requests)
07998 //   {
07999 //      if (req.Type == ImGuiSelectionRequestType_SetAll)    { Clear(); if (req.Selected) { for (int n = 0; n < items_count; n++) { SetItemSelected(n, true); } }
08000 //      if (req.Type == ImGuiSelectionRequestType_SetRange)  { for (int n = (int)ms_io->RangeFirstItem; n <= (int)ms_io->RangeLastItem; n++) { SetItemSelected(n, ms_io->Selected); } }
08001 //   }
08002 void ImGuiSelectionBasicStorage::ApplyRequests(ImGuiMultiSelectIO* ms_io)
08003 {
08004     // For convenience we obtain ItemsCount as passed to BeginMultiSelect(), which is optional.
08005     // It makes sense when using ImGuiSelectionBasicStorage to simply pass your items count to BeginMultiSelect().
08006     // Other scheme may handle SetAll differently.
08007     IM_ASSERT(ms_io->ItemsCount != -1 && "Missing value for items_count in BeginMultiSelect() call!");
08008     IM_ASSERT(AdapterIndexToStorageId != NULL);
08009 
08010     // This is optimized/specialized to cope with very large selections (e.g. 100k+ items)
08011     // - A simpler version could call SetItemSelected() directly instead of ImGuiSelectionBasicStorage_BatchSetItemSelected() + ImGuiSelectionBasicStorage_BatchFinish().
08012     // - Optimized select can append unsorted, then sort in a second pass. Optimized unselect can clear in-place then compact in a second pass.
08013     // - A more optimal version wouldn't even use ImGuiStorage but directly a ImVector<ImGuiID> to reduce bandwidth, but this is a reasonable trade off to reuse code.
08014     // - There are many ways this could be better optimized. The worse case scenario being: using BoxSelect2d in a grid, box-select scrolling down while wiggling
08015     //   left and right: it affects coarse clipping + can emit multiple SetRange with 1 item each.)
08016     // FIXME-OPT: For each block of consecutive SetRange request:
08017     // - add all requests to a sorted list, store ID, selected, offset in ImGuiStorage.
08018     // - rewrite sorted storage a single time.
08019     for (ImGuiSelectionRequest& req : ms_io->Requests)
08020     {
08021         if (req.Type == ImGuiSelectionRequestType_SetAll)
08022         {
08023             Clear();
08024             if (req.Selected)
08025             {
08026                 _Storage.Data.reserve(ms_io->ItemsCount);
08027                 const int size_before_amends = _Storage.Data.Size;
08028                 for (int idx = 0; idx < ms_io->ItemsCount; idx++, _SelectionOrder++)
08029                     ImGuiSelectionBasicStorage_BatchSetItemSelected(this, GetStorageIdFromIndex(idx), req.Selected, size_before_amends, _SelectionOrder);
08030                 ImGuiSelectionBasicStorage_BatchFinish(this, req.Selected, size_before_amends);
08031             }
08032         }
08033         else if (req.Type == ImGuiSelectionRequestType_SetRange)
08034         {
08035             const int selection_changes = (int)req.RangeLastItem - (int)req.RangeFirstItem + 1;
08036             //ImGuiContext& g = *GImGui; IMGUI_DEBUG_LOG_SELECTION("Req %d/%d: set %d to %d\n", ms_io->Requests.index_from_ptr(&req), ms_io->Requests.Size, selection_changes, req.Selected);
08037             if (selection_changes == 1 || (selection_changes < Size / 100))
08038             {
08039                 // Multiple sorted insertion + copy likely to be faster.
08040                 // Technically we could do a single copy with a little more work (sort sequential SetRange requests)
08041                 for (int idx = (int)req.RangeFirstItem; idx <= (int)req.RangeLastItem; idx++)
08042                     SetItemSelected(GetStorageIdFromIndex(idx), req.Selected);
08043             }
08044             else
08045             {
08046                 // Append insertion + single sort likely be faster.
08047                 // Use req.RangeDirection to set order field so that shift+clicking from 1 to 5 is different than shift+clicking from 5 to 1
08048                 const int size_before_amends = _Storage.Data.Size;
08049                 int selection_order = _SelectionOrder + ((req.RangeDirection < 0) ? selection_changes - 1 : 0);
08050                 for (int idx = (int)req.RangeFirstItem; idx <= (int)req.RangeLastItem; idx++, selection_order += req.RangeDirection)
08051                     ImGuiSelectionBasicStorage_BatchSetItemSelected(this, GetStorageIdFromIndex(idx), req.Selected, size_before_amends, selection_order);
08052                 if (req.Selected)
08053                     _SelectionOrder += selection_changes;
08054                 ImGuiSelectionBasicStorage_BatchFinish(this, req.Selected, size_before_amends);
08055             }
08056         }
08057     }
08058 }
