08068 // Apply requests coming from BeginMultiSelect() and EndMultiSelect().
08069 // We also pull 'ms_io->ItemsCount' as passed for BeginMultiSelect() for consistency with ImGuiSelectionBasicStorage
08070 // This makes no assumption about underlying storage.
08071 void ImGuiSelectionExternalStorage::ApplyRequests(ImGuiMultiSelectIO* ms_io)
08072 {
08073     IM_ASSERT(AdapterSetItemSelected);
08074     for (ImGuiSelectionRequest& req : ms_io->Requests)
08075     {
08076         if (req.Type == ImGuiSelectionRequestType_SetAll)
08077             for (int idx = 0; idx < ms_io->ItemsCount; idx++)
08078                 AdapterSetItemSelected(this, idx, req.Selected);
08079         if (req.Type == ImGuiSelectionRequestType_SetRange)
08080             for (int idx = (int)req.RangeFirstItem; idx <= (int)req.RangeLastItem; idx++)
08081                 AdapterSetItemSelected(this, idx, req.Selected);
08082     }
08083 }
