08085 //-------------------------------------------------------------------------
08086 // [SECTION] Widgets: ListBox
08087 //-------------------------------------------------------------------------
08088 // - BeginListBox()
08089 // - EndListBox()
08090 // - ListBox()
08091 //-------------------------------------------------------------------------
08092 
08093 // This is essentially a thin wrapper to using BeginChild/EndChild with the ImGuiChildFlags_FrameStyle flag for stylistic changes + displaying a label.
08094 // Tip: To have a list filling the entire window width, use size.x = -FLT_MIN and pass an non-visible label e.g. "##empty"
08095 // Tip: If your vertical size is calculated from an item count (e.g. 10 * item_height) consider adding a fractional part to facilitate seeing scrolling boundaries (e.g. 10.25 * item_height).
08096 bool ImGui::BeginListBox(const char* label, const ImVec2& size_arg)
08097 {
08098     ImGuiContext& g = *GImGui;
08099     ImGuiWindow* window = GetCurrentWindow();
08100     if (window->SkipItems)
08101         return false;
08102 
08103     const ImGuiStyle& style = g.Style;
08104     const ImGuiID id = GetID(label);
08105     const ImVec2 label_size = CalcTextSize(label, NULL, true);
08106 
08107     // Size default to hold ~7.25 items.
08108     // Fractional number of items helps seeing that we can scroll down/up without looking at scrollbar.
08109     ImVec2 size = ImTrunc(CalcItemSize(size_arg, CalcItemWidth(), GetTextLineHeightWithSpacing() * 7.25f + style.FramePadding.y * 2.0f));
08110     ImVec2 frame_size = ImVec2(size.x, ImMax(size.y, label_size.y));
08111     ImRect frame_bb(window->DC.CursorPos, window->DC.CursorPos + frame_size);
08112     ImRect bb(frame_bb.Min, frame_bb.Max + ImVec2(label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0.0f));
08113     g.NextItemData.ClearFlags();
08114 
08115     if (!IsRectVisible(bb.Min, bb.Max))
08116     {
08117         ItemSize(bb.GetSize(), style.FramePadding.y);
08118         ItemAdd(bb, 0, &frame_bb);
08119         g.NextWindowData.ClearFlags(); // We behave like Begin() and need to consume those values
08120         return false;
08121     }
08122 
08123     // FIXME-OPT: We could omit the BeginGroup() if label_size.x == 0.0f but would need to omit the EndGroup() as well.
08124     BeginGroup();
08125     if (label_size.x > 0.0f)
08126     {
08127         ImVec2 label_pos = ImVec2(frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y);
08128         RenderText(label_pos, label);
08129         window->DC.CursorMaxPos = ImMax(window->DC.CursorMaxPos, label_pos + label_size);
08130         AlignTextToFramePadding();
08131     }
08132 
08133     BeginChild(id, frame_bb.GetSize(), ImGuiChildFlags_FrameStyle);
08134     return true;
08135 }
08136 
08137 void ImGui::EndListBox()
08138 {
08139     ImGuiContext& g = *GImGui;
08140     ImGuiWindow* window = g.CurrentWindow;
08141     IM_ASSERT((window->Flags & ImGuiWindowFlags_ChildWindow) && "Mismatched BeginListBox/EndListBox calls. Did you test the return value of BeginListBox?");
08142     IM_UNUSED(window);
08143 
08144     EndChild();
08145     EndGroup(); // This is only required to be able to do IsItemXXX query on the whole ListBox including label
08146 }
08147 
08148 bool ImGui::ListBox(const char* label, int* current_item, const char* const items[], int items_count, int height_items)
08149 {
08150     const bool value_changed = ListBox(label, current_item, Items_ArrayGetter, (void*)items, items_count, height_items);
08151     return value_changed;
08152 }
08153 
08154 // This is merely a helper around BeginListBox(), EndListBox().
08155 // Considering using those directly to submit custom data or store selection differently.
08156 bool ImGui::ListBox(const char* label, int* current_item, const char* (*getter)(void* user_data, int idx), void* user_data, int items_count, int height_in_items)
08157 {
08158     ImGuiContext& g = *GImGui;
08159 
08160     // Calculate size from "height_in_items"
08161     if (height_in_items < 0)
08162         height_in_items = ImMin(items_count, 7);
08163     float height_in_items_f = height_in_items + 0.25f;
08164     ImVec2 size(0.0f, ImTrunc(GetTextLineHeightWithSpacing() * height_in_items_f + g.Style.FramePadding.y * 2.0f));
08165 
08166     if (!BeginListBox(label, size))
08167         return false;
08168 
08169     // Assume all items have even height (= 1 line of text). If you need items of different height,
08170     // you can create a custom version of ListBox() in your code without using the clipper.
08171     bool value_changed = false;
08172     ImGuiListClipper clipper;
08173     clipper.Begin(items_count, GetTextLineHeightWithSpacing()); // We know exactly our line height here so we pass it as a minor optimization, but generally you don't need to.
08174     clipper.IncludeItemByIndex(*current_item);
08175     while (clipper.Step())
08176         for (int i = clipper.DisplayStart; i < clipper.DisplayEnd; i++)
08177         {
08178             const char* item_text = getter(user_data, i);
08179             if (item_text == NULL)
08180                 item_text = "*Unknown item*";
08181 
08182             PushID(i);
08183             const bool item_selected = (i == *current_item);
08184             if (Selectable(item_text, item_selected))
08185             {
08186                 *current_item = i;
08187                 value_changed = true;
08188             }
08189             if (item_selected)
08190                 SetItemDefaultFocus();
08191             PopID();
08192         }
08193     EndListBox();
08194 
08195     if (value_changed)
08196         MarkItemEdited(g.LastItemData.ID);
08197 
08198     return value_changed;
08199 }
