08201 //-------------------------------------------------------------------------
08202 // [SECTION] Widgets: PlotLines, PlotHistogram
08203 //-------------------------------------------------------------------------
08204 // - PlotEx() [Internal]
08205 // - PlotLines()
08206 // - PlotHistogram()
08207 //-------------------------------------------------------------------------
08208 // Plot/Graph widgets are not very good.
08209 // Consider writing your own, or using a third-party one, see:
08210 // - ImPlot https://github.com/epezent/implot
08211 // - others https://github.com/ocornut/imgui/wiki/Useful-Extensions
08212 //-------------------------------------------------------------------------
08213 
08214 int ImGui::PlotEx(ImGuiPlotType plot_type, const char* label, float (*values_getter)(void* data, int idx), void* data, int values_count, int values_offset, const char* overlay_text, float scale_min, float scale_max, const ImVec2& size_arg)
08215 {
08216     ImGuiContext& g = *GImGui;
08217     ImGuiWindow* window = GetCurrentWindow();
08218     if (window->SkipItems)
08219         return -1;
08220 
08221     const ImGuiStyle& style = g.Style;
08222     const ImGuiID id = window->GetID(label);
08223 
08224     const ImVec2 label_size = CalcTextSize(label, NULL, true);
08225     const ImVec2 frame_size = CalcItemSize(size_arg, CalcItemWidth(), label_size.y + style.FramePadding.y * 2.0f);
08226 
08227     const ImRect frame_bb(window->DC.CursorPos, window->DC.CursorPos + frame_size);
08228     const ImRect inner_bb(frame_bb.Min + style.FramePadding, frame_bb.Max - style.FramePadding);
08229     const ImRect total_bb(frame_bb.Min, frame_bb.Max + ImVec2(label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0));
08230     ItemSize(total_bb, style.FramePadding.y);
08231     if (!ItemAdd(total_bb, 0, &frame_bb))
08232         return -1;
08233     const bool hovered = ItemHoverable(frame_bb, id, g.LastItemData.InFlags);
08234 
08235     // Determine scale from values if not specified
08236     if (scale_min == FLT_MAX || scale_max == FLT_MAX)
08237     {
08238         float v_min = FLT_MAX;
08239         float v_max = -FLT_MAX;
08240         for (int i = 0; i < values_count; i++)
08241         {
08242             const float v = values_getter(data, i);
08243             if (v != v) // Ignore NaN values
08244                 continue;
08245             v_min = ImMin(v_min, v);
08246             v_max = ImMax(v_max, v);
08247         }
08248         if (scale_min == FLT_MAX)
08249             scale_min = v_min;
08250         if (scale_max == FLT_MAX)
08251             scale_max = v_max;
08252     }
08253 
08254     RenderFrame(frame_bb.Min, frame_bb.Max, GetColorU32(ImGuiCol_FrameBg), true, style.FrameRounding);
08255 
08256     const int values_count_min = (plot_type == ImGuiPlotType_Lines) ? 2 : 1;
08257     int idx_hovered = -1;
08258     if (values_count >= values_count_min)
08259     {
08260         int res_w = ImMin((int)frame_size.x, values_count) + ((plot_type == ImGuiPlotType_Lines) ? -1 : 0);
08261         int item_count = values_count + ((plot_type == ImGuiPlotType_Lines) ? -1 : 0);
08262 
08263         // Tooltip on hover
08264         if (hovered && inner_bb.Contains(g.IO.MousePos))
08265         {
08266             const float t = ImClamp((g.IO.MousePos.x - inner_bb.Min.x) / (inner_bb.Max.x - inner_bb.Min.x), 0.0f, 0.9999f);
08267             const int v_idx = (int)(t * item_count);
08268             IM_ASSERT(v_idx >= 0 && v_idx < values_count);
08269 
08270             const float v0 = values_getter(data, (v_idx + values_offset) % values_count);
08271             const float v1 = values_getter(data, (v_idx + 1 + values_offset) % values_count);
08272             if (plot_type == ImGuiPlotType_Lines)
08273                 SetTooltip("%d: %8.4g\n%d: %8.4g", v_idx, v0, v_idx + 1, v1);
08274             else if (plot_type == ImGuiPlotType_Histogram)
08275                 SetTooltip("%d: %8.4g", v_idx, v0);
08276             idx_hovered = v_idx;
08277         }
08278 
08279         const float t_step = 1.0f / (float)res_w;
08280         const float inv_scale = (scale_min == scale_max) ? 0.0f : (1.0f / (scale_max - scale_min));
08281 
08282         float v0 = values_getter(data, (0 + values_offset) % values_count);
08283         float t0 = 0.0f;
08284         ImVec2 tp0 = ImVec2( t0, 1.0f - ImSaturate((v0 - scale_min) * inv_scale) );                       // Point in the normalized space of our target rectangle
08285         float histogram_zero_line_t = (scale_min * scale_max < 0.0f) ? (1 + scale_min * inv_scale) : (scale_min < 0.0f ? 0.0f : 1.0f);   // Where does the zero line stands
08286 
08287         const ImU32 col_base = GetColorU32((plot_type == ImGuiPlotType_Lines) ? ImGuiCol_PlotLines : ImGuiCol_PlotHistogram);
08288         const ImU32 col_hovered = GetColorU32((plot_type == ImGuiPlotType_Lines) ? ImGuiCol_PlotLinesHovered : ImGuiCol_PlotHistogramHovered);
08289 
08290         for (int n = 0; n < res_w; n++)
08291         {
08292             const float t1 = t0 + t_step;
08293             const int v1_idx = (int)(t0 * item_count + 0.5f);
08294             IM_ASSERT(v1_idx >= 0 && v1_idx < values_count);
08295             const float v1 = values_getter(data, (v1_idx + values_offset + 1) % values_count);
08296             const ImVec2 tp1 = ImVec2( t1, 1.0f - ImSaturate((v1 - scale_min) * inv_scale) );
08297 
08298             // NB: Draw calls are merged together by the DrawList system. Still, we should render our batch are lower level to save a bit of CPU.
08299             ImVec2 pos0 = ImLerp(inner_bb.Min, inner_bb.Max, tp0);
08300             ImVec2 pos1 = ImLerp(inner_bb.Min, inner_bb.Max, (plot_type == ImGuiPlotType_Lines) ? tp1 : ImVec2(tp1.x, histogram_zero_line_t));
08301             if (plot_type == ImGuiPlotType_Lines)
08302             {
08303                 window->DrawList->AddLine(pos0, pos1, idx_hovered == v1_idx ? col_hovered : col_base);
08304             }
08305             else if (plot_type == ImGuiPlotType_Histogram)
08306             {
08307                 if (pos1.x >= pos0.x + 2.0f)
08308                     pos1.x -= 1.0f;
08309                 window->DrawList->AddRectFilled(pos0, pos1, idx_hovered == v1_idx ? col_hovered : col_base);
08310             }
08311 
08312             t0 = t1;
08313             tp0 = tp1;
08314         }
08315     }
08316 
08317     // Text overlay
08318     if (overlay_text)
08319         RenderTextClipped(ImVec2(frame_bb.Min.x, frame_bb.Min.y + style.FramePadding.y), frame_bb.Max, overlay_text, NULL, NULL, ImVec2(0.5f, 0.0f));
08320 
08321     if (label_size.x > 0.0f)
08322         RenderText(ImVec2(frame_bb.Max.x + style.ItemInnerSpacing.x, inner_bb.Min.y), label);
08323 
08324     // Return hovered index or -1 if none are hovered.
08325     // This is currently not exposed in the public API because we need a larger redesign of the whole thing, but in the short-term we are making it available in PlotEx().
08326     return idx_hovered;
08327 }
