08416 // Helpers for internal use
08417 void ImGuiMenuColumns::Update(float spacing, bool window_reappearing)
08418 {
08419     if (window_reappearing)
08420         memset(Widths, 0, sizeof(Widths));
08421     Spacing = (ImU16)spacing;
08422     CalcNextTotalWidth(true);
08423     memset(Widths, 0, sizeof(Widths));
08424     TotalWidth = NextTotalWidth;
08425     NextTotalWidth = 0;
08426 }
08427 
08428 void ImGuiMenuColumns::CalcNextTotalWidth(bool update_offsets)
08429 {
08430     ImU16 offset = 0;
08431     bool want_spacing = false;
08432     for (int i = 0; i < IM_ARRAYSIZE(Widths); i++)
08433     {
08434         ImU16 width = Widths[i];
08435         if (want_spacing && width > 0)
08436             offset += Spacing;
08437         want_spacing |= (width > 0);
08438         if (update_offsets)
08439         {
08440             if (i == 1) { OffsetLabel = offset; }
08441             if (i == 2) { OffsetShortcut = offset; }
08442             if (i == 3) { OffsetMark = offset; }
08443         }
08444         offset += width;
08445     }
08446     NextTotalWidth = offset;
08447 }
08448 
08449 float ImGuiMenuColumns::DeclColumns(float w_icon, float w_label, float w_shortcut, float w_mark)
08450 {
08451     Widths[0] = ImMax(Widths[0], (ImU16)w_icon);
08452     Widths[1] = ImMax(Widths[1], (ImU16)w_label);
08453     Widths[2] = ImMax(Widths[2], (ImU16)w_shortcut);
08454     Widths[3] = ImMax(Widths[3], (ImU16)w_mark);
08455     CalcNextTotalWidth(false);
08456     return (float)ImMax(TotalWidth, NextTotalWidth);
08457 }
