08459 // FIXME: Provided a rectangle perhaps e.g. a BeginMenuBarEx() could be used anywhere..
08460 // Currently the main responsibility of this function being to setup clip-rect + horizontal layout + menu navigation layer.
08461 // Ideally we also want this to be responsible for claiming space out of the main window scrolling rectangle, in which case ImGuiWindowFlags_MenuBar will become unnecessary.
08462 // Then later the same system could be used for multiple menu-bars, scrollbars, side-bars.
08463 bool ImGui::BeginMenuBar()
08464 {
08465     ImGuiWindow* window = GetCurrentWindow();
08466     if (window->SkipItems)
08467         return false;
08468     if (!(window->Flags & ImGuiWindowFlags_MenuBar))
08469         return false;
08470 
08471     IM_ASSERT(!window->DC.MenuBarAppending);
08472     BeginGroup(); // Backup position on layer 0 // FIXME: Misleading to use a group for that backup/restore
08473     PushID("##menubar");
08474 
08475     // We don't clip with current window clipping rectangle as it is already set to the area below. However we clip with window full rect.
08476     // We remove 1 worth of rounding to Max.x to that text in long menus and small windows don't tend to display over the lower-right rounded area, which looks particularly glitchy.
08477     ImRect bar_rect = window->MenuBarRect();
08478     ImRect clip_rect(ImFloor(bar_rect.Min.x + window->WindowBorderSize), ImFloor(bar_rect.Min.y + window->WindowBorderSize), ImFloor(ImMax(bar_rect.Min.x, bar_rect.Max.x - ImMax(window->WindowRounding, window->WindowBorderSize))), ImFloor(bar_rect.Max.y));
08479     clip_rect.ClipWith(window->OuterRectClipped);
08480     PushClipRect(clip_rect.Min, clip_rect.Max, false);
08481 
08482     // We overwrite CursorMaxPos because BeginGroup sets it to CursorPos (essentially the .EmitItem hack in EndMenuBar() would need something analogous here, maybe a BeginGroupEx() with flags).
08483     window->DC.CursorPos = window->DC.CursorMaxPos = ImVec2(bar_rect.Min.x + window->DC.MenuBarOffset.x, bar_rect.Min.y + window->DC.MenuBarOffset.y);
08484     window->DC.LayoutType = ImGuiLayoutType_Horizontal;
08485     window->DC.IsSameLine = false;
08486     window->DC.NavLayerCurrent = ImGuiNavLayer_Menu;
08487     window->DC.MenuBarAppending = true;
08488     AlignTextToFramePadding();
08489     return true;
08490 }
08491 
08492 void ImGui::EndMenuBar()
08493 {
08494     ImGuiWindow* window = GetCurrentWindow();
08495     if (window->SkipItems)
08496         return;
08497     ImGuiContext& g = *GImGui;
08498 
08499     // Nav: When a move request within one of our child menu failed, capture the request to navigate among our siblings.
08500     if (NavMoveRequestButNoResultYet() && (g.NavMoveDir == ImGuiDir_Left || g.NavMoveDir == ImGuiDir_Right) && (g.NavWindow->Flags & ImGuiWindowFlags_ChildMenu))
08501     {
08502         // Try to find out if the request is for one of our child menu
08503         ImGuiWindow* nav_earliest_child = g.NavWindow;
08504         while (nav_earliest_child->ParentWindow && (nav_earliest_child->ParentWindow->Flags & ImGuiWindowFlags_ChildMenu))
08505             nav_earliest_child = nav_earliest_child->ParentWindow;
08506         if (nav_earliest_child->ParentWindow == window && nav_earliest_child->DC.ParentLayoutType == ImGuiLayoutType_Horizontal && (g.NavMoveFlags & ImGuiNavMoveFlags_Forwarded) == 0)
08507         {
08508             // To do so we claim focus back, restore NavId and then process the movement request for yet another frame.
08509             // This involve a one-frame delay which isn't very problematic in this situation. We could remove it by scoring in advance for multiple window (probably not worth bothering)
08510             const ImGuiNavLayer layer = ImGuiNavLayer_Menu;
08511             IM_ASSERT(window->DC.NavLayersActiveMaskNext & (1 << layer)); // Sanity check (FIXME: Seems unnecessary)
08512             FocusWindow(window);
08513             SetNavID(window->NavLastIds[layer], layer, 0, window->NavRectRel[layer]);
08514             g.NavDisableHighlight = true; // Hide highlight for the current frame so we don't see the intermediary selection.
08515             g.NavDisableMouseHover = g.NavMousePosDirty = true;
08516             NavMoveRequestForward(g.NavMoveDir, g.NavMoveClipDir, g.NavMoveFlags, g.NavMoveScrollFlags); // Repeat
08517         }
08518     }
08519 
08520     IM_MSVC_WARNING_SUPPRESS(6011); // Static Analysis false positive "warning C6011: Dereferencing NULL pointer 'window'"
08521     IM_ASSERT(window->Flags & ImGuiWindowFlags_MenuBar);
08522     IM_ASSERT(window->DC.MenuBarAppending);
08523     PopClipRect();
08524     PopID();
08525     window->DC.MenuBarOffset.x = window->DC.CursorPos.x - window->Pos.x; // Save horizontal position so next append can reuse it. This is kinda equivalent to a per-layer CursorPos.
08526 
08527     // FIXME: Extremely confusing, cleanup by (a) working on WorkRect stack system (b) not using a Group confusingly here.
08528     ImGuiGroupData& group_data = g.GroupStack.back();
08529     group_data.EmitItem = false;
08530     ImVec2 restore_cursor_max_pos = group_data.BackupCursorMaxPos;
08531     window->DC.IdealMaxPos.x = ImMax(window->DC.IdealMaxPos.x, window->DC.CursorMaxPos.x - window->Scroll.x); // Convert ideal extents for scrolling layer equivalent.
08532     EndGroup(); // Restore position on layer 0 // FIXME: Misleading to use a group for that backup/restore
08533     window->DC.LayoutType = ImGuiLayoutType_Vertical;
08534     window->DC.IsSameLine = false;
08535     window->DC.NavLayerCurrent = ImGuiNavLayer_Main;
08536     window->DC.MenuBarAppending = false;
08537     window->DC.CursorMaxPos = restore_cursor_max_pos;
08538 }
08539 
08540 // Important: calling order matters!
08541 // FIXME: Somehow overlapping with docking tech.
08542 // FIXME: The "rect-cut" aspect of this could be formalized into a lower-level helper (rect-cut: https://halt.software/dead-simple-layouts)
08543 bool ImGui::BeginViewportSideBar(const char* name, ImGuiViewport* viewport_p, ImGuiDir dir, float axis_size, ImGuiWindowFlags window_flags)
08544 {
08545     IM_ASSERT(dir != ImGuiDir_None);
08546 
08547     ImGuiWindow* bar_window = FindWindowByName(name);
08548     ImGuiViewportP* viewport = (ImGuiViewportP*)(void*)(viewport_p ? viewport_p : GetMainViewport());
08549     if (bar_window == NULL || bar_window->BeginCount == 0)
08550     {
08551         // Calculate and set window size/position
08552         ImRect avail_rect = viewport->GetBuildWorkRect();
08553         ImGuiAxis axis = (dir == ImGuiDir_Up || dir == ImGuiDir_Down) ? ImGuiAxis_Y : ImGuiAxis_X;
08554         ImVec2 pos = avail_rect.Min;
08555         if (dir == ImGuiDir_Right || dir == ImGuiDir_Down)
08556             pos[axis] = avail_rect.Max[axis] - axis_size;
08557         ImVec2 size = avail_rect.GetSize();
08558         size[axis] = axis_size;
08559         SetNextWindowPos(pos);
08560         SetNextWindowSize(size);
08561 
08562         // Report our size into work area (for next frame) using actual window size
08563         if (dir == ImGuiDir_Up || dir == ImGuiDir_Left)
08564             viewport->BuildWorkInsetMin[axis] += axis_size;
08565         else if (dir == ImGuiDir_Down || dir == ImGuiDir_Right)
08566             viewport->BuildWorkInsetMax[axis] += axis_size;
08567     }
08568 
08569     window_flags |= ImGuiWindowFlags_NoTitleBar | ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoMove | ImGuiWindowFlags_NoDocking;
08570     SetNextWindowViewport(viewport->ID); // Enforce viewport so we don't create our own viewport when ImGuiConfigFlags_ViewportsNoMerge is set.
08571     PushStyleVar(ImGuiStyleVar_WindowRounding, 0.0f);
08572     PushStyleVar(ImGuiStyleVar_WindowMinSize, ImVec2(0, 0)); // Lift normal size constraint
08573     bool is_open = Begin(name, NULL, window_flags);
08574     PopStyleVar(2);
08575 
08576     return is_open;
08577 }
08578 
08579 bool ImGui::BeginMainMenuBar()
08580 {
08581     ImGuiContext& g = *GImGui;
08582     ImGuiViewportP* viewport = (ImGuiViewportP*)(void*)GetMainViewport();
08583 
08584     // Notify of viewport change so GetFrameHeight() can be accurate in case of DPI change
08585     SetCurrentViewport(NULL, viewport);
08586 
08587     // For the main menu bar, which cannot be moved, we honor g.Style.DisplaySafeAreaPadding to ensure text can be visible on a TV set.
08588     // FIXME: This could be generalized as an opt-in way to clamp window->DC.CursorStartPos to avoid SafeArea?
08589     // FIXME: Consider removing support for safe area down the line... it's messy. Nowadays consoles have support for TV calibration in OS settings.
08590     g.NextWindowData.MenuBarOffsetMinVal = ImVec2(g.Style.DisplaySafeAreaPadding.x, ImMax(g.Style.DisplaySafeAreaPadding.y - g.Style.FramePadding.y, 0.0f));
08591     ImGuiWindowFlags window_flags = ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoSavedSettings | ImGuiWindowFlags_MenuBar;
08592     float height = GetFrameHeight();
08593     bool is_open = BeginViewportSideBar("##MainMenuBar", viewport, ImGuiDir_Up, height, window_flags);
08594     g.NextWindowData.MenuBarOffsetMinVal = ImVec2(0.0f, 0.0f);
08595 
08596     if (is_open)
08597         BeginMenuBar();
08598     else
08599         End();
08600     return is_open;
08601 }
08602 
08603 void ImGui::EndMainMenuBar()
08604 {
08605     EndMenuBar();
08606 
08607     // When the user has left the menu layer (typically: closed menus through activation of an item), we restore focus to the previous window
08608     // FIXME: With this strategy we won't be able to restore a NULL focus.
08609     ImGuiContext& g = *GImGui;
08610     if (g.CurrentWindow == g.NavWindow && g.NavLayer == ImGuiNavLayer_Main && !g.NavAnyRequest)
08611         FocusTopMostWindowUnderOne(g.NavWindow, NULL, NULL, ImGuiFocusRequestFlags_UnlessBelowModal | ImGuiFocusRequestFlags_RestoreFocusedChild);
08612 
08613     End();
08614 }
08615 
08616 static bool IsRootOfOpenMenuSet()
08617 {
08618     ImGuiContext& g = *GImGui;
08619     ImGuiWindow* window = g.CurrentWindow;
08620     if ((g.OpenPopupStack.Size <= g.BeginPopupStack.Size) || (window->Flags & ImGuiWindowFlags_ChildMenu))
08621         return false;
08622 
08623     // Initially we used 'upper_popup->OpenParentId == window->IDStack.back()' to differentiate multiple menu sets from each others
08624     // (e.g. inside menu bar vs loose menu items) based on parent ID.
08625     // This would however prevent the use of e.g. PushID() user code submitting menus.
08626     // Previously this worked between popup and a first child menu because the first child menu always had the _ChildWindow flag,
08627     // making hovering on parent popup possible while first child menu was focused - but this was generally a bug with other side effects.
08628     // Instead we don't treat Popup specifically (in order to consistently support menu features in them), maybe the first child menu of a Popup
08629     // doesn't have the _ChildWindow flag, and we rely on this IsRootOfOpenMenuSet() check to allow hovering between root window/popup and first child menu.
08630     // In the end, lack of ID check made it so we could no longer differentiate between separate menu sets. To compensate for that, we at least check parent window nav layer.
08631     // This fixes the most common case of menu opening on hover when moving between window content and menu bar. Multiple different menu sets in same nav layer would still
08632     // open on hover, but that should be a lesser problem, because if such menus are close in proximity in window content then it won't feel weird and if they are far apart
08633     // it likely won't be a problem anyone runs into.
08634     const ImGuiPopupData* upper_popup = &g.OpenPopupStack[g.BeginPopupStack.Size];
08635     if (window->DC.NavLayerCurrent != upper_popup->ParentNavLayer)
08636         return false;
08637     return upper_popup->Window && (upper_popup->Window->Flags & ImGuiWindowFlags_ChildMenu) && ImGui::IsWindowChildOf(upper_popup->Window, window, true, false);
08638 }
08639 
08640 bool ImGui::BeginMenuEx(const char* label, const char* icon, bool enabled)
08641 {
08642     ImGuiWindow* window = GetCurrentWindow();
08643     if (window->SkipItems)
08644         return false;
08645 
08646     ImGuiContext& g = *GImGui;
08647     const ImGuiStyle& style = g.Style;
08648     const ImGuiID id = window->GetID(label);
08649     bool menu_is_open = IsPopupOpen(id, ImGuiPopupFlags_None);
08650 
08651     // Sub-menus are ChildWindow so that mouse can be hovering across them (otherwise top-most popup menu would steal focus and not allow hovering on parent menu)
08652     // The first menu in a hierarchy isn't so hovering doesn't get across (otherwise e.g. resizing borders with ImGuiButtonFlags_FlattenChildren would react), but top-most BeginMenu() will bypass that limitation.
08653     ImGuiWindowFlags window_flags = ImGuiWindowFlags_ChildMenu | ImGuiWindowFlags_AlwaysAutoResize | ImGuiWindowFlags_NoMove | ImGuiWindowFlags_NoTitleBar | ImGuiWindowFlags_NoSavedSettings | ImGuiWindowFlags_NoNavFocus;
08654     if (window->Flags & ImGuiWindowFlags_ChildMenu)
08655         window_flags |= ImGuiWindowFlags_ChildWindow;
08656 
08657     // If a menu with same the ID was already submitted, we will append to it, matching the behavior of Begin().
08658     // We are relying on a O(N) search - so O(N log N) over the frame - which seems like the most efficient for the expected small amount of BeginMenu() calls per frame.
08659     // If somehow this is ever becoming a problem we can switch to use e.g. ImGuiStorage mapping key to last frame used.
08660     if (g.MenusIdSubmittedThisFrame.contains(id))
08661     {
08662         if (menu_is_open)
08663             menu_is_open = BeginPopupEx(id, window_flags); // menu_is_open can be 'false' when the popup is completely clipped (e.g. zero size display)
08664         else
08665             g.NextWindowData.ClearFlags();          // we behave like Begin() and need to consume those values
08666         return menu_is_open;
08667     }
08668 
08669     // Tag menu as used. Next time BeginMenu() with same ID is called it will append to existing menu
08670     g.MenusIdSubmittedThisFrame.push_back(id);
08671 
08672     ImVec2 label_size = CalcTextSize(label, NULL, true);
08673 
08674     // Odd hack to allow hovering across menus of a same menu-set (otherwise we wouldn't be able to hover parent without always being a Child window)
08675     // This is only done for items for the menu set and not the full parent window.
08676     const bool menuset_is_open = IsRootOfOpenMenuSet();
08677     if (menuset_is_open)
08678         PushItemFlag(ImGuiItemFlags_NoWindowHoverableCheck, true);
08679 
08680     // The reference position stored in popup_pos will be used by Begin() to find a suitable position for the child menu,
08681     // However the final position is going to be different! It is chosen by FindBestWindowPosForPopup().
08682     // e.g. Menus tend to overlap each other horizontally to amplify relative Z-ordering.
08683     ImVec2 popup_pos, pos = window->DC.CursorPos;
08684     PushID(label);
08685     if (!enabled)
08686         BeginDisabled();
08687     const ImGuiMenuColumns* offsets = &window->DC.MenuColumns;
08688     bool pressed;
08689 
08690     // We use ImGuiSelectableFlags_NoSetKeyOwner to allow down on one menu item, move, up on another.
08691     const ImGuiSelectableFlags selectable_flags = ImGuiSelectableFlags_NoHoldingActiveID | ImGuiSelectableFlags_NoSetKeyOwner | ImGuiSelectableFlags_SelectOnClick | ImGuiSelectableFlags_NoAutoClosePopups;
08692     if (window->DC.LayoutType == ImGuiLayoutType_Horizontal)
08693     {
08694         // Menu inside an horizontal menu bar
08695         // Selectable extend their highlight by half ItemSpacing in each direction.
08696         // For ChildMenu, the popup position will be overwritten by the call to FindBestWindowPosForPopup() in Begin()
08697         popup_pos = ImVec2(pos.x - 1.0f - IM_TRUNC(style.ItemSpacing.x * 0.5f), pos.y - style.FramePadding.y + window->MenuBarHeight);
08698         window->DC.CursorPos.x += IM_TRUNC(style.ItemSpacing.x * 0.5f);
08699         PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(style.ItemSpacing.x * 2.0f, style.ItemSpacing.y));
08700         float w = label_size.x;
08701         ImVec2 text_pos(window->DC.CursorPos.x + offsets->OffsetLabel, window->DC.CursorPos.y + window->DC.CurrLineTextBaseOffset);
08702         pressed = Selectable("", menu_is_open, selectable_flags, ImVec2(w, label_size.y));
08703         RenderText(text_pos, label);
08704         PopStyleVar();
08705         window->DC.CursorPos.x += IM_TRUNC(style.ItemSpacing.x * (-1.0f + 0.5f)); // -1 spacing to compensate the spacing added when Selectable() did a SameLine(). It would also work to call SameLine() ourselves after the PopStyleVar().
08706     }
08707     else
08708     {
08709         // Menu inside a regular/vertical menu
08710         // (In a typical menu window where all items are BeginMenu() or MenuItem() calls, extra_w will always be 0.0f.
08711         //  Only when they are other items sticking out we're going to add spacing, yet only register minimum width into the layout system.
08712         popup_pos = ImVec2(pos.x, pos.y - style.WindowPadding.y);
08713         float icon_w = (icon && icon[0]) ? CalcTextSize(icon, NULL).x : 0.0f;
08714         float checkmark_w = IM_TRUNC(g.FontSize * 1.20f);
08715         float min_w = window->DC.MenuColumns.DeclColumns(icon_w, label_size.x, 0.0f, checkmark_w); // Feedback to next frame
08716         float extra_w = ImMax(0.0f, GetContentRegionAvail().x - min_w);
08717         ImVec2 text_pos(window->DC.CursorPos.x + offsets->OffsetLabel, window->DC.CursorPos.y + window->DC.CurrLineTextBaseOffset);
08718         pressed = Selectable("", menu_is_open, selectable_flags | ImGuiSelectableFlags_SpanAvailWidth, ImVec2(min_w, label_size.y));
08719         RenderText(text_pos, label);
08720         if (icon_w > 0.0f)
08721             RenderText(pos + ImVec2(offsets->OffsetIcon, 0.0f), icon);
08722         RenderArrow(window->DrawList, pos + ImVec2(offsets->OffsetMark + extra_w + g.FontSize * 0.30f, 0.0f), GetColorU32(ImGuiCol_Text), ImGuiDir_Right);
08723     }
08724     if (!enabled)
08725         EndDisabled();
08726 
08727     const bool hovered = (g.HoveredId == id) && enabled && !g.NavDisableMouseHover;
08728     if (menuset_is_open)
08729         PopItemFlag();
08730 
08731     bool want_open = false;
08732     bool want_open_nav_init = false;
08733     bool want_close = false;
08734     if (window->DC.LayoutType == ImGuiLayoutType_Vertical) // (window->Flags & (ImGuiWindowFlags_Popup|ImGuiWindowFlags_ChildMenu))
08735     {
08736         // Close menu when not hovering it anymore unless we are moving roughly in the direction of the menu
08737         // Implement http://bjk5.com/post/44698559168/breaking-down-amazons-mega-dropdown to avoid using timers, so menus feels more reactive.
08738         bool moving_toward_child_menu = false;
08739         ImGuiPopupData* child_popup = (g.BeginPopupStack.Size < g.OpenPopupStack.Size) ? &g.OpenPopupStack[g.BeginPopupStack.Size] : NULL; // Popup candidate (testing below)
08740         ImGuiWindow* child_menu_window = (child_popup && child_popup->Window && child_popup->Window->ParentWindow == window) ? child_popup->Window : NULL;
08741         if (g.HoveredWindow == window && child_menu_window != NULL)
08742         {
08743             const float ref_unit = g.FontSize; // FIXME-DPI
08744             const float child_dir = (window->Pos.x < child_menu_window->Pos.x) ? 1.0f : -1.0f;
08745             const ImRect next_window_rect = child_menu_window->Rect();
08746             ImVec2 ta = (g.IO.MousePos - g.IO.MouseDelta);
08747             ImVec2 tb = (child_dir > 0.0f) ? next_window_rect.GetTL() : next_window_rect.GetTR();
08748             ImVec2 tc = (child_dir > 0.0f) ? next_window_rect.GetBL() : next_window_rect.GetBR();
08749             const float pad_farmost_h = ImClamp(ImFabs(ta.x - tb.x) * 0.30f, ref_unit * 0.5f, ref_unit * 2.5f); // Add a bit of extra slack.
08750             ta.x += child_dir * -0.5f;
08751             tb.x += child_dir * ref_unit;
08752             tc.x += child_dir * ref_unit;
08753             tb.y = ta.y + ImMax((tb.y - pad_farmost_h) - ta.y, -ref_unit * 8.0f); // Triangle has maximum height to limit the slope and the bias toward large sub-menus
08754             tc.y = ta.y + ImMin((tc.y + pad_farmost_h) - ta.y, +ref_unit * 8.0f);
08755             moving_toward_child_menu = ImTriangleContainsPoint(ta, tb, tc, g.IO.MousePos);
08756             //GetForegroundDrawList()->AddTriangleFilled(ta, tb, tc, moving_toward_child_menu ? IM_COL32(0,128,0,128) : IM_COL32(128,0,0,128)); // [DEBUG]
08757         }
08758 
08759         // The 'HovereWindow == window' check creates an inconsistency (e.g. moving away from menu slowly tends to hit same window, whereas moving away fast does not)
08760         // But we also need to not close the top-menu menu when moving over void. Perhaps we should extend the triangle check to a larger polygon.
08761         // (Remember to test this on BeginPopup("A")->BeginMenu("B") sequence which behaves slightly differently as B isn't a Child of A and hovering isn't shared.)
08762         if (menu_is_open && !hovered && g.HoveredWindow == window && !moving_toward_child_menu && !g.NavDisableMouseHover && g.ActiveId == 0)
08763             want_close = true;
08764 
08765         // Open
08766         // (note: at this point 'hovered' actually includes the NavDisableMouseHover == false test)
08767         if (!menu_is_open && pressed) // Click/activate to open
08768             want_open = true;
08769         else if (!menu_is_open && hovered && !moving_toward_child_menu) // Hover to open
08770             want_open = true;
08771         else if (!menu_is_open && hovered && g.HoveredIdTimer >= 0.30f && g.MouseStationaryTimer >= 0.30f) // Hover to open (timer fallback)
08772             want_open = true;
08773         if (g.NavId == id && g.NavMoveDir == ImGuiDir_Right) // Nav-Right to open
08774         {
08775             want_open = want_open_nav_init = true;
08776             NavMoveRequestCancel();
08777             NavRestoreHighlightAfterMove();
08778         }
08779     }
08780     else
08781     {
08782         // Menu bar
08783         if (menu_is_open && pressed && menuset_is_open) // Click an open menu again to close it
08784         {
08785             want_close = true;
08786             want_open = menu_is_open = false;
08787         }
08788         else if (pressed || (hovered && menuset_is_open && !menu_is_open)) // First click to open, then hover to open others
08789         {
08790             want_open = true;
08791         }
08792         else if (g.NavId == id && g.NavMoveDir == ImGuiDir_Down) // Nav-Down to open
08793         {
08794             want_open = true;
08795             NavMoveRequestCancel();
08796         }
08797     }
08798 
08799     if (!enabled) // explicitly close if an open menu becomes disabled, facilitate users code a lot in pattern such as 'if (BeginMenu("options", has_object)) { ..use object.. }'
08800         want_close = true;
08801     if (want_close && IsPopupOpen(id, ImGuiPopupFlags_None))
08802         ClosePopupToLevel(g.BeginPopupStack.Size, true);
08803 
08804     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Openable | (menu_is_open ? ImGuiItemStatusFlags_Opened : 0));
08805     PopID();
08806 
08807     if (want_open && !menu_is_open && g.OpenPopupStack.Size > g.BeginPopupStack.Size)
08808     {
08809         // Don't reopen/recycle same menu level in the same frame if it is a different menu ID, first close the other menu and yield for a frame.
08810         OpenPopup(label);
08811     }
08812     else if (want_open)
08813     {
08814         menu_is_open = true;
08815         OpenPopup(label, ImGuiPopupFlags_NoReopen);// | (want_open_nav_init ? ImGuiPopupFlags_NoReopenAlwaysNavInit : 0));
08816     }
08817 
08818     if (menu_is_open)
08819     {
08820         ImGuiLastItemData last_item_in_parent = g.LastItemData;
08821         SetNextWindowPos(popup_pos, ImGuiCond_Always);                  // Note: misleading: the value will serve as reference for FindBestWindowPosForPopup(), not actual pos.
08822         PushStyleVar(ImGuiStyleVar_ChildRounding, style.PopupRounding); // First level will use _PopupRounding, subsequent will use _ChildRounding
08823         menu_is_open = BeginPopupEx(id, window_flags);                  // menu_is_open can be 'false' when the popup is completely clipped (e.g. zero size display)
08824         PopStyleVar();
08825         if (menu_is_open)
08826         {
08827             // Implement what ImGuiPopupFlags_NoReopenAlwaysNavInit would do:
08828             // Perform an init request in the case the popup was already open (via a previous mouse hover)
08829             if (want_open && want_open_nav_init && !g.NavInitRequest)
08830             {
08831                 FocusWindow(g.CurrentWindow, ImGuiFocusRequestFlags_UnlessBelowModal);
08832                 NavInitWindow(g.CurrentWindow, false);
08833             }
08834 
08835             // Restore LastItemData so IsItemXXXX functions can work after BeginMenu()/EndMenu()
08836             // (This fixes using IsItemClicked() and IsItemHovered(), but IsItemHovered() also relies on its support for ImGuiItemFlags_NoWindowHoverableCheck)
08837             g.LastItemData = last_item_in_parent;
08838             if (g.HoveredWindow == window)
08839                 g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_HoveredWindow;
08840         }
08841     }
08842     else
08843     {
08844         g.NextWindowData.ClearFlags(); // We behave like Begin() and need to consume those values
08845     }
08846 
08847     return menu_is_open;
08848 }
08849 
08850 bool ImGui::BeginMenu(const char* label, bool enabled)
08851 {
08852     return BeginMenuEx(label, NULL, enabled);
08853 }
08854 
08855 void ImGui::EndMenu()
08856 {
08857     // Nav: When a left move request our menu failed, close ourselves.
08858     ImGuiContext& g = *GImGui;
08859     ImGuiWindow* window = g.CurrentWindow;
08860     IM_ASSERT(window->Flags & ImGuiWindowFlags_Popup);  // Mismatched BeginMenu()/EndMenu() calls
08861     ImGuiWindow* parent_window = window->ParentWindow;  // Should always be != NULL is we passed assert.
08862     if (window->BeginCount == window->BeginCountPreviousFrame)
08863         if (g.NavMoveDir == ImGuiDir_Left && NavMoveRequestButNoResultYet())
08864             if (g.NavWindow && (g.NavWindow->RootWindowForNav == window) && parent_window->DC.LayoutType == ImGuiLayoutType_Vertical)
08865             {
08866                 ClosePopupToLevel(g.BeginPopupStack.Size - 1, true);
08867                 NavMoveRequestCancel();
08868             }
08869 
08870     EndPopup();
08871 }
08872 
08873 bool ImGui::MenuItemEx(const char* label, const char* icon, const char* shortcut, bool selected, bool enabled)
08874 {
08875     ImGuiWindow* window = GetCurrentWindow();
08876     if (window->SkipItems)
08877         return false;
08878 
08879     ImGuiContext& g = *GImGui;
08880     ImGuiStyle& style = g.Style;
08881     ImVec2 pos = window->DC.CursorPos;
08882     ImVec2 label_size = CalcTextSize(label, NULL, true);
08883 
08884     // See BeginMenuEx() for comments about this.
08885     const bool menuset_is_open = IsRootOfOpenMenuSet();
08886     if (menuset_is_open)
08887         PushItemFlag(ImGuiItemFlags_NoWindowHoverableCheck, true);
08888 
08889     // We've been using the equivalent of ImGuiSelectableFlags_SetNavIdOnHover on all Selectable() since early Nav system days (commit 43ee5d73),
08890     // but I am unsure whether this should be kept at all. For now moved it to be an opt-in feature used by menus only.
08891     bool pressed;
08892     PushID(label);
08893     if (!enabled)
08894         BeginDisabled();
08895 
08896     // We use ImGuiSelectableFlags_NoSetKeyOwner to allow down on one menu item, move, up on another.
08897     const ImGuiSelectableFlags selectable_flags = ImGuiSelectableFlags_SelectOnRelease | ImGuiSelectableFlags_NoSetKeyOwner | ImGuiSelectableFlags_SetNavIdOnHover;
08898     const ImGuiMenuColumns* offsets = &window->DC.MenuColumns;
08899     if (window->DC.LayoutType == ImGuiLayoutType_Horizontal)
08900     {
08901         // Mimic the exact layout spacing of BeginMenu() to allow MenuItem() inside a menu bar, which is a little misleading but may be useful
08902         // Note that in this situation: we don't render the shortcut, we render a highlight instead of the selected tick mark.
08903         float w = label_size.x;
08904         window->DC.CursorPos.x += IM_TRUNC(style.ItemSpacing.x * 0.5f);
08905         ImVec2 text_pos(window->DC.CursorPos.x + offsets->OffsetLabel, window->DC.CursorPos.y + window->DC.CurrLineTextBaseOffset);
08906         PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(style.ItemSpacing.x * 2.0f, style.ItemSpacing.y));
08907         pressed = Selectable("", selected, selectable_flags, ImVec2(w, 0.0f));
08908         PopStyleVar();
08909         if (g.LastItemData.StatusFlags & ImGuiItemStatusFlags_Visible)
08910             RenderText(text_pos, label);
08911         window->DC.CursorPos.x += IM_TRUNC(style.ItemSpacing.x * (-1.0f + 0.5f)); // -1 spacing to compensate the spacing added when Selectable() did a SameLine(). It would also work to call SameLine() ourselves after the PopStyleVar().
08912     }
08913     else
08914     {
08915         // Menu item inside a vertical menu
08916         // (In a typical menu window where all items are BeginMenu() or MenuItem() calls, extra_w will always be 0.0f.
08917         //  Only when they are other items sticking out we're going to add spacing, yet only register minimum width into the layout system.
08918         float icon_w = (icon && icon[0]) ? CalcTextSize(icon, NULL).x : 0.0f;
08919         float shortcut_w = (shortcut && shortcut[0]) ? CalcTextSize(shortcut, NULL).x : 0.0f;
08920         float checkmark_w = IM_TRUNC(g.FontSize * 1.20f);
08921         float min_w = window->DC.MenuColumns.DeclColumns(icon_w, label_size.x, shortcut_w, checkmark_w); // Feedback for next frame
08922         float stretch_w = ImMax(0.0f, GetContentRegionAvail().x - min_w);
08923         pressed = Selectable("", false, selectable_flags | ImGuiSelectableFlags_SpanAvailWidth, ImVec2(min_w, label_size.y));
08924         if (g.LastItemData.StatusFlags & ImGuiItemStatusFlags_Visible)
08925         {
08926             RenderText(pos + ImVec2(offsets->OffsetLabel, 0.0f), label);
08927             if (icon_w > 0.0f)
08928                 RenderText(pos + ImVec2(offsets->OffsetIcon, 0.0f), icon);
08929             if (shortcut_w > 0.0f)
08930             {
08931                 PushStyleColor(ImGuiCol_Text, style.Colors[ImGuiCol_TextDisabled]);
08932                 RenderText(pos + ImVec2(offsets->OffsetShortcut + stretch_w, 0.0f), shortcut, NULL, false);
08933                 PopStyleColor();
08934             }
08935             if (selected)
08936                 RenderCheckMark(window->DrawList, pos + ImVec2(offsets->OffsetMark + stretch_w + g.FontSize * 0.40f, g.FontSize * 0.134f * 0.5f), GetColorU32(ImGuiCol_Text), g.FontSize * 0.866f);
08937         }
08938     }
08939     IMGUI_TEST_ENGINE_ITEM_INFO(g.LastItemData.ID, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Checkable | (selected ? ImGuiItemStatusFlags_Checked : 0));
08940     if (!enabled)
08941         EndDisabled();
08942     PopID();
08943     if (menuset_is_open)
08944         PopItemFlag();
08945 
08946     return pressed;
08947 }
08948 
08949 bool ImGui::MenuItem(const char* label, const char* shortcut, bool selected, bool enabled)
08950 {
08951     return MenuItemEx(label, NULL, shortcut, selected, enabled);
08952 }
08953 
08954 bool ImGui::MenuItem(const char* label, const char* shortcut, bool* p_selected, bool enabled)
08955 {
08956     if (MenuItemEx(label, NULL, shortcut, p_selected ? *p_selected : false, enabled))
08957     {
08958         if (p_selected)
08959             *p_selected = !*p_selected;
08960         return true;
08961     }
08962     return false;
08963 }
