08992 struct ImGuiTabBarSection
08993 {
08994     int                 TabCount;               // Number of tabs in this section.
08995     float               Width;                  // Sum of width of tabs in this section (after shrinking down)
08996     float               Spacing;                // Horizontal spacing at the end of the section.
08997 
08998     ImGuiTabBarSection() { memset(this, 0, sizeof(*this)); }
08999 };
09000 
09001 namespace ImGui
09002 {
09003     static void             TabBarLayout(ImGuiTabBar* tab_bar);
09004     static ImU32            TabBarCalcTabID(ImGuiTabBar* tab_bar, const char* label, ImGuiWindow* docked_window);
09005     static float            TabBarCalcMaxTabWidth();
09006     static float            TabBarScrollClamp(ImGuiTabBar* tab_bar, float scrolling);
09007     static void             TabBarScrollToTab(ImGuiTabBar* tab_bar, ImGuiID tab_id, ImGuiTabBarSection* sections);
09008     static ImGuiTabItem*    TabBarScrollingButtons(ImGuiTabBar* tab_bar);
09009     static ImGuiTabItem*    TabBarTabListPopupButton(ImGuiTabBar* tab_bar);
09010 }
09011 
09012 ImGuiTabBar::ImGuiTabBar()
09013 {
09014     memset(this, 0, sizeof(*this));
09015     CurrFrameVisible = PrevFrameVisible = -1;
09016     LastTabItemIdx = -1;
09017 }
09018 
09019 static inline int TabItemGetSectionIdx(const ImGuiTabItem* tab)
09020 {
09021     return (tab->Flags & ImGuiTabItemFlags_Leading) ? 0 : (tab->Flags & ImGuiTabItemFlags_Trailing) ? 2 : 1;
09022 }
09023 
09024 static int IMGUI_CDECL TabItemComparerBySection(const void* lhs, const void* rhs)
09025 {
09026     const ImGuiTabItem* a = (const ImGuiTabItem*)lhs;
09027     const ImGuiTabItem* b = (const ImGuiTabItem*)rhs;
09028     const int a_section = TabItemGetSectionIdx(a);
09029     const int b_section = TabItemGetSectionIdx(b);
09030     if (a_section != b_section)
09031         return a_section - b_section;
09032     return (int)(a->IndexDuringLayout - b->IndexDuringLayout);
09033 }
09034 
09035 static int IMGUI_CDECL TabItemComparerByBeginOrder(const void* lhs, const void* rhs)
09036 {
09037     const ImGuiTabItem* a = (const ImGuiTabItem*)lhs;
09038     const ImGuiTabItem* b = (const ImGuiTabItem*)rhs;
09039     return (int)(a->BeginOrder - b->BeginOrder);
09040 }
09041 
09042 static ImGuiTabBar* GetTabBarFromTabBarRef(const ImGuiPtrOrIndex& ref)
09043 {
09044     ImGuiContext& g = *GImGui;
09045     return ref.Ptr ? (ImGuiTabBar*)ref.Ptr : g.TabBars.GetByIndex(ref.Index);
09046 }
09047 
09048 static ImGuiPtrOrIndex GetTabBarRefFromTabBar(ImGuiTabBar* tab_bar)
09049 {
09050     ImGuiContext& g = *GImGui;
09051     if (g.TabBars.Contains(tab_bar))
09052         return ImGuiPtrOrIndex(g.TabBars.GetIndex(tab_bar));
09053     return ImGuiPtrOrIndex(tab_bar);
09054 }
09055 
09056 bool    ImGui::BeginTabBar(const char* str_id, ImGuiTabBarFlags flags)
09057 {
09058     ImGuiContext& g = *GImGui;
09059     ImGuiWindow* window = g.CurrentWindow;
09060     if (window->SkipItems)
09061         return false;
09062 
09063     ImGuiID id = window->GetID(str_id);
09064     ImGuiTabBar* tab_bar = g.TabBars.GetOrAddByKey(id);
09065     ImRect tab_bar_bb = ImRect(window->DC.CursorPos.x, window->DC.CursorPos.y, window->WorkRect.Max.x, window->DC.CursorPos.y + g.FontSize + g.Style.FramePadding.y * 2);
09066     tab_bar->ID = id;
09067     tab_bar->SeparatorMinX = tab_bar->BarRect.Min.x - IM_TRUNC(window->WindowPadding.x * 0.5f);
09068     tab_bar->SeparatorMaxX = tab_bar->BarRect.Max.x + IM_TRUNC(window->WindowPadding.x * 0.5f);
09069     //if (g.NavWindow && IsWindowChildOf(g.NavWindow, window, false, false))
09070     flags |= ImGuiTabBarFlags_IsFocused;
09071     return BeginTabBarEx(tab_bar, tab_bar_bb, flags);
09072 }
09073 
09074 bool    ImGui::BeginTabBarEx(ImGuiTabBar* tab_bar, const ImRect& tab_bar_bb, ImGuiTabBarFlags flags)
09075 {
09076     ImGuiContext& g = *GImGui;
09077     ImGuiWindow* window = g.CurrentWindow;
09078     if (window->SkipItems)
09079         return false;
09080 
09081     IM_ASSERT(tab_bar->ID != 0);
09082     if ((flags & ImGuiTabBarFlags_DockNode) == 0)
09083         PushOverrideID(tab_bar->ID);
09084 
09085     // Add to stack
09086     g.CurrentTabBarStack.push_back(GetTabBarRefFromTabBar(tab_bar));
09087     g.CurrentTabBar = tab_bar;
09088 
09089     // Append with multiple BeginTabBar()/EndTabBar() pairs.
09090     tab_bar->BackupCursorPos = window->DC.CursorPos;
09091     if (tab_bar->CurrFrameVisible == g.FrameCount)
09092     {
09093         window->DC.CursorPos = ImVec2(tab_bar->BarRect.Min.x, tab_bar->BarRect.Max.y + tab_bar->ItemSpacingY);
09094         tab_bar->BeginCount++;
09095         return true;
09096     }
09097 
09098     // Ensure correct ordering when toggling ImGuiTabBarFlags_Reorderable flag, or when a new tab was added while being not reorderable
09099     if ((flags & ImGuiTabBarFlags_Reorderable) != (tab_bar->Flags & ImGuiTabBarFlags_Reorderable) || (tab_bar->TabsAddedNew && !(flags & ImGuiTabBarFlags_Reorderable)))
09100         if ((flags & ImGuiTabBarFlags_DockNode) == 0) // FIXME: TabBar with DockNode can now be hybrid
09101             ImQsort(tab_bar->Tabs.Data, tab_bar->Tabs.Size, sizeof(ImGuiTabItem), TabItemComparerByBeginOrder);
09102     tab_bar->TabsAddedNew = false;
09103 
09104     // Flags
09105     if ((flags & ImGuiTabBarFlags_FittingPolicyMask_) == 0)
09106         flags |= ImGuiTabBarFlags_FittingPolicyDefault_;
09107 
09108     tab_bar->Flags = flags;
09109     tab_bar->BarRect = tab_bar_bb;
09110     tab_bar->WantLayout = true; // Layout will be done on the first call to ItemTab()
09111     tab_bar->PrevFrameVisible = tab_bar->CurrFrameVisible;
09112     tab_bar->CurrFrameVisible = g.FrameCount;
09113     tab_bar->PrevTabsContentsHeight = tab_bar->CurrTabsContentsHeight;
09114     tab_bar->CurrTabsContentsHeight = 0.0f;
09115     tab_bar->ItemSpacingY = g.Style.ItemSpacing.y;
09116     tab_bar->FramePadding = g.Style.FramePadding;
09117     tab_bar->TabsActiveCount = 0;
09118     tab_bar->LastTabItemIdx = -1;
09119     tab_bar->BeginCount = 1;
09120 
09121     // Set cursor pos in a way which only be used in the off-chance the user erroneously submits item before BeginTabItem(): items will overlap
09122     window->DC.CursorPos = ImVec2(tab_bar->BarRect.Min.x, tab_bar->BarRect.Max.y + tab_bar->ItemSpacingY);
09123 
09124     // Draw separator
09125     // (it would be misleading to draw this in EndTabBar() suggesting that it may be drawn over tabs, as tab bar are appendable)
09126     const ImU32 col = GetColorU32((flags & ImGuiTabBarFlags_IsFocused) ? ImGuiCol_TabSelected : ImGuiCol_TabDimmedSelected);
09127     if (g.Style.TabBarBorderSize > 0.0f)
09128     {
09129         const float y = tab_bar->BarRect.Max.y;
09130         window->DrawList->AddRectFilled(ImVec2(tab_bar->SeparatorMinX, y - g.Style.TabBarBorderSize), ImVec2(tab_bar->SeparatorMaxX, y), col);
09131     }
09132     return true;
09133 }
09134 
09135 void    ImGui::EndTabBar()
09136 {
09137     ImGuiContext& g = *GImGui;
09138     ImGuiWindow* window = g.CurrentWindow;
09139     if (window->SkipItems)
09140         return;
09141 
09142     ImGuiTabBar* tab_bar = g.CurrentTabBar;
09143     if (tab_bar == NULL)
09144     {
09145         IM_ASSERT_USER_ERROR(tab_bar != NULL, "Mismatched BeginTabBar()/EndTabBar()!");
09146         return;
09147     }
09148 
09149     // Fallback in case no TabItem have been submitted
09150     if (tab_bar->WantLayout)
09151         TabBarLayout(tab_bar);
09152 
09153     // Restore the last visible height if no tab is visible, this reduce vertical flicker/movement when a tabs gets removed without calling SetTabItemClosed().
09154     const bool tab_bar_appearing = (tab_bar->PrevFrameVisible + 1 < g.FrameCount);
09155     if (tab_bar->VisibleTabWasSubmitted || tab_bar->VisibleTabId == 0 || tab_bar_appearing)
09156     {
09157         tab_bar->CurrTabsContentsHeight = ImMax(window->DC.CursorPos.y - tab_bar->BarRect.Max.y, tab_bar->CurrTabsContentsHeight);
09158         window->DC.CursorPos.y = tab_bar->BarRect.Max.y + tab_bar->CurrTabsContentsHeight;
09159     }
09160     else
09161     {
09162         window->DC.CursorPos.y = tab_bar->BarRect.Max.y + tab_bar->PrevTabsContentsHeight;
09163     }
09164     if (tab_bar->BeginCount > 1)
09165         window->DC.CursorPos = tab_bar->BackupCursorPos;
09166 
09167     tab_bar->LastTabItemIdx = -1;
09168     if ((tab_bar->Flags & ImGuiTabBarFlags_DockNode) == 0)
09169         PopID();
09170 
09171     g.CurrentTabBarStack.pop_back();
09172     g.CurrentTabBar = g.CurrentTabBarStack.empty() ? NULL : GetTabBarFromTabBarRef(g.CurrentTabBarStack.back());
09173 }
09174 
09175 // Scrolling happens only in the central section (leading/trailing sections are not scrolling)
09176 static float TabBarCalcScrollableWidth(ImGuiTabBar* tab_bar, ImGuiTabBarSection* sections)
09177 {
09178     return tab_bar->BarRect.GetWidth() - sections[0].Width - sections[2].Width - sections[1].Spacing;
09179 }
09180 
09181 // This is called only once a frame before by the first call to ItemTab()
09182 // The reason we're not calling it in BeginTabBar() is to leave a chance to the user to call the SetTabItemClosed() functions.
09183 static void ImGui::TabBarLayout(ImGuiTabBar* tab_bar)
09184 {
09185     ImGuiContext& g = *GImGui;
09186     tab_bar->WantLayout = false;
09187 
09188     // Garbage collect by compacting list
09189     // Detect if we need to sort out tab list (e.g. in rare case where a tab changed section)
09190     int tab_dst_n = 0;
09191     bool need_sort_by_section = false;
09192     ImGuiTabBarSection sections[3]; // Layout sections: Leading, Central, Trailing
09193     for (int tab_src_n = 0; tab_src_n < tab_bar->Tabs.Size; tab_src_n++)
09194     {
09195         ImGuiTabItem* tab = &tab_bar->Tabs[tab_src_n];
09196         if (tab->LastFrameVisible < tab_bar->PrevFrameVisible || tab->WantClose)
09197         {
09198             // Remove tab
09199             if (tab_bar->VisibleTabId == tab->ID) { tab_bar->VisibleTabId = 0; }
09200             if (tab_bar->SelectedTabId == tab->ID) { tab_bar->SelectedTabId = 0; }
09201             if (tab_bar->NextSelectedTabId == tab->ID) { tab_bar->NextSelectedTabId = 0; }
09202             continue;
09203         }
09204         if (tab_dst_n != tab_src_n)
09205             tab_bar->Tabs[tab_dst_n] = tab_bar->Tabs[tab_src_n];
09206 
09207         tab = &tab_bar->Tabs[tab_dst_n];
09208         tab->IndexDuringLayout = (ImS16)tab_dst_n;
09209 
09210         // We will need sorting if tabs have changed section (e.g. moved from one of Leading/Central/Trailing to another)
09211         int curr_tab_section_n = TabItemGetSectionIdx(tab);
09212         if (tab_dst_n > 0)
09213         {
09214             ImGuiTabItem* prev_tab = &tab_bar->Tabs[tab_dst_n - 1];
09215             int prev_tab_section_n = TabItemGetSectionIdx(prev_tab);
09216             if (curr_tab_section_n == 0 && prev_tab_section_n != 0)
09217                 need_sort_by_section = true;
09218             if (prev_tab_section_n == 2 && curr_tab_section_n != 2)
09219                 need_sort_by_section = true;
09220         }
09221 
09222         sections[curr_tab_section_n].TabCount++;
09223         tab_dst_n++;
09224     }
09225     if (tab_bar->Tabs.Size != tab_dst_n)
09226         tab_bar->Tabs.resize(tab_dst_n);
09227 
09228     if (need_sort_by_section)
09229         ImQsort(tab_bar->Tabs.Data, tab_bar->Tabs.Size, sizeof(ImGuiTabItem), TabItemComparerBySection);
09230 
09231     // Calculate spacing between sections
09232     sections[0].Spacing = sections[0].TabCount > 0 && (sections[1].TabCount + sections[2].TabCount) > 0 ? g.Style.ItemInnerSpacing.x : 0.0f;
09233     sections[1].Spacing = sections[1].TabCount > 0 && sections[2].TabCount > 0 ? g.Style.ItemInnerSpacing.x : 0.0f;
09234 
09235     // Setup next selected tab
09236     ImGuiID scroll_to_tab_id = 0;
09237     if (tab_bar->NextSelectedTabId)
09238     {
09239         tab_bar->SelectedTabId = tab_bar->NextSelectedTabId;
09240         tab_bar->NextSelectedTabId = 0;
09241         scroll_to_tab_id = tab_bar->SelectedTabId;
09242     }
09243 
09244     // Process order change request (we could probably process it when requested but it's just saner to do it in a single spot).
09245     if (tab_bar->ReorderRequestTabId != 0)
09246     {
09247         if (TabBarProcessReorder(tab_bar))
09248             if (tab_bar->ReorderRequestTabId == tab_bar->SelectedTabId)
09249                 scroll_to_tab_id = tab_bar->ReorderRequestTabId;
09250         tab_bar->ReorderRequestTabId = 0;
09251     }
09252 
09253     // Tab List Popup (will alter tab_bar->BarRect and therefore the available width!)
09254     const bool tab_list_popup_button = (tab_bar->Flags & ImGuiTabBarFlags_TabListPopupButton) != 0;
09255     if (tab_list_popup_button)
09256         if (ImGuiTabItem* tab_to_select = TabBarTabListPopupButton(tab_bar)) // NB: Will alter BarRect.Min.x!
09257             scroll_to_tab_id = tab_bar->SelectedTabId = tab_to_select->ID;
09258 
09259     // Leading/Trailing tabs will be shrink only if central one aren't visible anymore, so layout the shrink data as: leading, trailing, central
09260     // (whereas our tabs are stored as: leading, central, trailing)
09261     int shrink_buffer_indexes[3] = { 0, sections[0].TabCount + sections[2].TabCount, sections[0].TabCount };
09262     g.ShrinkWidthBuffer.resize(tab_bar->Tabs.Size);
09263 
09264     // Compute ideal tabs widths + store them into shrink buffer
09265     ImGuiTabItem* most_recently_selected_tab = NULL;
09266     int curr_section_n = -1;
09267     bool found_selected_tab_id = false;
09268     for (int tab_n = 0; tab_n < tab_bar->Tabs.Size; tab_n++)
09269     {
09270         ImGuiTabItem* tab = &tab_bar->Tabs[tab_n];
09271         IM_ASSERT(tab->LastFrameVisible >= tab_bar->PrevFrameVisible);
09272 
09273         if ((most_recently_selected_tab == NULL || most_recently_selected_tab->LastFrameSelected < tab->LastFrameSelected) && !(tab->Flags & ImGuiTabItemFlags_Button))
09274             most_recently_selected_tab = tab;
09275         if (tab->ID == tab_bar->SelectedTabId)
09276             found_selected_tab_id = true;
09277         if (scroll_to_tab_id == 0 && g.NavJustMovedToId == tab->ID)
09278             scroll_to_tab_id = tab->ID;
09279 
09280         // Refresh tab width immediately, otherwise changes of style e.g. style.FramePadding.x would noticeably lag in the tab bar.
09281         // Additionally, when using TabBarAddTab() to manipulate tab bar order we occasionally insert new tabs that don't have a width yet,
09282         // and we cannot wait for the next BeginTabItem() call. We cannot compute this width within TabBarAddTab() because font size depends on the active window.
09283         const char* tab_name = TabBarGetTabName(tab_bar, tab);
09284         const bool has_close_button_or_unsaved_marker = (tab->Flags & ImGuiTabItemFlags_NoCloseButton) == 0 || (tab->Flags & ImGuiTabItemFlags_UnsavedDocument);
09285         tab->ContentWidth = (tab->RequestedWidth >= 0.0f) ? tab->RequestedWidth : TabItemCalcSize(tab_name, has_close_button_or_unsaved_marker).x;
09286 
09287         int section_n = TabItemGetSectionIdx(tab);
09288         ImGuiTabBarSection* section = &sections[section_n];
09289         section->Width += tab->ContentWidth + (section_n == curr_section_n ? g.Style.ItemInnerSpacing.x : 0.0f);
09290         curr_section_n = section_n;
09291 
09292         // Store data so we can build an array sorted by width if we need to shrink tabs down
09293         IM_MSVC_WARNING_SUPPRESS(6385);
09294         ImGuiShrinkWidthItem* shrink_width_item = &g.ShrinkWidthBuffer[shrink_buffer_indexes[section_n]++];
09295         shrink_width_item->Index = tab_n;
09296         shrink_width_item->Width = shrink_width_item->InitialWidth = tab->ContentWidth;
09297         tab->Width = ImMax(tab->ContentWidth, 1.0f);
09298     }
09299 
09300     // Compute total ideal width (used for e.g. auto-resizing a window)
09301     tab_bar->WidthAllTabsIdeal = 0.0f;
09302     for (int section_n = 0; section_n < 3; section_n++)
09303         tab_bar->WidthAllTabsIdeal += sections[section_n].Width + sections[section_n].Spacing;
09304 
09305     // Horizontal scrolling buttons
09306     // (note that TabBarScrollButtons() will alter BarRect.Max.x)
09307     if ((tab_bar->WidthAllTabsIdeal > tab_bar->BarRect.GetWidth() && tab_bar->Tabs.Size > 1) && !(tab_bar->Flags & ImGuiTabBarFlags_NoTabListScrollingButtons) && (tab_bar->Flags & ImGuiTabBarFlags_FittingPolicyScroll))
09308         if (ImGuiTabItem* scroll_and_select_tab = TabBarScrollingButtons(tab_bar))
09309         {
09310             scroll_to_tab_id = scroll_and_select_tab->ID;
09311             if ((scroll_and_select_tab->Flags & ImGuiTabItemFlags_Button) == 0)
09312                 tab_bar->SelectedTabId = scroll_to_tab_id;
09313         }
09314 
09315     // Shrink widths if full tabs don't fit in their allocated space
09316     float section_0_w = sections[0].Width + sections[0].Spacing;
09317     float section_1_w = sections[1].Width + sections[1].Spacing;
09318     float section_2_w = sections[2].Width + sections[2].Spacing;
09319     bool central_section_is_visible = (section_0_w + section_2_w) < tab_bar->BarRect.GetWidth();
09320     float width_excess;
09321     if (central_section_is_visible)
09322         width_excess = ImMax(section_1_w - (tab_bar->BarRect.GetWidth() - section_0_w - section_2_w), 0.0f); // Excess used to shrink central section
09323     else
09324         width_excess = (section_0_w + section_2_w) - tab_bar->BarRect.GetWidth(); // Excess used to shrink leading/trailing section
09325 
09326     // With ImGuiTabBarFlags_FittingPolicyScroll policy, we will only shrink leading/trailing if the central section is not visible anymore
09327     if (width_excess >= 1.0f && ((tab_bar->Flags & ImGuiTabBarFlags_FittingPolicyResizeDown) || !central_section_is_visible))
09328     {
09329         int shrink_data_count = (central_section_is_visible ? sections[1].TabCount : sections[0].TabCount + sections[2].TabCount);
09330         int shrink_data_offset = (central_section_is_visible ? sections[0].TabCount + sections[2].TabCount : 0);
09331         ShrinkWidths(g.ShrinkWidthBuffer.Data + shrink_data_offset, shrink_data_count, width_excess);
09332 
09333         // Apply shrunk values into tabs and sections
09334         for (int tab_n = shrink_data_offset; tab_n < shrink_data_offset + shrink_data_count; tab_n++)
09335         {
09336             ImGuiTabItem* tab = &tab_bar->Tabs[g.ShrinkWidthBuffer[tab_n].Index];
09337             float shrinked_width = IM_TRUNC(g.ShrinkWidthBuffer[tab_n].Width);
09338             if (shrinked_width < 0.0f)
09339                 continue;
09340 
09341             shrinked_width = ImMax(1.0f, shrinked_width);
09342             int section_n = TabItemGetSectionIdx(tab);
09343             sections[section_n].Width -= (tab->Width - shrinked_width);
09344             tab->Width = shrinked_width;
09345         }
09346     }
09347 
09348     // Layout all active tabs
09349     int section_tab_index = 0;
09350     float tab_offset = 0.0f;
09351     tab_bar->WidthAllTabs = 0.0f;
09352     for (int section_n = 0; section_n < 3; section_n++)
09353     {
09354         ImGuiTabBarSection* section = &sections[section_n];
09355         if (section_n == 2)
09356             tab_offset = ImMin(ImMax(0.0f, tab_bar->BarRect.GetWidth() - section->Width), tab_offset);
09357 
09358         for (int tab_n = 0; tab_n < section->TabCount; tab_n++)
09359         {
09360             ImGuiTabItem* tab = &tab_bar->Tabs[section_tab_index + tab_n];
09361             tab->Offset = tab_offset;
09362             tab->NameOffset = -1;
09363             tab_offset += tab->Width + (tab_n < section->TabCount - 1 ? g.Style.ItemInnerSpacing.x : 0.0f);
09364         }
09365         tab_bar->WidthAllTabs += ImMax(section->Width + section->Spacing, 0.0f);
09366         tab_offset += section->Spacing;
09367         section_tab_index += section->TabCount;
09368     }
09369 
09370     // Clear name buffers
09371     tab_bar->TabsNames.Buf.resize(0);
09372 
09373     // If we have lost the selected tab, select the next most recently active one
09374     if (found_selected_tab_id == false)
09375         tab_bar->SelectedTabId = 0;
09376     if (tab_bar->SelectedTabId == 0 && tab_bar->NextSelectedTabId == 0 && most_recently_selected_tab != NULL)
09377         scroll_to_tab_id = tab_bar->SelectedTabId = most_recently_selected_tab->ID;
09378 
09379     // Lock in visible tab
09380     tab_bar->VisibleTabId = tab_bar->SelectedTabId;
09381     tab_bar->VisibleTabWasSubmitted = false;
09382 
09383     // CTRL+TAB can override visible tab temporarily
09384     if (g.NavWindowingTarget != NULL && g.NavWindowingTarget->DockNode && g.NavWindowingTarget->DockNode->TabBar == tab_bar)
09385         tab_bar->VisibleTabId = scroll_to_tab_id = g.NavWindowingTarget->TabId;
09386 
09387     // Apply request requests
09388     if (scroll_to_tab_id != 0)
09389         TabBarScrollToTab(tab_bar, scroll_to_tab_id, sections);
09390     else if ((tab_bar->Flags & ImGuiTabBarFlags_FittingPolicyScroll) && IsMouseHoveringRect(tab_bar->BarRect.Min, tab_bar->BarRect.Max, true) && IsWindowContentHoverable(g.CurrentWindow))
09391     {
09392         const float wheel = g.IO.MouseWheelRequestAxisSwap ? g.IO.MouseWheel : g.IO.MouseWheelH;
09393         const ImGuiKey wheel_key = g.IO.MouseWheelRequestAxisSwap ? ImGuiKey_MouseWheelY : ImGuiKey_MouseWheelX;
09394         if (TestKeyOwner(wheel_key, tab_bar->ID) && wheel != 0.0f)
09395         {
09396             const float scroll_step = wheel * TabBarCalcScrollableWidth(tab_bar, sections) / 3.0f;
09397             tab_bar->ScrollingTargetDistToVisibility = 0.0f;
09398             tab_bar->ScrollingTarget = TabBarScrollClamp(tab_bar, tab_bar->ScrollingTarget - scroll_step);
09399         }
09400         SetKeyOwner(wheel_key, tab_bar->ID);
09401     }
09402 
09403     // Update scrolling
09404     tab_bar->ScrollingAnim = TabBarScrollClamp(tab_bar, tab_bar->ScrollingAnim);
09405     tab_bar->ScrollingTarget = TabBarScrollClamp(tab_bar, tab_bar->ScrollingTarget);
09406     if (tab_bar->ScrollingAnim != tab_bar->ScrollingTarget)
09407     {
09408         // Scrolling speed adjust itself so we can always reach our target in 1/3 seconds.
09409         // Teleport if we are aiming far off the visible line
09410         tab_bar->ScrollingSpeed = ImMax(tab_bar->ScrollingSpeed, 70.0f * g.FontSize);
09411         tab_bar->ScrollingSpeed = ImMax(tab_bar->ScrollingSpeed, ImFabs(tab_bar->ScrollingTarget - tab_bar->ScrollingAnim) / 0.3f);
09412         const bool teleport = (tab_bar->PrevFrameVisible + 1 < g.FrameCount) || (tab_bar->ScrollingTargetDistToVisibility > 10.0f * g.FontSize);
09413         tab_bar->ScrollingAnim = teleport ? tab_bar->ScrollingTarget : ImLinearSweep(tab_bar->ScrollingAnim, tab_bar->ScrollingTarget, g.IO.DeltaTime * tab_bar->ScrollingSpeed);
09414     }
09415     else
09416     {
09417         tab_bar->ScrollingSpeed = 0.0f;
09418     }
09419     tab_bar->ScrollingRectMinX = tab_bar->BarRect.Min.x + sections[0].Width + sections[0].Spacing;
09420     tab_bar->ScrollingRectMaxX = tab_bar->BarRect.Max.x - sections[2].Width - sections[1].Spacing;
09421 
09422     // Actual layout in host window (we don't do it in BeginTabBar() so as not to waste an extra frame)
09423     ImGuiWindow* window = g.CurrentWindow;
09424     window->DC.CursorPos = tab_bar->BarRect.Min;
09425     ItemSize(ImVec2(tab_bar->WidthAllTabs, tab_bar->BarRect.GetHeight()), tab_bar->FramePadding.y);
09426     window->DC.IdealMaxPos.x = ImMax(window->DC.IdealMaxPos.x, tab_bar->BarRect.Min.x + tab_bar->WidthAllTabsIdeal);
09427 }
