09429 // Dockable windows uses Name/ID in the global namespace. Non-dockable items use the ID stack.
09430 static ImU32   ImGui::TabBarCalcTabID(ImGuiTabBar* tab_bar, const char* label, ImGuiWindow* docked_window)
09431 {
09432     if (docked_window != NULL)
09433     {
09434         IM_UNUSED(tab_bar);
09435         IM_ASSERT(tab_bar->Flags & ImGuiTabBarFlags_DockNode);
09436         ImGuiID id = docked_window->TabId;
09437         KeepAliveID(id);
09438         return id;
09439     }
09440     else
09441     {
09442         ImGuiWindow* window = GImGui->CurrentWindow;
09443         return window->GetID(label);
09444     }
09445 }
