09501 // The purpose of this call is to register tab in advance so we can control their order at the time they appear.
09502 // Otherwise calling this is unnecessary as tabs are appending as needed by the BeginTabItem() function.
09503 void ImGui::TabBarAddTab(ImGuiTabBar* tab_bar, ImGuiTabItemFlags tab_flags, ImGuiWindow* window)
09504 {
09505     ImGuiContext& g = *GImGui;
09506     IM_ASSERT(TabBarFindTabByID(tab_bar, window->TabId) == NULL);
09507     IM_ASSERT(g.CurrentTabBar != tab_bar);  // Can't work while the tab bar is active as our tab doesn't have an X offset yet, in theory we could/should test something like (tab_bar->CurrFrameVisible < g.FrameCount) but we'd need to solve why triggers the commented early-out assert in BeginTabBarEx() (probably dock node going from implicit to explicit in same frame)
09508 
09509     if (!window->HasCloseButton)
09510         tab_flags |= ImGuiTabItemFlags_NoCloseButton;       // Set _NoCloseButton immediately because it will be used for first-frame width calculation.
09511 
09512     ImGuiTabItem new_tab;
09513     new_tab.ID = window->TabId;
09514     new_tab.Flags = tab_flags;
09515     new_tab.LastFrameVisible = tab_bar->CurrFrameVisible;   // Required so BeginTabBar() doesn't ditch the tab
09516     if (new_tab.LastFrameVisible == -1)
09517         new_tab.LastFrameVisible = g.FrameCount - 1;
09518     new_tab.Window = window;                                // Required so tab bar layout can compute the tab width before tab submission
09519     tab_bar->Tabs.push_back(new_tab);
09520 }
09521 
09522 // The *TabId fields are already set by the docking system _before_ the actual TabItem was created, so we clear them regardless.
09523 void ImGui::TabBarRemoveTab(ImGuiTabBar* tab_bar, ImGuiID tab_id)
09524 {
09525     if (ImGuiTabItem* tab = TabBarFindTabByID(tab_bar, tab_id))
09526         tab_bar->Tabs.erase(tab);
09527     if (tab_bar->VisibleTabId == tab_id)      { tab_bar->VisibleTabId = 0; }
09528     if (tab_bar->SelectedTabId == tab_id)     { tab_bar->SelectedTabId = 0; }
09529     if (tab_bar->NextSelectedTabId == tab_id) { tab_bar->NextSelectedTabId = 0; }
09530 }
09531 
09532 // Called on manual closure attempt
09533 void ImGui::TabBarCloseTab(ImGuiTabBar* tab_bar, ImGuiTabItem* tab)
09534 {
09535     if (tab->Flags & ImGuiTabItemFlags_Button)
09536         return; // A button appended with TabItemButton().
09537 
09538     if ((tab->Flags & (ImGuiTabItemFlags_UnsavedDocument | ImGuiTabItemFlags_NoAssumedClosure)) == 0)
09539     {
09540         // This will remove a frame of lag for selecting another tab on closure.
09541         // However we don't run it in the case where the 'Unsaved' flag is set, so user gets a chance to fully undo the closure
09542         tab->WantClose = true;
09543         if (tab_bar->VisibleTabId == tab->ID)
09544         {
09545             tab->LastFrameVisible = -1;
09546             tab_bar->SelectedTabId = tab_bar->NextSelectedTabId = 0;
09547         }
09548     }
09549     else
09550     {
09551         // Actually select before expecting closure attempt (on an UnsavedDocument tab user is expect to e.g. show a popup)
09552         if (tab_bar->VisibleTabId != tab->ID)
09553             TabBarQueueFocus(tab_bar, tab);
09554     }
09555 }
09556 
09557 static float ImGui::TabBarScrollClamp(ImGuiTabBar* tab_bar, float scrolling)
09558 {
09559     scrolling = ImMin(scrolling, tab_bar->WidthAllTabs - tab_bar->BarRect.GetWidth());
09560     return ImMax(scrolling, 0.0f);
09561 }
09562 
09563 // Note: we may scroll to tab that are not selected! e.g. using keyboard arrow keys
09564 static void ImGui::TabBarScrollToTab(ImGuiTabBar* tab_bar, ImGuiID tab_id, ImGuiTabBarSection* sections)
09565 {
09566     ImGuiTabItem* tab = TabBarFindTabByID(tab_bar, tab_id);
09567     if (tab == NULL)
09568         return;
09569     if (tab->Flags & ImGuiTabItemFlags_SectionMask_)
09570         return;
09571 
09572     ImGuiContext& g = *GImGui;
09573     float margin = g.FontSize * 1.0f; // When to scroll to make Tab N+1 visible always make a bit of N visible to suggest more scrolling area (since we don't have a scrollbar)
09574     int order = TabBarGetTabOrder(tab_bar, tab);
09575 
09576     // Scrolling happens only in the central section (leading/trailing sections are not scrolling)
09577     float scrollable_width = TabBarCalcScrollableWidth(tab_bar, sections);
09578 
09579     // We make all tabs positions all relative Sections[0].Width to make code simpler
09580     float tab_x1 = tab->Offset - sections[0].Width + (order > sections[0].TabCount - 1 ? -margin : 0.0f);
09581     float tab_x2 = tab->Offset - sections[0].Width + tab->Width + (order + 1 < tab_bar->Tabs.Size - sections[2].TabCount ? margin : 1.0f);
09582     tab_bar->ScrollingTargetDistToVisibility = 0.0f;
09583     if (tab_bar->ScrollingTarget > tab_x1 || (tab_x2 - tab_x1 >= scrollable_width))
09584     {
09585         // Scroll to the left
09586         tab_bar->ScrollingTargetDistToVisibility = ImMax(tab_bar->ScrollingAnim - tab_x2, 0.0f);
09587         tab_bar->ScrollingTarget = tab_x1;
09588     }
09589     else if (tab_bar->ScrollingTarget < tab_x2 - scrollable_width)
09590     {
09591         // Scroll to the right
09592         tab_bar->ScrollingTargetDistToVisibility = ImMax((tab_x1 - scrollable_width) - tab_bar->ScrollingAnim, 0.0f);
09593         tab_bar->ScrollingTarget = tab_x2 - scrollable_width;
09594     }
09595 }
09596 
09597 void ImGui::TabBarQueueFocus(ImGuiTabBar* tab_bar, ImGuiTabItem* tab)
09598 {
09599     tab_bar->NextSelectedTabId = tab->ID;
09600 }
