09602 void ImGui::TabBarQueueReorder(ImGuiTabBar* tab_bar, ImGuiTabItem* tab, int offset)
09603 {
09604     IM_ASSERT(offset != 0);
09605     IM_ASSERT(tab_bar->ReorderRequestTabId == 0);
09606     tab_bar->ReorderRequestTabId = tab->ID;
