09608 }
09609 
09610 void ImGui::TabBarQueueReorderFromMousePos(ImGuiTabBar* tab_bar, ImGuiTabItem* src_tab, ImVec2 mouse_pos)
09611 {
09612     ImGuiContext& g = *GImGui;
09613     IM_ASSERT(tab_bar->ReorderRequestTabId == 0);
09614     if ((tab_bar->Flags & ImGuiTabBarFlags_Reorderable) == 0)
09615         return;
09616 
09617     const bool is_central_section = (src_tab->Flags & ImGuiTabItemFlags_SectionMask_) == 0;
09618     const float bar_offset = tab_bar->BarRect.Min.x - (is_central_section ? tab_bar->ScrollingTarget : 0);
09619 
09620     // Count number of contiguous tabs we are crossing over
09621     const int dir = (bar_offset + src_tab->Offset) > mouse_pos.x ? -1 : +1;
09622     const int src_idx = tab_bar->Tabs.index_from_ptr(src_tab);
09623     int dst_idx = src_idx;
09624     for (int i = src_idx; i >= 0 && i < tab_bar->Tabs.Size; i += dir)
09625     {
09626         // Reordered tabs must share the same section
09627         const ImGuiTabItem* dst_tab = &tab_bar->Tabs[i];
09628         if (dst_tab->Flags & ImGuiTabItemFlags_NoReorder)
09629             break;
09630         if ((dst_tab->Flags & ImGuiTabItemFlags_SectionMask_) != (src_tab->Flags & ImGuiTabItemFlags_SectionMask_))
09631             break;
09632         dst_idx = i;
09633 
09634         // Include spacing after tab, so when mouse cursor is between tabs we would not continue checking further tabs that are not hovered.
09635         const float x1 = bar_offset + dst_tab->Offset - g.Style.ItemInnerSpacing.x;
09636         const float x2 = bar_offset + dst_tab->Offset + dst_tab->Width + g.Style.ItemInnerSpacing.x;
09637         //GetForegroundDrawList()->AddRect(ImVec2(x1, tab_bar->BarRect.Min.y), ImVec2(x2, tab_bar->BarRect.Max.y), IM_COL32(255, 0, 0, 255));
09638         if ((dir < 0 && mouse_pos.x > x1) || (dir > 0 && mouse_pos.x < x2))
09639             break;
09640     }
09641 
09642     if (dst_idx != src_idx)
09643         TabBarQueueReorder(tab_bar, src_tab, dst_idx - src_idx);
09644 }
09645 
09646 bool ImGui::TabBarProcessReorder(ImGuiTabBar* tab_bar)
09647 {
09648     ImGuiTabItem* tab1 = TabBarFindTabByID(tab_bar, tab_bar->ReorderRequestTabId);
09649     if (tab1 == NULL || (tab1->Flags & ImGuiTabItemFlags_NoReorder))
09650         return false;
09651 
09652     //IM_ASSERT(tab_bar->Flags & ImGuiTabBarFlags_Reorderable); // <- this may happen when using debug tools
09653     int tab2_order = TabBarGetTabOrder(tab_bar, tab1) + tab_bar->ReorderRequestOffset;
09654     if (tab2_order < 0 || tab2_order >= tab_bar->Tabs.Size)
09655         return false;
09656 
09657     // Reordered tabs must share the same section
09658     // (Note: TabBarQueueReorderFromMousePos() also has a similar test but since we allow direct calls to TabBarQueueReorder() we do it here too)
09659     ImGuiTabItem* tab2 = &tab_bar->Tabs[tab2_order];
09660     if (tab2->Flags & ImGuiTabItemFlags_NoReorder)
09661         return false;
09662     if ((tab1->Flags & ImGuiTabItemFlags_SectionMask_) != (tab2->Flags & ImGuiTabItemFlags_SectionMask_))
09663         return false;
09664 
09665     ImGuiTabItem item_tmp = *tab1;
09666     ImGuiTabItem* src_tab = (tab_bar->ReorderRequestOffset > 0) ? tab1 + 1 : tab2;
09667     ImGuiTabItem* dst_tab = (tab_bar->ReorderRequestOffset > 0) ? tab1 : tab2 + 1;
09668     const int move_count = (tab_bar->ReorderRequestOffset > 0) ? tab_bar->ReorderRequestOffset : -tab_bar->ReorderRequestOffset;
09669     memmove(dst_tab, src_tab, move_count * sizeof(ImGuiTabItem));
09670     *tab2 = item_tmp;
09671 
09672     if (tab_bar->Flags & ImGuiTabBarFlags_SaveSettings)
09673         MarkIniSettingsDirty();
09674     return true;
09675 }
09676 
09677 static ImGuiTabItem* ImGui::TabBarScrollingButtons(ImGuiTabBar* tab_bar)
09678 {
09679     ImGuiContext& g = *GImGui;
09680     ImGuiWindow* window = g.CurrentWindow;
09681 
09682     const ImVec2 arrow_button_size(g.FontSize - 2.0f, g.FontSize + g.Style.FramePadding.y * 2.0f);
09683     const float scrolling_buttons_width = arrow_button_size.x * 2.0f;
09684 
09685     const ImVec2 backup_cursor_pos = window->DC.CursorPos;
09686     //window->DrawList->AddRect(ImVec2(tab_bar->BarRect.Max.x - scrolling_buttons_width, tab_bar->BarRect.Min.y), ImVec2(tab_bar->BarRect.Max.x, tab_bar->BarRect.Max.y), IM_COL32(255,0,0,255));
09687 
09688     int select_dir = 0;
09689     ImVec4 arrow_col = g.Style.Colors[ImGuiCol_Text];
09690     arrow_col.w *= 0.5f;
09691 
09692     PushStyleColor(ImGuiCol_Text, arrow_col);
09693     PushStyleColor(ImGuiCol_Button, ImVec4(0, 0, 0, 0));
09694     const float backup_repeat_delay = g.IO.KeyRepeatDelay;
09695     const float backup_repeat_rate = g.IO.KeyRepeatRate;
09696     g.IO.KeyRepeatDelay = 0.250f;
09697     g.IO.KeyRepeatRate = 0.200f;
09698     float x = ImMax(tab_bar->BarRect.Min.x, tab_bar->BarRect.Max.x - scrolling_buttons_width);
09699     window->DC.CursorPos = ImVec2(x, tab_bar->BarRect.Min.y);
09700     if (ArrowButtonEx("##<", ImGuiDir_Left, arrow_button_size, ImGuiButtonFlags_PressedOnClick | ImGuiButtonFlags_Repeat))
09701         select_dir = -1;
09702     window->DC.CursorPos = ImVec2(x + arrow_button_size.x, tab_bar->BarRect.Min.y);
09703     if (ArrowButtonEx("##>", ImGuiDir_Right, arrow_button_size, ImGuiButtonFlags_PressedOnClick | ImGuiButtonFlags_Repeat))
09704         select_dir = +1;
09705     PopStyleColor(2);
09706     g.IO.KeyRepeatRate = backup_repeat_rate;
09707     g.IO.KeyRepeatDelay = backup_repeat_delay;
09708 
09709     ImGuiTabItem* tab_to_scroll_to = NULL;
09710     if (select_dir != 0)
09711         if (ImGuiTabItem* tab_item = TabBarFindTabByID(tab_bar, tab_bar->SelectedTabId))
09712         {
09713             int selected_order = TabBarGetTabOrder(tab_bar, tab_item);
09714             int target_order = selected_order + select_dir;
09715 
09716             // Skip tab item buttons until another tab item is found or end is reached
09717             while (tab_to_scroll_to == NULL)
09718             {
09719                 // If we are at the end of the list, still scroll to make our tab visible
09720                 tab_to_scroll_to = &tab_bar->Tabs[(target_order >= 0 && target_order < tab_bar->Tabs.Size) ? target_order : selected_order];
09721 
09722                 // Cross through buttons
09723                 // (even if first/last item is a button, return it so we can update the scroll)
09724                 if (tab_to_scroll_to->Flags & ImGuiTabItemFlags_Button)
09725                 {
09726                     target_order += select_dir;
09727                     selected_order += select_dir;
09728                     tab_to_scroll_to = (target_order < 0 || target_order >= tab_bar->Tabs.Size) ? tab_to_scroll_to : NULL;
09729                 }
09730             }
09731         }
09732     window->DC.CursorPos = backup_cursor_pos;
09733     tab_bar->BarRect.Max.x -= scrolling_buttons_width + 1.0f;
09734 
09735     return tab_to_scroll_to;
09736 }
09737 
09738 static ImGuiTabItem* ImGui::TabBarTabListPopupButton(ImGuiTabBar* tab_bar)
09739 {
09740     ImGuiContext& g = *GImGui;
09741     ImGuiWindow* window = g.CurrentWindow;
09742 
09743     // We use g.Style.FramePadding.y to match the square ArrowButton size
09744     const float tab_list_popup_button_width = g.FontSize + g.Style.FramePadding.y;
09745     const ImVec2 backup_cursor_pos = window->DC.CursorPos;
09746     window->DC.CursorPos = ImVec2(tab_bar->BarRect.Min.x - g.Style.FramePadding.y, tab_bar->BarRect.Min.y);
09747     tab_bar->BarRect.Min.x += tab_list_popup_button_width;
09748 
09749     ImVec4 arrow_col = g.Style.Colors[ImGuiCol_Text];
09750     arrow_col.w *= 0.5f;
09751     PushStyleColor(ImGuiCol_Text, arrow_col);
09752     PushStyleColor(ImGuiCol_Button, ImVec4(0, 0, 0, 0));
09753     bool open = BeginCombo("##v", NULL, ImGuiComboFlags_NoPreview | ImGuiComboFlags_HeightLargest);
09754     PopStyleColor(2);
09755 
09756     ImGuiTabItem* tab_to_select = NULL;
09757     if (open)
09758     {
09759         for (int tab_n = 0; tab_n < tab_bar->Tabs.Size; tab_n++)
09760         {
09761             ImGuiTabItem* tab = &tab_bar->Tabs[tab_n];
09762             if (tab->Flags & ImGuiTabItemFlags_Button)
09763                 continue;
09764 
09765             const char* tab_name = TabBarGetTabName(tab_bar, tab);
09766             if (Selectable(tab_name, tab_bar->SelectedTabId == tab->ID))
09767                 tab_to_select = tab;
09768         }
09769         EndCombo();
09770     }
09771 
09772     window->DC.CursorPos = backup_cursor_pos;
09773     return tab_to_select;
09774 }
