09789 bool    ImGui::BeginTabItem(const char* label, bool* p_open, ImGuiTabItemFlags flags)
09790 {
09791     ImGuiContext& g = *GImGui;
09792     ImGuiWindow* window = g.CurrentWindow;
09793     if (window->SkipItems)
09794         return false;
09795 
09796     ImGuiTabBar* tab_bar = g.CurrentTabBar;
09797     if (tab_bar == NULL)
09798     {
09799         IM_ASSERT_USER_ERROR(tab_bar, "Needs to be called between BeginTabBar() and EndTabBar()!");
09800         return false;
09801     }
09802     IM_ASSERT((flags & ImGuiTabItemFlags_Button) == 0);             // BeginTabItem() Can't be used with button flags, use TabItemButton() instead!
09803 
09804     bool ret = TabItemEx(tab_bar, label, p_open, flags, NULL);
09805     if (ret && !(flags & ImGuiTabItemFlags_NoPushId))
09806     {
09807         ImGuiTabItem* tab = &tab_bar->Tabs[tab_bar->LastTabItemIdx];
09808         PushOverrideID(tab->ID); // We already hashed 'label' so push into the ID stack directly instead of doing another hash through PushID(label)
09809     }
09810     return ret;
09811 }
09812 
09813 void    ImGui::EndTabItem()
09814 {
09815     ImGuiContext& g = *GImGui;
09816     ImGuiWindow* window = g.CurrentWindow;
09817     if (window->SkipItems)
09818         return;
09819 
09820     ImGuiTabBar* tab_bar = g.CurrentTabBar;
09821     if (tab_bar == NULL)
09822     {
09823         IM_ASSERT_USER_ERROR(tab_bar != NULL, "Needs to be called between BeginTabBar() and EndTabBar()!");
09824         return;
09825     }
09826     IM_ASSERT(tab_bar->LastTabItemIdx >= 0);
09827     ImGuiTabItem* tab = &tab_bar->Tabs[tab_bar->LastTabItemIdx];
09828     if (!(tab->Flags & ImGuiTabItemFlags_NoPushId))
09829         PopID();
09830 }
