09847 
09848 bool    ImGui::TabItemEx(ImGuiTabBar* tab_bar, const char* label, bool* p_open, ImGuiTabItemFlags flags, ImGuiWindow* docked_window)
09849 {
09850     // Layout whole tab bar if not already done
09851     ImGuiContext& g = *GImGui;
09852     if (tab_bar->WantLayout)
09853     {
09854         ImGuiNextItemData backup_next_item_data = g.NextItemData;
09855         TabBarLayout(tab_bar);
09856         g.NextItemData = backup_next_item_data;
09857     }
09858     ImGuiWindow* window = g.CurrentWindow;
09859     if (window->SkipItems)
09860         return false;
09861 
09862     const ImGuiStyle& style = g.Style;
09863     const ImGuiID id = TabBarCalcTabID(tab_bar, label, docked_window);
09864 
09865     // If the user called us with *p_open == false, we early out and don't render.
09866     // We make a call to ItemAdd() so that attempts to use a contextual popup menu with an implicit ID won't use an older ID.
09867     IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags);
09868     if (p_open && !*p_open)
09869     {
09870         ItemAdd(ImRect(), id, NULL, ImGuiItemFlags_NoNav);
09871         return false;
09872     }
09873 
09874     IM_ASSERT(!p_open || !(flags & ImGuiTabItemFlags_Button));
09875     IM_ASSERT((flags & (ImGuiTabItemFlags_Leading | ImGuiTabItemFlags_Trailing)) != (ImGuiTabItemFlags_Leading | ImGuiTabItemFlags_Trailing)); // Can't use both Leading and Trailing
09876 
09877     // Store into ImGuiTabItemFlags_NoCloseButton, also honor ImGuiTabItemFlags_NoCloseButton passed by user (although not documented)
09878     if (flags & ImGuiTabItemFlags_NoCloseButton)
09879         p_open = NULL;
09880     else if (p_open == NULL)
09881         flags |= ImGuiTabItemFlags_NoCloseButton;
09882 
09883     // Acquire tab data
09884     ImGuiTabItem* tab = TabBarFindTabByID(tab_bar, id);
09885     bool tab_is_new = false;
09886     if (tab == NULL)
09887     {
09888         tab_bar->Tabs.push_back(ImGuiTabItem());
09889         tab = &tab_bar->Tabs.back();
09890         tab->ID = id;
09891         tab_bar->TabsAddedNew = tab_is_new = true;
09892     }
09893     tab_bar->LastTabItemIdx = (ImS16)tab_bar->Tabs.index_from_ptr(tab);
09894 
09895     // Calculate tab contents size
09896     ImVec2 size = TabItemCalcSize(label, (p_open != NULL) || (flags & ImGuiTabItemFlags_UnsavedDocument));
09897     tab->RequestedWidth = -1.0f;
09898     if (g.NextItemData.Flags & ImGuiNextItemDataFlags_HasWidth)
09899         size.x = tab->RequestedWidth = g.NextItemData.Width;
09900     if (tab_is_new)
09901         tab->Width = ImMax(1.0f, size.x);
09902     tab->ContentWidth = size.x;
09903     tab->BeginOrder = tab_bar->TabsActiveCount++;
09904 
09905     const bool tab_bar_appearing = (tab_bar->PrevFrameVisible + 1 < g.FrameCount);
09906     const bool tab_bar_focused = (tab_bar->Flags & ImGuiTabBarFlags_IsFocused) != 0;
09907     const bool tab_appearing = (tab->LastFrameVisible + 1 < g.FrameCount);
09908     const bool tab_just_unsaved = (flags & ImGuiTabItemFlags_UnsavedDocument) && !(tab->Flags & ImGuiTabItemFlags_UnsavedDocument);
09909     const bool is_tab_button = (flags & ImGuiTabItemFlags_Button) != 0;
09910     tab->LastFrameVisible = g.FrameCount;
09911     tab->Flags = flags;
09912     tab->Window = docked_window;
09913 
09914     // Append name _WITH_ the zero-terminator
09915     // (regular tabs are permitted in a DockNode tab bar, but window tabs not permitted in a non-DockNode tab bar)
09916     if (docked_window != NULL)
09917     {
09918         IM_ASSERT(tab_bar->Flags & ImGuiTabBarFlags_DockNode);
09919         tab->NameOffset = -1;
09920     }
09921     else
09922     {
09923         tab->NameOffset = (ImS32)tab_bar->TabsNames.size();
09924         tab_bar->TabsNames.append(label, label + strlen(label) + 1);
09925     }
09926 
09927     // Update selected tab
09928     if (!is_tab_button)
09929     {
09930         if (tab_appearing && (tab_bar->Flags & ImGuiTabBarFlags_AutoSelectNewTabs) && tab_bar->NextSelectedTabId == 0)
09931             if (!tab_bar_appearing || tab_bar->SelectedTabId == 0)
09932                 TabBarQueueFocus(tab_bar, tab); // New tabs gets activated
09933         if ((flags & ImGuiTabItemFlags_SetSelected) && (tab_bar->SelectedTabId != id)) // _SetSelected can only be passed on explicit tab bar
09934             TabBarQueueFocus(tab_bar, tab);
09935     }
09936 
09937     // Lock visibility
09938     // (Note: tab_contents_visible != tab_selected... because CTRL+TAB operations may preview some tabs without selecting them!)
09939     bool tab_contents_visible = (tab_bar->VisibleTabId == id);
09940     if (tab_contents_visible)
09941         tab_bar->VisibleTabWasSubmitted = true;
09942 
09943     // On the very first frame of a tab bar we let first tab contents be visible to minimize appearing glitches
09944     if (!tab_contents_visible && tab_bar->SelectedTabId == 0 && tab_bar_appearing && docked_window == NULL)
09945         if (tab_bar->Tabs.Size == 1 && !(tab_bar->Flags & ImGuiTabBarFlags_AutoSelectNewTabs))
09946             tab_contents_visible = true;
09947 
09948     // Note that tab_is_new is not necessarily the same as tab_appearing! When a tab bar stops being submitted
09949     // and then gets submitted again, the tabs will have 'tab_appearing=true' but 'tab_is_new=false'.
09950     if (tab_appearing && (!tab_bar_appearing || tab_is_new))
09951     {
09952         ItemAdd(ImRect(), id, NULL, ImGuiItemFlags_NoNav);
09953         if (is_tab_button)
09954             return false;
09955         return tab_contents_visible;
09956     }
09957 
09958     if (tab_bar->SelectedTabId == id)
09959         tab->LastFrameSelected = g.FrameCount;
09960 
09961     // Backup current layout position
09962     const ImVec2 backup_main_cursor_pos = window->DC.CursorPos;
09963 
09964     // Layout
09965     const bool is_central_section = (tab->Flags & ImGuiTabItemFlags_SectionMask_) == 0;
09966     size.x = tab->Width;
09967     if (is_central_section)
09968         window->DC.CursorPos = tab_bar->BarRect.Min + ImVec2(IM_TRUNC(tab->Offset - tab_bar->ScrollingAnim), 0.0f);
09969     else
09970         window->DC.CursorPos = tab_bar->BarRect.Min + ImVec2(tab->Offset, 0.0f);
09971     ImVec2 pos = window->DC.CursorPos;
09972     ImRect bb(pos, pos + size);
09973 
09974     // We don't have CPU clipping primitives to clip the CloseButton (until it becomes a texture), so need to add an extra draw call (temporary in the case of vertical animation)
09975     const bool want_clip_rect = is_central_section && (bb.Min.x < tab_bar->ScrollingRectMinX || bb.Max.x > tab_bar->ScrollingRectMaxX);
09976     if (want_clip_rect)
09977         PushClipRect(ImVec2(ImMax(bb.Min.x, tab_bar->ScrollingRectMinX), bb.Min.y - 1), ImVec2(tab_bar->ScrollingRectMaxX, bb.Max.y), true);
09978 
09979     ImVec2 backup_cursor_max_pos = window->DC.CursorMaxPos;
09980     ItemSize(bb.GetSize(), style.FramePadding.y);
09981     window->DC.CursorMaxPos = backup_cursor_max_pos;
09982 
09983     if (!ItemAdd(bb, id))
09984     {
09985         if (want_clip_rect)
09986             PopClipRect();
09987         window->DC.CursorPos = backup_main_cursor_pos;
09988         return tab_contents_visible;
09989     }
09990 
09991     // Click to Select a tab
09992     ImGuiButtonFlags button_flags = ((is_tab_button ? ImGuiButtonFlags_PressedOnClickRelease : ImGuiButtonFlags_PressedOnClick) | ImGuiButtonFlags_AllowOverlap);
09993     if (g.DragDropActive && !g.DragDropPayload.IsDataType(IMGUI_PAYLOAD_TYPE_WINDOW)) // FIXME: May be an opt-in property of the payload to disable this
09994         button_flags |= ImGuiButtonFlags_PressedOnDragDropHold;
09995     bool hovered, held;
09996     bool pressed = ButtonBehavior(bb, id, &hovered, &held, button_flags);
09997     if (pressed && !is_tab_button)
09998         TabBarQueueFocus(tab_bar, tab);
09999 
10000     // Transfer active id window so the active id is not owned by the dock host (as StartMouseMovingWindow()
10001     // will only do it on the drag). This allows FocusWindow() to be more conservative in how it clears active id.
10002     if (held && docked_window && g.ActiveId == id && g.ActiveIdIsJustActivated)
10003         g.ActiveIdWindow = docked_window;
10004 
10005     // Drag and drop a single floating window node moves it
10006     ImGuiDockNode* node = docked_window ? docked_window->DockNode : NULL;
10007     const bool single_floating_window_node = node && node->IsFloatingNode() && (node->Windows.Size == 1);
10008     if (held && single_floating_window_node && IsMouseDragging(0, 0.0f))
10009     {
10010         // Move
10011         StartMouseMovingWindow(docked_window);
10012     }
10013     else if (held && !tab_appearing && IsMouseDragging(0))
10014     {
10015         // Drag and drop: re-order tabs
10016         int drag_dir = 0;
10017         float drag_distance_from_edge_x = 0.0f;
10018         if (!g.DragDropActive && ((tab_bar->Flags & ImGuiTabBarFlags_Reorderable) || (docked_window != NULL)))
10019         {
10020             // While moving a tab it will jump on the other side of the mouse, so we also test for MouseDelta.x
10021             if (g.IO.MouseDelta.x < 0.0f && g.IO.MousePos.x < bb.Min.x)
10022             {
10023                 drag_dir = -1;
10024                 drag_distance_from_edge_x = bb.Min.x - g.IO.MousePos.x;
10025                 TabBarQueueReorderFromMousePos(tab_bar, tab, g.IO.MousePos);
10026             }
10027             else if (g.IO.MouseDelta.x > 0.0f && g.IO.MousePos.x > bb.Max.x)
10028             {
10029                 drag_dir = +1;
10030                 drag_distance_from_edge_x = g.IO.MousePos.x - bb.Max.x;
10031                 TabBarQueueReorderFromMousePos(tab_bar, tab, g.IO.MousePos);
10032             }
10033         }
10034 
10035         // Extract a Dockable window out of it's tab bar
10036         const bool can_undock = docked_window != NULL && !(docked_window->Flags & ImGuiWindowFlags_NoMove) && !(node->MergedFlags & ImGuiDockNodeFlags_NoUndocking);
10037         if (can_undock)
10038         {
10039             // We use a variable threshold to distinguish dragging tabs within a tab bar and extracting them out of the tab bar
10040             bool undocking_tab = (g.DragDropActive && g.DragDropPayload.SourceId == id);
10041             if (!undocking_tab) //&& (!g.IO.ConfigDockingWithShift || g.IO.KeyShift)
10042             {
10043                 float threshold_base = g.FontSize;
10044                 float threshold_x = (threshold_base * 2.2f);
10045                 float threshold_y = (threshold_base * 1.5f) + ImClamp((ImFabs(g.IO.MouseDragMaxDistanceAbs[0].x) - threshold_base * 2.0f) * 0.20f, 0.0f, threshold_base * 4.0f);
10046                 //GetForegroundDrawList()->AddRect(ImVec2(bb.Min.x - threshold_x, bb.Min.y - threshold_y), ImVec2(bb.Max.x + threshold_x, bb.Max.y + threshold_y), IM_COL32_WHITE); // [DEBUG]
10047 
10048                 float distance_from_edge_y = ImMax(bb.Min.y - g.IO.MousePos.y, g.IO.MousePos.y - bb.Max.y);
10049                 if (distance_from_edge_y >= threshold_y)
10050                     undocking_tab = true;
10051                 if (drag_distance_from_edge_x > threshold_x)
10052                     if ((drag_dir < 0 && TabBarGetTabOrder(tab_bar, tab) == 0) || (drag_dir > 0 && TabBarGetTabOrder(tab_bar, tab) == tab_bar->Tabs.Size - 1))
10053                         undocking_tab = true;
10054             }
10055 
10056             if (undocking_tab)
10057             {
10058                 // Undock
10059                 // FIXME: refactor to share more code with e.g. StartMouseMovingWindow
10060                 DockContextQueueUndockWindow(&g, docked_window);
10061                 g.MovingWindow = docked_window;
10062                 SetActiveID(g.MovingWindow->MoveId, g.MovingWindow);
10063                 g.ActiveIdClickOffset -= g.MovingWindow->Pos - bb.Min;
10064                 g.ActiveIdNoClearOnFocusLoss = true;
10065                 SetActiveIdUsingAllKeyboardKeys();
10066             }
10067         }
10068     }
10069 
10070 #if 0
10071     if (hovered && g.HoveredIdNotActiveTimer > TOOLTIP_DELAY && bb.GetWidth() < tab->ContentWidth)
10072     {
10073         // Enlarge tab display when hovering
10074         bb.Max.x = bb.Min.x + IM_TRUNC(ImLerp(bb.GetWidth(), tab->ContentWidth, ImSaturate((g.HoveredIdNotActiveTimer - 0.40f) * 6.0f)));
10075         display_draw_list = GetForegroundDrawList(window);
10076         TabItemBackground(display_draw_list, bb, flags, GetColorU32(ImGuiCol_TitleBgActive));
10077     }
10078 #endif
10079 
10080     // Render tab shape
10081     ImDrawList* display_draw_list = window->DrawList;
10082     const ImU32 tab_col = GetColorU32((held || hovered) ? ImGuiCol_TabHovered : tab_contents_visible ? (tab_bar_focused ? ImGuiCol_TabSelected : ImGuiCol_TabDimmedSelected) : (tab_bar_focused ? ImGuiCol_Tab : ImGuiCol_TabDimmed));
10083     TabItemBackground(display_draw_list, bb, flags, tab_col);
10084     if (tab_contents_visible && (tab_bar->Flags & ImGuiTabBarFlags_DrawSelectedOverline) && style.TabBarOverlineSize > 0.0f)
10085     {
10086         float x_offset = IM_TRUNC(0.4f * style.TabRounding);
10087         if (x_offset < 2.0f * g.CurrentDpiScale)
10088             x_offset = 0.0f;
10089         float y_offset = 1.0f * g.CurrentDpiScale;
10090         display_draw_list->AddLine(bb.GetTL() + ImVec2(x_offset, y_offset), bb.GetTR() + ImVec2(-x_offset, y_offset), GetColorU32(tab_bar_focused ? ImGuiCol_TabSelectedOverline : ImGuiCol_TabDimmedSelectedOverline), style.TabBarOverlineSize);
10091     }
10092     RenderNavHighlight(bb, id);
10093 
10094     // Select with right mouse button. This is so the common idiom for context menu automatically highlight the current widget.
10095     const bool hovered_unblocked = IsItemHovered(ImGuiHoveredFlags_AllowWhenBlockedByPopup);
10096     if (hovered_unblocked && (IsMouseClicked(1) || IsMouseReleased(1)) && !is_tab_button)
10097         TabBarQueueFocus(tab_bar, tab);
10098 
10099     if (tab_bar->Flags & ImGuiTabBarFlags_NoCloseWithMiddleMouseButton)
10100         flags |= ImGuiTabItemFlags_NoCloseWithMiddleMouseButton;
10101 
10102     // Render tab label, process close button
10103     const ImGuiID close_button_id = p_open ? GetIDWithSeed("#CLOSE", NULL, docked_window ? docked_window->ID : id) : 0;
10104     bool just_closed;
10105     bool text_clipped;
10106     TabItemLabelAndCloseButton(display_draw_list, bb, tab_just_unsaved ? (flags & ~ImGuiTabItemFlags_UnsavedDocument) : flags, tab_bar->FramePadding, label, id, close_button_id, tab_contents_visible, &just_closed, &text_clipped);
10107     if (just_closed && p_open != NULL)
10108     {
10109         *p_open = false;
10110         TabBarCloseTab(tab_bar, tab);
10111     }
10112 
10113     // Forward Hovered state so IsItemHovered() after Begin() can work (even though we are technically hovering our parent)
10114     // That state is copied to window->DockTabItemStatusFlags by our caller.
10115     if (docked_window && (hovered || g.HoveredId == close_button_id))
10116         g.LastItemData.StatusFlags |= ImGuiItemStatusFlags_HoveredWindow;
10117 
10118     // Restore main window position so user can draw there
10119     if (want_clip_rect)
10120         PopClipRect();
10121     window->DC.CursorPos = backup_main_cursor_pos;
10122 
10123     // Tooltip
10124     // (Won't work over the close button because ItemOverlap systems messes up with HoveredIdTimer-> seems ok)
10125     // (We test IsItemHovered() to discard e.g. when another item is active or drag and drop over the tab bar, which g.HoveredId ignores)
10126     // FIXME: This is a mess.
10127     // FIXME: We may want disabled tab to still display the tooltip?
10128     if (text_clipped && g.HoveredId == id && !held)
10129         if (!(tab_bar->Flags & ImGuiTabBarFlags_NoTooltip) && !(tab->Flags & ImGuiTabItemFlags_NoTooltip))
10130             SetItemTooltip("%.*s", (int)(FindRenderedTextEnd(label) - label), label);
10131 
10132     IM_ASSERT(!is_tab_button || !(tab_bar->SelectedTabId == tab->ID && is_tab_button)); // TabItemButton should not be selected
10133     if (is_tab_button)
10134         return pressed;
10135     return tab_contents_visible;
10136 }
