10138 // [Public] This is call is 100% optional but it allows to remove some one-frame glitches when a tab has been unexpectedly removed.
10139 // To use it to need to call the function SetTabItemClosed() between BeginTabBar() and EndTabBar().
10140 // Tabs closed by the close button will automatically be flagged to avoid this issue.
10141 void    ImGui::SetTabItemClosed(const char* label)
10142 {
10143     ImGuiContext& g = *GImGui;
10144     bool is_within_manual_tab_bar = g.CurrentTabBar && !(g.CurrentTabBar->Flags & ImGuiTabBarFlags_DockNode);
10145     if (is_within_manual_tab_bar)
10146     {
10147         ImGuiTabBar* tab_bar = g.CurrentTabBar;
10148         ImGuiID tab_id = TabBarCalcTabID(tab_bar, label, NULL);
10149         if (ImGuiTabItem* tab = TabBarFindTabByID(tab_bar, tab_id))
10150             tab->WantClose = true; // Will be processed by next call to TabBarLayout()
10151     }
10152     else if (ImGuiWindow* window = FindWindowByName(label))
10153     {
10154         if (window->DockIsActive)
10155             if (ImGuiDockNode* node = window->DockNode)
10156             {
10157                 ImGuiID tab_id = TabBarCalcTabID(node->TabBar, label, window);
10158                 TabBarRemoveTab(node->TabBar, tab_id);
10159                 window->DockTabWantClose = true;
10160             }
10161     }
10162 }
