10164 ImVec2 ImGui::TabItemCalcSize(const char* label, bool has_close_button_or_unsaved_marker)
10165 {
10166     ImGuiContext& g = *GImGui;
10167     ImVec2 label_size = CalcTextSize(label, NULL, true);
10168     ImVec2 size = ImVec2(label_size.x + g.Style.FramePadding.x, label_size.y + g.Style.FramePadding.y * 2.0f);
10169     if (has_close_button_or_unsaved_marker)
10170         size.x += g.Style.FramePadding.x + (g.Style.ItemInnerSpacing.x + g.FontSize); // We use Y intentionally to fit the close button circle.
10171     else
10172         size.x += g.Style.FramePadding.x + 1.0f;
10173     return ImVec2(ImMin(size.x, TabBarCalcMaxTabWidth()), size.y);
10174 }
10175 
10176 ImVec2 ImGui::TabItemCalcSize(ImGuiWindow* window)
10177 {
10178     return TabItemCalcSize(window->Name, window->HasCloseButton || (window->Flags & ImGuiWindowFlags_UnsavedDocument));
10179 }
