10181 void ImGui::TabItemBackground(ImDrawList* draw_list, const ImRect& bb, ImGuiTabItemFlags flags, ImU32 col)
10182 {
10183     // While rendering tabs, we trim 1 pixel off the top of our bounding box so they can fit within a regular frame height while looking "detached" from it.
10184     ImGuiContext& g = *GImGui;
10185     const float width = bb.GetWidth();
10186     IM_UNUSED(flags);
10187     IM_ASSERT(width > 0.0f);
10188     const float rounding = ImMax(0.0f, ImMin((flags & ImGuiTabItemFlags_Button) ? g.Style.FrameRounding : g.Style.TabRounding, width * 0.5f - 1.0f));
10189     const float y1 = bb.Min.y + 1.0f;
10190     const float y2 = bb.Max.y - g.Style.TabBarBorderSize;
10191     draw_list->PathLineTo(ImVec2(bb.Min.x, y2));
10192     draw_list->PathArcToFast(ImVec2(bb.Min.x + rounding, y1 + rounding), rounding, 6, 9);
10193     draw_list->PathArcToFast(ImVec2(bb.Max.x - rounding, y1 + rounding), rounding, 9, 12);
10194     draw_list->PathLineTo(ImVec2(bb.Max.x, y2));
10195     draw_list->PathFillConvex(col);
10196     if (g.Style.TabBorderSize > 0.0f)
10197     {
10198         draw_list->PathLineTo(ImVec2(bb.Min.x + 0.5f, y2));
10199         draw_list->PathArcToFast(ImVec2(bb.Min.x + rounding + 0.5f, y1 + rounding + 0.5f), rounding, 6, 9);
10200         draw_list->PathArcToFast(ImVec2(bb.Max.x - rounding - 0.5f, y1 + rounding + 0.5f), rounding, 9, 12);
10201         draw_list->PathLineTo(ImVec2(bb.Max.x - 0.5f, y2));
10202         draw_list->PathStroke(GetColorU32(ImGuiCol_Border), 0, g.Style.TabBorderSize);
10203     }
10204 }
