10206 // Render text label (with custom clipping) + Unsaved Document marker + Close Button logic
10207 // We tend to lock style.FramePadding for a given tab-bar, hence the 'frame_padding' parameter.
10208 void ImGui::TabItemLabelAndCloseButton(ImDrawList* draw_list, const ImRect& bb, ImGuiTabItemFlags flags, ImVec2 frame_padding, const char* label, ImGuiID tab_id, ImGuiID close_button_id, bool is_contents_visible, bool* out_just_closed, bool* out_text_clipped)
10209 {
10210     ImGuiContext& g = *GImGui;
10211     ImVec2 label_size = CalcTextSize(label, NULL, true);
10212 
10213     if (out_just_closed)
10214         *out_just_closed = false;
10215     if (out_text_clipped)
10216         *out_text_clipped = false;
10217 
10218     if (bb.GetWidth() <= 1.0f)
10219         return;
10220 
10221     // In Style V2 we'll have full override of all colors per state (e.g. focused, selected)
10222     // But right now if you want to alter text color of tabs this is what you need to do.
10223 #if 0
10224     const float backup_alpha = g.Style.Alpha;
10225     if (!is_contents_visible)
10226         g.Style.Alpha *= 0.7f;
10227 #endif
10228 
10229     // Render text label (with clipping + alpha gradient) + unsaved marker
10230     ImRect text_pixel_clip_bb(bb.Min.x + frame_padding.x, bb.Min.y + frame_padding.y, bb.Max.x - frame_padding.x, bb.Max.y);
10231     ImRect text_ellipsis_clip_bb = text_pixel_clip_bb;
10232 
10233     // Return clipped state ignoring the close button
10234     if (out_text_clipped)
10235     {
10236         *out_text_clipped = (text_ellipsis_clip_bb.Min.x + label_size.x) > text_pixel_clip_bb.Max.x;
10237         //draw_list->AddCircle(text_ellipsis_clip_bb.Min, 3.0f, *out_text_clipped ? IM_COL32(255, 0, 0, 255) : IM_COL32(0, 255, 0, 255));
10238     }
10239 
10240     const float button_sz = g.FontSize;
10241     const ImVec2 button_pos(ImMax(bb.Min.x, bb.Max.x - frame_padding.x - button_sz), bb.Min.y + frame_padding.y);
10242 
10243     // Close Button & Unsaved Marker
10244     // We are relying on a subtle and confusing distinction between 'hovered' and 'g.HoveredId' which happens because we are using ImGuiButtonFlags_AllowOverlapMode + SetItemAllowOverlap()
10245     //  'hovered' will be true when hovering the Tab but NOT when hovering the close button
10246     //  'g.HoveredId==id' will be true when hovering the Tab including when hovering the close button
10247     //  'g.ActiveId==close_button_id' will be true when we are holding on the close button, in which case both hovered booleans are false
10248     bool close_button_pressed = false;
10249     bool close_button_visible = false;
10250     if (close_button_id != 0)
10251         if (is_contents_visible || bb.GetWidth() >= ImMax(button_sz, g.Style.TabMinWidthForCloseButton))
10252             if (g.HoveredId == tab_id || g.HoveredId == close_button_id || g.ActiveId == tab_id || g.ActiveId == close_button_id)
10253                 close_button_visible = true;
10254     bool unsaved_marker_visible = (flags & ImGuiTabItemFlags_UnsavedDocument) != 0 && (button_pos.x + button_sz <= bb.Max.x);
10255 
10256     if (close_button_visible)
10257     {
10258         ImGuiLastItemData last_item_backup = g.LastItemData;
10259         if (CloseButton(close_button_id, button_pos))
10260             close_button_pressed = true;
10261         g.LastItemData = last_item_backup;
10262 
10263         // Close with middle mouse button
10264         if (!(flags & ImGuiTabItemFlags_NoCloseWithMiddleMouseButton) && IsMouseClicked(2))
10265             close_button_pressed = true;
10266     }
10267     else if (unsaved_marker_visible)
10268     {
10269         const ImRect bullet_bb(button_pos, button_pos + ImVec2(button_sz, button_sz));
10270         RenderBullet(draw_list, bullet_bb.GetCenter(), GetColorU32(ImGuiCol_Text));
10271     }
10272 
10273     // This is all rather complicated
10274     // (the main idea is that because the close button only appears on hover, we don't want it to alter the ellipsis position)
10275     // FIXME: if FramePadding is noticeably large, ellipsis_max_x will be wrong here (e.g. #3497), maybe for consistency that parameter of RenderTextEllipsis() shouldn't exist..
10276     float ellipsis_max_x = close_button_visible ? text_pixel_clip_bb.Max.x : bb.Max.x - 1.0f;
10277     if (close_button_visible || unsaved_marker_visible)
10278     {
10279         text_pixel_clip_bb.Max.x -= close_button_visible ? (button_sz) : (button_sz * 0.80f);
10280         text_ellipsis_clip_bb.Max.x -= unsaved_marker_visible ? (button_sz * 0.80f) : 0.0f;
10281         ellipsis_max_x = text_pixel_clip_bb.Max.x;
10282     }
10283     RenderTextEllipsis(draw_list, text_ellipsis_clip_bb.Min, text_ellipsis_clip_bb.Max, text_pixel_clip_bb.Max.x, ellipsis_max_x, label, NULL, &label_size);
10284 
10285 #if 0
10286     if (!is_contents_visible)
10287         g.Style.Alpha = backup_alpha;
10288 #endif
10289 
10290     if (out_just_closed)
10291         *out_just_closed = close_button_pressed;
10292 }
